export interface Student {
  id: string;
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  gender: 'Male' | 'Female';
  classId: string;

  // Family
  fatherName: string;
  motherName: string;
  fatherPhone: string;
  motherPhone: string;
  parish: string; // Giáo họ
  address: string;

  // Sacraments
  baptismDate?: string; // Rửa tội
  baptismBy?: string;
  baptismSponsor?: string;

  eucharistDate?: string; // Rước lễ
  eucharistBy?: string;

  confirmationDate?: string; // Thêm sức
  confirmationBy?: string;
  confirmationSponsor?: string;
  confirmationOathDate?: string;

  note?: string;
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  score15m: number;
  score45m: number;
  scorePray: number; // Điểm kinh
  scoreExam: number;
  // Computed
  average: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
  class: boolean; // Học giáo lý
  classExcused: boolean;
}

export interface ClassRoom {
  id: string;
  name: string; // e.g., Chiên Con 1
  grade: string; // e.g., Khối Khai Tâm
}

export interface Transaction {
  id: string;
  date: string;
  type: 'INCOME' | 'EXPENSE';
  amount: number;
  description: string;
  note?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  type: 'NOTICE' | 'MEETING_MINUTES';
}

import React from 'react';
import { LayoutDashboard, Users, GraduationCap, Settings, Wallet, Church } from 'lucide-react';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Trang Chủ', icon: LayoutDashboard },
    { id: 'students', label: 'Học Viên', icon: Users },
    { id: 'academic', label: 'Điểm & Chuyên Cần', icon: GraduationCap },
    { id: 'finance', label: 'Thủ Quỹ', icon: Wallet },
    { id: 'settings', label: 'Cài Đặt', icon: Settings },
  ];

  return (
    <div className="w-64 bg-slate-900 text-white flex flex-col h-screen fixed left-0 top-0 shadow-lg z-50">
      <div className="p-6 flex items-center gap-3 border-b border-slate-700">
        <Church className="w-8 h-8 text-yellow-400" />
        <div>
          <h1 className="font-bold text-lg leading-tight">QL Giáo Lý</h1>
          <p className="text-xs text-slate-400">Giáo xứ Thánh Tâm</p>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                isActive 
                  ? 'bg-blue-600 text-white shadow-md' 
                  : 'text-slate-300 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <Icon className="w-5 h-5" />
              <span className="font-medium">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-700">
        <div className="text-xs text-slate-500 text-center">
          &copy; 2024 CatholicRE CRM <br/> v1.0.0
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_ACADEMIC_RECORDS } from '../constants';
import { Check, X } from 'lucide-react';

export const Academic: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'attendance' | 'grades'>('attendance');
  const [selectedClass, setSelectedClass] = useState('c1');
  const [term, setTerm] = useState('HK1');
  const [date, setDate] = useState('2023-10-22');

  const filteredStudents = MOCK_STUDENTS.filter(s => s.classId === selectedClass);

  const getRecord = (studentId: string) => {
    return MOCK_ACADEMIC_RECORDS.find(r => r.studentId === studentId && r.term === term) || {
      score15m: 0, score45m: 0, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const calculateAvg = (s15: number, s45: number, pray: number, exam: number) => {
    // Formula: (15' + 45'*2 + Pray + Exam*3) / 7 (Example logic)
    // Simplified for demo:
    const avg = (s15 + s45 * 2 + pray + exam * 2) / 6;
    return avg.toFixed(1);
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Số & Chuyên Cần</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex">
          <button 
            onClick={() => setActiveTab('attendance')}
            className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'attendance' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600'}`}
          >
            Chuyên Cần
          </button>
          <button 
            onClick={() => setActiveTab('grades')}
            className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'grades' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600'}`}
          >
            Bảng Điểm
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
        <select 
          className="px-3 py-2 border rounded-lg"
          value={selectedClass}
          onChange={(e) => setSelectedClass(e.target.value)}
        >
          {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>

        {activeTab === 'grades' && (
          <select 
            className="px-3 py-2 border rounded-lg"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
          >
            <option value="HK1">Học Kỳ 1</option>
            <option value="HK2">Học Kỳ 2</option>
          </select>
        )}

        {activeTab === 'attendance' && (
          <input 
            type="date" 
            className="px-3 py-2 border rounded-lg"
            value={date}
            onChange={(e) => setDate(e.target.value)}
          />
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          {activeTab === 'attendance' ? (
             <table className="w-full text-left border-collapse">
             <thead>
               <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                 <th className="p-4 w-16 text-center">STT</th>
                 <th className="p-4">Học Viên</th>
                 <th className="p-4 text-center border-l">Đi Lễ (Có/Ko Phép)</th>
                 <th className="p-4 text-center border-l">Học GL (Có/Ko Phép)</th>
                 <th className="p-4 text-center">Ghi chú</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-slate-50">
                   <td className="p-4 text-center">{idx + 1}</td>
                   <td className="p-4 font-medium">{s.saintName} {s.fullName}</td>
                   <td className="p-4 border-l">
                     <div className="flex justify-center gap-4">
                       <label className="flex items-center gap-2 cursor-pointer">
                         <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                         <span className="text-sm">Có mặt</span>
                       </label>
                       <label className="flex items-center gap-2 cursor-pointer text-slate-400">
                         <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-orange-500 focus:ring-orange-500" />
                         <span className="text-sm">Phép</span>
                       </label>
                     </div>
                   </td>
                   <td className="p-4 border-l">
                     <div className="flex justify-center gap-4">
                       <label className="flex items-center gap-2 cursor-pointer">
                         <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                         <span className="text-sm">Có mặt</span>
                       </label>
                       <label className="flex items-center gap-2 cursor-pointer text-slate-400">
                         <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-orange-500 focus:ring-orange-500" />
                         <span className="text-sm">Phép</span>
                       </label>
                     </div>
                   </td>
                   <td className="p-4">
                     <input type="text" className="w-full bg-transparent border-b border-dashed border-slate-300 focus:border-blue-500 outline-none text-sm" placeholder="..." />
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
          ) : (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                  <th className="p-4 w-16 text-center">STT</th>
                  <th className="p-4 min-w-[200px]">Học Viên</th>
                  <th className="p-4 w-24 text-center border-l bg-slate-50">15' (x1)</th>
                  <th className="p-4 w-24 text-center border-l bg-slate-50">45' (x2)</th>
                  <th className="p-4 w-24 text-center border-l bg-slate-50">Kinh (x1)</th>
                  <th className="p-4 w-24 text-center border-l bg-slate-50">Thi (x2)</th>
                  <th className="p-4 w-24 text-center border-l bg-blue-50 font-bold text-blue-700">TB</th>
                  <th className="p-4 w-32 text-center border-l">Xếp loại</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredStudents.map((s, idx) => {
                  const r = getRecord(s.id);
                  const avg = parseFloat(r.average.toString());
                  let rank = 'Giỏi';
                  let rankColor = 'text-green-600 bg-green-50';
                  if (avg < 5) { rank = 'Yếu'; rankColor = 'text-red-600 bg-red-50'; }
                  else if (avg < 6.5) { rank = 'TB'; rankColor = 'text-orange-600 bg-orange-50'; }
                  else if (avg < 8) { rank = 'Khá'; rankColor = 'text-blue-600 bg-blue-50'; }

                  return (
                    <tr key={s.id} className="hover:bg-slate-50 group">
                      <td className="p-4 text-center">{idx + 1}</td>
                      <td className="p-4 font-medium">{s.saintName} {s.fullName}</td>
                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.score15m} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.score45m} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scorePray} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                       <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scoreExam} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-4 border-l text-center font-bold text-slate-800">
                        {r.average || '-'}
                      </td>
                      <td className="p-4 border-l text-center">
                         {r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rankColor}`}>{rank}</span>}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {activeTab === 'grades' && (
           <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700">Lưu Bảng Điểm</button>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Academic } from './components/Academic';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'students':
        return <Students />;
      case 'academic':
        return <Academic />;
      case 'finance':
        return <Finance />;
      case 'settings':
        return <Settings />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { Church, Lock, User } from 'lucide-react';

interface LoginProps {
  onLogin: () => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simple mock authentication
    if (username && password) {
      onLogin();
    } else {
      setError('Vui lòng nhập tài khoản và mật khẩu');
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden">
        <div className="bg-blue-600 p-8 text-center">
          <div className="mx-auto w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mb-4 backdrop-blur-sm">
            <Church className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-white">Giáo xứ Tân Thành</h1>
          <p className="text-blue-100 mt-2">Hệ thống Quản lý Giáo Lý</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Tên đăng nhập</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" 
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                  placeholder="admin"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Mật khẩu</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                  placeholder="••••••••"
                />
              </div>
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg text-center font-medium">
                {error}
              </div>
            )}

            <button 
              type="submit" 
              className="w-full py-3 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 transition-all shadow-lg hover:shadow-xl transform hover:-translate-y-0.5"
            >
              Đăng Nhập
            </button>
          </form>

          <div className="mt-6 text-center text-xs text-slate-400">
            &copy; 2024 CatholicRE CRM System
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { LayoutDashboard, Users, CalendarCheck, BookOpenCheck, Settings, Wallet, Church, LogOut } from 'lucide-react';

