import React, { useState } from 'react';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_ACADEMIC_RECORDS } from '../constants';
import { Plus, Trash2 } from 'lucide-react';

interface TestColumn {
  id: string;
  name: string;
  weight: number;
}

export const Grades: React.FC = () => {
  const [selectedClass, setSelectedClass] = useState('c1');
  const [term, setTerm] = useState('HK1');

  // Dynamic columns state
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 }
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  const filteredStudents = MOCK_STUDENTS.filter(s => s.classId === selectedClass);

  const getRecord = (studentId: string) => {
    return MOCK_ACADEMIC_RECORDS.find(r => r.studentId === studentId && r.term === term) || {
      scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm Học Tập</h2>
        <div className="flex gap-2">
            <button className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50">Xuất Excel</button>
            <button className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50">In Bảng Điểm</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center">
          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Chọn lớp</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[200px]"
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
            >
              {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Học Kỳ</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[150px]"
              value={term}
              onChange={(e) => setTerm(e.target.value)}
            >
              <option value="HK1">Học Kỳ 1</option>
              <option value="HK2">Học Kỳ 2</option>
            </select>
          </div>
        </div>

        {/* Add Column Controls */}
        <div className="flex items-center gap-2">
          {showAddColumn ? (
            <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in">
              <input 
                type="text" 
                placeholder="Tên cột (VD: 15p lần 2)" 
                className="px-2 py-1 border rounded text-sm w-40"
                value={newColName}
                onChange={(e) => setNewColName(e.target.value)}
              />
              <select 
                className="px-2 py-1 border rounded text-sm"
                value={newColWeight}
                onChange={(e) => setNewColWeight(Number(e.target.value))}
              >
                <option value={1}>Hệ số 1</option>
                <option value={2}>Hệ số 2</option>
                <option value={3}>Hệ số 3</option>
              </select>
              <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button>
              <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button>
            </div>
          ) : (
            <button 
              onClick={() => setShowAddColumn(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"
            >
              <Plus size={16} /> Thêm Cột Điểm
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                  <th className="p-4 w-16 text-center sticky left-0 bg-slate-50 z-10">STT</th>
                  <th className="p-4 min-w-[200px] sticky left-16 bg-slate-50 z-10">Học Viên</th>

                  {/* Dynamic Headers */}
                  {testColumns.map(col => (
                    <th key={col.id} className="p-4 w-28 text-center border-l bg-slate-50 group relative">
                      <div className="flex flex-col items-center">
                        <span>{col.name}</span>
                        <span className="text-[10px] text-slate-400 font-normal">Hệ số {col.weight}</span>
                      </div>
                      <button 
                        onClick={() => removeColumn(col.id)}
                        className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
                        title="Xóa cột"
                      >
                        <Trash2 size={12} />
                      </button>
                    </th>
                  ))}

                  <th className="p-4 w-24 text-center border-l bg-slate-50">
                    <div className="flex flex-col items-center">
                        <span>Kinh</span>
                        <span className="text-[10px] text-slate-400 font-normal">Hệ số 1</span>
                    </div>
                  </th>
                  <th className="p-4 w-24 text-center border-l bg-slate-50">
                     <div className="flex flex-col items-center">
                        <span>Thi</span>
                        <span className="text-[10px] text-slate-400 font-normal">Hệ số 2</span>
                    </div>
                  </th>
                  <th className="p-4 w-24 text-center border-l bg-blue-50 font-bold text-blue-700">TB</th>
                  <th className="p-4 w-32 text-center border-l">Xếp loại</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredStudents.map((s, idx) => {
                  const r = getRecord(s.id);

                  // Calculate Dynamic Average locally for display
                  let totalScore = 0;
                  let totalWeight = 0;

                  // Dynamic columns
                  testColumns.forEach(col => {
                    const score = r.scores ? (r.scores[col.id] || 0) : 0;
                    if (score > 0) {
                      totalScore += score * col.weight;
                      totalWeight += col.weight;
                    }
                  });

                  // Pray & Exam (Fixed weights for demo: Pray=1, Exam=2)
                  if (r.scorePray > 0) { totalScore += r.scorePray * 1; totalWeight += 1; }
                  if (r.scoreExam > 0) { totalScore += r.scoreExam * 2; totalWeight += 2; }

                  const avg = totalWeight > 0 ? (totalScore / totalWeight) : 0;
                  const displayAvg = avg > 0 ? avg.toFixed(1) : '-';

                  let rank = 'Giỏi';
                  let rankColor = 'text-green-600 bg-green-50';
                  if (avg < 5) { rank = 'Yếu'; rankColor = 'text-red-600 bg-red-50'; }
                  else if (avg < 6.5) { rank = 'TB'; rankColor = 'text-orange-600 bg-orange-50'; }
                  else if (avg < 8) { rank = 'Khá'; rankColor = 'text-blue-600 bg-blue-50'; }

                  return (
                    <tr key={s.id} className="hover:bg-slate-50 group">
                      <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td>
                      <td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>

                      {/* Dynamic Inputs */}
                      {testColumns.map(col => (
                        <td key={col.id} className="p-2 border-l text-center">
                           <input 
                              type="number" 
                              defaultValue={r.scores ? r.scores[col.id] : ''} 
                              className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" 
                           />
                        </td>
                      ))}

                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scorePray || ''} className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                      </td>
                       <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scoreExam || ''} className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                      </td>
                      <td className="p-4 border-l text-center font-bold text-slate-800 bg-blue-50/20">
                        {displayAvg}
                      </td>
                      <td className="p-4 border-l text-center">
                         {avg > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rankColor}`}>{rank}</span>}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
        </div>

        <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium">Lưu Bảng Điểm</button>
        </div>
      </div>
    </div>
  );
};

