import React, { useState, useEffect } from 'react';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_ACADEMIC_RECORDS } from '../constants';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, FileSpreadsheet, Trophy } from 'lucide-react';
import { AcademicRecord } from '../types';

interface TestColumn {
  id: string;
  name: string;
  weight: number;
}

export const Grades: React.FC = () => {
  const [selectedClass, setSelectedClass] = useState('c1');
  const [term, setTerm] = useState<'HK1' | 'HK2' | 'YEAR'>('HK1');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');

  // Local state to handle score updates
  const [localRecords, setLocalRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);

  // Dynamic columns state
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 }
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  const filteredStudents = MOCK_STUDENTS.filter(s => s.classId === selectedClass);
  const currentClass = MOCK_CLASSES.find(c => c.id === selectedClass);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return localRecords.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, field: string, value: string) => {
    if (term === 'YEAR') return; // Cannot edit in YEAR mode

    const numValue = parseFloat(value) || 0;

    setLocalRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;

        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };

            if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            }

            const newRecords = [...prev];
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             // Create new record
             updatedRecord = {
                 studentId,
                 term: term as 'HK1'|'HK2',
                 scores: {},
                 scorePray: 0,
                 scoreExam: 0,
                 average: 0
             };
             if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { [field]: numValue };
            }
            return [...prev, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      testColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { // Count 0 if explicitly set
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });

      if (record.scorePray !== undefined) { totalScore += record.scorePray * 1; totalWeight += 1; }
      if (record.scoreExam !== undefined) { totalScore += record.scoreExam * 2; totalWeight += 2; }

      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     if (term === 'YEAR') return;

     // Recalculate averages for all visible students in current term
     const updatedRecords = localRecords.map(r => {
         if (r.term === term && filteredStudents.some(s => s.id === r.studentId)) {
             return { ...r, average: calculateAvg(r) };
         }
         return r;
     });

     // Also add records for students who might have scores in state but average not calculated yet if they were just added
     // (Simplified for demo: just updating existing records in state)
     setLocalRecords(updatedRecords);
     alert("Đã lưu bảng điểm và tính điểm trung bình!");
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
  };

  const handleExportExcel = () => {
      let csvContent = "data:text/csv;charset=utf-8,";

      if (term === 'YEAR') {
          const header = ["STT", "Mã HV", "Tên Thánh", "Họ Tên", "ĐTB HK1", "ĐTB HK2", "ĐTB Cả Năm", "Xếp Loại", "Xếp Hạng"];
          csvContent += header.join(",") + "\n";

          processedStudentsYear.forEach((s, idx) => {
              const row = [
                  idx + 1,
                  s.id,
                  s.saintName,
                  s.fullName,
                  s.avg1,
                  s.avg2,
                  s.avgYear,
                  s.rank.label,
                  s.ranking
              ];
              csvContent += row.join(",") + "\n";
          });
      } else {
           const header = ["STT", "Mã HV", "Tên Thánh", "Họ Tên", ...testColumns.map(c => c.name), "Kinh", "Thi", "ĐTB", "Xếp Loại"];
           csvContent += header.join(",") + "\n";

           filteredStudents.forEach((s, idx) => {
               const r = getRecord(s.id, term);
               const row = [
                   idx + 1,
                   s.id,
                   s.saintName,
                   s.fullName,
                   ...testColumns.map(c => r.scores[c.id] || 0),
                   r.scorePray,
                   r.scoreExam,
                   r.average,
                   getRank(r.average).label
               ];
               csvContent += row.join(",") + "\n";
           });
      }

      const encodedUri = encodeURI(csvContent);
      const link = document.createElement("a");
      link.setAttribute("href", encodedUri);
      link.setAttribute("download", `bang_diem_${selectedClass}_${term}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };


  // Logic for Summary/Year View
  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    // Calculate final average: (HK1 + HK2) / 2
    const finalAvg = (r1.average > 0 && r2.average > 0) ? (r1.average + r2.average) / 2 : 0;

    return {
      ...s,
      avg1: r1.average,
      avg2: r2.average,
      avgYear: finalAvg,
      rank: getRank(finalAvg),
      isPassed: finalAvg >= 5.0
    };
  }).sort((a, b) => b.avgYear - a.avgYear) // Sort for ranking
    .map((s, index) => ({...s, ranking: index + 1})); // Add ranking

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button 
             onClick={() => setViewMode('entry')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <Table size={16}/> Sổ Điểm
           </button>
           <button 
             onClick={() => setViewMode('summary')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <ListChecks size={16}/> Thống Kê
           </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center">
          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Chọn lớp</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[200px]"
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
            >
              {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Học Kỳ</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[150px]"
              value={term}
              onChange={(e) => setTerm(e.target.value as any)}
            >
              <option value="HK1">Học Kỳ 1</option>
              <option value="HK2">Học Kỳ 2</option>
              <option value="YEAR">Cả Năm</option>
            </select>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2">
            {term !== 'YEAR' && viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in">
                    <input 
                    type="text" 
                    placeholder="Tên cột" 
                    className="px-2 py-1 border rounded text-sm w-32"
                    value={newColName}
                    onChange={(e) => setNewColName(e.target.value)}
                    />
                    <select 
                    className="px-2 py-1 border rounded text-sm"
                    value={newColWeight}
                    onChange={(e) => setNewColWeight(Number(e.target.value))}
                    >
                    <option value={1}>x1</option>
                    <option value={2}>x2</option>
                    </select>
                    <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button>
                    <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button>
                </div>
                ) : (
                <button 
                    onClick={() => setShowAddColumn(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"
                >
                    <Plus size={16} /> Thêm Cột
                </button>
                )}
                </>
            )}

             <button 
                onClick={handleExportExcel}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50"
             >
                 <FileSpreadsheet size={16}/> Xuất Excel
             </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
          // ENTRY VIEW
          <>
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                    <th className="p-4 w-16 text-center sticky left-0 bg-slate-50 z-10">STT</th>
                    <th className="p-4 min-w-[200px] sticky left-16 bg-slate-50 z-10">Học Viên</th>

                    {term === 'YEAR' ? (
                        <>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK1</th>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK2</th>
                            <th className="p-4 text-center border-l bg-blue-100 font-bold text-blue-800">ĐTB Cả Năm</th>
                            <th className="p-4 text-center border-l">Xếp loại</th>
                            <th className="p-4 text-center border-l">Hạng</th>
                        </>
                    ) : (
                        <>
                            {testColumns.map(col => (
                            <th key={col.id} className="p-4 w-28 text-center border-l bg-slate-50 group relative">
                                <div className="flex flex-col items-center">
                                <span>{col.name}</span>
                                <span className="text-[10px] text-slate-400 font-normal">Hệ số {col.weight}</span>
