export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // MOCK LOGIN LOGIC
    // In a real app, verify password. 
    // Here we allow login if username matches an email in MOCK_TEACHERS
    // Password "admin" for simplicity for everyone

    const user = MOCK_TEACHERS.find(t => t.email === username || t.id === username);

    if (user) {
        if (password === 'admin') {
            onLogin(user);
        } else {
            setError('Mật khẩu sai. Gợi ý: admin');
        }
    } else {
      // Create a fallback demo user if list empty or not found (for easy testing)
      if (username === 'admin') {
          onLogin({
              id: 'admin',
              saintName: 'Admin',
              fullName: 'System Admin',
              email: 'admin',
              role: 'ADMIN',
              dob: '', birthPlace: '', address: '', phone: '', educationLevel: ''
          });
      } else if (username === 'glv') {
          onLogin({
              id: 'glv',
              saintName: 'GLV',
              fullName: 'Demo GLV',
              email: 'glv',
              role: 'GLV',
               dob: '', birthPlace: '', address: '', phone: '', educationLevel: ''
          });
      } else {
          setError('Tài khoản không tồn tại (Thử: admin hoặc glv)');
