import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Login } from './components/Login';
import { ClassPlacement } from './components/ClassPlacement';
import { Teacher } from './types';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<Teacher | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');

  const handleLogin = (user: Teacher) => {
      setCurrentUser(user);
      setIsAuthenticated(true);
      setActiveTab('dashboard');
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setIsAuthenticated(false);
      setActiveTab('dashboard');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'students':
        return <Students />;
      case 'teachers':
        // Only Admin can see teachers
        return currentUser?.role === 'ADMIN' ? <Teachers /> : <Dashboard />;
      case 'placement':
         // Only Admin can see placement
        return currentUser?.role === 'ADMIN' ? <ClassPlacement /> : <Dashboard />;
      case 'attendance':
        return <Attendance />;
      case 'grades':
        return <Grades />;
      case 'finance':
        return currentUser?.role === 'ADMIN' ? <Finance /> : <Dashboard />;
      case 'settings':
        return currentUser?.role === 'ADMIN' ? <Settings /> : <Dashboard />;
      default:
        return <Dashboard />;
    }
  };

  if (!isAuthenticated) {
      return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
        userRole={currentUser?.role || 'GLV'}
        onLogout={handleLogout}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

