import React, { useState } from 'react';
import { MOCK_CLASSES, MOCK_STUDENTS } from '../constants';
import { Student } from '../types';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight } from 'lucide-react';

export const ClassPlacement: React.FC = () => {
  const [mode, setMode] = useState<'BATCH' | 'SEARCH'>('BATCH');

  // Local State to manage transfers in this session
  const [localStudents, setLocalStudents] = useState<Student[]>(MOCK_STUDENTS);

  // Batch Mode State
  const [sourceClassId, setSourceClassId] = useState<string>('');
  const [targetClassId, setTargetClassId] = useState<string>('');
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Search Mode State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  // Helpers
  const sourceStudents = sourceClassId ? localStudents.filter(s => s.classId === sourceClassId) : [];

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId) return alert("Vui lòng chọn lớp nguồn và lớp đích");
    if (sourceClassId === targetClassId) return alert("Lớp nguồn và đích phải khác nhau");
    if (selectedStudentIds.length === 0) return alert("Vui lòng chọn ít nhất 1 học viên");

    const targetClass = MOCK_CLASSES.find(c => c.id === targetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển ${selectedStudentIds.length} học viên sang lớp ${targetClass}?`);

    if (confirm) {
      // Update local state
      const updatedStudents = localStudents.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });
      setLocalStudents(updatedStudents);

      alert("Đã thực hiện chuyển lớp thành công!");
      setSelectedStudentIds([]);
    }
  };

  const handleSearch = () => {
    const q = searchQuery.toLowerCase();
    const found = localStudents.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q ||
      s.fatherName.toLowerCase().includes(q) || // Tìm theo tên Bố
      s.motherName.toLowerCase().includes(q)    // Tìm theo tên Mẹ
    );

    setSearchedStudent(found || null);
    if (found) setSingleTargetClassId(found.classId);
    if (!found) alert("Không tìm thấy học viên (Kiểm tra tên, mã HV hoặc tên phụ huynh)");
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) return;
    if (searchedStudent.classId === singleTargetClassId) return alert("Học viên đã ở trong lớp này");

    const targetClass = MOCK_CLASSES.find(c => c.id === singleTargetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển em ${searchedStudent.saintName} ${searchedStudent.fullName} sang lớp ${targetClass}?`);

    if (confirm) {
       // Update Local State
       const updatedStudents = localStudents.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setLocalStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });

       alert("Đã cập nhật lớp thành công!");
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Chuyển Lớp</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex">
           <button 
             onClick={() => setMode('BATCH')}
             className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${mode === 'BATCH' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}
           >
             Chuyển Lớp Hàng Loạt
           </button>
           <button 
             onClick={() => setMode('SEARCH')}
             className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${mode === 'SEARCH' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}
           >
             Tìm & Xếp Lớp
           </button>
        </div>
      </div>

      {mode === 'BATCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          {/* SOURCE PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 rounded-t-xl">
              <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Lớp Nguồn</label>
              <select 
                className="w-full p-2 border rounded-lg bg-white"
                value={sourceClassId}
                onChange={(e) => {
                    setSourceClassId(e.target.value);
                    setSelectedStudentIds([]);
                }}
              >
                <option value="">-- Chọn lớp đi --</option>
                {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm">
                     <tr>
                       <th className="p-2 w-10">
                         <input type="checkbox" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/>
                       </th>
                       <th className="p-2">Học Viên ({sourceStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y">
                     {sourceStudents.map(s => (
                       <tr key={s.id} className={selectedStudentIds.includes(s.id) ? 'bg-blue-50' : ''}>
                         <td className="p-2">
                           <input 
                             type="checkbox" 
                             checked={selectedStudentIds.includes(s.id)}
                             onChange={() => handleCheckboxChange(s.id)}
                           />
                         </td>
                         <td className="p-2">
                           <div className="font-medium">{s.saintName} {s.fullName}</div>
                           <div className="text-xs text-slate-400">{s.id}</div>
                         </td>
                       </tr>
                     ))}
                     {sourceStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}
                   </tbody>
                 </table>
               ) : (
                 <div className="h-full flex items-center justify-center text-slate-400 text-sm">Vui lòng chọn lớp nguồn</div>
               )}
            </div>
          </div>

          {/* ACTION PANEL */}
          <div className="w-16 flex flex-col items-center justify-center gap-4">
             <div className="bg-slate-200 p-2 rounded-full">
               <ArrowRight className="text-slate-400" />
             </div>
             <button 
                onClick={executeBatchTransfer}
                disabled={selectedStudentIds.length === 0 || !targetClassId}
                className="p-3 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 disabled:bg-slate-300 disabled:cursor-not-allowed transition-all"
                title="Thực hiện chuyển lớp"
             >
               <ArrowRightLeft size={20} />
             </button>
             <div className="text-xs text-center font-medium text-blue-600">
               {selectedStudentIds.length > 0 ? `${selectedStudentIds.length} em` : ''}
             </div>
          </div>

          {/* TARGET PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-blue-50 rounded-t-xl">
              <label className="text-xs font-bold text-blue-600 uppercase mb-2 block">Lớp Đích (Lên lớp)</label>
              <select 
                className="w-full p-2 border border-blue-200 rounded-lg bg-white"
                value={targetClassId}
                onChange={(e) => setTargetClassId(e.target.value)}
              >
                <option value="">-- Chọn lớp đến --</option>
                {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 flex items-center justify-center flex-col text-slate-400">
                {targetClassId ? (
                   <>
                      <CheckCircle2 size={48} className="text-blue-100 mb-2" />
                      <p>Sẵn sàng tiếp nhận học viên vào lớp</p>
                      <p className="font-bold text-blue-600 mt-1">{MOCK_CLASSES.find(c => c.id === targetClassId)?.name}</p>
                   </>
                ) : (
                   <p>Chọn lớp đích để tiếp tục</p>
                )}
            </div>
          </div>
        </div>
      ) : (
        // SEARCH MODE
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 flex flex-col items-center">
            <div className="w-full max-w-xl mb-8">
               <div className="flex gap-2">
                 <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Tìm theo Tên/Mã HV hoặc Tên Bố/Mẹ..." 
                        className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                    />
                 </div>
                 <button onClick={handleSearch} className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Tìm Kiếm</button>
               </div>
            </div>

            {searchedStudent ? (
                <div className="w-full max-w-2xl bg-slate-50 rounded-xl border border-slate-200 p-6 animate-fade-in">
                    <div className="flex items-start gap-4 mb-6">
                       <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold text-xl">
                          {searchedStudent.fullName.charAt(0)}
                       </div>
                       <div>
                          <h3 className="text-xl font-bold text-slate-800">{searchedStudent.saintName} {searchedStudent.fullName}</h3>
                          <p className="text-slate-500 text-sm">Mã HV: {searchedStudent.id}</p>
                          <p className="text-slate-500 text-sm">Ngày sinh: {new Date(searchedStudent.dob).toLocaleDateString('vi-VN')}</p>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-6 text-sm bg-slate-100 p-4 rounded-lg">
                        <div>
                            <span className="font-semibold text-slate-600">Bố:</span> {searchedStudent.fatherName}
                        </div>
                        <div>
                            <span className="font-semibold text-slate-600">Mẹ:</span> {searchedStudent.motherName}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-8 items-center">
                       <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Lớp Hiện Tại</label>
                          <div className="p-3 bg-white border border-slate-200 rounded-lg font-medium text-slate-700">
                             {MOCK_CLASSES.find(c => c.id === searchedStudent.classId)?.name || 'Chưa xếp lớp'}
                          </div>
                       </div>

                       <div className="flex flex-col justify-center">
                          <label className="block text-xs font-bold text-blue-600 uppercase mb-2">Chuyển Đến Lớp</label>
                          <select 
                            className="w-full p-3 border border-blue-300 rounded-lg bg-white focus:ring-2 focus:ring-blue-500"
                            value={singleTargetClassId}
                            onChange={(e) => setSingleTargetClassId(e.target.value)}
                          >
                             {MOCK_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                          </select>
                       </div>
                    </div>

                    <div className="mt-8 flex justify-end">
                       <button 
                         onClick={executeSingleTransfer}
                         className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 shadow-lg shadow-green-200 flex items-center gap-2"
                       >
                         <CheckCircle2 size={18} /> Lưu Thay Đổi
                       </button>
                    </div>
                </div>
            ) : (
                <div className="text-center text-slate-400 mt-10">
                   <AlertCircle size={48} className="mx-auto mb-2 opacity-20" />
                   <p>Nhập thông tin để tìm kiếm học viên</p>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

export interface Student {
  id: string; // Mã học viên (Số tự động)
  saintName: string; // Tên Thánh
  fullName: string; // Họ tên
  dob: string; // Ngày tháng năm sinh
  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
  baptismBy?: string; // Do (Linh mục rửa tội)
  baptismSponsor?: string; // Người đỡ đầu Rửa tội

  eucharistDate?: string; // Ngày rước lễ
  eucharistBy?: string; // Do (Linh mục cho rước lễ)

  confirmationDate?: string; // Ngày thêm sức
  confirmationBy?: string; // Do (ĐGM/Cha ban thêm sức)
  confirmationSponsor?: string; // Người đỡ đầu Thêm sức

  confirmationOathDate?: string; // Ngày tuyên hứa (Bao đồng)

  note?: string; // Ghi chú
}

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
  educationLevel: string; // Học vấn Giáo Lý (VD: Cấp 1, 2, 3...)
  role: 'ADMIN' | 'GLV'; // Phân quyền
}

export interface Saint {
  id: string;
  name: string;
  gender: 'Male' | 'Female' | 'Both';
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  // Dynamic scores stored as key-value pairs
  scores: { [key: string]: number }; 
  scorePray: number; // Điểm kinh (keep separate as it's standard)
  scoreExam: number; // Thi (keep separate)
  // Computed
  average: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
  class: boolean; // Học giáo lý
  classExcused: boolean;
}

export interface ClassRoom {
  id: string;
  name: string; // e.g., Chiên Con 1
  gradeId: string; // Linked to Grade
  yearId: string; // Linked to School Year
  teacher?: string; // Giáo lý viên phụ trách
}

export interface Grade {
  id: string;
  name: string; // e.g., Khối Khai Tâm
}

export interface SchoolYear {
  id: string;
  name: string;
  isActive: boolean;
}

export interface Transaction {
  id: string;
  date: string;
  type: 'INCOME' | 'EXPENSE';
  amount: number;
  description: string;
  note?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  type: 'NOTICE' | 'MEETING_MINUTES';
}

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { ClassPlacement } from './components/ClassPlacement';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // GLOBAL STATE
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
        />;
      case 'teachers':
        return <Teachers />;
      case 'placement':
        return <ClassPlacement 
          students={students} 
          setStudents={setStudents}
          classes={classes}
          years={years}
        />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MOCK_GRADES, MOCK_SAINTS } from '../constants';
import { Calendar, Layers, Save, Plus, Trash2, Cross, CheckCircle } from 'lucide-react';
import { Saint, SchoolYear, ClassRoom } from '../types';

interface SettingsProps {
    years: SchoolYear[];
    setYears: (years: SchoolYear[]) => void;
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ years, setYears, classes, setClasses }) => {
  const [saints, setSaints] = useState<Saint[]>(MOCK_SAINTS);
  const [newSaintName, setNewSaintName] = useState('');
  const [newSaintGender, setNewSaintGender] = useState<'Male'|'Female'>('Male');

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState('g1');

  // Filter classes by active year for display in the simple list
  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  const handleAddSaint = () => {
    if (newSaintName) {
      const newSaint: Saint = {
        id: `s${Date.now()}`,
        name: newSaintName,
        gender: newSaintGender
      };
      setSaints([...saints, newSaint]);
      setNewSaintName('');
    }
  };

  const handleRemoveSaint = (id: string) => {
    setSaints(saints.filter(s => s.id !== id));
  };

  const handleAddYear = () => {
      if (newYearName) {
          const newId = newYearName.replace(/\s/g, '-');
          const newYear: SchoolYear = {
              id: newId,
              name: newYearName,
              isActive: false
          };
          setYears([...years, newYear]);
          setNewYearName('');
          alert(`Đã thêm năm học: ${newYearName}`);
      }
  };

  const handleSetActiveYear = (id: string) => {
      const updatedYears = years.map(y => ({
          ...y,
          isActive: y.id === id
      }));
      setYears(updatedYears);
  };

  const handleAddClass = () => {
      if (newClassName && activeYear) {
          const newClass: ClassRoom = {
              id: `c_${Date.now()}`,
              name: newClassName,
              gradeId: newClassGrade,
              yearId: activeYear.id,
              teacher: 'Chưa phân công'
          };
          setClasses([...classes, newClass]);
          setNewClassName('');
      } else {
          alert("Vui lòng nhập tên lớp và đảm bảo có năm học đang kích hoạt.");
      }
  };

  return (
    <div className="p-6 h-screen overflow-y-auto custom-scrollbar">
      <h2 className="text-2xl font-bold text-slate-800 mb-6">Cài Đặt Hệ Thống</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">

        {/* School Year Config */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4">
            <Calendar className="text-blue-600" />
            <h3 className="font-bold text-lg text-slate-800">Quản Lý Năm Học</h3>
          </div>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Danh sách năm học</label>
              <div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar border rounded-lg p-2">
                  {years.map(y => (
                      <div key={y.id} className={`flex justify-between items-center p-2 rounded-lg ${y.isActive ? 'bg-blue-50 border border-blue-200' : 'bg-slate-50'}`}>
                          <span className={y.isActive ? 'font-bold text-blue-700' : 'text-slate-700'}>
                              {y.name} {y.isActive && '(Hiện tại)'}
                          </span>
                          {!y.isActive && (
                              <button 
                                onClick={() => handleSetActiveYear(y.id)}
                                className="text-xs px-2 py-1 bg-white border border-slate-300 rounded hover:bg-slate-100"
                              >
                                Đặt làm hiện tại
                              </button>
                          )}
                      </div>
                  ))}
              </div>
            </div>

            <div className="border-t pt-4 mt-4">
               <h4 className="font-semibold text-sm mb-3">Tạo Năm Học Mới</h4>
               <div className="grid grid-cols-2 gap-4 mb-3">
                 <input 
                    type="text" 
                    placeholder="Tên năm học (VD: 2024-2025)" 
                    className="w-full p-2 border rounded-lg text-sm" 
                    value={newYearName}
                    onChange={(e) => setNewYearName(e.target.value)}
                 />
                 <button 
                    onClick={handleAddYear}
                    className="flex items-center justify-center gap-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
                 >
                    <Plus size={16}/> Thêm mới
                 </button>
               </div>
            </div>
          </div>
        </div>

        {/* Saint Names Management */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4">
            <Cross className="text-amber-600" />
            <h3 className="font-bold text-lg text-slate-800">Quản Lý Tên Thánh</h3>
          </div>
          <div className="space-y-4">
             <div className="flex gap-2">
               <input 
                 type="text" 
                 placeholder="Tên Thánh (VD: Đaminh)" 
                 className="flex-1 p-2 border rounded-lg text-sm"
                 value={newSaintName}
                 onChange={(e) => setNewSaintName(e.target.value)}
               />
               <select 
                 className="p-2 border rounded-lg text-sm"
                 value={newSaintGender}
