               <button onClick={handleAddSaint} className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 font-bold">+</button>
            </div>

            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar">
               <table className="w-full text-left text-sm">
                 <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="p-3">Tên Thánh</th>
                      <th className="p-3 w-20">Giới tính</th>
                      <th className="p-3 text-right w-16"></th>
