                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
            </div>
          </div>
        </div>

        {/* Grades (Khối) Config */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4">
            <Layers className="text-purple-600" />
            <h3 className="font-bold text-lg text-slate-800">Quản Lý Khối Lớp</h3>
          </div>
          <div className="space-y-4">
             <div className="flex gap-2">
               <input type="text" placeholder="Tên khối (VD: Khối Vào Đời)" className="flex-1 p-2 border rounded-lg" />
               <button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 font-bold">+</button>
            </div>

            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar">
               <table className="w-full text-left text-sm">
