          <div className="space-y-4">
            <div className="flex gap-2">
               <input 
                type="text" 
                placeholder="Tên lớp mới" 
                className="flex-1 p-2 border rounded-lg"
                value={newClassName}
                onChange={(e) => setNewClassName(e.target.value)} 
                />
               <select 
                className="p-2 border rounded-lg w-28"
                value={newClassGrade}
                onChange={(e) => setNewClassGrade(e.target.value)}
               >
                 {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
               </select>
               <button 
                onClick={handleAddClass}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-bold"
               >
                +
               </button>
            </div>

            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar">
               <table className="w-full text-left text-sm">
                 <thead className="bg-slate-50">
                    <tr>
                      <th className="p-3">Tên Lớp</th>
                      <th className="p-3">Khối</th>
                      <th className="p-3 text-right"></th>
                    </tr>
                 </thead>
                 <tbody className="divide-y">
                   {classesInActiveYear.length > 0 ? (
                       classesInActiveYear.map(c => {
                        const gradeName = MOCK_GRADES.find(g => g.id === c.gradeId)?.name || '---';
                        return (
                        <tr key={c.id}>
                          <td className="p-3 font-medium">{c.name}</td>
                          <td className="p-3 text-slate-500 text-xs">{gradeName}</td>
                          <td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer">
                             <Trash2 size={16} className="ml-auto" />
                          </td>
                        </tr>
                      )})
                   ) : (
                       <tr><td colSpan={3} className="p-4 text-center text-slate-500 italic">Chưa có lớp nào trong năm học này</td></tr>
                   )}
                 </tbody>
               </table>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { Search, Plus, FileSpreadsheet, Edit, Trash2, X, Printer, ChevronDown, AlertTriangle } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [showPrintMenu, setShowPrintMenu] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Delete Confirmation State
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Saint Selector State
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [saintInput, setSaintInput] = useState('');

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Handle Grade Change
  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); // Reset class when grade changes
  };

  // Filter Logic
  const filteredStudents = students.filter(student => {
    // Search
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    // Determine the list of valid class IDs based on current filters
    let validClassIds: string[] = [];

    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        // If Year is selected but Grade/Class is ALL, show all students in that YEAR
        validClassIds = classesInYear.map(c => c.id);
    }

    // Only show students belonging to the valid classes
    const matchClass = validClassIds.includes(student.classId);

    return matchSearch && matchClass;
  });

  const filteredSaints = MOCK_SAINTS.filter(s => 
    s.name.toLowerCase().includes(saintInput.toLowerCase())
  );

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const handlePrintPDF = (type: 'short' | 'full') => {
      // Print logic remains same...
  };

  const handleExportExcel = () => {
    alert(`Tính năng đang phát triển...`);
  };

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setSaintInput(student.saintName);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setSaintInput('');
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setShowSaintSuggestions(false);
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      alert(`Đã xóa học viên: ${studentToDelete.fullName}`);
      setStudentToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
          {/* Print Dropdown */}
          <div className="relative">
             <button 
                onClick={() => setShowPrintMenu(!showPrintMenu)}
                className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm"
              >
                <Printer size={16} /> In Danh Sách <ChevronDown size={14}/>
              </button>
              {showPrintMenu && (
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-slate-200 z-10 overflow-hidden">
                  <button onClick={() => handlePrintPDF('short')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50">Danh sách Rút gọn</button>
                  <button onClick={() => handlePrintPDF('full')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 border-t">Danh sách Đầy đủ</button>
                </div>
              )}
          </div>

          <button 
            onClick={handleExportExcel}
