            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                <th className="p-4 font-semibold w-16 text-center">STT</th>
                <th className="p-4 font-semibold w-24">Mã HV</th>
                <th className="p-4 font-semibold">Tên Thánh & Họ Tên</th>
                <th className="p-4 font-semibold">Ngày Sinh</th>
                <th className="p-4 font-semibold">Lớp</th>
                <th className="p-4 font-semibold">Phụ Huynh</th>
                <th className="p-4 font-semibold">Ghi chú</th>
                <th className="p-4 font-semibold text-center">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((student, index) => (
                <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4 font-mono text-xs text-slate-500 bg-slate-100 rounded inline-block my-3 mx-4">{student.id}</td>
                  <td className="p-4">
                    <div className="font-semibold text-slate-800">{student.saintName} {student.fullName}</div>
