                         <span className="text-sm font-medium text-slate-700">Có mặt</span>
                       </label>
                       <label className="flex items-center gap-2 cursor-pointer select-none">
                         <input type="checkbox" className="w-5 h-5 rounded border-gray-300 text-orange-500 focus:ring-orange-500" />
                         <span className="text-sm text-slate-500">Phép</span>
                       </label>
                     </div>
                   </td>
                   <td className="p-4">
                     <input type="text" className="w-full bg-transparent border-b border-dashed border-slate-300 focus:border-blue-500 outline-none text-sm py-1" placeholder="Nhập ghi chú..." />
