               )}
             </tbody>
           </table>
        </div>
        <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium">Lưu Điểm Danh</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
