  const [selectedClass, setSelectedClass] = useState('');

  const [term, setTerm] = useState<'HK1' | 'HK2' | 'YEAR'>('HK1');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');

  // Dynamic columns state
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 }
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Auto-select first class if available when grade changes
  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, field: string, value: string) => {
    if (term === 'YEAR') return; // Cannot edit in YEAR mode

    const numValue = parseFloat(value) || 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];

        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };

            if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            }

            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             // Create new record
             updatedRecord = {
                 studentId,
                 term: term as 'HK1'|'HK2',
                 scores: {},
                 scorePray: 0,
                 scoreExam: 0,
                 average: 0
             };
             if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { [field]: numValue };
            }
            return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      testColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { // Count 0 if explicitly set
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });

      if (record.scorePray !== undefined) { totalScore += record.scorePray * 1; totalWeight += 1; }
      if (record.scoreExam !== undefined) { totalScore += record.scoreExam * 2; totalWeight += 2; }

      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     if (term === 'YEAR') return;

     // Recalculate averages for all visible students in current term
     const updatedRecords = records.map(r => {
         if (r.term === term && filteredStudents.some(s => s.id === r.studentId)) {
             return { ...r, average: calculateAvg(r) };
         }
         return r;
     });

     // Also logic needed for newly created records that are not yet in 'records' if we were strictly using local state, but here we update 'records' directly in handleScoreChange.
     // However, we need to ensure averages are updated.
     // In a real app, this might be a bulk update. Here we just set state.

     setRecords(updatedRecords);
     alert("Đã lưu bảng điểm và tính điểm trung bình!");
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
  };

  const moveColumn = (index: number, direction: 'left' | 'right') => {
    if (direction === 'left' && index > 0) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index - 1];
      newCols[index - 1] = temp;
      setTestColumns(newCols);
    } else if (direction === 'right' && index < testColumns.length - 1) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index + 1];
      newCols[index + 1] = temp;
      setTestColumns(newCols);
    }
  };

  const handleExportExcel = () => {
     // ... (Keep existing logic, omitted for brevity)
     alert("Tính năng xuất Excel đang cập nhật...");
  };


  // Logic for Summary/Year View
  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    // Calculate final average: (HK1 + HK2) / 2
    const finalAvg = (r1.average > 0 && r2.average > 0) ? (r1.average + r2.average) / 2 : 0;

    return {
      ...s,
      avg1: r1.average,
      avg2: r2.average,
      avgYear: finalAvg,
      rank: getRank(finalAvg),
      isPassed: finalAvg >= 5.0
    };
  }).sort((a, b) => b.avgYear - a.avgYear) // Sort for ranking
    .map((s, index) => ({...s, ranking: index + 1})); // Add ranking

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button 
             onClick={() => setViewMode('entry')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <Table size={16}/> Sổ Điểm
           </button>
           <button 
             onClick={() => setViewMode('summary')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <ListChecks size={16}/> Thống Kê
           </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">

          <div className="flex flex-col">
              <label className="text-xs font-bold text-slate-500 uppercase mb-1">Năm học</label>
              <select 
                className="px-3 py-2 border rounded-lg min-w-[140px]"
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
              >
                {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
              </select>
          </div>

          <div className="flex flex-col">
              <label className="text-xs font-bold text-slate-500 uppercase mb-1">Khối</label>
              <select 
                className="px-3 py-2 border rounded-lg min-w-[140px]"
                value={selectedGrade}
                onChange={(e) => setSelectedGrade(e.target.value)}
              >
                <option value="all">-- Tất cả --</option>
                {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
              </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Chọn lớp</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[160px]"
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
            >
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              {availableClasses.length === 0 && <option value="">Không có lớp</option>}
            </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Học Kỳ</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[140px]"
              value={term}
              onChange={(e) => setTerm(e.target.value as any)}
            >
              <option value="HK1">Học Kỳ 1</option>
              <option value="HK2">Học Kỳ 2</option>
              <option value="YEAR">Cả Năm</option>
            </select>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2">
            {term !== 'YEAR' && viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in">
                    <input 
                    type="text" 
                    placeholder="Tên cột" 
                    className="px-2 py-1 border rounded text-sm w-32"
                    value={newColName}
                    onChange={(e) => setNewColName(e.target.value)}
                    />
                    <select 
                    className="px-2 py-1 border rounded text-sm"
                    value={newColWeight}
                    onChange={(e) => setNewColWeight(Number(e.target.value))}
                    >
                    <option value={1}>x1</option>
                    <option value={2}>x2</option>
                    </select>
                    <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button>
                    <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button>
                </div>
                ) : (
                <button 
                    onClick={() => setShowAddColumn(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"
                >
                    <Plus size={16} /> Thêm Cột
                </button>
                )}
                </>
            )}

             <button 
                onClick={handleExportExcel}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50"
             >
                 <FileSpreadsheet size={16}/> Xuất Excel
             </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
          // ENTRY VIEW
          <>
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                    <th className="p-4 w-16 text-center sticky left-0 bg-slate-50 z-10">STT</th>
                    <th className="p-4 min-w-[200px] sticky left-16 bg-slate-50 z-10">Học Viên</th>

                    {term === 'YEAR' ? (
                        <>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK1</th>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK2</th>
                            <th className="p-4 text-center border-l bg-blue-100 font-bold text-blue-800">ĐTB Cả Năm</th>
                            <th className="p-4 text-center border-l">Xếp loại</th>
                            <th className="p-4 text-center border-l">Hạng</th>
                        </>
                    ) : (
                        <>
                            {testColumns.map((col, idx) => (
                            <th key={col.id} className="p-4 w-32 text-center border-l bg-slate-50 group relative">
                                <div className="flex flex-col items-center">
                                <span>{col.name}</span>
                                <span className="text-[10px] text-slate-400 font-normal">Hệ số {col.weight}</span>
                                </div>

                                {/* Controls */}
                                <div className="absolute inset-x-0 bottom-0 flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pb-1">
                                   {idx > 0 && <button onClick={() => moveColumn(idx, 'left')} className="p-1 hover:bg-slate-200 rounded"><ArrowLeft size={10}/></button>}
                                   {idx < testColumns.length - 1 && <button onClick={() => moveColumn(idx, 'right')} className="p-1 hover:bg-slate-200 rounded"><ArrowRight size={10}/></button>}
                                </div>

                                <button 
                                onClick={() => removeColumn(col.id)}
                                className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
                                title="Xóa cột"
                                >
                                <Trash2 size={12} />
                                </button>
                            </th>
                            ))}

                            <th className="p-4 w-24 text-center border-l bg-slate-50">Kinh (x1)</th>
                            <th className="p-4 w-24 text-center border-l bg-slate-50">Thi (x2)</th>
                            <th className="p-4 w-24 text-center border-l bg-blue-50 font-bold text-blue-700">TB</th>
                            <th className="p-4 w-32 text-center border-l">Xếp loại</th>
                        </>
                    )}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                   {filteredStudents.length > 0 ? (
                      term === 'YEAR' 
                    ? processedStudentsYear.map((s, idx) => (
                         <tr key={s.id} className="hover:bg-slate-50 group">
                            <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td>
                            <td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>
                            <td className="p-4 text-center border-l text-slate-500">{s.avg1 || '-'}</td>
                            <td className="p-4 text-center border-l text-slate-500">{s.avg2 || '-'}</td>
                            <td className="p-4 text-center border-l font-bold text-blue-700 bg-blue-50/30">{s.avgYear.toFixed(1)}</td>
                            <td className="p-4 text-center border-l">
                                <span className={`px-2 py-1 rounded text-xs font-bold ${s.rank.color}`}>{s.rank.label}</span>
                            </td>
                            <td className="p-4 text-center border-l font-mono font-bold text-slate-600">
                                {s.ranking <= 3 ? <span className="flex items-center justify-center gap-1 text-yellow-600"><Trophy size={14}/> {s.ranking}</span> : s.ranking}
                            </td>
                         </tr>
                    ))
                    : filteredStudents.map((s, idx) => {
                    const r = getRecord(s.id, term as 'HK1' | 'HK2');
                    const rank = getRank(r.average);

                    return (
                      <tr key={s.id} className="hover:bg-slate-50 group">
                        <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td>
                        <td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>

                        {testColumns.map(col => (
                          <td key={col.id} className="p-2 border-l text-center">
                            <input 
                                type="number" 
                                value={r.scores ? r.scores[col.id] || '' : ''}
                                onChange={(e) => handleScoreChange(s.id, col.id, e.target.value)}
                                className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" 
                            />
                          </td>
                        ))}

                        <td className="p-2 border-l text-center">
                          <input 
                            type="number" 
                            value={r.scorePray || ''} 
                            onChange={(e) => handleScoreChange(s.id, 'pray', e.target.value)}
                            className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                        </td>
                        <td className="p-2 border-l text-center">
                          <input 
                            type="number" 
                            value={r.scoreExam || ''} 
                            onChange={(e) => handleScoreChange(s.id, 'exam', e.target.value)}
                            className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                        </td>
                        <td className="p-4 border-l text-center font-bold text-slate-800 bg-blue-50/20">
                          {r.average > 0 ? r.average : '-'}
                        </td>
                        <td className="p-4 border-l text-center">
                          {r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rank.color}`}>{rank.label}</span>}
                        </td>
                      </tr>
                    );
                  })
                   ) : (
                       <tr><td colSpan={10} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                   )}
                </tbody>
              </table>
            </div>
            {term !== 'YEAR' && filteredStudents.length > 0 && (
                <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
                <button 
                    onClick={handleSaveGrades}
                    className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium"
                >
                    <Save size={18} /> Lưu Bảng Điểm
                </button>
                </div>
            )}
          </>
        ) : (
          // SUMMARY VIEW
          <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
             {/* Header Info */}
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-500 flex items-center gap-2">
                      <UserCheck size={18} />
                      GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.teacher || 'Chưa cập nhật'}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-slate-500">Sĩ số</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Passed List */}
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                   <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                      <div className="flex items-center gap-2">
                        <CheckCircle2 className="text-green-600" />
                        <h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4>
                      </div>
                      <span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">
                        {passedStudents.length} em
                      </span>
                   </div>
                   <div className="overflow-x-auto">
                     <table className="w-full text-sm">
                       <thead className="bg-slate-50 text-slate-500">
                         <tr>
                           <th className="p-3 text-left">Học Viên</th>
                           <th className="p-3 text-center">ĐTB Cả Năm</th>
                           <th className="p-3 text-center">Xếp loại</th>
                         </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                         {passedStudents.map(s => (
                           <tr key={s.id} className="hover:bg-green-50/30">
                             <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                             <td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td>
                             <td className="p-3 text-center">
                               <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span>
                             </td>
                           </tr>
                         ))}
                         {passedStudents.length === 0 && (
                           <tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>
                         )}
                       </tbody>
                     </table>
                   </div>
                </div>

                {/* Failed List */}
                <div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden">
                   <div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center">
                      <div className="flex items-center gap-2">
                        <XCircle className="text-red-600" />
                        <h4 className="font-bold text-red-800">Danh Sách Ở Lại Lớp</h4>
                      </div>
                      <span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">
                        {failedStudents.length} em
                      </span>
                   </div>
                   <div className="overflow-x-auto">
                     <table className="w-full text-sm">
                       <thead className="bg-slate-50 text-slate-500">
                         <tr>
                           <th className="p-3 text-left">Học Viên</th>
                           <th className="p-3 text-center">ĐTB Cả Năm</th>
                           <th className="p-3 text-center">Xếp loại</th>
                         </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                         {failedStudents.map(s => (
                           <tr key={s.id} className="hover:bg-red-50/30">
                             <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                             <td className="p-3 text-center font-bold text-red-600">{s.avgYear.toFixed(1)}</td>
                             <td className="p-3 text-center">
                               <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span>
                             </td>
                           </tr>
                         ))}
                          {failedStudents.length === 0 && (
                           <tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Không có học viên ở lại lớp</td></tr>
                         )}
                       </tbody>
                     </table>
                   </div>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<'BATCH' | 'SEARCH'>('BATCH');

  // === Source Filters ===
  const [sourceYearId, setSourceYearId] = useState<string>('');
  const [sourceGradeId, setSourceGradeId] = useState<string>('all');
  const [sourceClassId, setSourceClassId] = useState<string>('');

  // === Target Filters ===
  const [targetYearId, setTargetYearId] = useState<string>('');
  const [targetGradeId, setTargetGradeId] = useState<string>('all');
  const [targetClassId, setTargetClassId] = useState<string>('');

  // Set default active year
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) {
      setSourceYearId(active.id);
      setTargetYearId(active.id);
    }
  }, [years]);

  // Derived Source Classes
  const sourceClassesAvailable = useMemo(() => {
    if (sourceGradeId === 'all') return [];
    return classes.filter(c => c.yearId === sourceYearId && c.gradeId === sourceGradeId);
  }, [classes, sourceYearId, sourceGradeId]);

  // Derived Target Classes
  const targetClassesAvailable = useMemo(() => {
    if (targetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === targetYearId && c.gradeId === targetGradeId);
  }, [classes, targetYearId, targetGradeId]);

  // --- Batch Logic ---
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  const sourceStudents = useMemo(() => {
      return sourceClassId ? students.filter(s => s.classId === sourceClassId) : [];
  }, [students, sourceClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId) return alert("Vui lòng chọn đầy đủ lớp nguồn và lớp đích");
    if (sourceClassId === targetClassId) return alert("Lớp nguồn và đích phải khác nhau");
    if (selectedStudentIds.length === 0) return alert("Vui lòng chọn ít nhất 1 học viên");

    const targetClass = classes.find(c => c.id === targetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển ${selectedStudentIds.length} học viên sang lớp ${targetClass}?`);

    if (confirm) {
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });
      setStudents(updatedStudents);
      alert("Đã thực hiện chuyển lớp thành công!");
      setSelectedStudentIds([]);
    }
  };

  // --- Search Logic ---
  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);

  // Single Transfer Target
  const [singleTargetYearId, setSingleTargetYearId] = useState('');
  const [singleTargetGradeId, setSingleTargetGradeId] = useState('all');
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  const singleTargetClassesAvailable = useMemo(() => {
    if (singleTargetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === singleTargetYearId && c.gradeId === singleTargetGradeId);
  }, [classes, singleTargetYearId, singleTargetGradeId]);

  const handleSearch = () => {
    const q = searchQuery.toLowerCase();
    const found = students.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q ||
      s.fatherName.toLowerCase().includes(q) ||
      s.motherName.toLowerCase().includes(q)
    );

    setSearchedStudent(found || null);
    if (found) {
        // Init target selectors for single mode to current active year
        const active = years.find(y => y.isActive);
        if(active) setSingleTargetYearId(active.id);
    }
    if (!found) alert("Không tìm thấy học viên");
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) return alert("Vui lòng chọn lớp đích");

    const targetClass = classes.find(c => c.id === singleTargetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển em ${searchedStudent.saintName} ${searchedStudent.fullName} sang lớp ${targetClass}?`);

    if (confirm) {
       const updatedStudents = students.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });
       alert("Đã cập nhật lớp thành công!");
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Chuyển Lớp</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex">
           <button onClick={() => setMode('BATCH')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${mode === 'BATCH' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}>Chuyển Lớp Hàng Loạt</button>
           <button onClick={() => setMode('SEARCH')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${mode === 'SEARCH' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}>Tìm & Xếp Lớp</button>
        </div>
      </div>

      {mode === 'BATCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          {/* SOURCE PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 rounded-t-xl space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase block">Lớp Nguồn</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={sourceYearId} onChange={e => { setSourceYearId(e.target.value); setSourceClassId(''); }}>
                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                 </select>
                 <select className="p-2 border rounded-lg text-sm" value={sourceGradeId} onChange={e => { setSourceGradeId(e.target.value); setSourceClassId(''); }}>
                    <option value="all">-- Chọn Khối --</option>
                    {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                 </select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={sourceClassId} onChange={e => { setSourceClassId(e.target.value); setSelectedStudentIds([]); }}>
                <option value="">-- Chọn Lớp --</option>
                {sourceClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10">
                     <tr>
                       <th className="p-2 w-10"><input type="checkbox" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/></th>
                       <th className="p-2">Học Viên ({sourceStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y">
                     {sourceStudents.map(s => (
                       <tr key={s.id} className={selectedStudentIds.includes(s.id) ? 'bg-blue-50' : ''}>
                         <td className="p-2"><input type="checkbox" checked={selectedStudentIds.includes(s.id)} onChange={() => handleCheckboxChange(s.id)}/></td>
                         <td className="p-2">
                           <div className="font-medium">{s.saintName} {s.fullName}</div>
                           <div className="text-xs text-slate-400">{s.id}</div>
                         </td>
                       </tr>
                     ))}
                     {sourceStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}
                   </tbody>
                 </table>
               ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">Vui lòng chọn lớp nguồn</div>}
            </div>
          </div>

          {/* ACTION PANEL */}
          <div className="w-16 flex flex-col items-center justify-center gap-4">
             <div className="bg-slate-200 p-2 rounded-full"><ArrowRight className="text-slate-400" /></div>
             <button 
                onClick={executeBatchTransfer}
                disabled={selectedStudentIds.length === 0 || !targetClassId}
                className="p-3 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 disabled:bg-slate-300 disabled:cursor-not-allowed transition-all"
                title="Thực hiện chuyển lớp"
             >
               <ArrowRightLeft size={20} />
             </button>
             <div className="text-xs text-center font-medium text-blue-600">{selectedStudentIds.length > 0 ? `${selectedStudentIds.length} em` : ''}</div>
          </div>

          {/* TARGET PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-blue-50 rounded-t-xl space-y-3">
              <label className="text-xs font-bold text-blue-600 uppercase block">Lớp Đích</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={targetYearId} onChange={e => { setTargetYearId(e.target.value); setTargetClassId(''); }}>
                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                 </select>
                 <select className="p-2 border rounded-lg text-sm" value={targetGradeId} onChange={e => { setTargetGradeId(e.target.value); setTargetClassId(''); }}>
                    <option value="all">-- Chọn Khối --</option>
                    {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                 </select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={targetClassId} onChange={e => setTargetClassId(e.target.value)}>
                <option value="">-- Chọn Lớp Đến --</option>
                {targetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 flex items-center justify-center flex-col text-slate-400">
                {targetClassId ? (
                   <>
                      <CheckCircle2 size={48} className="text-blue-100 mb-2" />
                      <p>Sẵn sàng tiếp nhận học viên vào lớp</p>
                      <p className="font-bold text-blue-600 mt-1">{classes.find(c => c.id === targetClassId)?.name}</p>
                   </>
                ) : <p className="italic">Vui lòng chọn khối và lớp đích</p>}
            </div>
          </div>
        </div>
      ) : (
        // SEARCH MODE
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 flex flex-col items-center">
            <div className="w-full max-w-xl mb-8 flex gap-2">
                 <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="text" placeholder="Tìm theo Tên/Mã HV hoặc Tên Bố/Mẹ..." className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()}/>
                 </div>
                 <button onClick={handleSearch} className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Tìm Kiếm</button>
            </div>

            {searchedStudent ? (
                <div className="w-full max-w-2xl bg-slate-50 rounded-xl border border-slate-200 p-6 animate-fade-in">
                    <div className="flex items-start gap-4 mb-6">
                       <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold text-xl">{searchedStudent.fullName.charAt(0)}</div>
                       <div>
                          <h3 className="text-xl font-bold text-slate-800">{searchedStudent.saintName} {searchedStudent.fullName}</h3>
                          <p className="text-slate-500 text-sm">Mã HV: {searchedStudent.id} | DOB: {searchedStudent.dob}</p>
                       </div>
                    </div>
                    <div className="grid grid-cols-2 gap-8 items-center">
                       <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Lớp Hiện Tại</label>
                          <div className="p-3 bg-white border border-slate-200 rounded-lg font-medium text-slate-700">
                             {classes.find(c => c.id === searchedStudent.classId)?.name || 'Chưa xếp lớp'}
                             <span className="block text-xs text-slate-400 font-normal">{years.find(y => y.id === classes.find(c => c.id === searchedStudent.classId)?.yearId)?.name}</span>
                          </div>
                       </div>
                       <div className="flex flex-col justify-center space-y-2">
                          <label className="block text-xs font-bold text-blue-600 uppercase">Chuyển Đến Lớp</label>
                          <select className="w-full p-2 border rounded text-sm" value={singleTargetYearId} onChange={e => {setSingleTargetYearId(e.target.value); setSingleTargetClassId('');}}>
                             {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                          </select>
                          <select className="w-full p-2 border rounded text-sm" value={singleTargetGradeId} onChange={e => {setSingleTargetGradeId(e.target.value); setSingleTargetClassId('');}}>
                             <option value="all">-- Chọn Khối --</option>
                             {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                          </select>
                          <select className="w-full p-2 border rounded text-sm bg-white font-medium" value={singleTargetClassId} onChange={e => setSingleTargetClassId(e.target.value)}>
                             <option value="">-- Chọn Lớp --</option>
                             {singleTargetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                          </select>
                       </div>
                    </div>
                    <div className="mt-8 flex justify-end">
                       <button onClick={executeSingleTransfer} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 shadow flex items-center gap-2"><CheckCircle2 size={18} /> Lưu Thay Đổi</button>
                    </div>
                </div>
            ) : <div className="text-center text-slate-400 mt-10"><AlertCircle size={48} className="mx-auto mb-2 opacity-20" /><p>Nhập thông tin để tìm kiếm học viên</p></div>}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { Search, Plus, FileSpreadsheet, Edit, Trash2, X, Printer, ChevronDown } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [saintInput, setSaintInput] = useState('');

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Handle Grade Change
  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  // Filter Logic
  const filteredStudents = students.filter(student => {
    // Search
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    // Determine the list of valid class IDs based on current filters
    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const filteredSaints = MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setSaintInput(student.saintName);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setSaintInput('');
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setShowSaintSuggestions(false);
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      setStudentToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
          <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">-- Tất cả Khối --</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">-- Tất cả Lớp --</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      {/* Table - FULL COLUMNS */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="min-w-max text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="p-3 border-b border-r text-center bg-slate-50 sticky left-0 z-20 w-12">STT</th>
                <th className="p-3 border-b border-r text-center bg-slate-50 sticky left-12 z-20 w-16">Thao tác</th>
                <th className="p-3 border-b border-r w-24">Mã HV</th>
                <th className="p-3 border-b border-r w-28">Tên Thánh</th>
                <th className="p-3 border-b border-r w-48">Họ Tên</th>
                <th className="p-3 border-b border-r w-28">Ngày Sinh</th>
                <th className="p-3 border-b border-r w-32">Nơi Sinh</th>
                <th className="p-3 border-b border-r w-40">Tên Bố</th>
                <th className="p-3 border-b border-r w-40">Tên Mẹ</th>
                <th className="p-3 border-b border-r w-32">Giáo Họ</th>
                <th className="p-3 border-b border-r w-64">Địa Chỉ</th>
                <th className="p-3 border-b border-r w-28">SĐT Bố</th>
                <th className="p-3 border-b border-r w-28">SĐT Mẹ</th>

                {/* Rửa Tội */}
                <th className="p-3 border-b border-r bg-blue-50 w-28">Ngày Rửa Tội</th>
                <th className="p-3 border-b border-r bg-blue-50 w-40">Linh mục Rửa Tội</th>
                <th className="p-3 border-b border-r bg-blue-50 w-40">Người đỡ đầu RT</th>

                {/* Rước Lễ */}
                <th className="p-3 border-b border-r bg-green-50 w-28">Ngày Rước Lễ</th>
                <th className="p-3 border-b border-r bg-green-50 w-40">Linh mục Rước Lễ</th>

                {/* Thêm Sức */}
                <th className="p-3 border-b border-r bg-purple-50 w-28">Ngày Thêm Sức</th>
                <th className="p-3 border-b border-r bg-purple-50 w-40">ĐGM/Cha Thêm Sức</th>
                <th className="p-3 border-b border-r bg-purple-50 w-40">Người đỡ đầu TS</th>

                <th className="p-3 border-b border-r w-28">Ngày Tuyên Hứa</th>
                <th className="p-3 border-b border-r min-w-[200px]">Ghi chú</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-3 border-r text-center text-slate-500 sticky left-0 bg-white hover:bg-slate-50">{index + 1}</td>
                  <td className="p-3 border-r text-center sticky left-12 bg-white hover:bg-slate-50">
                     <div className="flex justify-center gap-1">
                        <button onClick={() => openStudentDetail(s)} className="p-1 text-blue-600 hover:bg-blue-100 rounded"><Edit size={16} /></button>
