                 <div className="p-2 bg-blue-100 rounded-lg text-blue-600"><User size={24}/></div>
                 <div>
                    <h3 className="text-xl font-bold text-slate-800">
                        {selectedStudent ? 'Cập nhật Hồ Sơ' : 'Thêm Học Viên Mới'}
                    </h3>
                    <p className="text-xs text-slate-500">Vui lòng điền đầy đủ thông tin bên dưới</p>
