                 <div className="mb-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">B. Bí tích Thánh Thể (Rước lễ lần đầu)</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Rước Lễ</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.eucharistDate} />
                        </div>
                        <div className="md:col-span-2">
                            <label className="block text-xs font-bold text-slate-500 mb-1">Linh mục ban BT (Do)</label>
                            <input className="w-full border border-slate-300 p-2 rounded" placeholder="Cha..." defaultValue={selectedStudent?.eucharistBy} />
                        </div>
                    </div>
                 </div>

                 {/* Thêm Sức */}
                 <div className="mb-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">C. Bí tích Thêm Sức</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Thêm Sức</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationDate} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">ĐGM/Linh mục ban (Do)</label>
                            <input className="w-full border border-slate-300 p-2 rounded" placeholder="Đức Cha..." defaultValue={selectedStudent?.confirmationBy} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Người đỡ đầu</label>
                            <input className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationSponsor} />
                        </div>
                    </div>
                 </div>

                 {/* Bao Đồng */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">D. Tuyên Hứa (Bao Đồng)</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Tuyên Hứa</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationOathDate} />
                        </div>
                    </div>
                 </div>
               </div>

               {/* Section 4: Ghi chú */}
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                   <label className="block text-sm font-bold text-slate-700 mb-2">Ghi chú khác</label>
                   <textarea className="w-full border border-slate-300 p-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24" placeholder="Nhập các ghi chú đặc biệt về học viên..." defaultValue={selectedStudent?.note}></textarea>
               </div>

            </div>

            {/* Modal Footer */}
            <div className="p-5 border-t border-slate-200 bg-white flex justify-end gap-3 z-10">
              <button onClick={closeModal} className="px-6 py-2.5 border border-slate-300 rounded-lg text-slate-700 font-medium hover:bg-slate-50 transition-colors">Hủy Bỏ</button>
              <button onClick={closeModal} className="px-6 py-2.5 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-colors flex items-center gap-2">
                 <Check size={18} /> Lưu Hồ Sơ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Modal */}
      {studentToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
             <div className="flex items-center gap-3 text-red-600 mb-4">
               <div className="p-3 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
               <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa?</h3>
             </div>
             <p className="text-slate-600 mb-6">Bạn có chắc muốn xóa hồ sơ học viên <span className="font-bold text-slate-900">{studentToDelete.fullName}</span>? Hành động này không thể hoàn tác.</p>
             <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setStudentToDelete(null)} className="px-4 py-2 bg-slate-100 rounded-lg text-slate-700 hover:bg-slate-200 font-medium">Hủy</button>
                 <button onClick={handleDeleteStudent} className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow">Xóa Vĩnh Viễn</button>
             </div>
          </div>
        </div>
       )}

       {/* Helper for Icons that might not be imported in original file but used in new modal */}
       <div className="hidden">
         <Church /> <Check /> <AlertTriangle />
       </div>
    </div>
  );
};

// Simple Icon imports to ensure no runtime errors if lucide-react tree-shaking is weird
const Check = ({size}: {size?: number}) => <svg xmlns="http://www.w3.org/2000/svg" width={size || 24} height={size || 24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>;
const Church = ({size}: {size?: number}) => <svg xmlns="http://www.w3.org/2000/svg" width={size || 24} height={size || 24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m18 7 4 2v11a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9l4-2"/><path d="M14 22v-4a2 2 0 0 0-2-2v0a2 2 0 0 0-2 2v4"/><path d="M18 2a5 5 0 0 0-10 0v5h10Z"/><line x1="12" x2="12" y1="15" y2="15"/></svg>;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { Search, Plus, Edit, Trash2, X, Phone, MapPin, Calendar, User, Printer, ChevronDown, FileSpreadsheet, AlertTriangle, Check, Church } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [saintInput, setSaintInput] = useState('');

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Handle Grade Change
  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  // Filter Logic
  const filteredStudents = students.filter(student => {
    // Search
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    // Determine the list of valid class IDs based on current filters
    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const filteredSaints = MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setSaintInput(student.saintName);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setSaintInput('');
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setShowSaintSuggestions(false);
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      setStudentToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">-- Tất cả Khối --</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">-- Tất cả Lớp --</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      {/* Table - SIMPLIFIED COLUMNS */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b">
              <tr>
                <th className="p-4 w-12 text-center">STT</th>
                <th className="p-4">Tên Thánh & Họ Tên</th>
                <th className="p-4">Ngày Sinh & Nơi Sinh</th>
                <th className="p-4">Phụ Huynh</th>
                <th className="p-4">Liên Hệ (SĐT)</th>
                <th className="p-4">Lớp</th>
                <th className="p-4">Ghi chú</th>
                <th className="p-4 text-center w-24">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4">
                    <div className="font-bold text-slate-700">{s.saintName}</div>
                    <div className="text-base font-bold text-slate-800">{s.fullName}</div>
                    <div className="text-xs text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'} - {s.id}</div>
                  </td>
                  <td className="p-4">
                    <div className="flex items-center gap-1.5 text-slate-700"><Calendar size={14} className="text-slate-400"/> {new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                    <div className="flex items-center gap-1.5 text-slate-500 text-xs mt-1"><MapPin size={14} className="text-slate-400"/> {s.birthPlace}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div><span className="text-xs font-semibold text-slate-400">B:</span> {s.fatherName}</div>
                    <div><span className="text-xs font-semibold text-slate-400">M:</span> {s.motherName}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div>{s.fatherPhone}</div>
                    <div>{s.motherPhone}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="p-4 italic text-slate-500 max-w-xs truncate">{s.note}</td>
                  <td className="p-4 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={8} className="p-8 text-center text-slate-400 italic">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 text-right">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {/* FULL DETAIL MODAL - CONTAINS ALL REQUESTED FIELDS */}
      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col animate-fade-in">
            {/* Modal Header */}
            <div className="p-5 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-100 rounded-lg text-blue-600"><User size={24}/></div>
                 <div>
                    <h3 className="text-xl font-bold text-slate-800">
                        {selectedStudent ? 'Cập nhật Hồ Sơ' : 'Thêm Học Viên Mới'}
                    </h3>
                    <p className="text-xs text-slate-500">Vui lòng điền đầy đủ thông tin bên dưới</p>
                 </div>
              </div>
              <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 transition-colors"><X size={24} /></button>
            </div>

            {/* Modal Body - Scrollable Form */}
            <div className="p-8 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">

               {/* Section 1: Thông tin cá nhân */}
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                 <h4 className="font-bold text-blue-700 uppercase text-sm tracking-wider mb-4 border-b pb-2 flex items-center gap-2">
                    <User size={16}/> 1. Thông tin cá nhân
                 </h4>
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Mã Học Viên (Auto)</label>
                        <input className="w-full border border-slate-300 p-2 rounded bg-slate-100 text-slate-500 font-mono" disabled defaultValue={selectedStudent?.id || 'AUTO_GEN'} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Lớp Học</label>
                        <select className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.classId}>
                            <option value="">-- Chọn Lớp --</option>
                            {classesInYear.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Tên Thánh</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none font-medium" placeholder="VD: Giuse" defaultValue={selectedStudent?.saintName} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Họ và Tên</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none font-bold uppercase" placeholder="NGUYỄN VĂN A" defaultValue={selectedStudent?.fullName} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Ngày sinh</label>
                        <input type="date" className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.dob} />
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1">Nơi sinh</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" placeholder="VD: Bệnh viện Từ Dũ, TP.HCM" defaultValue={selectedStudent?.birthPlace} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 mb-1">Giới tính</label>
                        <select className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.gender}>
                            <option value="Male">Nam</option>
                            <option value="Female">Nữ</option>
                        </select>
                    </div>
                 </div>
               </div>

               {/* Section 2: Gia đình & Liên hệ */}
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                 <h4 className="font-bold text-blue-700 uppercase text-sm tracking-wider mb-4 border-b pb-2 flex items-center gap-2">
                    <Phone size={16}/> 2. Gia đình & Liên hệ
                 </h4>
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1">Họ tên Bố</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.fatherName} />
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1">SĐT Bố</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.fatherPhone} />
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1">Họ tên Mẹ</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.motherName} />
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1">SĐT Mẹ</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.motherPhone} />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1">Thuộc Giáo Họ</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.parish} />
                    </div>
                    <div className="md:col-span-3">
                        <label className="block text-xs font-bold text-slate-500 mb-1">Địa chỉ thường trú</label>
                        <input className="w-full border border-slate-300 p-2 rounded focus:ring-2 focus:ring-blue-500 outline-none" defaultValue={selectedStudent?.address} />
                    </div>
                 </div>
               </div>

               {/* Section 3: Hồ sơ Bí Tích */}
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                 <h4 className="font-bold text-blue-700 uppercase text-sm tracking-wider mb-4 border-b pb-2 flex items-center gap-2">
                    <Church size={16}/> 3. Hồ sơ Bí tích
                 </h4>

                 {/* Rửa tội */}
                 <div className="mb-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">A. Bí tích Rửa Tội</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Rửa Tội</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.baptismDate} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Linh mục Rửa Tội (Do)</label>
                            <input className="w-full border border-slate-300 p-2 rounded" placeholder="Cha..." defaultValue={selectedStudent?.baptismBy} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Người đỡ đầu</label>
                            <input className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.baptismSponsor} />
                        </div>
                    </div>
                 </div>

                 {/* Rước lễ */}
                 <div className="mb-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">B. Bí tích Thánh Thể (Rước lễ lần đầu)</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Rước Lễ</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.eucharistDate} />
                        </div>
                        <div className="md:col-span-2">
                            <label className="block text-xs font-bold text-slate-500 mb-1">Linh mục ban BT (Do)</label>
                            <input className="w-full border border-slate-300 p-2 rounded" placeholder="Cha..." defaultValue={selectedStudent?.eucharistBy} />
                        </div>
                    </div>
                 </div>

                 {/* Thêm Sức */}
                 <div className="mb-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">C. Bí tích Thêm Sức</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Thêm Sức</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationDate} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">ĐGM/Linh mục ban (Do)</label>
                            <input className="w-full border border-slate-300 p-2 rounded" placeholder="Đức Cha..." defaultValue={selectedStudent?.confirmationBy} />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Người đỡ đầu</label>
                            <input className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationSponsor} />
                        </div>
                    </div>
                 </div>

                 {/* Bao Đồng */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                    <h5 className="font-bold text-slate-700 text-xs mb-3 uppercase">D. Tuyên Hứa (Bao Đồng)</h5>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 mb-1">Ngày Tuyên Hứa</label>
                            <input type="date" className="w-full border border-slate-300 p-2 rounded" defaultValue={selectedStudent?.confirmationOathDate} />
                        </div>
                    </div>
                 </div>
               </div>

               {/* Section 4: Ghi chú */}
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                   <label className="block text-sm font-bold text-slate-700 mb-2">Ghi chú khác</label>
                   <textarea className="w-full border border-slate-300 p-3 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24" placeholder="Nhập các ghi chú đặc biệt về học viên..." defaultValue={selectedStudent?.note}></textarea>
               </div>

            </div>

            {/* Modal Footer */}
            <div className="p-5 border-t border-slate-200 bg-white flex justify-end gap-3 z-10">
              <button onClick={closeModal} className="px-6 py-2.5 border border-slate-300 rounded-lg text-slate-700 font-medium hover:bg-slate-50 transition-colors">Hủy Bỏ</button>
              <button onClick={closeModal} className="px-6 py-2.5 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-colors flex items-center gap-2">
                 <Check size={18} /> Lưu Hồ Sơ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Modal */}
      {studentToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
             <div className="flex items-center gap-3 text-red-600 mb-4">
               <div className="p-3 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
               <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa?</h3>
             </div>
             <p className="text-slate-600 mb-6">Bạn có chắc muốn xóa hồ sơ học viên <span className="font-bold text-slate-900">{studentToDelete.fullName}</span>? Hành động này không thể hoàn tác.</p>
             <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setStudentToDelete(null)} className="px-4 py-2 bg-slate-100 rounded-lg text-slate-700 hover:bg-slate-200 font-medium">Hủy</button>
                 <button onClick={handleDeleteStudent} className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow">Xóa Vĩnh Viễn</button>
             </div>
          </div>
        </div>
       )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { Search, Plus, Edit, Trash2, X, Phone, MapPin, Calendar, User, Printer, FileSpreadsheet, AlertTriangle, Check, Church, Save } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'INFO' | 'SACRAMENTS'>('INFO');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Handle Grade Change
  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  // Filter Logic
  const filteredStudents = students.filter(student => {
    // Search
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    // Determine the list of valid class IDs based on current filters
    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setActiveTab('INFO');
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setActiveTab('INFO');
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      setStudentToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">-- Tất cả Khối --</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">-- Tất cả Lớp --</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b">
              <tr>
                <th className="p-4 w-12 text-center">STT</th>
                <th className="p-4">Tên Thánh & Họ Tên</th>
                <th className="p-4">Ngày Sinh</th>
                <th className="p-4">Phụ Huynh</th>
                <th className="p-4">Liên Hệ (SĐT)</th>
                <th className="p-4">Lớp</th>
                <th className="p-4">Ghi chú</th>
                <th className="p-4 text-center w-24">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4">
                    <div className="font-bold text-slate-700">{s.saintName}</div>
                    <div className="text-base font-bold text-slate-800">{s.fullName}</div>
                    <div className="text-xs text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'} - {s.id}</div>
                  </td>
                  <td className="p-4">
                    <div className="flex items-center gap-1.5 text-slate-700"><Calendar size={14} className="text-slate-400"/> {new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div><span className="text-xs font-semibold text-slate-400">B:</span> {s.fatherName}</div>
                    <div><span className="text-xs font-semibold text-slate-400">M:</span> {s.motherName}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div>{s.fatherPhone}</div>
                    <div>{s.motherPhone}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="p-4 italic text-slate-500 max-w-xs truncate">{s.note}</td>
                  <td className="p-4 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={8} className="p-8 text-center text-slate-400 italic">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 text-right">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {/* NEW REDESIGNED MODAL WITH TABS */}
      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col animate-fade-in">
            {/* Header */}
            <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-xl shadow-md">
                      {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus />}
                   </div>
                   <div>
                       <h3 className="text-lg font-bold text-slate-800">{selectedStudent ? `${selectedStudent.saintName} ${selectedStudent.fullName}` : 'Thêm Học Viên Mới'}</h3>
                       <p className="text-xs text-slate-500 font-mono">{selectedStudent?.id || 'New Student'}</p>
                   </div>
                </div>
                <button onClick={closeModal} className="text-slate-400 hover:text-red-500 transition-colors"><X size={24} /></button>
            </div>

            {/* Tabs */}
            <div className="flex border-b border-slate-200 px-6 bg-white">
                <button 
                  onClick={() => setActiveTab('INFO')}
                  className={`py-3 px-4 text-sm font-bold border-b-2 transition-all ${activeTab === 'INFO' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                >
                    Thông Tin & Gia Đình
                </button>
                <button 
                  onClick={() => setActiveTab('SACRAMENTS')}
                  className={`py-3 px-4 text-sm font-bold border-b-2 transition-all ${activeTab === 'SACRAMENTS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                >
                    Hồ Sơ Bí Tích
                </button>
            </div>

            {/* Body */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50/50">
               {activeTab === 'INFO' ? (
                   <div className="space-y-6">
                       {/* Personal Info Block */}
                       <div className="bg-white p-5 rounded-lg border border-slate-200 shadow-sm">
                           <h4 className="text-xs font-bold text-slate-400 uppercase mb-4 border-b pb-2">Thông tin cá nhân</h4>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                               <div className="grid grid-cols-3 gap-2 col-span-2">
                                   <div className="col-span-1">
                                       <label className="label-text">Tên Thánh</label>
                                       <input className="input-field" defaultValue={selectedStudent?.saintName} placeholder="VD: Giuse" />
                                   </div>
                                   <div className="col-span-2">
                                       <label className="label-text">Họ và Tên</label>
                                       <input className="input-field uppercase font-bold" defaultValue={selectedStudent?.fullName} placeholder="NGUYỄN VĂN A" />
                                   </div>
                               </div>
                               <div>
                                   <label className="label-text">Ngày sinh</label>
                                   <input type="date" className="input-field" defaultValue={selectedStudent?.dob} />
                               </div>
                               <div>
                                   <label className="label-text">Giới tính</label>
                                   <select className="input-field" defaultValue={selectedStudent?.gender}>
                                       <option value="Male">Nam</option>
                                       <option value="Female">Nữ</option>
                                   </select>
                               </div>
                               <div className="col-span-2">
                                   <label className="label-text">Nơi sinh</label>
                                   <input className="input-field" defaultValue={selectedStudent?.birthPlace} placeholder="Nơi sinh..." />
                               </div>
                               <div>
                                   <label className="label-text">Lớp Giáo Lý</label>
                                   <select className="input-field" defaultValue={selectedStudent?.classId}>
                                       <option value="">-- Chọn Lớp --</option>
                                       {classesInYear.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                   </select>
                               </div>
                           </div>
                       </div>

                       {/* Family Info Block */}
                       <div className="bg-white p-5 rounded-lg border border-slate-200 shadow-sm">
                           <h4 className="text-xs font-bold text-slate-400 uppercase mb-4 border-b pb-2">Gia đình & Liên hệ</h4>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                               {/* Father */}
                               <div className="space-y-2">
                                   <label className="label-text text-blue-600">Thông tin Bố</label>
                                   <input className="input-field" defaultValue={selectedStudent?.fatherName} placeholder="Họ tên Bố" />
                                   <input className="input-field" defaultValue={selectedStudent?.fatherPhone} placeholder="Số điện thoại Bố" />
                               </div>
                               {/* Mother */}
                               <div className="space-y-2">
                                   <label className="label-text text-pink-600">Thông tin Mẹ</label>
                                   <input className="input-field" defaultValue={selectedStudent?.motherName} placeholder="Họ tên Mẹ" />
                                   <input className="input-field" defaultValue={selectedStudent?.motherPhone} placeholder="Số điện thoại Mẹ" />
                               </div>
                               {/* Address */}
                               <div className="col-span-2 pt-2">
                                   <label className="label-text">Giáo Họ</label>
                                   <input className="input-field mb-2" defaultValue={selectedStudent?.parish} placeholder="Tên Giáo họ" />
                                   <label className="label-text">Địa chỉ thường trú</label>
                                   <input className="input-field" defaultValue={selectedStudent?.address} placeholder="Số nhà, đường, phường/xã..." />
                               </div>
                           </div>
                       </div>
                   </div>
               ) : (
                   <div className="space-y-6">
                       <div className="grid grid-cols-1 gap-4">
                           {/* Baptism */}
                           <div className="bg-white p-5 rounded-lg border-l-4 border-blue-500 shadow-sm">
                               <h4 className="font-bold text-blue-700 mb-4 flex items-center gap-2"><Church size={18}/> Bí Tích Rửa Tội</h4>
                               <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                   <div>
                                       <label className="label-text">Ngày Rửa Tội</label>
                                       <input type="date" className="input-field" defaultValue={selectedStudent?.baptismDate} />
                                   </div>
                                   <div className="md:col-span-2">
                                       <label className="label-text">Linh mục rửa tội (Do)</label>
                                       <input className="input-field" defaultValue={selectedStudent?.baptismBy} placeholder="Cha..." />
                                   </div>
                                   <div className="md:col-span-3">
                                       <label className="label-text">Người đỡ đầu</label>
                                       <input className="input-field" defaultValue={selectedStudent?.baptismSponsor} />
                                   </div>
                               </div>
                           </div>

                           {/* Eucharist */}
                           <div className="bg-white p-5 rounded-lg border-l-4 border-green-500 shadow-sm">
                               <h4 className="font-bold text-green-700 mb-4 flex items-center gap-2"><Church size={18}/> Rước Lễ Lần Đầu</h4>
                               <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                   <div>
                                       <label className="label-text">Ngày Rước Lễ</label>
                                       <input type="date" className="input-field" defaultValue={selectedStudent?.eucharistDate} />
                                   </div>
                                   <div className="md:col-span-2">
                                       <label className="label-text">Linh mục ban (Do)</label>
                                       <input className="input-field" defaultValue={selectedStudent?.eucharistBy} placeholder="Cha..." />
                                   </div>
                               </div>
                           </div>

                           {/* Confirmation */}
                           <div className="bg-white p-5 rounded-lg border-l-4 border-red-500 shadow-sm">
                               <h4 className="font-bold text-red-700 mb-4 flex items-center gap-2"><Church size={18}/> Bí Tích Thêm Sức</h4>
                               <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                   <div>
                                       <label className="label-text">Ngày Thêm Sức</label>
                                       <input type="date" className="input-field" defaultValue={selectedStudent?.confirmationDate} />
                                   </div>
                                   <div className="md:col-span-2">
                                       <label className="label-text">ĐGM/Linh mục ban (Do)</label>
                                       <input className="input-field" defaultValue={selectedStudent?.confirmationBy} placeholder="Đức Cha..." />
                                   </div>
                                   <div className="md:col-span-3">
                                       <label className="label-text">Người đỡ đầu</label>
                                       <input className="input-field" defaultValue={selectedStudent?.confirmationSponsor} />
                                   </div>
                               </div>
                           </div>

                           {/* Oath */}
                           <div className="bg-white p-5 rounded-lg border-l-4 border-purple-500 shadow-sm">
                               <h4 className="font-bold text-purple-700 mb-4 flex items-center gap-2"><Church size={18}/> Tuyên Hứa (Bao Đồng)</h4>
                               <div>
                                   <label className="label-text">Ngày Tuyên Hứa</label>
                                   <input type="date" className="input-field w-full md:w-1/3" defaultValue={selectedStudent?.confirmationOathDate} />
                               </div>
                           </div>
                       </div>

                       <div className="bg-white p-5 rounded-lg border border-slate-200 shadow-sm">
                           <label className="label-text font-bold mb-2 block">Ghi chú khác</label>
                           <textarea className="input-field h-20" defaultValue={selectedStudent?.note} placeholder="Nhập ghi chú..."></textarea>
                       </div>
                   </div>
               )}
            </div>

            {/* Footer */}
            <div className="px-6 py-4 bg-white border-t border-slate-200 flex justify-end gap-3">
                <button onClick={closeModal} className="px-5 py-2 rounded-lg border border-slate-300 text-slate-600 font-medium hover:bg-slate-50 transition-colors">Đóng</button>
                <button onClick={closeModal} className="px-5 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 flex items-center gap-2">
                    <Save size={18} /> Lưu Hồ Sơ
                </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Modal */}
      {studentToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
             <div className="flex items-center gap-3 text-red-600 mb-4">
               <div className="p-3 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
               <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa?</h3>
             </div>
             <p className="text-slate-600 mb-6">Bạn có chắc muốn xóa hồ sơ học viên <span className="font-bold text-slate-900">{studentToDelete.fullName}</span>? Hành động này không thể hoàn tác.</p>
             <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setStudentToDelete(null)} className="px-4 py-2 bg-slate-100 rounded-lg text-slate-700 hover:bg-slate-200 font-medium">Hủy</button>
                 <button onClick={handleDeleteStudent} className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow">Xóa Vĩnh Viễn</button>
             </div>
          </div>
        </div>
       )}

      <style>{`
        .label-text { display: block; font-size: 0.75rem; font-weight: 700; color: #64748b; margin-bottom: 0.25rem; text-transform: uppercase; }
        .input-field { width: 100%; padding: 0.5rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.5rem; outline: none; transition: all 0.2s; font-size: 0.875rem; }
        .input-field:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, FileSpreadsheet, Trophy, ListChecks, ArrowLeft, ArrowRight } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords }) => {
  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');

  const [term, setTerm] = useState<'HK1' | 'HK2' | 'YEAR'>('HK1');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');

  // Dynamic columns state - Added Coefficient 3 by default
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 },
    { id: 'col_hso3', name: "Hệ số 3", weight: 3 }
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  // 1. Get Classes that belong to the Selected Year
  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  // 2. Get Classes that belong to the Selected Grade (within the year)
  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Auto-select first class if available when grade changes
  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, field: string, value: string) => {
    if (term === 'YEAR') return; // Cannot edit in YEAR mode

    const numValue = parseFloat(value) || 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];

        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };

            if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            }

            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             // Create new record
             updatedRecord = {
                 studentId,
                 term: term as 'HK1'|'HK2',
                 scores: {},
                 scorePray: 0,
                 scoreExam: 0,
                 average: 0
             };
             if (field === 'pray') updatedRecord.scorePray = numValue;
            else if (field === 'exam') updatedRecord.scoreExam = numValue;
            else {
                updatedRecord.scores = { [field]: numValue };
            }
            return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      testColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { // Count 0 if explicitly set
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });

      if (record.scorePray !== undefined) { totalScore += record.scorePray * 1; totalWeight += 1; }
      if (record.scoreExam !== undefined) { totalScore += record.scoreExam * 2; totalWeight += 2; }

      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     if (term === 'YEAR') return;

     // Recalculate averages for all visible students in current term
     const updatedRecords = records.map(r => {
         if (r.term === term && filteredStudents.some(s => s.id === r.studentId)) {
             return { ...r, average: calculateAvg(r) };
         }
         return r;
     });

     setRecords(updatedRecords);
     alert("Đã lưu bảng điểm và tính điểm trung bình!");
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
  };

  const moveColumn = (index: number, direction: 'left' | 'right') => {
    if (direction === 'left' && index > 0) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index - 1];
      newCols[index - 1] = temp;
      setTestColumns(newCols);
    } else if (direction === 'right' && index < testColumns.length - 1) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index + 1];
      newCols[index + 1] = temp;
      setTestColumns(newCols);
    }
  };

  const handleExportExcel = () => {
     // ... (Keep existing logic, omitted for brevity)
     alert("Tính năng xuất Excel đang cập nhật...");
  };


  // Logic for Summary/Year View
  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    // Calculate final average: (HK1 + HK2) / 2
    const finalAvg = (r1.average > 0 && r2.average > 0) ? (r1.average + r2.average) / 2 : 0;

    return {
      ...s,
      avg1: r1.average,
      avg2: r2.average,
      avgYear: finalAvg,
      rank: getRank(finalAvg),
      isPassed: finalAvg >= 5.0
    };
  }).sort((a, b) => b.avgYear - a.avgYear) // Sort for ranking
    .map((s, index) => ({...s, ranking: index + 1})); // Add ranking

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>

        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button 
             onClick={() => setViewMode('entry')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <Table size={16}/> Sổ Điểm
           </button>
           <button 
             onClick={() => setViewMode('summary')}
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}
           >
             <ListChecks size={16}/> Thống Kê
           </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">

          <div className="flex flex-col">
              <label className="text-xs font-bold text-slate-500 uppercase mb-1">Năm học</label>
              <select 
                className="px-3 py-2 border rounded-lg min-w-[140px]"
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
              >
                {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
              </select>
          </div>

          <div className="flex flex-col">
              <label className="text-xs font-bold text-slate-500 uppercase mb-1">Khối</label>
              <select 
                className="px-3 py-2 border rounded-lg min-w-[140px]"
                value={selectedGrade}
                onChange={(e) => setSelectedGrade(e.target.value)}
              >
                <option value="all">-- Tất cả --</option>
                {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
              </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Chọn lớp</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[160px]"
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
            >
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              {availableClasses.length === 0 && <option value="">Không có lớp</option>}
            </select>
          </div>

          <div className="flex flex-col">
            <label className="text-xs font-bold text-slate-500 uppercase mb-1">Học Kỳ</label>
            <select 
              className="px-3 py-2 border rounded-lg min-w-[140px]"
              value={term}
              onChange={(e) => setTerm(e.target.value as any)}
            >
              <option value="HK1">Học Kỳ 1</option>
              <option value="HK2">Học Kỳ 2</option>
              <option value="YEAR">Cả Năm</option>
            </select>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2">
            {term !== 'YEAR' && viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in">
                    <input 
                    type="text" 
                    placeholder="Tên cột" 
                    className="px-2 py-1 border rounded text-sm w-32"
                    value={newColName}
                    onChange={(e) => setNewColName(e.target.value)}
                    />
                    <select 
                    className="px-2 py-1 border rounded text-sm"
                    value={newColWeight}
                    onChange={(e) => setNewColWeight(Number(e.target.value))}
                    >
                    <option value={1}>x1</option>
                    <option value={2}>x2</option>
                    <option value={3}>x3</option>
                    </select>
                    <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button>
                    <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button>
                </div>
                ) : (
                <button 
                    onClick={() => setShowAddColumn(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"
                >
                    <Plus size={16} /> Thêm Cột
                </button>
                )}
                </>
            )}

             <button 
                onClick={handleExportExcel}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50"
             >
                 <FileSpreadsheet size={16}/> Xuất Excel
             </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
          // ENTRY VIEW
          <>
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                    <th className="p-4 w-16 text-center sticky left-0 bg-slate-50 z-10">STT</th>
                    <th className="p-4 min-w-[200px] sticky left-16 bg-slate-50 z-10">Học Viên</th>

                    {term === 'YEAR' ? (
                        <>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK1</th>
                            <th className="p-4 text-center border-l bg-slate-50">ĐTB HK2</th>
                            <th className="p-4 text-center border-l bg-blue-100 font-bold text-blue-800">ĐTB Cả Năm</th>
                            <th className="p-4 text-center border-l">Xếp loại</th>
                            <th className="p-4 text-center border-l">Hạng</th>
                        </>
                    ) : (
                        <>
                            {testColumns.map((col, idx) => (
                            <th key={col.id} className="p-4 w-32 text-center border-l bg-slate-50 group relative">
                                <div className="flex flex-col items-center">
                                <span>{col.name}</span>
                                <span className="text-[10px] text-slate-400 font-normal">Hệ số {col.weight}</span>
                                </div>

                                {/* Controls */}
                                <div className="absolute inset-x-0 bottom-0 flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pb-1">
                                   {idx > 0 && <button onClick={() => moveColumn(idx, 'left')} className="p-1 hover:bg-slate-200 rounded"><ArrowLeft size={10}/></button>}
                                   {idx < testColumns.length - 1 && <button onClick={() => moveColumn(idx, 'right')} className="p-1 hover:bg-slate-200 rounded"><ArrowRight size={10}/></button>}
                                </div>

                                <button 
                                onClick={() => removeColumn(col.id)}
                                className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
                                title="Xóa cột"
                                >
                                <Trash2 size={12} />
                                </button>
                            </th>
                            ))}

                            <th className="p-4 w-24 text-center border-l bg-slate-50">Kinh (x1)</th>
                            <th className="p-4 w-24 text-center border-l bg-slate-50">Thi (x2)</th>
                            <th className="p-4 w-24 text-center border-l bg-blue-50 font-bold text-blue-700">TB</th>
                            <th className="p-4 w-32 text-center border-l">Xếp loại</th>
                        </>
                    )}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                   {filteredStudents.length > 0 ? (
                      term === 'YEAR' 
                    ? processedStudentsYear.map((s, idx) => (
                         <tr key={s.id} className="hover:bg-slate-50 group">
                            <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td>
                            <td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>
                            <td className="p-4 text-center border-l text-slate-500">{s.avg1 || '-'}</td>
                            <td className="p-4 text-center border-l text-slate-500">{s.avg2 || '-'}</td>
                            <td className="p-4 text-center border-l font-bold text-blue-700 bg-blue-50/30">{s.avgYear.toFixed(1)}</td>
                            <td className="p-4 text-center border-l">
                                <span className={`px-2 py-1 rounded text-xs font-bold ${s.rank.color}`}>{s.rank.label}</span>
                            </td>
                            <td className="p-4 text-center border-l font-mono font-bold text-slate-600">
                                {s.ranking <= 3 ? <span className="flex items-center justify-center gap-1 text-yellow-600"><Trophy size={14}/> {s.ranking}</span> : s.ranking}
                            </td>
                         </tr>
                    ))
                    : filteredStudents.map((s, idx) => {
                    const r = getRecord(s.id, term as 'HK1' | 'HK2');
                    const rank = getRank(r.average);

                    return (
                      <tr key={s.id} className="hover:bg-slate-50 group">
                        <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td>
                        <td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>

                        {testColumns.map(col => (
                          <td key={col.id} className="p-2 border-l text-center">
                            <input 
                                type="number" 
                                value={r.scores ? r.scores[col.id] || '' : ''}
                                onChange={(e) => handleScoreChange(s.id, col.id, e.target.value)}
                                className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" 
                            />
                          </td>
                        ))}

                        <td className="p-2 border-l text-center">
                          <input 
                            type="number" 
                            value={r.scorePray || ''} 
                            onChange={(e) => handleScoreChange(s.id, 'pray', e.target.value)}
                            className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                        </td>
                        <td className="p-2 border-l text-center">
                          <input 
                            type="number" 
                            value={r.scoreExam || ''} 
                            onChange={(e) => handleScoreChange(s.id, 'exam', e.target.value)}
                            className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" />
                        </td>
                        <td className="p-4 border-l text-center font-bold text-slate-800 bg-blue-50/20">
                          {r.average > 0 ? r.average : '-'}
                        </td>
                        <td className="p-4 border-l text-center">
                          {r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rank.color}`}>{rank.label}</span>}
                        </td>
                      </tr>
                    );
                  })
                   ) : (
                       <tr><td colSpan={10} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                   )}
                </tbody>
              </table>
            </div>
            {term !== 'YEAR' && filteredStudents.length > 0 && (
                <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
                <button 
                    onClick={handleSaveGrades}
                    className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium"
                >
                    <Save size={18} /> Lưu Bảng Điểm
                </button>
                </div>
            )}
          </>
        ) : (
          // SUMMARY VIEW
          <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
             {/* Header Info */}
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-500 flex items-center gap-2">
                      <UserCheck size={18} />
                      GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.teacher || 'Chưa cập nhật'}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-slate-500">Sĩ số</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Passed List */}
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                   <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                      <div className="flex items-center gap-2">
                        <CheckCircle2 className="text-green-600" />
                        <h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4>
                      </div>
                      <span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">
                        {passedStudents.length} em
                      </span>
                   </div>
                   <div className="overflow-x-auto">
                     <table className="w-full text-sm">
                       <thead className="bg-slate-50 text-slate-500">
                         <tr>
                           <th className="p-3 text-left">Học Viên</th>
                           <th className="p-3 text-center">ĐTB Cả Năm</th>
                           <th className="p-3 text-center">Xếp loại</th>
                         </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                         {passedStudents.map(s => (
                           <tr key={s.id} className="hover:bg-green-50/30">
                             <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                             <td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td>
                             <td className="p-3 text-center">
                               <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span>
                             </td>
                           </tr>
                         ))}
                         {passedStudents.length === 0 && (
                           <tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>
                         )}
                       </tbody>
                     </table>
                   </div>
                </div>

