    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId) return alert("Vui lòng chọn đầy đủ lớp nguồn và lớp đích");
    if (sourceClassId === targetClassId) return alert("Lớp nguồn và đích phải khác nhau");
    if (selectedStudentIds.length === 0) return alert("Vui lòng chọn ít nhất 1 học viên");

