                                  <input className="input-field" defaultValue={selectedStudent?.motherName} />
                               </div>
                               <div className="col-span-2 md:col-span-1">
                                  <label className="label-text">Số điện thoại</label>
                                  <input className="input-field" defaultValue={selectedStudent?.motherPhone} />
                               </div>
