                         <div>
                            <label className="label-text">Địa chỉ thường trú</label>
                            <input className="input-field" defaultValue={selectedStudent?.address} placeholder="Số nhà, đường..." />
                         </div>
                         <div>
                            <label className="label-text">Thuộc Giáo Họ</label>
                            <input className="input-field" defaultValue={selectedStudent?.parish} placeholder="Tên giáo họ..." />
                         </div>
                     </div>
                 )}

                 {activeSection === 'SACRAMENTS' && (
                    <div className="space-y-8">
                       {/* Baptism */}
                       <div className="relative pl-6 border-l-2 border-slate-200">
                          <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-blue-500 ring-4 ring-white"></div>
                          <h4 className="font-bold text-lg text-slate-800 mb-4">Rửa Tội</h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div><label className="label-text">Ngày nhận</label><input type="date" className="input-field" defaultValue={selectedStudent?.baptismDate} /></div>
                             <div><label className="label-text">Tại (Nhà thờ/Gx)</label><input className="input-field" defaultValue={selectedStudent?.baptismPlace} placeholder="Nơi rửa tội..." /></div>
                             <div><label className="label-text">Do (Linh mục)</label><input className="input-field" defaultValue={selectedStudent?.baptismBy} placeholder="Cha..." /></div>
                             <div><label className="label-text">Người đỡ đầu</label><input className="input-field" defaultValue={selectedStudent?.baptismSponsor} /></div>
                          </div>
                       </div>

                       {/* Eucharist */}
                       <div className="relative pl-6 border-l-2 border-slate-200">
                          <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-green-500 ring-4 ring-white"></div>
                          <h4 className="font-bold text-lg text-slate-800 mb-4">Rước Lễ Lần Đầu</h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div><label className="label-text">Ngày nhận</label><input type="date" className="input-field" defaultValue={selectedStudent?.eucharistDate} /></div>
                             <div><label className="label-text">Tại (Nhà thờ/Gx)</label><input className="input-field" defaultValue={selectedStudent?.eucharistPlace} placeholder="Nơi rước lễ..." /></div>
                             <div className="col-span-2"><label className="label-text">Do (Linh mục)</label><input className="input-field" defaultValue={selectedStudent?.eucharistBy} placeholder="Cha..." /></div>
                          </div>
                       </div>

                       {/* Confirmation */}
                       <div className="relative pl-6 border-l-2 border-slate-200">
                          <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-red-500 ring-4 ring-white"></div>
                          <h4 className="font-bold text-lg text-slate-800 mb-4">Thêm Sức</h4>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div><label className="label-text">Ngày nhận</label><input type="date" className="input-field" defaultValue={selectedStudent?.confirmationDate} /></div>
                             <div><label className="label-text">Tại (Nhà thờ/Gx)</label><input className="input-field" defaultValue={selectedStudent?.confirmationPlace} placeholder="Nơi thêm sức..." /></div>
                             <div><label className="label-text">Do (ĐGM/Linh mục)</label><input className="input-field" defaultValue={selectedStudent?.confirmationBy} placeholder="Đức Cha..." /></div>
