                        {/* Oath & Note */}
                        <div className="bg-white p-5 rounded-xl border-l-4 border-l-purple-500 shadow-sm border border-slate-200">
                             <h4 className="font-bold text-purple-700 mb-3 uppercase text-sm">Bao Đồng & Ghi Chú</h4>
