                                 </div>
                             </div>
                        </div>
                    </div>

                </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete Modal */}
      {studentToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
             <div className="flex items-center gap-3 text-red-600 mb-4">
               <div className="p-3 bg-red-100 rounded-full"><AlertTriangle size={24} /></div>
               <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa?</h3>
             </div>
             <p className="text-slate-600 mb-6">Bạn có chắc muốn xóa hồ sơ học viên <span className="font-bold text-slate-900">{studentToDelete.fullName}</span>? Hành động này không thể hoàn tác.</p>
             <div className="flex justify-end gap-3 mt-4">
                 <button onClick={() => setStudentToDelete(null)} className="px-4 py-2 bg-slate-100 rounded-lg text-slate-700 hover:bg-slate-200 font-medium">Hủy</button>
                 <button onClick={handleDeleteStudent} className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-bold shadow">Xóa Vĩnh Viễn</button>
             </div>
