};

export interface Student {
  id: string; // Mã học viên (Số tự động)
  saintName: string; // Tên Thánh
  fullName: string; // Họ tên
  dob: string; // Ngày tháng năm sinh
  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
  baptismBy?: string; // Do (Linh mục rửa tội)
  baptismSponsor?: string; // Người đỡ đầu Rửa tội
  baptismPlace?: string; // Tại (Nơi rửa tội)

  eucharistDate?: string; // Ngày rước lễ
  eucharistBy?: string; // Do (Linh mục cho rước lễ)
  eucharistPlace?: string; // Tại (Nơi rước lễ)

  confirmationDate?: string; // Ngày thêm sức
  confirmationBy?: string; // Do (ĐGM/Cha ban thêm sức)
  confirmationSponsor?: string; // Người đỡ đầu Thêm sức
  confirmationPlace?: string; // Tại (Nơi thêm sức)

  confirmationOathDate?: string; // Ngày tuyên hứa (Bao đồng)

  note?: string; // Ghi chú
}

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
  educationLevel: string; // Học vấn Giáo Lý (VD: Cấp 1, 2, 3...)
  role: 'ADMIN' | 'GLV'; // Phân quyền
}

export interface Saint {
  id: string;
  name: string;
  gender: 'Male' | 'Female' | 'Both';
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  // Dynamic scores stored as key-value pairs
  scores: { [key: string]: number }; 
  scorePray: number; // Điểm kinh (keep separate as it's standard)
  scoreExam: number; // Thi (keep separate)
  // Computed
  average: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
  class: boolean; // Học giáo lý
  classExcused: boolean;
}

export interface ClassRoom {
  id: string;
  name: string; // e.g., Chiên Con 1
  gradeId: string; // Linked to Grade
  yearId: string; // Linked to School Year
  mainTeacher?: string; // GLV Chủ nhiệm
  assistants?: string; // GLV Phụ trách/Phụ tá
  room?: string; // Phòng học
}

export interface Grade {
  id: string;
  name: string; // e.g., Khối Khai Tâm
}

export interface SchoolYear {
  id: string;
  name: string;
  isActive: boolean;
}

export interface Transaction {
  id: string;
  date: string;
  type: 'INCOME' | 'EXPENSE';
  amount: number;
  description: string;
  note?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  type: 'NOTICE' | 'MEETING_MINUTES';
}

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_ANNOUNCEMENTS, MOCK_YEARS } from '../constants';
import { Users, User, UserCheck, Bell, FileText } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

export const Dashboard: React.FC = () => {
  const [selectedYear, setSelectedYear] = useState('');

  // Default to active year
  useEffect(() => {
    const active = MOCK_YEARS.find(y => y.isActive);
    if (active) setSelectedYear(active.id);
  }, []);

  // Filter classes by selected year
  const classesInYear = useMemo(() => {
    return MOCK_CLASSES.filter(c => c.yearId === selectedYear);
  }, [selectedYear]);

  // Filter students belonging to those classes
  const studentsInYear = useMemo(() => {
    const classIds = classesInYear.map(c => c.id);
    return MOCK_STUDENTS.filter(s => classIds.includes(s.classId));
  }, [classesInYear]);

  const totalStudents = studentsInYear.length;
  const maleCount = studentsInYear.filter(s => s.gender === 'Male').length;
  const femaleCount = studentsInYear.filter(s => s.gender === 'Female').length;

  const studentsByClassData = classesInYear.map(c => ({
    name: c.name,
    count: MOCK_STUDENTS.filter(s => s.classId === c.id).length
  }));

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
         <h2 className="text-2xl font-bold text-slate-800">Tổng Quan</h2>
         <select 
            className="px-4 py-2 border rounded-lg bg-white shadow-sm text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {MOCK_YEARS.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <div className="p-3 bg-blue-100 rounded-full text-blue-600">
            <Users size={32} />
          </div>
          <div>
            <p className="text-slate-500 text-sm">Tổng học viên</p>
            <p className="text-2xl font-bold text-slate-800">{totalStudents}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <div className="p-3 bg-indigo-100 rounded-full text-indigo-600">
            <User size={32} />
          </div>
          <div>
            <p className="text-slate-500 text-sm">Nam</p>
            <p className="text-2xl font-bold text-slate-800">{maleCount}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center gap-4">
          <div className="p-3 bg-pink-100 rounded-full text-pink-600">
            <UserCheck size={32} />
          </div>
          <div>
            <p className="text-slate-500 text-sm">Nữ</p>
            <p className="text-2xl font-bold text-slate-800">{femaleCount}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="font-semibold text-lg mb-4 text-slate-800">Phân Bố Học Viên Theo Lớp</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={studentsByClassData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{fontSize: 12}} />
                <YAxis allowDecimals={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                  cursor={{fill: 'transparent'}}
                />
                <Bar dataKey="count" name="Số lượng" radius={[4, 4, 0, 0]}>
                  {studentsByClassData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Notices */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col">
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold text-lg text-slate-800">Bảng Thông Báo</h3>
            <button className="text-xs text-blue-600 hover:underline">Xem tất cả</button>
          </div>
          <div className="flex-1 overflow-y-auto space-y-3 custom-scrollbar max-h-64">
            {MOCK_ANNOUNCEMENTS.map((item) => (
