                             {classes.find(c => c.id === searchedStudent.classId)?.name || 'Chưa xếp lớp'}
                             <span className="block text-xs text-slate-400 font-normal">{years.find(y => y.id === classes.find(c => c.id === searchedStudent.classId)?.yearId)?.name}</span>
