  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'classes':
        return <Classes 
          classes={classes}
          students={students}
          years={years}
        />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
        />;
      case 'placement':
        return <ClassPlacement 
          students={students}
          setStudents={setStudents}
          classes={classes}
          years={years}
        />;
      case 'teachers':
        return <Teachers />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

