import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { ClassPlacement } from './components/ClassPlacement';
import { Classes } from './components/Classes';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // GLOBAL STATE
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'classes':
        return <Classes 
          classes={classes}
          setClasses={setClasses}
          students={students}
          years={years}
        />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
        />;
      case 'placement':
        return <ClassPlacement 
          students={students}
          setStudents={setStudents}
          classes={classes}
          years={years}
        />;
      case 'teachers':
        return <Teachers />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_GRADES } from '../constants';
import { ClassRoom, SchoolYear, Student } from '../types';
import { Users, User, UserCheck, Edit, X, Save } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');

  // Edit State
  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const filteredClasses = useMemo(() => {
      return classes.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [classes, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        const updatedClasses = classes.map(c => c.id === editingClass.id ? editingClass : c);
        setClasses(updatedClasses);
        setEditingClass(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2 border rounded-lg bg-white font-medium min-w-[150px]"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2 border rounded-lg bg-white min-w-[150px]"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                         <th className="p-4 w-12 text-center">STT</th>
                         <th className="p-4">Tên Lớp</th>
                         <th className="p-4">Khối</th>
                         <th className="p-4 text-center">Sĩ số</th>
                         <th className="p-4 text-center">Nam</th>
                         <th className="p-4 text-center">Nữ</th>
                         <th className="p-4 text-center">Phòng Học</th>
                         <th className="p-4">GLV Chủ Nhiệm</th>
                         <th className="p-4">GLV Phụ Trách</th>
                         <th className="p-4 w-16 text-center"></th>
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = MOCK_GRADES.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50">
                                     <td className="p-4 text-center text-slate-500">{index + 1}</td>
                                     <td className="p-4 font-bold text-slate-800">{c.name}</td>
                                     <td className="p-4 text-slate-600 text-sm">{gradeName}</td>
                                     <td className="p-4 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.male}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.female}</td>
                                     <td className="p-4 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="p-4 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="p-4 text-sm text-slate-600">{c.assistants || '---'}</td>
                                     <td className="p-4 text-center">
                                         <button onClick={() => handleEditClass(c)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                             <Edit size={16} />
                                         </button>
                                     </td>
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={10} className="p-8 text-center text-slate-400">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-6 justify-end text-sm font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={16}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={16}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={16}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {/* Edit Modal */}
      {editingClass && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-lg text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                </div>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg bg-slate-100 text-slate-500" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Chủ Nhiệm</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.mainTeacher || ''} 
                            onChange={(e) => setEditingClass({...editingClass, mainTeacher: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Phụ Trách</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.assistants || ''} 
                            onChange={(e) => setEditingClass({...editingClass, assistants: e.target.value})}
                        />
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                    <button onClick={() => setEditingClass(null)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium">Hủy</button>
                    <button onClick={handleSaveClass} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight, BookUp, Repeat } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

type Mode = 'TRANSFER' | 'PROMOTION' | 'SEARCH';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER');

  // === Source Filters ===
  const [sourceYearId, setSourceYearId] = useState<string>('');
  const [sourceGradeId, setSourceGradeId] = useState<string>('all');
  const [sourceClassId, setSourceClassId] = useState<string>('');

  // === Target Filters ===
  const [targetYearId, setTargetYearId] = useState<string>('');
  const [targetGradeId, setTargetGradeId] = useState<string>('all');
  const [targetClassId, setTargetClassId] = useState<string>('');

  // Set defaults when mode or years change
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;

    if (mode === 'TRANSFER') {
        // Transfer: Same year source and target
        setSourceYearId(active.id);
        setTargetYearId(active.id);
    } else if (mode === 'PROMOTION') {
        // Promotion: Source = Active, Target = Next year (if exists) or Active
        setSourceYearId(active.id);
        const nextYear = years.find(y => y.id !== active.id && y.name > active.name); // Simple string compare for now
        setTargetYearId(nextYear ? nextYear.id : active.id);
    }
  }, [years, mode]);

  // Derived Source Classes
  const sourceClassesAvailable = useMemo(() => {
    if (sourceGradeId === 'all') return [];
    return classes.filter(c => c.yearId === sourceYearId && c.gradeId === sourceGradeId);
  }, [classes, sourceYearId, sourceGradeId]);

  // Derived Target Classes
  const targetClassesAvailable = useMemo(() => {
    if (targetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === targetYearId && c.gradeId === targetGradeId);
  }, [classes, targetYearId, targetGradeId]);

  // --- Batch Logic ---
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  const sourceStudents = useMemo(() => {
      return sourceClassId ? students.filter(s => s.classId === sourceClassId) : [];
  }, [students, sourceClassId]);

  const targetStudents = useMemo(() => {
      return targetClassId ? students.filter(s => s.classId === targetClassId) : [];
  }, [students, targetClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId) return alert("Vui lòng chọn đầy đủ lớp nguồn và lớp đích");
    if (sourceClassId === targetClassId) return alert("Lớp nguồn và đích phải khác nhau");
    if (selectedStudentIds.length === 0) return alert("Vui lòng chọn ít nhất 1 học viên");

    const targetClass = classes.find(c => c.id === targetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển ${selectedStudentIds.length} học viên sang lớp ${targetClass}?`);

    if (confirm) {
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });
      setStudents(updatedStudents);
      setSelectedStudentIds([]);
      alert("Đã thực hiện chuyển lớp thành công!");
    }
  };

  // --- Search Logic ---
  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);

  // Single Transfer Target
  const [singleTargetYearId, setSingleTargetYearId] = useState('');
  const [singleTargetGradeId, setSingleTargetGradeId] = useState('all');
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  const singleTargetClassesAvailable = useMemo(() => {
    if (singleTargetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === singleTargetYearId && c.gradeId === singleTargetGradeId);
  }, [classes, singleTargetYearId, singleTargetGradeId]);

  const handleSearch = () => {
    const q = searchQuery.toLowerCase();
    const found = students.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q
    );

    setSearchedStudent(found || null);
    if (found) {
        const active = years.find(y => y.isActive);
        if(active) setSingleTargetYearId(active.id);
    }
    if (!found) alert("Không tìm thấy học viên");
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) return alert("Vui lòng chọn lớp đích");

    const targetClass = classes.find(c => c.id === singleTargetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển em ${searchedStudent.saintName} ${searchedStudent.fullName} sang lớp ${targetClass}?`);

    if (confirm) {
       const updatedStudents = students.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });
       alert("Đã cập nhật lớp thành công!");
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Chuyển Lớp</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex gap-1">
           <button 
             onClick={() => setMode('TRANSFER')} 
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'TRANSFER' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}
           >
             <Repeat size={16}/> Từ lớp qua lớp
           </button>
           <button 
             onClick={() => setMode('PROMOTION')} 
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'PROMOTION' ? 'bg-white shadow text-green-600' : 'text-slate-600'}`}
           >
             <BookUp size={16}/> Từ lớp lên lớp
           </button>
           <button 
             onClick={() => setMode('SEARCH')} 
             className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'SEARCH' ? 'bg-white shadow text-purple-600' : 'text-slate-600'}`}
           >
             <Search size={16}/> Tìm & Xếp lớp
           </button>
        </div>
      </div>

      {mode !== 'SEARCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          {/* SOURCE PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 rounded-t-xl space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase block">Lớp Nguồn (Năm cũ/Hiện tại)</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={sourceYearId} onChange={e => { setSourceYearId(e.target.value); setSourceClassId(''); }}>
                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                 </select>
                 <select className="p-2 border rounded-lg text-sm" value={sourceGradeId} onChange={e => { setSourceGradeId(e.target.value); setSourceClassId(''); }}>
                    <option value="all">-- Chọn Khối --</option>
                    {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                 </select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={sourceClassId} onChange={e => { setSourceClassId(e.target.value); setSelectedStudentIds([]); }}>
                <option value="">-- Chọn Lớp --</option>
                {sourceClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10">
                     <tr>
                       <th className="p-2 w-10"><input type="checkbox" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/></th>
                       <th className="p-2">Học Viên ({sourceStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y">
                     {sourceStudents.map(s => (
                       <tr key={s.id} className={selectedStudentIds.includes(s.id) ? 'bg-blue-50' : ''}>
                         <td className="p-2"><input type="checkbox" checked={selectedStudentIds.includes(s.id)} onChange={() => handleCheckboxChange(s.id)}/></td>
                         <td className="p-2">
                           <div className="font-medium">{s.saintName} {s.fullName}</div>
                           <div className="text-xs text-slate-400">{s.id}</div>
                         </td>
                       </tr>
                     ))}
                     {sourceStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}
                   </tbody>
                 </table>
               ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">Vui lòng chọn lớp nguồn</div>}
            </div>
          </div>

          {/* ACTION PANEL */}
          <div className="w-16 flex flex-col items-center justify-center gap-4">
             <button 
                onClick={executeBatchTransfer}
                disabled={selectedStudentIds.length === 0 || !targetClassId}
                className={`p-3 text-white rounded-full shadow-lg hover:brightness-110 disabled:bg-slate-300 disabled:cursor-not-allowed transition-all ${mode === 'PROMOTION' ? 'bg-green-600' : 'bg-blue-600'}`}
                title="Thực hiện chuyển lớp"
             >
               {mode === 'PROMOTION' ? <BookUp size={20}/> : <ArrowRightLeft size={20} />}
             </button>
             <div className="text-xs text-center font-medium text-slate-600">{selectedStudentIds.length > 0 ? `${selectedStudentIds.length} em` : ''}</div>
          </div>

          {/* TARGET PANEL */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className={`p-4 border-b border-slate-200 rounded-t-xl space-y-3 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
              <label className={`text-xs font-bold uppercase block ${mode === 'PROMOTION' ? 'text-green-700' : 'text-blue-700'}`}>Lớp Đích (Năm mới/Đích đến)</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={targetYearId} onChange={e => { setTargetYearId(e.target.value); setTargetClassId(''); }}>
                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                 </select>
                 <select className="p-2 border rounded-lg text-sm" value={targetGradeId} onChange={e => { setTargetGradeId(e.target.value); setTargetClassId(''); }}>
                    <option value="all">-- Chọn Khối --</option>
                    {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                 </select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={targetClassId} onChange={e => setTargetClassId(e.target.value)}>
                <option value="">-- Chọn Lớp Đến --</option>
                {targetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                {targetClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10">
                     <tr>
                       <th className="p-2 w-10">#</th>
                       <th className="p-2">Học Viên Lớp Đích ({targetStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y">
                     {targetStudents.map((s, idx) => (
                       <tr key={s.id}>
                         <td className="p-2 text-slate-500 text-xs">{idx + 1}</td>
                         <td className="p-2">
                           <div className="font-medium">{s.saintName} {s.fullName}</div>
                           <div className="text-xs text-slate-400">{s.id}</div>
                         </td>
                       </tr>
                     ))}
                     {targetStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}
                   </tbody>
                 </table>
                ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">Vui lòng chọn lớp đích</div>}
            </div>
          </div>
        </div>
      ) : (
        // SEARCH MODE
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 flex flex-col items-center">
            <div className="w-full max-w-xl mb-8 flex gap-2">
                 <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="text" placeholder="Tìm theo Tên/Mã HV hoặc Tên Bố/Mẹ..." className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()}/>
                 </div>
                 <button onClick={handleSearch} className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Tìm Kiếm</button>
            </div>

            {searchedStudent ? (
                <div className="w-full max-w-2xl bg-slate-50 rounded-xl border border-slate-200 p-6 animate-fade-in">
                    <div className="flex items-start gap-4 mb-6">
                       <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold text-xl">{searchedStudent.fullName.charAt(0)}</div>
                       <div>
                          <h3 className="text-xl font-bold text-slate-800">{searchedStudent.saintName} {searchedStudent.fullName}</h3>
                          <p className="text-slate-500 text-sm">Mã HV: {searchedStudent.id} | DOB: {searchedStudent.dob}</p>
                       </div>
                    </div>
                    <div className="grid grid-cols-2 gap-8 items-center">
                       <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Lớp Hiện Tại</label>
                          <div className="p-3 bg-white border border-slate-200 rounded-lg font-medium text-slate-700">
                             {classes.find(c => c.id === searchedStudent.classId)?.name || 'Chưa xếp lớp'}
                             <span className="block text-xs text-slate-400 font-normal">{years.find(y => y.id === classes.find(c => c.id === searchedStudent.classId)?.yearId)?.name}</span>
                          </div>
                       </div>
                       <div className="flex flex-col justify-center space-y-2">
                          <label className="block text-xs font-bold text-blue-600 uppercase">Chuyển Đến Lớp</label>
                          <select className="w-full p-2 border rounded text-sm" value={singleTargetYearId} onChange={e => {setSingleTargetYearId(e.target.value); setSingleTargetClassId('');}}>
                             {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                          </select>
                          <select className="w-full p-2 border rounded text-sm" value={singleTargetGradeId} onChange={e => {setSingleTargetGradeId(e.target.value); setSingleTargetClassId('');}}>
                             <option value="all">-- Chọn Khối --</option>
                             {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                          </select>
                          <select className="w-full p-2 border rounded text-sm bg-white font-medium" value={singleTargetClassId} onChange={e => setSingleTargetClassId(e.target.value)}>
                             <option value="">-- Chọn Lớp --</option>
                             {singleTargetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                          </select>
                       </div>
                    </div>
                    <div className="mt-8 flex justify-end">
                       <button onClick={executeSingleTransfer} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 shadow flex items-center gap-2"><CheckCircle2 size={18} /> Lưu Thay Đổi</button>
                    </div>
                </div>
            ) : <div className="text-center text-slate-400 mt-10"><AlertCircle size={48} className="mx-auto mb-2 opacity-20" /><p>Nhập thông tin để tìm kiếm học viên</p></div>}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { Search, Plus, Edit, Trash2, X, Calendar, Printer, FileSpreadsheet, AlertTriangle, Save, User, MapPin, Phone, Users, CheckCircle2 } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string) => {
    setToast({ message, type: 'success' });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = students.filter(student => {
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
  };

  const handleSaveStudent = () => {
    // In real app, logic to update state/db would be here
    showToast(selectedStudent ? "Đã cập nhật thông tin học viên thành công!" : "Đã thêm học viên mới thành công!");
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
