sYear.map((s, idx) => (<tr key={s.id} className="hover:bg-slate-50 group"><td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td><td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td><td className="p-4 text-center border-l text-slate-500">{s.avg1 || '-'}</td><td className="p-4 text-center border-l text-slate-500">{s.avg2 || '-'}</td><td className="p-4 text-center border-l font-bold text-blue-700 bg-blue-50/30">{s.avgYear.toFixed(1)}</td><td className="p-4 text-center border-l"><span className={`px-2 py-1 rounded text-xs font-bold ${s.rank.color}`}>{s.rank.label}</span></td><td className="p-4 text-center border-l font-mono font-bold text-slate-600">{s.ranking <= 3 ? <span className="flex items-center justify-center gap-1 text-yellow-600"><Trophy size={14}/> {s.ranking}</span> : s.ranking}</td></tr>)) : filteredStudents.map((s, idx) => {const r = getRecord(s.id, term as 'HK1' | 'HK2'); const rank = getRank(r.average); return (<tr key={s.id} className="hover:bg-slate-50 group"><td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td><td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>{testColumns.map(col => (<td key={col.id} className="p-2 border-l text-center"><input type="number" value={r.scores ? r.scores[col.id] || '' : ''} onChange={(e) => handleScoreChange(s.id, col.id, e.target.value)} className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" /></td>))}<td className="p-2 border-l text-center"><input type="number" value={r.scoreExam || ''} onChange={(e) => handleScoreChange(s.id, 'exam', e.target.value)} className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" /></td><td className="p-4 border-l text-center font-bold text-slate-800 bg-blue-50/20">{r.average > 0 ? r.average : '-'}</td><td className="p-4 border-l text-center">{r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rank.color}`}>{rank.label}</span>}</td></tr>);})) : (<tr><td colSpan={10} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để xem bảng điểm</td></tr>)}</tbody></table></div>{term !== 'YEAR' && filteredStudents.length > 0 && (<div className="p-4 border-t border-slate-200 bg-slate-50 text-right"><button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium"><Save size={18} /> Lưu Bảng Điểm</button></div>)}</>) : (<div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50"><div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6"><div className="flex justify-between items-start"><div><h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3><div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div></div><div className="text-right"><div className="text-sm text-slate-500">Sĩ số</div><div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div></div></div></div><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden"><div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center"><div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div><span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{passedStudents.map(s => (<tr key={s.id} className="hover:bg-green-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{passedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>)}</tbody></table></div></div><div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden"><div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center"><div className="flex items-center gap-2"><XCircle className="text-red-600" /><h4 className="font-bold text-red-800">Danh Sách Ở Lại Lớp</h4></div><span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">{failedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{failedStudents.map(s => (<tr key={s.id} className="hover:bg-red-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-red-600">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{failedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Không có học viên ở lại lớp</td></tr>)}</tbody></table></div></div></div></div>)}
