import React, { useState } from 'react';
import { MOCK_GRADES, MOCK_SAINTS } from '../constants';
import { Calendar, Layers, Save, Plus, Trash2, Cross, CheckCircle, CheckCircle2 } from 'lucide-react';
import { Saint, SchoolYear, ClassRoom } from '../types';

interface SettingsProps {
    years: SchoolYear[];
    setYears: (years: SchoolYear[]) => void;
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ years, setYears, classes, setClasses }) => {
  const [saints, setSaints] = useState<Saint[]>(MOCK_SAINTS);
  const [newSaintName, setNewSaintName] = useState('');
  const [newSaintGender, setNewSaintGender] = useState<'Male'|'Female'>('Male');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState('g1');

  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  const handleAddSaint = () => {
    if (newSaintName) {
      const newSaint: Saint = { id: `s${Date.now()}`, name: newSaintName, gender: newSaintGender };
      setSaints([...saints, newSaint]);
      showToast(`Đã thêm tên thánh "${newSaintName}" thành công!`);
      setNewSaintName('');
    }
  };

  const handleRemoveSaint = (id: string) => {
    const saint = saints.find(s => s.id === id);
    setSaints(saints.filter(s => s.id !== id));
    showToast(`Đã xóa tên thánh "${saint?.name}" thành công!`);
  };

  const handleAddYear = () => {
      if (newYearName) {
          const newId = newYearName.replace(/\s/g, '-');
          const newYear: SchoolYear = { id: newId, name: newYearName, isActive: false };
          setYears([...years, newYear]);
          showToast(`Đã thêm năm học "${newYearName}" thành công!`);
          setNewYearName('');
      }
  };

  const handleSetActiveYear = (id: string) => {
      const year = years.find(y => y.id === id);
      const updatedYears = years.map(y => ({ ...y, isActive: y.id === id }));
      setYears(updatedYears);
      showToast(`Đã đặt "${year?.name}" làm năm học hiện tại!`);
  };

  const handleAddClass = () => {
      if (newClassName && activeYear) {
          const newClass: ClassRoom = { id: `c_${Date.now()}`, name: newClassName, gradeId: newClassGrade, yearId: activeYear.id, mainTeacher: 'Chưa phân công' };
          setClasses([...classes, newClass]);
          showToast(`Đã thêm lớp "${newClassName}" thành công!`);
          setNewClassName('');
      } else {
          alert("Vui lòng nhập tên lớp và đảm bảo có năm học đang kích hoạt.");
      }
  };

  return (
    <div className="p-6 h-screen overflow-y-auto custom-scrollbar relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <h2 className="text-2xl font-bold text-slate-800 mb-6">Cài Đặt Hệ Thống</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Calendar className="text-blue-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Năm Học</h3></div>
          <div className="space-y-4">
            <div><label className="block text-sm font-medium text-slate-700 mb-2">Danh sách năm học</label><div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar border rounded-lg p-2">{years.map(y => (<div key={y.id} className={`flex justify-between items-center p-2 rounded-lg ${y.isActive ? 'bg-blue-50 border border-blue-200' : 'bg-slate-50'}`}><span className={y.isActive ? 'font-bold text-blue-700' : 'text-slate-700'}>{y.name} {y.isActive && '(Hiện tại)'}</span>{!y.isActive && (<button onClick={() => handleSetActiveYear(y.id)} className="text-xs px-2 py-1 bg-white border border-slate-300 rounded hover:bg-slate-100">Đặt làm hiện tại</button>)}</div>))}</div></div>
            <div className="border-t pt-4 mt-4"><h4 className="font-semibold text-sm mb-3">Tạo Năm Học Mới</h4><div className="grid grid-cols-2 gap-4 mb-3"><input type="text" placeholder="Tên năm học (VD: 2024-2025)" className="w-full p-2 border rounded-lg text-sm" value={newYearName} onChange={(e) => setNewYearName(e.target.value)}/><button onClick={handleAddYear} className="flex items-center justify-center gap-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"><Plus size={16}/> Thêm mới</button></div></div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Cross className="text-amber-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Tên Thánh</h3></div>
          <div className="space-y-4">
             <div className="flex gap-2"><input type="text" placeholder="Tên Thánh (VD: Đaminh)" className="flex-1 p-2 border rounded-lg text-sm" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-2 border rounded-lg text-sm" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar"><table className="w-full text-left text-sm"><thead className="bg-slate-50 sticky top-0"><tr><th className="p-3">Tên Thánh</th><th className="p-3 w-20">Giới tính</th><th className="p-3 text-right w-16"></th></tr></thead><tbody className="divide-y">{saints.map(s => (<tr key={s.id} className="hover:bg-slate-50"><td className="p-3 font-medium">{s.name}</td><td className="p-3 text-slate-500 text-xs">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</td><td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" onClick={() => handleRemoveSaint(s.id)} /></td></tr>))}</tbody></table></div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Layers className="text-purple-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Khối Lớp</h3></div>
          <div className="space-y-4">
             <div className="flex gap-2"><input type="text" placeholder="Tên khối (VD: Khối Vào Đời)" className="flex-1 p-2 border rounded-lg" /><button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar"><table className="w-full text-left text-sm"><thead className="bg-slate-50"><tr><th className="p-3">Tên Khối</th><th className="p-3 text-right">Thao tác</th></tr></thead><tbody className="divide-y">{MOCK_GRADES.map(g => (<tr key={g.id}><td className="p-3 font-medium">{g.name}</td><td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" /></td></tr>))}</tbody></table></div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Layers className="text-green-600" /><h3 className="font-bold text-lg text-slate-800">Danh Sách Lớp Học ({activeYear?.name})</h3></div>
          <div className="space-y-4">
            <div className="flex gap-2"><input type="text" placeholder="Tên lớp mới" className="flex-1 p-2 border rounded-lg" value={newClassName} onChange={(e) => setNewClassName(e.target.value)} /><select className="p-2 border rounded-lg w-28" value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value)}>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select><button onClick={handleAddClass} className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar"><table className="w-full text-left text-sm"><thead className="bg-slate-50"><tr><th className="p-3">Tên Lớp</th><th className="p-3">Khối</th><th className="p-3 text-right"></th></tr></thead><tbody className="divide-y">{classesInActiveYear.length > 0 ? (classesInActiveYear.map(c => {const gradeName = MOCK_GRADES.find(g => g.id === c.gradeId)?.name || '---'; return (<tr key={c.id}><td className="p-3 font-medium">{c.name}</td><td className="p-3 text-slate-500 text-xs">{gradeName}</td><td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" /></td></tr>)})) : (<tr><td colSpan={3} className="p-4 text-center text-slate-500 italic">Chưa có lớp nào trong năm học này</td></tr>)}</tbody></table></div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight, BookUp, Repeat } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

type Mode = 'TRANSFER' | 'PROMOTION' | 'SEARCH';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // === Source Filters ===
  const [sourceYearId, setSourceYearId] = useState<string>('');
  const [sourceGradeId, setSourceGradeId] = useState<string>('all');
  const [sourceClassId, setSourceClassId] = useState<string>('');

  // === Target Filters ===
  const [targetYearId, setTargetYearId] = useState<string>('');
  const [targetGradeId, setTargetGradeId] = useState<string>('all');
  const [targetClassId, setTargetClassId] = useState<string>('');

  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;

    if (mode === 'TRANSFER') {
        setSourceYearId(active.id);
        setTargetYearId(active.id);
    } else if (mode === 'PROMOTION') {
        setSourceYearId(active.id);
        const nextYear = years.find(y => y.id !== active.id && y.name > active.name);
        setTargetYearId(nextYear ? nextYear.id : active.id);
    }
  }, [years, mode]);

  const sourceClassesAvailable = useMemo(() => {
    if (sourceGradeId === 'all') return [];
    return classes.filter(c => c.yearId === sourceYearId && c.gradeId === sourceGradeId);
  }, [classes, sourceYearId, sourceGradeId]);

  const targetClassesAvailable = useMemo(() => {
    if (targetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === targetYearId && c.gradeId === targetGradeId);
  }, [classes, targetYearId, targetGradeId]);

  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  const sourceStudents = useMemo(() => {
      return sourceClassId ? students.filter(s => s.classId === sourceClassId) : [];
  }, [students, sourceClassId]);

  const targetStudents = useMemo(() => {
      return targetClassId ? students.filter(s => s.classId === targetClassId) : [];
  }, [students, targetClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId) return;
    if (sourceClassId === targetClassId) {
        alert("Lớp nguồn và đích phải khác nhau");
        return;
    }

    const targetClass = classes.find(c => c.id === targetClassId)?.name;
    const confirm = window.confirm(`Xác nhận chuyển ${selectedStudentIds.length} học viên sang lớp ${targetClass}?`);

    if (confirm) {
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });
      setStudents(updatedStudents);
      setSelectedStudentIds([]);
      showToast(`Đã chuyển thành công ${selectedStudentIds.length} học viên sang lớp ${targetClass}!`);
    }
  };

  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);
  const [singleTargetYearId, setSingleTargetYearId] = useState('');
  const [singleTargetGradeId, setSingleTargetGradeId] = useState('all');
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  const singleTargetClassesAvailable = useMemo(() => {
    if (singleTargetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === singleTargetYearId && c.gradeId === singleTargetGradeId);
  }, [classes, singleTargetYearId, singleTargetGradeId]);

  const handleSearch = () => {
    const q = searchQuery.toLowerCase();
    const found = students.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q
    );

    setSearchedStudent(found || null);
    if (found) {
        const active = years.find(y => y.isActive);
        if(active) setSingleTargetYearId(active.id);
    }
    if (!found) alert("Không tìm thấy học viên");
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) return;

    const targetClass = classes.find(c => c.id === singleTargetClassId)?.name;
    const confirm = window.confirm(`Xác nhận xếp em ${searchedStudent.saintName} ${searchedStudent.fullName} vào lớp ${targetClass}?`);

    if (confirm) {
       const updatedStudents = students.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });
       showToast(`Đã xếp em ${searchedStudent.fullName} vào lớp ${targetClass} thành công!`);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Chuyển Lớp</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex gap-1">
           <button onClick={() => setMode('TRANSFER')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'TRANSFER' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}><Repeat size={16}/> Từ lớp qua lớp</button>
           <button onClick={() => setMode('PROMOTION')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'PROMOTION' ? 'bg-white shadow text-green-600' : 'text-slate-600'}`}><BookUp size={16}/> Từ lớp lên lớp</button>
           <button onClick={() => setMode('SEARCH')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'SEARCH' ? 'bg-white shadow text-purple-600' : 'text-slate-600'}`}><Search size={16}/> Tìm & Xếp lớp</button>
        </div>
      </div>

      {mode !== 'SEARCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 rounded-t-xl space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase block">Lớp Nguồn</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={sourceYearId} onChange={e => { setSourceYearId(e.target.value); setSourceClassId(''); }}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select>
                 <select className="p-2 border rounded-lg text-sm" value={sourceGradeId} onChange={e => { setSourceGradeId(e.target.value); setSourceClassId(''); }}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={sourceClassId} onChange={e => { setSourceClassId(e.target.value); setSelectedStudentIds([]); }}><option value="">-- Chọn Lớp --</option>{sourceClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10"><tr><th className="p-2 w-10"><input type="checkbox" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/></th><th className="p-2">Học Viên ({sourceStudents.length})</th></tr></thead>
                   <tbody className="divide-y">{sourceStudents.map(s => (<tr key={s.id} className={selectedStudentIds.includes(s.id) ? 'bg-blue-50' : ''}><td className="p-2"><input type="checkbox" checked={selectedStudentIds.includes(s.id)} onChange={() => handleCheckboxChange(s.id)}/></td><td className="p-2"><div className="font-medium">{s.saintName} {s.fullName}</div><div className="text-xs text-slate-400">{s.id}</div></td></tr>))}{sourceStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}</tbody>
                 </table>
               ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">Vui lòng chọn lớp nguồn</div>}
            </div>
          </div>

          {/* Action Center - Removed redundant icon */}
          <div className="w-20 flex flex-col items-center justify-center gap-4">
             <button 
                onClick={executeBatchTransfer} 
                disabled={selectedStudentIds.length === 0 || !targetClassId} 
                className={`w-14 h-14 flex items-center justify-center text-white rounded-full shadow-lg hover:scale-105 active:scale-95 disabled:bg-slate-300 disabled:cursor-not-allowed transition-all ${mode === 'PROMOTION' ? 'bg-green-600 shadow-green-200' : 'bg-blue-600 shadow-blue-200'}`} 
                title="Thực hiện chuyển lớp"
             >
               {mode === 'PROMOTION' ? <BookUp size={28}/> : <ArrowRightLeft size={28} />}
             </button>
             <div className="text-xs text-center font-bold text-slate-600 px-2">{selectedStudentIds.length > 0 ? `${selectedStudentIds.length} em` : 'Chọn HV'}</div>
          </div>

          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className={`p-4 border-b border-slate-200 rounded-t-xl space-y-3 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
              <label className={`text-xs font-bold uppercase block ${mode === 'PROMOTION' ? 'text-green-700' : 'text-blue-700'}`}>Lớp Đích</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm" value={targetYearId} onChange={e => { setTargetYearId(e.target.value); setTargetClassId(''); }}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select>
                 <select className="p-2 border rounded-lg text-sm" value={targetGradeId} onChange={e => { setTargetGradeId(e.target.value); setTargetClassId(''); }}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-medium" value={targetClassId} onChange={e => setTargetClassId(e.target.value)}><option value="">-- Chọn Lớp Đến --</option>{targetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                {targetClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10"><tr><th className="p-2 w-10">#</th><th className="p-2">Học Viên Lớp Đích ({targetStudents.length})</th></tr></thead>
                   <tbody className="divide-y">{targetStudents.map((s, idx) => (<tr key={s.id}><td className="p-2 text-slate-500 text-xs">{idx + 1}</td><td className="p-2"><div className="font-medium">{s.saintName} {s.fullName}</div><div className="text-xs text-slate-400">{s.id}</div></td></tr>))}{targetStudents.length === 0 && <tr><td colSpan={2} className="p-4 text-center text-slate-400">Lớp trống</td></tr>}</tbody>
                 </table>
                ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">Vui lòng chọn lớp đích</div>}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 flex flex-col items-center">
            <div className="w-full max-w-xl mb-8 flex gap-2">
                 <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="text" placeholder="Tìm theo Tên/Mã HV hoặc Tên Bố/Mẹ..." className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()}/>
                 </div>
                 <button onClick={handleSearch} className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Tìm Kiếm</button>
            </div>
            {searchedStudent ? (
                <div className="w-full max-w-2xl bg-slate-50 rounded-xl border border-slate-200 p-6 animate-fade-in">
                    <div className="flex items-start gap-4 mb-6"><div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold text-xl">{searchedStudent.fullName.charAt(0)}</div><div><h3 className="text-xl font-bold text-slate-800">{searchedStudent.saintName} {searchedStudent.fullName}</h3><p className="text-slate-500 text-sm">Mã HV: {searchedStudent.id} | DOB: {searchedStudent.dob}</p></div></div>
                    <div className="grid grid-cols-2 gap-8 items-center"><div><label className="block text-xs font-bold text-slate-500 uppercase mb-2">Lớp Hiện Tại</label><div className="p-3 bg-white border border-slate-200 rounded-lg font-medium text-slate-700">{classes.find(c => c.id === searchedStudent.classId)?.name || 'Chưa xếp lớp'}<span className="block text-xs text-slate-400 font-normal">{years.find(y => y.id === classes.find(c => c.id === searchedStudent.classId)?.yearId)?.name}</span></div></div><div className="flex flex-col justify-center space-y-2"><label className="block text-xs font-bold text-blue-600 uppercase">Chuyển Đến Lớp</label><select className="w-full p-2 border rounded text-sm" value={singleTargetYearId} onChange={e => {setSingleTargetYearId(e.target.value); setSingleTargetClassId('');}}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select><select className="w-full p-2 border rounded text-sm" value={singleTargetGradeId} onChange={e => {setSingleTargetGradeId(e.target.value); setSingleTargetClassId('');}}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select><select className="w-full p-2 border rounded text-sm bg-white font-medium" value={singleTargetClassId} onChange={e => setSingleTargetClassId(e.target.value)}><option value="">-- Chọn Lớp --</option>{singleTargetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div></div>
                    <div className="mt-8 flex justify-end"><button onClick={executeSingleTransfer} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 shadow flex items-center gap-2"><CheckCircle2 size={18} /> Lưu Thay Đổi</button></div>
                </div>
            ) : <div className="text-center text-slate-400 mt-10"><AlertCircle size={48} className="mx-auto mb-2 opacity-20" /><p>Nhập thông tin để tìm kiếm học viên</p></div>}
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight, BookUp, Repeat } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

type Mode = 'TRANSFER' | 'PROMOTION' | 'SEARCH';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // === Source Filters ===
  const [sourceYearId, setSourceYearId] = useState<string>('');
  const [sourceGradeId, setSourceGradeId] = useState<string>('all');
  const [sourceClassId, setSourceClassId] = useState<string>('');

  // === Target Filters ===
  const [targetYearId, setTargetYearId] = useState<string>('');
  const [targetGradeId, setTargetGradeId] = useState<string>('all');
  const [targetClassId, setTargetClassId] = useState<string>('');

  // Initial Defaults & Mode Switch Reset
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;

    setSelectedStudentIds([]);
    setSourceClassId('');
    setTargetClassId('');

    if (mode === 'TRANSFER') {
        setSourceYearId(active.id);
        setTargetYearId(active.id);
    } else if (mode === 'PROMOTION') {
        setSourceYearId(active.id);
        const nextYear = years.find(y => y.id !== active.id && y.name > active.name);
        setTargetYearId(nextYear ? nextYear.id : active.id);
    }
  }, [mode, years]);

  // Sync Source Classes
  const sourceClassesAvailable = useMemo(() => {
    if (sourceGradeId === 'all') return [];
    return classes.filter(c => c.yearId === sourceYearId && c.gradeId === sourceGradeId);
  }, [classes, sourceYearId, sourceGradeId]);

  // Sync Target Classes
  const targetClassesAvailable = useMemo(() => {
    if (targetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === targetYearId && c.gradeId === targetGradeId);
  }, [classes, targetYearId, targetGradeId]);

  // Reset class selection when source filters change
  useEffect(() => {
    setSourceClassId('');
    setSelectedStudentIds([]);
  }, [sourceYearId, sourceGradeId]);

  // Reset class selection when target filters change
  useEffect(() => {
    setTargetClassId('');
  }, [targetYearId, targetGradeId]);

  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  const sourceStudents = useMemo(() => {
      return sourceClassId ? students.filter(s => s.classId === sourceClassId) : [];
  }, [students, sourceClassId]);

  const targetStudents = useMemo(() => {
      return targetClassId ? students.filter(s => s.classId === targetClassId) : [];
  }, [students, targetClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    if (selectedStudentIds.includes(id)) {
      setSelectedStudentIds(selectedStudentIds.filter(sid => sid !== id));
    } else {
      setSelectedStudentIds([...selectedStudentIds, id]);
    }
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId || selectedStudentIds.length === 0) return;

    if (sourceClassId === targetClassId) {
        alert("Lớp đích phải khác lớp nguồn!");
        return;
    }

    const targetClassName = classes.find(c => c.id === targetClassId)?.name;
    const confirmMsg = mode === 'PROMOTION' 
        ? `Xác nhận LÊN LỚP cho ${selectedStudentIds.length} học viên sang lớp ${targetClassName}?`
        : `Xác nhận CHUYỂN ${selectedStudentIds.length} học viên sang lớp ${targetClassName}?`;

    if (window.confirm(confirmMsg)) {
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });

      setStudents(updatedStudents);
      setSelectedStudentIds([]);
      showToast(`Thành công! Đã chuyển ${selectedStudentIds.length} em vào lớp ${targetClassName}.`);
    }
  };

  // --- Search Logic ---
  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);
  const [singleTargetYearId, setSingleTargetYearId] = useState('');
  const [singleTargetGradeId, setSingleTargetGradeId] = useState('all');
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  const singleTargetClassesAvailable = useMemo(() => {
    if (singleTargetGradeId === 'all') return [];
    return classes.filter(c => c.yearId === singleTargetYearId && c.gradeId === singleTargetGradeId);
  }, [classes, singleTargetYearId, singleTargetGradeId]);

  const handleSearch = () => {
    if (!searchQuery.trim()) return;
    const q = searchQuery.toLowerCase();
    const found = students.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q
    );

    if (found) {
        setSearchedStudent(found);
        const active = years.find(y => y.isActive);
        if(active) setSingleTargetYearId(active.id);
    } else {
        alert("Không tìm thấy học viên với thông tin đã nhập!");
    }
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) return;

    const targetClass = classes.find(c => c.id === singleTargetClassId)?.name;
    if (window.confirm(`Xác nhận xếp em ${searchedStudent.saintName} ${searchedStudent.fullName} vào lớp ${targetClass}?`)) {
       const updatedStudents = students.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });
       showToast(`Đã cập nhật lớp cho em ${searchedStudent.fullName} thành công!`);
    }
  };

  const isReadyToTransfer = selectedStudentIds.length > 0 && targetClassId;

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Chuyển Lớp</h2>
        <div className="bg-slate-200 p-1 rounded-lg flex gap-1">
           <button onClick={() => setMode('TRANSFER')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'TRANSFER' ? 'bg-white shadow text-blue-600' : 'text-slate-600'}`}><Repeat size={16}/> Chuyển Lớp</button>
           <button onClick={() => setMode('PROMOTION')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'PROMOTION' ? 'bg-white shadow text-green-600' : 'text-slate-600'}`}><BookUp size={16}/> Lên Lớp</button>
           <button onClick={() => setMode('SEARCH')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${mode === 'SEARCH' ? 'bg-white shadow text-purple-600' : 'text-slate-600'}`}><Search size={16}/> Xếp Lớp Cá Nhân</button>
        </div>
      </div>

      {mode !== 'SEARCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          {/* SOURCE */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className="p-4 border-b border-slate-200 bg-slate-50 rounded-t-xl space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase block">Lớp Nguồn (Cũ)</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm bg-white" value={sourceYearId} onChange={e => setSourceYearId(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select>
                 <select className="p-2 border rounded-lg text-sm bg-white" value={sourceGradeId} onChange={e => setSourceGradeId(e.target.value)}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-bold text-slate-700" value={sourceClassId} onChange={e => setSourceClassId(e.target.value)}><option value="">-- Chọn Lớp Nguồn --</option>{sourceClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10">
                     <tr className="border-b">
                        <th className="p-2 w-10"><input type="checkbox" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/></th>
                        <th className="p-2">Học Viên ({sourceStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y">
                     {sourceStudents.map(s => (
                       <tr key={s.id} className={`${selectedStudentIds.includes(s.id) ? 'bg-blue-50' : 'hover:bg-slate-50'} transition-colors cursor-pointer`} onClick={() => handleCheckboxChange(s.id)}>
                         <td className="p-2" onClick={(e) => e.stopPropagation()}><input type="checkbox" checked={selectedStudentIds.includes(s.id)} onChange={() => handleCheckboxChange(s.id)}/></td>
                         <td className="p-2">
                           <div className="font-bold text-slate-700">{s.saintName} {s.fullName}</div>
                           <div className="text-[10px] text-slate-400 font-mono uppercase">{s.id}</div>
                         </td>
                       </tr>
                     ))}
                     {sourceStudents.length === 0 && <tr><td colSpan={2} className="p-8 text-center text-slate-400 italic">Lớp không có học viên</td></tr>}
                   </tbody>
                 </table>
               ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic p-4 text-center">Hãy chọn năm, khối và lớp nguồn để xem danh sách học viên</div>}
            </div>
          </div>

          {/* ACTION */}
          <div className="w-24 flex flex-col items-center justify-center gap-4">
             <button 
                onClick={executeBatchTransfer} 
                disabled={!isReadyToTransfer} 
                className={`w-16 h-16 flex items-center justify-center text-white rounded-full shadow-xl transition-all 
                    ${isReadyToTransfer 
                        ? (mode === 'PROMOTION' ? 'bg-green-600 hover:scale-110 active:scale-95 animate-pulse-subtle shadow-green-200' : 'bg-blue-600 hover:scale-110 active:scale-95 animate-pulse-subtle shadow-blue-200') 
                        : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`} 
                title="Bấm để thực hiện chuyển"
             >
               {mode === 'PROMOTION' ? <BookUp size={32}/> : <ArrowRightLeft size={32} />}
             </button>
             <div className="text-[10px] text-center font-bold text-slate-500 uppercase tracking-tighter">
                {selectedStudentIds.length > 0 ? `${selectedStudentIds.length} học viên` : 'Chưa chọn'}
             </div>
          </div>

          {/* TARGET */}
          <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
            <div className={`p-4 border-b border-slate-200 rounded-t-xl space-y-3 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
              <label className={`text-xs font-bold uppercase block ${mode === 'PROMOTION' ? 'text-green-700' : 'text-blue-700'}`}>Lớp Đích (Mới)</label>
              <div className="grid grid-cols-2 gap-2">
                 <select className="p-2 border rounded-lg text-sm bg-white" value={targetYearId} onChange={e => setTargetYearId(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select>
                 <select className="p-2 border rounded-lg text-sm bg-white" value={targetGradeId} onChange={e => setTargetGradeId(e.target.value)}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
              </div>
              <select className="w-full p-2 border rounded-lg text-sm bg-white font-bold text-slate-700" value={targetClassId} onChange={e => setTargetClassId(e.target.value)}><option value="">-- Chọn Lớp Đến --</option>{targetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                {targetClassId ? (
                 <table className="w-full text-left text-sm">
                   <thead className="sticky top-0 bg-white shadow-sm z-10"><tr className="border-b"><th className="p-2 w-10 text-slate-400">#</th><th className="p-2">Học Viên Hiện Có ({targetStudents.length})</th></tr></thead>
                   <tbody className="divide-y">
                     {targetStudents.map((s, idx) => (
                       <tr key={s.id} className="hover:bg-slate-50">
                         <td className="p-2 text-slate-400 text-[10px]">{idx + 1}</td>
                         <td className="p-2">
                           <div className="font-medium text-slate-700">{s.saintName} {s.fullName}</div>
                         </td>
                       </tr>
                     ))}
                     {targetStudents.length === 0 && <tr><td colSpan={2} className="p-8 text-center text-slate-400 italic">Lớp đang trống</td></tr>}
                   </tbody>
                 </table>
                ) : <div className="h-full flex items-center justify-center text-slate-400 text-sm italic p-4 text-center">Hãy chọn năm, khối và lớp đích để xem danh sách hiện có</div>}
            </div>
          </div>
        </div>
      ) : (
        /* SEARCH MODE */
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 flex flex-col items-center">
            <div className="w-full max-w-xl mb-8 flex gap-2">
                 <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="text" placeholder="Tìm theo Tên Thánh, Họ Tên hoặc Mã HV..." className="w-full pl-10 pr-4 py-3 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-purple-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()}/>
                 </div>
                 <button onClick={handleSearch} className="px-6 py-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700 font-bold shadow-lg shadow-purple-200 transition-all">Tìm Kiếm</button>
            </div>

            {searchedStudent ? (
                <div className="w-full max-w-2xl bg-slate-50 rounded-2xl border border-slate-200 p-8 shadow-sm animate-fade-in">
                    <div className="flex items-center gap-6 mb-8 pb-6 border-b border-slate-200">
                        <div className="w-20 h-20 bg-purple-100 rounded-full flex items-center justify-center text-purple-600 font-black text-2xl shadow-inner">{searchedStudent.fullName.charAt(0)}</div>
                        <div>
                            <h3 className="text-2xl font-black text-slate-800 tracking-tight">{searchedStudent.saintName} {searchedStudent.fullName}</h3>
                            <p className="text-slate-500 font-medium">Mã HV: <span className="font-mono text-purple-600">{searchedStudent.id}</span> | DOB: {searchedStudent.dob}</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
                       <div className="space-y-4">
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest">Thông tin hiện tại</label>
                          <div className="p-4 bg-white border border-slate-200 rounded-xl">
                             <div className="text-xs text-slate-400 mb-1 font-bold">Đang học lớp:</div>
                             <div className="text-lg font-bold text-slate-700">{classes.find(c => c.id === searchedStudent.classId)?.name || 'Chưa có lớp'}</div>
                             <div className="text-sm text-slate-400">{years.find(y => y.id === classes.find(c => c.id === searchedStudent.classId)?.yearId)?.name}</div>
                          </div>
                       </div>

                       <div className="space-y-4">
                          <label className="block text-xs font-black text-blue-600 uppercase tracking-widest">Chuyển sang lớp</label>
                          <div className="space-y-2">
                             <select className="w-full p-2.5 border rounded-lg text-sm bg-white" value={singleTargetYearId} onChange={e => setSingleTargetYearId(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}</select>
                             <select className="w-full p-2.5 border rounded-lg text-sm bg-white" value={singleTargetGradeId} onChange={e => setSingleTargetGradeId(e.target.value)}><option value="all">-- Chọn Khối --</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
                             <select className="w-full p-2.5 border rounded-lg text-sm bg-white font-bold text-blue-700" value={singleTargetClassId} onChange={e => setSingleTargetClassId(e.target.value)}><option value="">-- Chọn Lớp Mới --</option>{singleTargetClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
                          </div>
                       </div>
                    </div>

                    <div className="mt-10 pt-6 border-t border-slate-200 flex justify-end">
                       <button onClick={executeSingleTransfer} disabled={!singleTargetClassId} className="px-8 py-3 bg-emerald-600 text-white rounded-xl font-black hover:bg-emerald-700 disabled:bg-slate-200 disabled:cursor-not-allowed shadow-lg shadow-emerald-100 transition-all flex items-center gap-2">
                           <CheckCircle2 size={20} /> HOÀN TẤT XẾP LỚP
                       </button>
                    </div>
                </div>
            ) : (
                <div className="text-center text-slate-400 mt-12 py-12 px-6 border-2 border-dashed border-slate-100 rounded-3xl w-full max-w-xl">
                    <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4"><Search size={32} className="opacity-20" /></div>
                    <p className="font-medium">Vui lòng nhập thông tin để tìm học viên cần xếp lớp</p>
                    <p className="text-xs mt-1">Hỗ trợ tìm kiếm theo Tên Thánh, Họ tên đầy đủ hoặc Mã học viên</p>
                </div>
            )}
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        @keyframes pulse-subtle { 0% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.4); } 70% { box-shadow: 0 0 0 15px rgba(59, 130, 246, 0); } 100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        .animate-pulse-subtle { animation: pulse-subtle 2s infinite; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRightLeft, Search, CheckCircle2, AlertCircle, ArrowRight, BookUp, Repeat } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

type Mode = 'TRANSFER' | 'PROMOTION' | 'SEARCH';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // === Source Filters ===
  const [sourceYearId, setSourceYearId] = useState<string>('');
  const [sourceGradeId, setSourceGradeId] = useState<string>('all');
  const [sourceClassId, setSourceClassId] = useState<string>('');

  // === Target Filters ===
  const [targetYearId, setTargetYearId] = useState<string>('');
  const [targetGradeId, setTargetGradeId] = useState<string>('all');
  const [targetClassId, setTargetClassId] = useState<string>('');

  // Sync initial years and reset selections when mode changes
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;

    // Reset IDs on mode switch to prevent invalid state
    setSelectedStudentIds([]);
    setSourceClassId('');
    setTargetClassId('');

    if (mode === 'TRANSFER') {
        setSourceYearId(active.id);
        setTargetYearId(active.id);
    } else if (mode === 'PROMOTION') {
        setSourceYearId(active.id);
        const nextYear = years.find(y => y.id !== active.id && y.name > active.name);
        setTargetYearId(nextYear ? nextYear.id : active.id);
    }
  }, [mode, years]);

  // Derived list of classes based on year/grade filters
  const sourceClassesAvailable = useMemo(() => {
    if (sourceGradeId === 'all') return classes.filter(c => c.yearId === sourceYearId);
    return classes.filter(c => c.yearId === sourceYearId && c.gradeId === sourceGradeId);
  }, [classes, sourceYearId, sourceGradeId]);

  const targetClassesAvailable = useMemo(() => {
    if (targetGradeId === 'all') return classes.filter(c => c.yearId === targetYearId);
    return classes.filter(c => c.yearId === targetYearId && c.gradeId === targetGradeId);
  }, [classes, targetYearId, targetGradeId]);

  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Students currently in the selected source class
  const sourceStudents = useMemo(() => {
      return sourceClassId ? students.filter(s => s.classId === sourceClassId) : [];
  }, [students, sourceClassId]);

  // Students currently in the selected target class (to show existing roster)
  const targetStudents = useMemo(() => {
      return targetClassId ? students.filter(s => s.classId === targetClassId) : [];
  }, [students, targetClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedStudentIds(sourceStudents.map(s => s.id));
    } else {
      setSelectedStudentIds([]);
    }
  };

  const handleCheckboxChange = (id: string) => {
    setSelectedStudentIds(prev => 
      prev.includes(id) ? prev.filter(sid => sid !== id) : [...prev, id]
    );
  };

  const executeBatchTransfer = () => {
    if (!sourceClassId || !targetClassId || selectedStudentIds.length === 0) {
      alert("Vui lòng chọn đầy đủ lớp nguồn, lớp đích và ít nhất một học viên.");
      return;
    }

    if (sourceClassId === targetClassId) {
        alert("Lớp đích phải khác lớp nguồn!");
        return;
    }

    const targetClassName = classes.find(c => c.id === targetClassId)?.name;
    const confirmMsg = mode === 'PROMOTION' 
        ? `Xác nhận LÊN LỚP cho ${selectedStudentIds.length} học viên sang lớp ${targetClassName}?`
        : `Xác nhận CHUYỂN ${selectedStudentIds.length} học viên sang lớp ${targetClassName}?`;

    if (window.confirm(confirmMsg)) {
      // Logic: Update the global students array
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: targetClassId };
          }
          return s;
      });

      setStudents(updatedStudents);
      setSelectedStudentIds([]);
      showToast(`Hoàn tất! Đã cập nhật ${selectedStudentIds.length} học viên vào lớp ${targetClassName}.`);
    }
  };

  // --- Search & Single Placement Logic ---
  const [searchQuery, setSearchQuery] = useState('');
  const [searchedStudent, setSearchedStudent] = useState<Student | null>(null);
  const [singleTargetYearId, setSingleTargetYearId] = useState('');
  const [singleTargetGradeId, setSingleTargetGradeId] = useState('all');
  const [singleTargetClassId, setSingleTargetClassId] = useState('');

  const singleTargetClassesAvailable = useMemo(() => {
    if (singleTargetGradeId === 'all') return classes.filter(c => c.yearId === singleTargetYearId);
    return classes.filter(c => c.yearId === singleTargetYearId && c.gradeId === singleTargetGradeId);
  }, [classes, singleTargetYearId, singleTargetGradeId]);

  const handleSearch = () => {
    if (!searchQuery.trim()) return;
    const q = searchQuery.toLowerCase();
    const found = students.find(s => 
      s.fullName.toLowerCase().includes(q) ||
      s.saintName.toLowerCase().includes(q) ||
      s.id.toLowerCase() === q
    );

    if (found) {
        setSearchedStudent(found);
        const active = years.find(y => y.isActive);
        if(active) setSingleTargetYearId(active.id);
    } else {
        alert("Không tìm thấy học viên!");
    }
  };

  const executeSingleTransfer = () => {
    if (!searchedStudent || !singleTargetClassId) {
      alert("Vui lòng chọn lớp đích.");
      return;
    }

    const targetClass = classes.find(c => c.id === singleTargetClassId)?.name;
    if (window.confirm(`Xác nhận xếp em ${searchedStudent.saintName} ${searchedStudent.fullName} vào lớp ${targetClass}?`)) {
       const updatedStudents = students.map(s => {
           if (s.id === searchedStudent.id) {
               return { ...s, classId: singleTargetClassId };
           }
           return s;
       });
       setStudents(updatedStudents);
       setSearchedStudent({ ...searchedStudent, classId: singleTargetClassId });
       showToast(`Đã xếp em ${searchedStudent.fullName} vào lớp ${targetClass} thành công!`);
    }
  };

  const isBatchReady = selectedStudentIds.length > 0 && targetClassId && sourceClassId !== targetClassId;

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification Popup */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Điều Chuyển & Xếp Lớp</h2>
          <p className="text-sm text-slate-500">Quản lý hồ sơ học viên giữa các niên khóa và khối lớp</p>
        </div>
        <div className="bg-slate-200 p-1 rounded-xl flex gap-1 shadow-inner">
           <button onClick={() => setMode('TRANSFER')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${mode === 'TRANSFER' ? 'bg-white shadow-md text-blue-600' : 'text-slate-600 hover:bg-slate-300/50'}`}><Repeat size={16}/> Chuyển Lớp</button>
           <button onClick={() => setMode('PROMOTION')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${mode === 'PROMOTION' ? 'bg-white shadow-md text-green-600' : 'text-slate-600 hover:bg-slate-300/50'}`}><BookUp size={16}/> Lên Lớp</button>
           <button onClick={() => setMode('SEARCH')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${mode === 'SEARCH' ? 'bg-white shadow-md text-purple-600' : 'text-slate-600 hover:bg-slate-300/50'}`}><Search size={16}/> Xếp Lớp Lẻ</button>
        </div>
      </div>

      {mode !== 'SEARCH' ? (
        <div className="flex-1 flex gap-6 overflow-hidden">
          {/* LEFT: SOURCE PANEL */}
          <div className="flex-1 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col overflow-hidden">
            <div className="p-5 border-b border-slate-100 bg-slate-50/50 space-y-3">
              <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Lớp Nguồn (Dữ liệu gốc)</label>
              <div className="grid grid-cols-2 gap-3">
                 <div className="space-y-1">
                   <span className="text-[10px] text-slate-500 font-bold ml-1">Năm học</span>
                   <select className="w-full p-2 border rounded-lg text-sm bg-white shadow-sm outline-none focus:ring-2 focus:ring-blue-500" value={sourceYearId} onChange={e => {setSourceYearId(e.target.value); setSourceClassId('');}}>
                     {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                   </select>
                 </div>
                 <div className="space-y-1">
                   <span className="text-[10px] text-slate-500 font-bold ml-1">Khối lớp</span>
                   <select className="w-full p-2 border rounded-lg text-sm bg-white shadow-sm outline-none focus:ring-2 focus:ring-blue-500" value={sourceGradeId} onChange={e => {setSourceGradeId(e.target.value); setSourceClassId('');}}>
                     <option value="all">Tất cả Khối</option>
                     {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                   </select>
                 </div>
              </div>
              <div className="space-y-1">
                 <span className="text-[10px] text-slate-500 font-bold ml-1">Chọn lớp để chuyển</span>
                 <select className="w-full p-2.5 border rounded-xl text-sm bg-white font-bold text-slate-700 shadow-sm outline-none focus:ring-2 focus:ring-blue-500" value={sourceClassId} onChange={e => {setSourceClassId(e.target.value); setSelectedStudentIds([]);}}>
                   <option value="">-- Chọn Lớp --</option>
                   {sourceClassesAvailable.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                 </select>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
               {sourceClassId ? (
                 <table className="w-full text-left text-sm border-separate border-spacing-0">
                   <thead className="sticky top-0 bg-white z-10">
                     <tr className="text-slate-500 font-bold">
                        <th className="p-3 w-10 border-b"><input type="checkbox" className="w-4 h-4 rounded" onChange={handleSelectAll} checked={sourceStudents.length > 0 && selectedStudentIds.length === sourceStudents.length}/></th>
                        <th className="p-3 border-b">Học Viên ({sourceStudents.length})</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                     {sourceStudents.map(s => (
                       <tr key={s.id} className={`${selectedStudentIds.includes(s.id) ? 'bg-blue-50/50' : 'hover:bg-slate-50'} transition-all cursor-pointer`} onClick={() => handleCheckboxChange(s.id)}>
                         <td className="p-3" onClick={(e) => e.stopPropagation()}><input type="checkbox" className="w-4 h-4 rounded text-blue-600" checked={selectedStudentIds.includes(s.id)} onChange={() => handleCheckboxChange(s.id)}/></td>
                         <td className="p-3">
                           <div className="font-bold text-slate-800">{s.saintName} {s.fullName}</div>
