import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear } from '../types';
import { MOCK_GRADES } from '../constants';
import { ArrowRight, Search, CheckCircle2, Users, ArrowRightLeft, ArrowUpRight, GraduationCap, Filter, Globe, List } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
}

type Mode = 'TRANSFER' | 'PROMOTION';
type SearchMode = 'CLASS' | 'GLOBAL';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER'); 
  const [searchMode, setSearchMode] = useState<SearchMode>('CLASS');
  const [toast, setToast] = useState<string | null>(null);

  // === FILTER STATE ===
  // Source (Nguồn)
  const [srcYear, setSrcYear] = useState('');
  const [srcGrade, setSrcGrade] = useState('all');
  const [srcClassId, setSrcClassId] = useState('');
  const [srcSearch, setSrcSearch] = useState('');

  // Target (Đích)
  const [tgtYear, setTgtYear] = useState('');
  const [tgtGrade, setTgtGrade] = useState('all');
  const [tgtClassId, setTgtClassId] = useState('');

  // Selection
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Init default years
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;
    setSrcYear(active.id);
    setTgtYear(active.id); 
  }, [years]);

  // Reset selection when source changes
  useEffect(() => {
    setSelectedStudentIds([]);
  }, [srcClassId, searchMode]);

  // Logic to filter Source Classes
  const srcClasses = useMemo(() => {
    return classes.filter(c => c.yearId === srcYear && (srcGrade === 'all' || c.gradeId === srcGrade));
  }, [classes, srcYear, srcGrade]);

  // Logic to filter Target Classes
  const tgtClasses = useMemo(() => {
    return classes.filter(c => c.yearId === tgtYear && (tgtGrade === 'all' || c.gradeId === tgtGrade));
  }, [classes, tgtYear, tgtGrade]);

  // Students in Source
  const srcStudents = useMemo(() => {
    let list: Student[] = [];

    if (searchMode === 'CLASS') {
        if (!srcClassId) return [];
        list = students.filter(s => s.classId === srcClassId);
    } else {
        // GLOBAL SEARCH MODE
        // Only show if user has typed something to avoid massive list
        if (!srcSearch) return [];
        list = students; // Will filter below
    }

    if (srcSearch) {
        const q = srcSearch.toLowerCase();
        list = list.filter(s => s.fullName.toLowerCase().includes(q) || s.saintName.toLowerCase().includes(q) || s.id.toLowerCase().includes(q));
    }

    // Sort primarily by name
    return list.slice(0, 100); // Limit results for performance if global
  }, [students, srcClassId, srcSearch, searchMode]);

  // Students in Target Class (for preview)
  const tgtStudents = useMemo(() => {
    if (!tgtClassId) return [];
    return students.filter(s => s.classId === tgtClassId);
  }, [students, tgtClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
        setSelectedStudentIds(srcStudents.map(s => s.id));
    } else {
        setSelectedStudentIds([]);
    }
  };

  const toggleSelect = (id: string) => {
      setSelectedStudentIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const handleExecute = () => {
      if (selectedStudentIds.length === 0) return alert("Chưa chọn học viên nào!");
      if (!tgtClassId) return alert("Chưa chọn lớp đích!");

      const tgtClass = classes.find(c => c.id === tgtClassId);

      if (window.confirm(`Bạn có chắc muốn chuyển ${selectedStudentIds.length} học viên sang lớp ${tgtClass?.name}?`)) {
          const updatedStudents = students.map(s => {
              if (selectedStudentIds.includes(s.id)) {
                  return { ...s, classId: tgtClassId };
              }
              return s;
          });
          setStudents(updatedStudents);
          setToast(`Đã chuyển thành công ${selectedStudentIds.length} học viên!`);
          setSelectedStudentIds([]);
          // If in global search mode, clear search to reset view
          if (searchMode === 'GLOBAL') {
             // Optional: keep search to continue working or clear? Let's keep it.
          }
      }
  };

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Chưa xếp lớp';

  return (
    <div className="p-6 h-screen flex flex-col bg-slate-100 relative">
       {/* Toast */}
       {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Điều Chuyển</h2>
            <p className="text-slate-500 text-sm">Quản lý danh sách học viên giữa các lớp</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg shadow-sm border border-slate-200">
            <button 
                onClick={() => setMode('TRANSFER')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'TRANSFER' ? 'bg-blue-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowRightLeft size={16} /> Chuyển Lớp (Trong năm)
            </button>
            <button 
                onClick={() => setMode('PROMOTION')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'PROMOTION' ? 'bg-green-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowUpRight size={16} /> Lên Lớp (Niên khóa mới)
            </button>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="flex flex-1 gap-6 overflow-hidden">

          {/* LEFT: SOURCE */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
              <div className="bg-slate-50 border-b border-slate-200">
                  <div className="flex border-b border-slate-200">
                      <button 
                        onClick={() => setSearchMode('CLASS')}
                        className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'CLASS' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <List size={14}/> Theo Lớp
                      </button>
                      <button 
                         onClick={() => setSearchMode('GLOBAL')}
                         className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'GLOBAL' ? 'bg-white text-purple-600 border-b-2 border-purple-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <Globe size={14}/> Tìm Học Viên
                      </button>
                  </div>

                  <div className="p-4">
                    {searchMode === 'CLASS' ? (
                        <div className="space-y-2">
                             <div className="grid grid-cols-2 gap-2">
                                <select className="input-select" value={srcYear} onChange={e => setSrcYear(e.target.value)}>
                                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                                </select>
                                <select className="input-select" value={srcGrade} onChange={e => setSrcGrade(e.target.value)}>
                                    <option value="all">Tất cả Khối</option>
                                    {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                </select>
                            </div>
                            <select className={`input-select w-full font-bold ${srcClassId ? 'text-slate-800' : 'text-slate-400'}`} value={srcClassId} onChange={e => setSrcClassId(e.target.value)}>
                                <option value="">-- Chọn Lớp Nguồn --</option>
                                {srcClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    ) : (
                        <div className="relative">
                            <input 
                                type="text" 
                                placeholder="Nhập tên học viên để tìm..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border border-purple-300 rounded-lg bg-white focus:ring-2 focus:ring-purple-200 outline-none"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                                autoFocus
                            />
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-purple-400" size={16}/>
                            <div className="text-[10px] text-slate-400 mt-1 italic text-right">*Tìm trong toàn bộ hệ thống</div>
                        </div>
                    )}
                  </div>
              </div>

              {/* Source List */}
              <div className="flex-1 flex flex-col overflow-hidden relative">
                 {searchMode === 'CLASS' && srcClassId && (
                     <div className="p-2 border-b border-slate-100 sticky top-0 bg-white z-10">
                         <div className="relative">
                             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                             <input 
                                type="text" 
                                placeholder="Lọc tên trong lớp này..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border rounded-lg bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-100"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                             />
                         </div>
                     </div>
                 )}

                 <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {(searchMode === 'GLOBAL' && srcSearch) || (searchMode === 'CLASS' && srcClassId) ? (
                         srcStudents.length > 0 ? (
                             <div className="space-y-1">
                                 <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg mb-2">
                                     <input type="checkbox" className="w-4 h-4 rounded cursor-pointer" onChange={handleSelectAll} checked={srcStudents.length > 0 && selectedStudentIds.length === srcStudents.length}/>
                                     <span className="text-sm font-bold text-slate-600">Chọn tất cả ({srcStudents.length})</span>
                                 </div>
                                 {srcStudents.map(s => (
                                     <div 
                                        key={s.id} 
                                        onClick={() => toggleSelect(s.id)}
                                        className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all ${selectedStudentIds.includes(s.id) ? 'bg-blue-50 border-blue-300 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
                                     >
                                         <input type="checkbox" className="w-4 h-4 rounded cursor-pointer" checked={selectedStudentIds.includes(s.id)} onChange={() => toggleSelect(s.id)} />
                                         <div className="flex-1">
                                             <div className="flex justify-between">
                                                <div className="text-sm font-bold text-slate-800">{s.saintName} {s.fullName}</div>
                                                {searchMode === 'GLOBAL' && <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-medium">{getClassName(s.classId)}</span>}
                                             </div>
                                             <div className="text-[10px] text-slate-400 font-mono">{s.id} - {new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                                         </div>
                                     </div>
                                 ))}
                             </div>
                         ) : (
                             <div className="h-full flex flex-col items-center justify-center text-slate-400">
                                 <span className="text-sm italic">Không tìm thấy học viên</span>
                             </div>
                         )
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <GraduationCap size={48} className="mb-2"/>
                             <span className="text-sm font-medium">
                                 {searchMode === 'CLASS' ? 'Vui lòng chọn lớp nguồn' : 'Nhập tên để tìm kiếm'}
                             </span>
                         </div>
                     )}
                 </div>
              </div>
              <div className="p-3 bg-slate-50 border-t border-slate-200 text-xs font-bold text-slate-500 text-right">
                  Đã chọn: {selectedStudentIds.length} / {srcStudents.length}
              </div>
          </div>

          {/* MIDDLE: ACTIONS */}
          <div className="flex flex-col items-center justify-center gap-4">
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
              <button 
                onClick={handleExecute}
                disabled={selectedStudentIds.length === 0 || !tgtClassId}
                className={`w-14 h-14 rounded-full flex items-center justify-center shadow-lg transition-all transform hover:scale-110 active:scale-95 ${selectedStudentIds.length > 0 && tgtClassId ? 'bg-blue-600 text-white cursor-pointer' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                title="Thực hiện chuyển lớp"
              >
                  <ArrowRight size={24} />
              </button>
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
          </div>

          {/* RIGHT: TARGET */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
             <div className={`p-4 border-b border-slate-200 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
                  <div className={`flex items-center gap-2 mb-3 font-bold uppercase text-xs tracking-wider ${mode === 'PROMOTION' ? 'text-green-800' : 'text-blue-800'}`}>
                      <Users size={14}/> Lớp Đích
                  </div>
                  <div className="grid grid-cols-2 gap-2 mb-2">
                      <select className="input-select" value={tgtYear} onChange={e => setTgtYear(e.target.value)}>
                          {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                      </select>
                      <select className="input-select" value={tgtGrade} onChange={e => setTgtGrade(e.target.value)}>
                          <option value="all">Tất cả Khối</option>
                          {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                      </select>
                  </div>
                  <select className={`input-select w-full font-bold ${tgtClassId ? 'text-slate-800' : 'text-slate-400'} ${mode === 'PROMOTION' ? 'focus:ring-green-500' : 'focus:ring-blue-500'}`} value={tgtClassId} onChange={e => setTgtClassId(e.target.value)}>
                      <option value="">-- Chọn Lớp Đích --</option>
                      {tgtClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
              </div>

              {/* Target Preview List */}
              <div className="flex-1 flex flex-col overflow-hidden bg-slate-50/30">
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {tgtClassId ? (
                         <div className="space-y-1">
                             <div className="text-xs font-bold text-slate-400 uppercase p-2">Danh sách hiện tại ({tgtStudents.length})</div>
                             {tgtStudents.map((s, idx) => (
                                 <div key={s.id} className="flex items-center justify-between p-3 bg-white rounded-lg border border-slate-100">
                                     <div className="flex items-center gap-3">
                                         <span className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center text-[10px] text-slate-500 font-bold">{idx + 1}</span>
                                         <div>
                                             <div className="text-sm font-medium text-slate-700">{s.saintName} {s.fullName}</div>
                                         </div>
                                     </div>
                                 </div>
                             ))}
                             {tgtStudents.length === 0 && <div className="p-8 text-center text-sm text-slate-400 italic">Lớp chưa có học viên</div>}
                         </div>
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <Users size={48} className="mb-2"/>
                             <span className="text-sm font-medium">Vui lòng chọn lớp đích</span>
                         </div>
                     )}
                  </div>
              </div>
          </div>

      </div>

      <style>{`
        .input-select {
            width: 100%;
            padding: 0.5rem;
            border-radius: 0.5rem;
            border: 1px solid #cbd5e1;
            font-size: 0.875rem;
            outline: none;
            transition: all 0.2s;
        }
        .input-select:focus {
            border-color: #3b82f6;
            box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
        }
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear, AcademicRecord } from '../types';
import { Search, Plus, Edit, Trash2, X, Calendar, Printer, FileSpreadsheet, AlertTriangle, Save, User, MapPin, Phone, Users, CheckCircle2, History, GitMerge, AlertCircle, ScrollText, GraduationCap } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = students.filter(student => {
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const handleSaveStudent = () => {
    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }
    showToast(selectedStudent ? "Đã cập nhật thông tin học viên thành công!" : "Đã thêm học viên mới thành công!");
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  // --- DEDUPLICATION LOGIC ---
  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};

      students.forEach(s => {
          // Key based on Name + DOB
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });

      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) {
              duplicates.push({ key, students: groups[key] });
          }
      });

      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      // Keep survivor, delete others
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;

      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);

      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); // Remove processed group from list
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  // --- HISTORY LOGIC ---
  const getStudentHistory = (studentId: string) => {
    // In a real app, this would query a backend for past years. 
    // Here we construct it from current records and active classes
    const studentRecords = records.filter(r => r.studentId === studentId);

    // Group records by context (we assume records belong to the active year for simplicity in this mock, 
    // but in a real app, AcademicRecord would have a yearId)
    // We will simulate a history entry
    const history = [];

    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);

        // Find current class
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';

        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }

    // Mocking a past record for demonstration
    history.push({
        year: 'Năm học 2022 - 2023',
        className: 'Khai Tâm 1',
        hk1: 8.5,
        hk2: 9.0,
        final: 8.8,
        rank: 'Giỏi'
    });

    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-3 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={16} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b">
              <tr>
                <th className="p-4 w-12 text-center">STT</th>
                <th className="p-4">Tên Thánh & Họ Tên</th>
                <th className="p-4">Ngày Sinh</th>
                <th className="p-4">Phụ Huynh</th>
                <th className="p-4">Liên Hệ (SĐT)</th>
                <th className="p-4">Lớp</th>
                <th className="p-4">Ghi chú</th>
                <th className="p-4 text-center w-24">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4">
                    <div className="font-bold text-slate-700">{s.saintName}</div>
                    <div className="text-base font-bold text-slate-800">{s.fullName}</div>
                    <div className="text-xs text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'} - {s.id}</div>
                  </td>
                  <td className="p-4">
                    <div className="text-slate-700">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div><span className="text-xs font-semibold text-slate-400">B:</span> {s.fatherName}</div>
                    <div><span className="text-xs font-semibold text-slate-400">M:</span> {s.motherName}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div>{s.fatherPhone}</div>
                    <div>{s.motherPhone}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="p-4 italic text-slate-500 max-w-xs truncate">{s.note}</td>
                  <td className="p-4 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={8} className="p-8 text-center text-slate-400 italic">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 text-right">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-[90rem] h-[90vh] flex flex-col animate-fade-in overflow-hidden">

            {/* Modal Header */}
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-lg shadow">
                    {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus />}
                 </div>
                 <div>
                    <h3 className="font-bold text-lg text-slate-800">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-xs text-slate-500 font-mono">{selectedStudent.id}</p>}
                 </div>
              </div>
              <div className="flex gap-2">
