import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_GRADES, MOCK_TEACHERS } from '../constants';
import { ClassRoom, SchoolYear, Student } from '../types';
import { Users, User, UserCheck, Edit, X, Save, CheckCircle2, Search } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  // State for Main Teacher Autocomplete
  const [mainTeacherInput, setMainTeacherInput] = useState('');
  const [showMainTeacherSuggestions, setShowMainTeacherSuggestions] = useState(false);

  // State for Assistants Autocomplete (3 slots)
  const [assistants, setAssistants] = useState<string[]>(['', '', '']);
  const [showAssistSuggestions, setShowAssistSuggestions] = useState<boolean[]>([false, false, false]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  // Sync internal assistant states when editingClass changes
  useEffect(() => {
    if (editingClass) {
        // Split by comma
        const parts = editingClass.assistants ? editingClass.assistants.split(',').map(s => s.trim()) : [];
        setAssistants([parts[0] || '', parts[1] || '', parts[2] || '']);
        setMainTeacherInput(editingClass.mainTeacher || '');
    }
  }, [editingClass]);

  const filteredClasses = useMemo(() => {
      return classes.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [classes, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        // Combine assistants back into one string
        const combinedAssistants = assistants
            .map(s => s.trim())
            .filter(s => s !== '')
            .join(', ');

        const finalClassData = { 
            ...editingClass, 
            mainTeacher: mainTeacherInput, // Use input value
            assistants: combinedAssistants 
        };

        const updatedClasses = classes.map(c => c.id === editingClass.id ? finalClassData : c);
        setClasses(updatedClasses);
        showToast(`Đã cập nhật thông tin lớp ${editingClass.name} thành công!`);
        setEditingClass(null);
    }
  };

  // Sort teachers alphabetically for easier selection
  const sortedTeachers = useMemo(() => {
      return [...MOCK_TEACHERS].sort((a, b) => a.fullName.localeCompare(b.fullName));
  }, []);

  // Filter helper for Autocomplete
  const getFilteredTeachers = (input: string) => {
      if (!input) return sortedTeachers;
      const lowerInput = input.toLowerCase();
      return sortedTeachers.filter(t => 
          t.fullName.toLowerCase().includes(lowerInput) || 
          t.saintName.toLowerCase().includes(lowerInput)
      );
  };

  const filteredMainTeacherSuggestions = useMemo(() => getFilteredTeachers(mainTeacherInput), [mainTeacherInput, sortedTeachers]);

  const updateAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = true;
      setShowAssistSuggestions(newShow);
  };

  const selectAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = false;
      setShowAssistSuggestions(newShow);
  }

  const toggleAssistSuggestion = (index: number, status: boolean) => {
      const newShow = [...showAssistSuggestions];
      newShow[index] = status;
      setShowAssistSuggestions(newShow);
  }

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2 border rounded-lg bg-white font-medium min-w-[150px]"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2 border rounded-lg bg-white min-w-[150px]"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                         <th className="p-4 w-12 text-center">STT</th>
                         <th className="p-4">Tên Lớp</th>
                         <th className="p-4">Khối</th>
                         <th className="p-4 text-center">Sĩ số</th>
                         <th className="p-4 text-center">Nam</th>
                         <th className="p-4 text-center">Nữ</th>
                         <th className="p-4 text-center">Phòng Học</th>
                         <th className="p-4">GLV Chủ Nhiệm</th>
                         <th className="p-4">GLV Phụ Trách</th>
                         <th className="p-4 w-16 text-center"></th>
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = MOCK_GRADES.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50">
                                     <td className="p-4 text-center text-slate-500">{index + 1}</td>
                                     <td className="p-4 font-bold text-slate-800">{c.name}</td>
                                     <td className="p-4 text-slate-600 text-sm">{gradeName}</td>
                                     <td className="p-4 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.male}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.female}</td>
                                     <td className="p-4 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="p-4 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="p-4 text-sm text-slate-600 max-w-xs truncate" title={c.assistants}>{c.assistants || '---'}</td>
                                     <td className="p-4 text-center">
                                         <button onClick={() => handleEditClass(c)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                             <Edit size={16} />
                                         </button>
                                     </td>
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={10} className="p-8 text-center text-slate-400">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-6 justify-end text-sm font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={16}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={16}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={16}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {editingClass && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in flex flex-col max-h-[90vh]">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-lg text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                </div>
                <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg bg-slate-100 text-slate-500" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>

                    {/* Autocomplete for Main Teacher */}
                    <div className="relative">
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Chủ Nhiệm</label>
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full p-2 pl-3 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={mainTeacherInput}
                                onChange={(e) => {
                                    setMainTeacherInput(e.target.value);
                                    setShowMainTeacherSuggestions(true);
                                }}
                                onFocus={() => setShowMainTeacherSuggestions(true)}
                                onBlur={() => setTimeout(() => setShowMainTeacherSuggestions(false), 200)}
                                placeholder="Nhập tên GLV..."
                            />
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        </div>
                        {showMainTeacherSuggestions && (
                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                {filteredMainTeacherSuggestions.length > 0 ? (
                                    filteredMainTeacherSuggestions.map(t => (
                                        <div 
                                            key={t.id}
                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                            onClick={() => {
                                                setMainTeacherInput(`${t.saintName} ${t.fullName}`);
                                                setShowMainTeacherSuggestions(false);
                                            }}
                                        >
                                            <span>{t.saintName} {t.fullName}</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="p-3 text-xs text-slate-400 text-center italic">Không tìm thấy GLV phù hợp</div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* GLV Phụ Trách - 3 Autocomplete Inputs */}
                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                        <label className="block text-sm font-bold text-slate-700 mb-2">GLV Phụ Trách</label>
                        <div className="space-y-3">
                             {assistants.map((val, idx) => {
                                const suggestions = getFilteredTeachers(val);
                                return (
                                    <div key={idx} className="relative">
                                        <div className="relative">
                                            <input 
                                                type="text"
                                                className="w-full p-2 pl-3 pr-8 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm bg-white"
                                                placeholder={`GLV Phụ trách ${idx + 1}`}
                                                value={val}
                                                onChange={(e) => updateAssistant(idx, e.target.value)}
                                                onFocus={() => toggleAssistSuggestion(idx, true)}
                                                onBlur={() => setTimeout(() => toggleAssistSuggestion(idx, false), 200)}
                                            />
                                             <Search className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                                        </div>
                                        {showAssistSuggestions[idx] && (
                                            <div className="absolute z-20 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {suggestions.length > 0 ? (
                                                    suggestions.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                                            onClick={() => selectAssistant(idx, `${t.saintName} ${t.fullName}`)}
                                                        >
                                                            <span>{t.saintName} {t.fullName}</span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="p-2 text-xs text-slate-400 text-center italic">Không tìm thấy</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                             })}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3 mt-auto">
                    <button onClick={() => setEditingClass(null)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium">Hủy</button>
                    <button onClick={handleSaveClass} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { CheckCircle2 } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');

  // Month selection (YYYY-MM)
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);

  // Helper to get Sundays in the selected month
  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];

      // Move to first day of next month to loop backwards or loop forward
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleSave = () => {
      // Mock save action
      showToast("Đã lưu dữ liệu điểm danh thành công!");
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Danh Chuyên Cần</h2>
        <div className="text-sm text-slate-500">Giáo lý viên chịu trách nhiệm điểm danh trước giờ học</div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center flex-wrap">

        <select 
          className="px-3 py-2 border rounded-lg min-w-[140px] text-sm"
          value={selectedYear}
          onChange={(e) => setSelectedYear(e.target.value)}
        >
          {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
        </select>

        <select 
          className="px-3 py-2 border rounded-lg min-w-[140px] text-sm"
          value={selectedGrade}
          onChange={(e) => setSelectedGrade(e.target.value)}
        >
          <option value="all">Tất cả Khối</option>
          {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
        </select>

        <select 
          className="px-3 py-2 border rounded-lg min-w-[180px] text-sm"
          value={selectedClass}
          onChange={(e) => setSelectedClass(e.target.value)}
        >
          {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          {availableClasses.length === 0 && <option value="">Không có lớp</option>}
        </select>

        <div className="flex items-center gap-2 border-l pl-4 ml-2">
            <label className="text-sm font-bold text-slate-600">Tháng:</label>
            <input 
              type="month" 
              className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-medium"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
            />
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse">
             <thead>
               <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                 <th className="p-4 w-12 text-center sticky left-0 bg-slate-50 z-10">STT</th>
                 <th className="p-4 min-w-[200px] sticky left-12 bg-slate-50 z-10 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => (
                    <th key={idx} className="p-4 text-center border-l min-w-[100px]">
                        <div className="flex flex-col">
                            <span className="font-bold text-blue-600">CN {idx + 1}</span>
                            <span className="text-xs font-normal text-slate-500">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                        </div>
                    </th>
                 ))}
                 <th className="p-4 text-center border-l">Ghi chú</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-slate-50 group">
                   <td className="p-4 text-center text-slate-500 sticky left-0 bg-white group-hover:bg-slate-50 z-10">{idx + 1}</td>
                   <td className="p-4 sticky left-12 bg-white group-hover:bg-slate-50 z-10 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-medium text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => (
                       <td key={i} className="p-4 border-l text-center">
                           {/* Mock Attendance Checkbox - In real app, bind to specific record for date */}
                           <input 
                              type="checkbox" 
                              className="w-5 h-5 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                           />
                       </td>
                   ))}

                   <td className="p-4 border-l">
                     <input type="text" className="w-full bg-transparent border-b border-dashed border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-xs py-1" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length + 3} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để hiển thị danh sách</td></tr>
               )}
             </tbody>
           </table>
        </div>
        <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium flex items-center gap-2 ml-auto">
                 <CheckCircle2 size={18}/> Lưu Điểm Danh
             </button>
        </div>
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, FileSpreadsheet, Trophy, ListChecks, ArrowLeft, ArrowRight } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [term, setTerm] = useState<'HK1' | 'HK2' | 'YEAR'>('HK1');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Default columns now include Thi (Exam) x3
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 },
    { id: 'col_exam', name: "Thi", weight: 3 },
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, field: string, value: string) => {
    if (term === 'YEAR') return;
    const numValue = parseFloat(value) || 0;
    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            // Update dynamic scores
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term as 'HK1'|'HK2', scores: {}, scorePray: 0, scoreExam: 0, average: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      testColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { 
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      // Removed hardcoded scoreExam check since it is now in testColumns
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     if (term === 'YEAR') return;
     const updatedRecords = records.map(r => {
         if (r.term === term && filteredStudents.some(s => s.id === r.studentId)) {
             return { ...r, average: calculateAvg(r) };
         }
         return r;
     });
     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
    showToast("Đã xóa cột điểm thành công!");
  };

  const moveColumn = (index: number, direction: 'left' | 'right') => {
    if (direction === 'left' && index > 0) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index - 1];
      newCols[index - 1] = temp;
      setTestColumns(newCols);
    } else if (direction === 'right' && index < testColumns.length - 1) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index + 1];
      newCols[index + 1] = temp;
      setTestColumns(newCols);
    }
  };

  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    const finalAvg = (r1.average > 0 && r2.average > 0) ? (r1.average + r2.average) / 2 : 0;
    return { ...s, avg1: r1.average, avg2: r2.average, avgYear: finalAvg, rank: getRank(finalAvg), isPassed: finalAvg >= 5.0 };
  }).sort((a, b) => b.avgYear - a.avgYear).map((s, index) => ({...s, ranking: index + 1}));

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border rounded-lg min-w-[160px] text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
          <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm" value={term} onChange={(e) => setTerm(e.target.value as any)}><option value="HK1">Học Kỳ 1</option><option value="HK2">Học Kỳ 2</option><option value="YEAR">Cả Năm</option></select>
        </div>
        <div className="flex items-center gap-2">
            {term !== 'YEAR' && viewMode === 'entry' && (<>{showAddColumn ? (<div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in"><input type="text" placeholder="Tên cột" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/><select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}><option value={0}>x0</option><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select><button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button><button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button></div>) : (<button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"><Plus size={16} /> Thêm Cột</button>)}</>)}
             <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50"><FileSpreadsheet size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (<><div className="overflow-x-auto custom-scrollbar"><table className="w-full text-left border-collapse"><thead><tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200"><th className="p-4 w-16 text-center sticky left-0 bg-slate-50 z-10">STT</th><th className="p-4 min-w-[200px] sticky left-16 bg-slate-50 z-10">Học Viên</th>{term === 'YEAR' ? (<><th className="p-4 text-center border-l bg-slate-50">ĐTB HK1</th><th className="p-4 text-center border-l bg-slate-50">ĐTB HK2</th><th className="p-4 text-center border-l bg-blue-100 font-bold text-blue-800">ĐTB Cả Năm</th><th className="p-4 text-center border-l">Xếp loại</th><th className="p-4 text-center border-l">Hạng</th></>) : (<>{testColumns.map((col, idx) => (<th key={col.id} className="p-4 w-32 text-center border-l bg-slate-50 group relative"><div className="flex flex-col items-center"><span>{col.name}</span><span className="text-[10px] text-slate-400 font-normal">Hệ số {col.weight}</span></div><div className="absolute inset-x-0 bottom-0 flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pb-1">{idx > 0 && <button onClick={() => moveColumn(idx, 'left')} className="p-1 hover:bg-slate-200 rounded"><ArrowLeft size={10}/></button>}{idx < testColumns.length - 1 && <button onClick={() => moveColumn(idx, 'right')} className="p-1 hover:bg-slate-200 rounded"><ArrowRight size={10}/></button>}</div><button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={12} /></button></th>))}<th className="p-4 w-24 text-center border-l bg-blue-50 font-bold text-blue-700">TB</th><th className="p-4 w-32 text-center border-l">Xếp loại</th></>)}</tr></thead><tbody className="divide-y divide-slate-100">{filteredStudents.length > 0 ? (term === 'YEAR' ? processedStudentsYear.map((s, idx) => (<tr key={s.id} className="hover:bg-slate-50 group"><td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td><td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td><td className="p-4 text-center border-l text-slate-500">{s.avg1 || '-'}</td><td className="p-4 text-center border-l text-slate-500">{s.avg2 || '-'}</td><td className="p-4 text-center border-l font-bold text-blue-700 bg-blue-50/30">{s.avgYear.toFixed(1)}</td><td className="p-4 text-center border-l"><span className={`px-2 py-1 rounded text-xs font-bold ${s.rank.color}`}>{s.rank.label}</span></td><td className="p-4 text-center border-l font-mono font-bold text-slate-600">{s.ranking <= 3 ? <span className="flex items-center justify-center gap-1 text-yellow-600"><Trophy size={14}/> {s.ranking}</span> : s.ranking}</td></tr>)) : filteredStudents.map((s, idx) => {const r = getRecord(s.id, term as 'HK1' | 'HK2'); const rank = getRank(r.average); return (<tr key={s.id} className="hover:bg-slate-50 group"><td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50">{idx + 1}</td><td className="p-4 font-medium sticky left-16 bg-white group-hover:bg-slate-50">{s.saintName} {s.fullName}</td>{testColumns.map(col => (<td key={col.id} className="p-2 border-l text-center"><input type="number" value={r.scores ? r.scores[col.id] || '' : ''} onChange={(e) => handleScoreChange(s.id, col.id, e.target.value)} className="w-full text-center p-2 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none transition-all" /></td>))}<td className="p-4 border-l text-center font-bold text-slate-800 bg-blue-50/20">{r.average > 0 ? r.average : '-'}</td><td className="p-4 border-l text-center">{r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rank.color}`}>{rank.label}</span>}</td></tr>);})) : (<tr><td colSpan={10} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để xem bảng điểm</td></tr>)}</tbody></table></div>{term !== 'YEAR' && filteredStudents.length > 0 && (<div className="p-4 border-t border-slate-200 bg-slate-50 text-right"><button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium"><Save size={18} /> Lưu Bảng Điểm</button></div>)}</>) : (<div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50"><div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6"><div className="flex justify-between items-start"><div><h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3><div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div></div><div className="text-right"><div className="text-sm text-slate-500">Sĩ số</div><div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div></div></div></div><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden"><div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center"><div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div><span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{passedStudents.map(s => (<tr key={s.id} className="hover:bg-green-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{passedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>)}</tbody></table></div></div><div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden"><div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center"><div className="flex items-center gap-2"><XCircle className="text-red-600" /><h4 className="font-bold text-red-800">Danh Sách Ở Lại Lớp</h4></div><span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">{failedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{failedStudents.map(s => (<tr key={s.id} className="hover:bg-red-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-red-600">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{failedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Không có học viên ở lại lớp</td></tr>)}</tbody></table></div></div></div></div>)}
