import React, { useState } from 'react';
import { Wallet, TrendingUp, TrendingDown, Plus, Minus, PieChart as PieChartIcon, FileSpreadsheet } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Transaction } from '../types';

interface FinanceProps {
    transactions: Transaction[];
    setTransactions: (t: Transaction[]) => void;
}

export const Finance: React.FC<FinanceProps> = ({ transactions, setTransactions }) => {
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [note, setNote] = useState('');
  const [type, setType] = useState<'INCOME'|'EXPENSE'>('INCOME');

  const totalIncome = transactions.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const data = [
    { name: 'Tổng Thu', value: totalIncome },
    { name: 'Tổng Chi', value: totalExpense },
  ];
  const COLORS = ['#10b981', '#ef4444'];

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
  };

  const handleAddTransaction = () => {
      if (!amount || !description) return alert("Vui lòng nhập số tiền và nội dung");

      const newTx: Transaction = {
          id: `T${Date.now()}`,
          date: new Date().toISOString().split('T')[0],
          type: type,
          amount: parseFloat(amount),
          description: description,
          note: note
      };

      setTransactions([newTx, ...transactions]);

      // Reset form
      setAmount('');
      setDescription('');
      setNote('');
  };

  const handleExportExcel = () => {
    // Generate CSV content
    const headers = ["ID", "Ngày", "Loại", "Số tiền", "Nội dung", "Ghi chú"];
    const rows = transactions.map(t => [
      t.id,
      t.date,
      t.type === 'INCOME' ? 'THU' : 'CHI',
      t.amount,
      `"${t.description}"`, // Quote strings to handle commas
      `"${t.note || ''}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "so_quy_giao_ly.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen overflow-y-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Thủ Quỹ & Tài Chính</h2>
        <button 
          onClick={handleExportExcel}
          className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg shadow hover:bg-green-700 transition-colors"
        >
          <FileSpreadsheet size={18} /> Xuất Excel
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Wallet className="absolute right-4 top-4 opacity-20 w-24 h-24" />
          <p className="text-blue-100 mb-1">Tổng quỹ hiện tại</p>
          <h3 className="text-3xl font-bold">{formatCurrency(balance)}</h3>
          <p className="text-xs text-blue-200 mt-4 opacity-80">Cập nhật lần cuối: Hôm nay</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-green-100 rounded-lg text-green-600">
               <TrendingUp size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Thu (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalIncome)}</h3>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 rounded-lg text-red-600">
               <TrendingDown size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Chi (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalExpense)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Form and Chart */}
        <div className="lg:col-span-1 space-y-8">
            {/* Chart */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-80 flex flex-col">
              <div className="flex items-center gap-2 mb-2">
                <PieChartIcon className="text-slate-400" size={20} />
                <h3 className="font-bold text-lg text-slate-800">Biểu Đồ Thu Chi</h3>
              </div>
              <div className="flex-1 w-full h-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={data}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {data.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => formatCurrency(value as number)} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Transaction Form */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h3 className="font-bold text-lg mb-4 text-slate-800">Tạo Giao Dịch Mới</h3>
            <div className="space-y-4">
                <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
                <button 
                    onClick={() => setType('INCOME')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'INCOME' ? 'bg-white text-green-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Plus size={16}/> Thu
                </button>
                <button 
                    onClick={() => setType('EXPENSE')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'EXPENSE' ? 'bg-white text-red-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Minus size={16}/> Chi
                </button>
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Số tiền (VND)</label>
                <input 
                    type="number" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="0" 
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nội dung <span className="text-red-500">*</span></label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="VD: Thu tiền sách..." 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
                <textarea 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24" 
                    placeholder="..." 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                ></textarea>
                </div>

                <button 
                    onClick={handleAddTransaction}
                    className="w-full py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 shadow-lg shadow-blue-200"
                >
                Lưu Giao Dịch
                </button>
            </div>
            </div>
        </div>

        {/* History Table */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
          <div className="p-4 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-lg text-slate-800">Lịch Sử Giao Dịch</h3>
            <button className="text-sm text-blue-600 hover:underline">Xem báo cáo chi tiết</button>
          </div>
          <div className="overflow-x-auto max-h-[800px] custom-scrollbar">
            <table className="w-full text-left">
              <thead className="sticky top-0 bg-white shadow-sm">
                <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                  <th className="p-4">Ngày</th>
                  <th className="p-4">Nội dung</th>
                  <th className="p-4 text-right">Số tiền</th>
                  <th className="p-4 text-center">Loại</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {transactions.map((t) => (
                  <tr key={t.id} className="hover:bg-slate-50">
                    <td className="p-4 text-slate-500 text-sm">{t.date}</td>
                    <td className="p-4">
                      <div className="font-medium text-slate-800">{t.description}</div>
                      <div className="text-xs text-slate-400">{t.note}</div>
                    </td>
                    <td className="p-4 text-right font-mono font-medium">
                      {formatCurrency(t.amount)}
                    </td>
                    <td className="p-4 text-center">
                       {t.type === 'INCOME' ? (
                         <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs font-bold">THU</span>
                       ) : (
                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">CHI</span>
                       )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear } from '../types';
import { CheckCircle2, Church, BookOpen } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
}

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');

  // Month selection (YYYY-MM)
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);

  // Helper to get Sundays in the selected month
  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];

      // Move to first day of next month to loop backwards or loop forward
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleSave = () => {
      // Mock save action
      showToast("Đã lưu dữ liệu điểm danh thành công!");
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Danh Chuyên Cần</h2>
        <div className="text-sm text-slate-500">Giáo lý viên chịu trách nhiệm điểm danh trước giờ học</div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center flex-wrap">

        <select 
          className="px-3 py-2 border rounded-lg min-w-[140px] text-sm"
          value={selectedYear}
          onChange={(e) => setSelectedYear(e.target.value)}
        >
          {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
        </select>

        <select 
          className="px-3 py-2 border rounded-lg min-w-[140px] text-sm"
          value={selectedGrade}
          onChange={(e) => setSelectedGrade(e.target.value)}
        >
          <option value="all">Tất cả Khối</option>
          {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
        </select>

        <select 
          className="px-3 py-2 border rounded-lg min-w-[180px] text-sm"
          value={selectedClass}
          onChange={(e) => setSelectedClass(e.target.value)}
        >
          {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          {availableClasses.length === 0 && <option value="">Không có lớp</option>}
        </select>

        <div className="flex items-center gap-2 border-l pl-4 ml-2">
            <label className="text-sm font-bold text-slate-600">Tháng:</label>
            <input 
              type="month" 
              className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-medium"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
            />
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-50 text-slate-600 text-sm">
                 <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-50 z-20 border-b border-r border-slate-200">STT</th>
                 <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-50 z-20 border-b border-r border-slate-200 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => (
                    <th key={idx} colSpan={2} className="p-2 text-center border-b border-r border-slate-200">
                        <div className="flex flex-col">
                            <span className="font-bold text-blue-600">CN {idx + 1}</span>
                            <span className="text-[10px] font-normal text-slate-500">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                        </div>
                    </th>
                 ))}
                 <th rowSpan={2} className="p-4 text-center border-b border-slate-200 min-w-[150px]">Ghi chú</th>
               </tr>
               <tr className="bg-slate-50 text-slate-500 text-xs">
                    {sundaysInMonth.map((_, idx) => (
                        <React.Fragment key={idx}>
                            <th className="p-2 text-center border-b border-r border-slate-200 bg-slate-50 min-w-[40px]" title="Đi Lễ">
                                <Church size={14} className="mx-auto text-purple-600"/>
                            </th>
                            <th className="p-2 text-center border-b border-r border-slate-200 bg-slate-50 min-w-[40px]" title="Học Giáo Lý">
                                <BookOpen size={14} className="mx-auto text-blue-600"/>
                            </th>
                        </React.Fragment>
                    ))}
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-slate-50 group">
                   <td className="p-4 text-center text-slate-500 sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100">{idx + 1}</td>
                   <td className="p-4 sticky left-12 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-medium text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => (
                       <React.Fragment key={i}>
                           {/* Mass Attendance */}
                           <td className="p-2 border-r border-slate-100 text-center">
                               <input 
                                  type="checkbox" 
                                  className="w-4 h-4 rounded border-slate-300 text-purple-600 focus:ring-purple-500 cursor-pointer" 
                               />
                           </td>
                           {/* Class Attendance */}
                           <td className="p-2 border-r border-slate-100 text-center">
                               <input 
                                  type="checkbox" 
                                  className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                               />
                           </td>
                       </React.Fragment>
                   ))}

                   <td className="p-4">
                     <input type="text" className="w-full bg-transparent border-b border-dashed border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-xs py-1" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để hiển thị danh sách</td></tr>
               )}
             </tbody>
           </table>
        </div>
        <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium flex items-center gap-2 ml-auto">
                 <CheckCircle2 size={18}/> Lưu Điểm Danh
             </button>
        </div>
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, FileSpreadsheet, Trophy, ListChecks, ArrowLeft, ArrowRight } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Default columns now include Thi (Exam) x3
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'col_15m', name: "15'", weight: 1 },
    { id: 'col_45m', name: "45'", weight: 2 },
    { id: 'col_exam', name: "Thi", weight: 3 },
  ]);
  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    const numValue = parseFloat(value) || 0;
    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            // Update dynamic scores
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term, scores: {}, scorePray: 0, scoreExam: 0, average: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      testColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { 
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     // Save both HK1 and HK2 by iterating through filtered students
     const updatedRecords = [...records];

     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });

     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    setTestColumns(testColumns.filter(c => c.id !== id));
    showToast("Đã xóa cột điểm thành công!");
  };

  const moveColumn = (index: number, direction: 'left' | 'right') => {
    if (direction === 'left' && index > 0) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index - 1];
      newCols[index - 1] = temp;
      setTestColumns(newCols);
    } else if (direction === 'right' && index < testColumns.length - 1) {
      const newCols = [...testColumns];
      const temp = newCols[index];
      newCols[index] = newCols[index + 1];
      newCols[index + 1] = temp;
      setTestColumns(newCols);
    }
  };

  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    const finalAvg = (r1.average > 0 && r2.average > 0) ? (r1.average + r2.average) / 2 : 0;
    return { ...s, avg1: r1.average, avg2: r2.average, avgYear: finalAvg, rank: getRank(finalAvg), isPassed: finalAvg >= 5.0 };
  }).sort((a, b) => b.avgYear - a.avgYear).map((s, index) => ({...s, ranking: index + 1}));

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border rounded-lg min-w-[160px] text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (<>{showAddColumn ? (<div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg animate-fade-in"><input type="text" placeholder="Tên cột" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/><select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}><option value={0}>x0</option><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select><button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold">OK</button><button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm">Hủy</button></div>) : (<button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-medium"><Plus size={16} /> Thêm Cột</button>)}</>)}
             <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm hover:bg-slate-50"><FileSpreadsheet size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-separate border-spacing-0">
                    <thead>
                        {/* Top Header Row: Grouping */}
                        <tr className="bg-slate-50 text-slate-700 text-sm">
                            <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-50 z-20 border-b border-r border-slate-200">STT</th>
                            <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-50 z-20 border-b border-r border-slate-200 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">Học Viên</th>

                            {/* HK1 Group */}
                            <th colSpan={testColumns.length + 1} className="p-2 text-center bg-blue-50 border-b border-r border-blue-100 font-bold text-blue-800">HỌC KỲ 1</th>

                            {/* HK2 Group */}
                            <th colSpan={testColumns.length + 1} className="p-2 text-center bg-purple-50 border-b border-r border-purple-100 font-bold text-purple-800">HỌC KỲ 2</th>

                            <th rowSpan={2} className="p-4 w-20 text-center border-b border-slate-200 font-bold bg-slate-100">Cả Năm</th>
                        </tr>

                        {/* Sub Header Row: Columns */}
                        <tr className="bg-slate-50 text-slate-600 text-xs">
                             {/* HK1 Columns */}
                             {testColumns.map((col, idx) => (
                                <th key={`hk1-${col.id}`} className="p-2 w-24 text-center border-b border-r border-slate-200 group relative min-w-[80px]">
                                    <div className="flex flex-col items-center">
                                        <span>{col.name}</span>
                                        <span className="text-[10px] text-slate-400 font-normal">x{col.weight}</span>
                                    </div>
                                    <button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={10} /></button>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-slate-200 font-bold bg-blue-50/50 text-blue-700">TB</th>

                             {/* HK2 Columns */}
                             {testColumns.map((col, idx) => (
                                <th key={`hk2-${col.id}`} className="p-2 w-24 text-center border-b border-r border-slate-200 min-w-[80px]">
                                    <div className="flex flex-col items-center">
                                        <span>{col.name}</span>
                                        <span className="text-[10px] text-slate-400 font-normal">x{col.weight}</span>
                                    </div>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-slate-200 font-bold bg-purple-50/50 text-purple-700">TB</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {filteredStudents.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');

                                return (
                                <tr key={s.id} className="hover:bg-slate-50 group">
                                    <td className="p-4 text-center sticky left-0 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100">{idx + 1}</td>
                                    <td className="p-4 font-medium sticky left-12 bg-white group-hover:bg-slate-50 z-10 border-r border-slate-100 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                                        <div className="text-sm text-slate-800">{s.saintName} {s.fullName}</div>
                                    </td>

                                    {/* HK1 Inputs */}
                                    {testColumns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-2 border-r border-slate-100 text-center">
                                            <input 
                                                type="number" 
                                                value={r1.scores ? r1.scores[col.id] || '' : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full text-center p-1 rounded border border-transparent hover:border-slate-300 focus:border-blue-500 outline-none transition-all text-sm bg-transparent" 
                                            />
                                        </td>
                                    ))}
                                    <td className="p-2 border-r border-slate-100 text-center font-bold text-blue-600 bg-blue-50/20">
                                        {r1.average > 0 ? r1.average : '-'}
                                    </td>

                                    {/* HK2 Inputs */}
                                    {testColumns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-2 border-r border-slate-100 text-center">
                                            <input 
                                                type="number" 
                                                value={r2.scores ? r2.scores[col.id] || '' : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} 
                                                className="w-full text-center p-1 rounded border border-transparent hover:border-slate-300 focus:border-purple-500 outline-none transition-all text-sm bg-transparent" 
                                            />
                                        </td>
                                    ))}
                                    <td className="p-2 border-r border-slate-100 text-center font-bold text-purple-600 bg-purple-50/20">
                                        {r2.average > 0 ? r2.average : '-'}
                                    </td>

                                    {/* Final Year */}
                                    <td className="p-2 text-center font-bold text-slate-800 bg-slate-50/50">
                                        {s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}
                                    </td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={10 + testColumns.length * 2} className="p-8 text-center text-slate-400">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {filteredStudents.length > 0 && (
                <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-medium">
                        <Save size={18} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50"><div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6"><div className="flex justify-between items-start"><div><h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3><div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div></div><div className="text-right"><div className="text-sm text-slate-500">Sĩ số</div><div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div></div></div></div><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden"><div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center"><div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div><span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{passedStudents.map(s => (<tr key={s.id} className="hover:bg-green-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{passedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>)}</tbody></table></div></div><div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden"><div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center"><div className="flex items-center gap-2"><XCircle className="text-red-600" /><h4 className="font-bold text-red-800">Danh Sách Ở Lại Lớp</h4></div><span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">{failedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{failedStudents.map(s => (<tr key={s.id} className="hover:bg-red-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-red-600">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{failedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Không có học viên ở lại lớp</td></tr>)}</tbody></table></div></div></div></div>
        )}
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { MOCK_GRADES } from '../constants';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, FileSpreadsheet, Trophy, ListChecks, ArrowLeft, ArrowRight, Download } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Default columns split by Term
  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);
  const [newColTerm, setNewColTerm] = useState<'HK1' | 'HK2'>('HK1');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  // Derived columns for each term
  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    const numValue = parseFloat(value) || 0;
    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term, scores: {}, scorePray: 0, scoreExam: 0, average: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      // Only calculate based on columns belonging to the record's term
      const termColumns = testColumns.filter(c => c.term === record.term);

      termColumns.forEach(col => {
          const score = record.scores ? (record.scores[col.id] || 0) : 0;
          if (score > 0 || (record.scores && record.scores[col.id] === 0)) { 
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = [...records];
     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });

     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      // Add to end of the list, rendering logic will sort by term
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight, term: newColTerm }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" vào ${newColTerm} thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    if (window.confirm("Bạn có chắc chắn muốn xóa cột điểm này? Dữ liệu điểm của cột này sẽ bị mất hiển thị.")) {
        setTestColumns(testColumns.filter(c => c.id !== id));
        showToast("Đã xóa cột điểm thành công!");
    }
  };

  const moveColumn = (columnId: string, direction: 'left' | 'right') => {
      const index = testColumns.findIndex(c => c.id === columnId);
      if (index === -1) return;

      const col = testColumns[index];
      const newCols = [...testColumns];

      // We only allow swapping with a neighbor if the neighbor is in the SAME term
      // Since testColumns might be mixed in state (though usually grouped), 
      // we need to be careful. For simplicity, let's just swap in the main array
      // but check the term of the target.

      let targetIndex = -1;

      if (direction === 'left' && index > 0) {
          targetIndex = index - 1;
      } else if (direction === 'right' && index < testColumns.length - 1) {
          targetIndex = index + 1;
      }

      if (targetIndex !== -1) {
          // Check if target has same term
          if (newCols[targetIndex].term === col.term) {
              const temp = newCols[index];
              newCols[index] = newCols[targetIndex];
              newCols[targetIndex] = temp;
              setTestColumns(newCols);
          }
      }
  };

  const processedStudentsYear = filteredStudents.map(s => {
    const r1 = getRecord(s.id, 'HK1');
    const r2 = getRecord(s.id, 'HK2');
    // Ensure average is calculated live if needed, or use stored
    const avg1 = calculateAvg(r1);
    const avg2 = calculateAvg(r2);
    const finalAvg = (avg1 > 0 && avg2 > 0) ? (avg1 + avg2) / 2 : 0;

    return { ...s, avg1, avg2, avgYear: finalAvg, rank: getRank(finalAvg), isPassed: finalAvg >= 5.0 };
  }).sort((a, b) => b.avgYear - a.avgYear).map((s, index) => ({...s, ranking: index + 1}));

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const handleExportExcel = () => {
    if (!currentClass) return;

    // Build Header
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "\uFEFF"; // UTF-8 BOM

    // Header Row 1
    const headerRow = [
        "STT", "Họ và Tên", "Mã Học Viên",
        ...hk1Columns.map(c => `${c.name} (x${c.weight})`), "TB HK1",
        ...hk2Columns.map(c => `${c.name} (x${c.weight})`), "TB HK2",
        "TB Cả Năm", "Xếp Loại"
    ];
    csvContent += headerRow.join(",") + "\n";

    // Rows
    processedStudentsYear.forEach((s, idx) => {
        const r1 = getRecord(s.id, 'HK1');
        const r2 = getRecord(s.id, 'HK2');

        const hk1Scores = hk1Columns.map(c => r1.scores?.[c.id] || 0);
        const hk2Scores = hk2Columns.map(c => r2.scores?.[c.id] || 0);

        const row = [
            idx + 1,
            `"${s.saintName} ${s.fullName}"`,
            s.id,
            ...hk1Scores,
            s.avg1.toFixed(1),
            ...hk2Scores,
            s.avg2.toFixed(1),
            s.avgYear.toFixed(1),
            s.rank.label
        ];
        csvContent += row.join(",") + "\n";
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Bang_Diem_${currentClass.name.replace(/\s/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-300 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[160px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                    <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg border border-slate-300 animate-fade-in shadow-lg absolute right-6 top-24 z-50">
                        <select className="px-2 py-1 border rounded text-sm font-bold text-blue-700" value={newColTerm} onChange={(e) => setNewColTerm(e.target.value as any)}>
                            <option value="HK1">Học Kỳ 1</option>
                            <option value="HK2">Học Kỳ 2</option>
                        </select>
                        <input type="text" placeholder="Tên cột (VD: 15')" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/>
                        <select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select>
                        <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold hover:bg-green-700">OK</button>
                        <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm hover:bg-slate-400">Hủy</button>
                    </div>
                ) : (
                    <button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-bold transition-all"><Plus size={16} /> Thêm Cột</button>
                )}
                </>
            )}
             <button onClick={handleExportExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white border border-green-700 rounded-lg text-sm hover:bg-green-700 font-bold shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-spacing-0">
                    <thead>
                        {/* Top Header Row: Grouping */}
                        <tr className="bg-slate-100 text-slate-800 text-sm">
                            <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-20 border-b border-r border-slate-300 font-bold">STT</th>
                            <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-100 z-20 border-b border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>

                            {/* HK1 Group */}
                            <th colSpan={hk1Columns.length + 1} className="p-2 text-center bg-blue-100/50 border-b border-r border-blue-200 font-extrabold text-blue-800 tracking-wider">HỌC KỲ 1</th>

                            {/* HK2 Group */}
                            <th colSpan={hk2Columns.length + 1} className="p-2 text-center bg-purple-100/50 border-b border-r border-purple-200 font-extrabold text-purple-800 tracking-wider">HỌC KỲ 2</th>

                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-300 font-bold bg-slate-200 text-slate-800">Cả Năm</th>
                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-300 font-bold bg-slate-200 text-slate-800">Xếp Loại</th>
                        </tr>

                        {/* Sub Header Row: Columns */}
                        <tr className="bg-slate-50 text-slate-600 text-xs">
                             {/* HK1 Columns */}
                             {hk1Columns.map((col, idx) => (
                                <th key={col.id} className="p-2 w-24 text-center border-b border-r border-slate-300 group relative min-w-[90px] bg-blue-50/30">
                                    <div className="flex flex-col items-center">
                                        <span className="font-bold text-slate-700">{col.name}</span>
                                        <span className="text-[10px] text-slate-500 font-normal">Hệ số {col.weight}</span>
                                    </div>
                                    <div className="absolute inset-x-0 bottom-0 flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pb-0.5 bg-blue-50/80 w-full">
                                         <button onClick={() => moveColumn(col.id, 'left')} className="p-1 hover:bg-blue-200 rounded text-blue-700"><ArrowLeft size={10}/></button>
                                         <button onClick={() => moveColumn(col.id, 'right')} className="p-1 hover:bg-blue-200 rounded text-blue-700"><ArrowRight size={10}/></button>
                                    </div>
                                    <button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={12} /></button>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-blue-300 font-bold bg-blue-100 text-blue-800">TB HK1</th>

                             {/* HK2 Columns */}
                             {hk2Columns.map((col, idx) => (
                                <th key={col.id} className="p-2 w-24 text-center border-b border-r border-slate-300 group relative min-w-[90px] bg-purple-50/30">
                                    <div className="flex flex-col items-center">
                                        <span className="font-bold text-slate-700">{col.name}</span>
                                        <span className="text-[10px] text-slate-500 font-normal">Hệ số {col.weight}</span>
                                    </div>
                                    <div className="absolute inset-x-0 bottom-0 flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pb-0.5 bg-purple-50/80 w-full">
                                         <button onClick={() => moveColumn(col.id, 'left')} className="p-1 hover:bg-purple-200 rounded text-purple-700"><ArrowLeft size={10}/></button>
                                         <button onClick={() => moveColumn(col.id, 'right')} className="p-1 hover:bg-purple-200 rounded text-purple-700"><ArrowRight size={10}/></button>
                                    </div>
                                    <button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={12} /></button>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-purple-300 font-bold bg-purple-100 text-purple-800">TB HK2</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                        {filteredStudents.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');

                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors">
                                    <td className="p-3 text-center sticky left-0 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 font-medium text-slate-500">{idx + 1}</td>
                                    <td className="p-3 font-medium sticky left-12 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                                        <div className="text-sm text-slate-800">{s.saintName} {s.fullName}</div>
                                    </td>

                                    {/* HK1 Inputs */}
                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-1 border-r border-slate-300 text-center relative">
                                            <input 
                                                type="number" 
                                                value={r1.scores ? r1.scores[col.id] || '' : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full h-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm" 
                                                placeholder="-"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-blue-200 text-center font-bold text-blue-700 bg-blue-50">
                                        {s.avg1 > 0 ? s.avg1.toFixed(1) : '-'}
                                    </td>

                                    {/* HK2 Inputs */}
                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-1 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r2.scores ? r2.scores[col.id] || '' : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} 
                                                className="w-full h-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-all text-sm" 
                                                placeholder="-"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-purple-200 text-center font-bold text-purple-700 bg-purple-50">
                                        {s.avg2 > 0 ? s.avg2.toFixed(1) : '-'}
                                    </td>

                                    {/* Final Year */}
                                    <td className="p-3 text-center font-bold text-slate-900 bg-slate-100 border-r border-slate-300">
                                        {s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}
                                    </td>
                                    <td className="p-3 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${s.rank.color}`}>
                                                {s.rank.label}
                                            </span>
                                        )}
                                    </td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={20} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {filteredStudents.length > 0 && (
                <div className="p-4 border-t border-slate-300 bg-slate-50 text-right sticky bottom-0 z-20 shadow-md">
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-bold transition-all">
                        <Save size={18} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50"><div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6"><div className="flex justify-between items-start"><div><h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3><div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div></div><div className="text-right"><div className="text-sm text-slate-500">Sĩ số</div><div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div></div></div></div><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden"><div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center"><div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div><span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{passedStudents.map(s => (<tr key={s.id} className="hover:bg-green-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{passedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Chưa có dữ liệu</td></tr>)}</tbody></table></div></div><div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden"><div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center"><div className="flex items-center gap-2"><XCircle className="text-red-600" /><h4 className="font-bold text-red-800">Danh Sách Ở Lại Lớp</h4></div><span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">{failedStudents.length} em</span></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50 text-slate-500"><tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr></thead><tbody className="divide-y divide-slate-100">{failedStudents.map(s => (<tr key={s.id} className="hover:bg-red-50/30"><td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td><td className="p-3 text-center font-bold text-red-600">{s.avgYear.toFixed(1)}</td><td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td></tr>))}{failedStudents.length === 0 && (<tr><td colSpan={3} className="p-4 text-center text-slate-400 italic">Không có học viên ở lại lớp</td></tr>)}</tbody></table></div></div></div></div>
        )}
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS, MOCK_GRADES } from '../constants';
import { Student, ClassRoom, SchoolYear, AcademicRecord } from '../types';
import { Search, Plus, Edit, Trash2, X, Calendar, Printer, FileSpreadsheet, AlertTriangle, Save, User, MapPin, Phone, Users, CheckCircle2, History, GitMerge, AlertCircle, ScrollText, GraduationCap } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = students.filter(student => {
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const handleSaveStudent = () => {
    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }
    showToast(selectedStudent ? "Đã cập nhật thông tin học viên thành công!" : "Đã thêm học viên mới thành công!");
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  // --- DEDUPLICATION LOGIC ---
  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};

      students.forEach(s => {
          // Key based on Name + DOB
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });

      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) {
              duplicates.push({ key, students: groups[key] });
          }
      });

      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      // Keep survivor, delete others
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;

      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);

      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); // Remove processed group from list
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  // --- HISTORY LOGIC ---
  const getStudentHistory = (studentId: string) => {
    // In a real app, this would query a backend for past years. 
    // Here we construct it from current records and active classes
    const studentRecords = records.filter(r => r.studentId === studentId);

    // Group records by context (we assume records belong to the active year for simplicity in this mock, 
    // but in a real app, AcademicRecord would have a yearId)
    // We will simulate a history entry
    const history = [];

    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);

        // Find current class
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';

        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }

    // Mocking a past record for demonstration
    history.push({
        year: 'Năm học 2022 - 2023',
        className: 'Khai Tâm 1',
        hk1: 8.5,
        hk2: 9.0,
        final: 8.8,
        rank: 'Giỏi'
    });

    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-3 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={16} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {MOCK_GRADES.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b">
              <tr>
                <th className="p-4 w-12 text-center">STT</th>
                <th className="p-4">Tên Thánh & Họ Tên</th>
                <th className="p-4">Ngày Sinh</th>
                <th className="p-4">Phụ Huynh</th>
                <th className="p-4">Liên Hệ (SĐT)</th>
                <th className="p-4">Lớp</th>
                <th className="p-4">Ghi chú</th>
                <th className="p-4 text-center w-24">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4">
                    <div className="font-bold text-slate-700">{s.saintName}</div>
                    <div className="text-base font-bold text-slate-800">{s.fullName}</div>
                    <div className="text-xs text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'} - {s.id}</div>
                  </td>
                  <td className="p-4">
                    <div className="text-slate-700">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div><span className="text-xs font-semibold text-slate-400">B:</span> {s.fatherName}</div>
                    <div><span className="text-xs font-semibold text-slate-400">M:</span> {s.motherName}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div>{s.fatherPhone}</div>
                    <div>{s.motherPhone}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="p-4 italic text-slate-500 max-w-xs truncate">{s.note}</td>
                  <td className="p-4 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={8} className="p-8 text-center text-slate-400 italic">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 text-right">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-[90rem] h-[90vh] flex flex-col animate-fade-in overflow-hidden">

            {/* Modal Header */}
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-lg shadow">
                    {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus />}
                 </div>
                 <div>
                    <h3 className="font-bold text-lg text-slate-800">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-xs text-slate-500 font-mono">{selectedStudent.id}</p>}
                 </div>
              </div>
              <div className="flex gap-2">
                <button onClick={closeModal} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition-colors">Đóng</button>
                <button onClick={handleSaveStudent} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md flex items-center gap-2">
                   <Save size={18} /> Lưu Hồ Sơ
                </button>
              </div>
            </div>

            {/* Warning Alert if Duplicate */}
            {realtimeDuplicates.length > 0 && (
                <div className="bg-red-50 border-b border-red-100 p-4 flex items-start gap-3 animate-pulse">
                    <AlertTriangle className="text-red-600 mt-0.5" />
                    <div>
                        <h4 className="font-bold text-red-800 text-sm">Cảnh báo: Dữ liệu có thể bị trùng lặp!</h4>
                        <p className="text-xs text-red-600 mb-1">Hệ thống phát hiện học viên sau có cùng Tên và Ngày sinh:</p>
