interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
}

type AttendanceStatus = 'H' | 'P' | 'K'; // H: Hiện diện, P: Phép, K: Không phép

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years }) => {
