            <input type="month" className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-bold text-blue-600 focus:ring-2 focus:ring-blue-500 outline-none" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} />
        </div>
      </div>

      {/* Note Section - Clear and prominent */}
      <div className="bg-blue-600 text-white p-3 mb-4 flex items-center gap-3 shadow-lg rounded-xl animate-fade-in border-b-4 border-blue-800">
        <div className="bg-white/20 p-1.5 rounded-lg"><Info size={20} className="text-white" /></div>
        <div className="flex flex-col">
            <span className="font-bold text-sm">HƯỚNG DẪN ĐIỂM DANH NHANH:</span>
            <span className="text-xs opacity-90">Mặc định các ô để trống = <b>Có hiện diện (H)</b>. Bạn chỉ cần chọn <b>P</b> (Vắng có phép) hoặc <b>K</b> (Vắng không phép).</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-100 text-slate-800 text-xs">
                 <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-30 border-b border-r border-slate-300 font-bold">STT</th>
                 <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-100 z-30 border-b border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => {
                    const isEven = idx % 2 === 0;
                    const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50';
                    return (
                        <th key={idx} colSpan={2} className={`p-2 text-center border-b border-r border-slate-300 ${bgClass}`}>
                            <div className="flex flex-col">
                                <span className={`font-bold ${isEven ? 'text-slate-600' : 'text-blue-700'}`}>CN {idx + 1}</span>
                                <span className="text-[10px] font-normal text-slate-400">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                            </div>
                        </th>
                    );
                 })}
                 <th rowSpan={2} className="p-4 text-center border-b border-slate-300 min-w-[150px] font-bold">Ghi chú</th>
               </tr>
               <tr className="text-[10px] uppercase tracking-tighter font-bold bg-slate-50">
                    {sundaysInMonth.map((_, idx) => {
                        const isEven = idx % 2 === 0;
                        const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50/50';
                        return (
                            <React.Fragment key={idx}>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[45px] text-purple-600 ${bgClass}`}>Lễ</th>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[45px] text-blue-600 ${bgClass}`}>Học</th>
                            </React.Fragment>
                        );
                    })}
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-200">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-blue-50/20 group transition-colors">
                   <td className="p-3 text-center text-slate-400 sticky left-0 bg-white group-hover:bg-blue-50/50 z-20 border-r border-slate-200 text-xs">{idx + 1}</td>
                   <td className="p-3 sticky left-12 bg-white group-hover:bg-blue-50/50 z-20 border-r border-slate-200 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const isEven = i % 2 === 0;
                       const cellClass = isEven ? 'bg-white group-hover:bg-blue-50/20' : 'bg-blue-50/10 group-hover:bg-blue-50/30';

                       const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const classStatus = attendanceData[`${s.id}-${dateStr}-class`];

                       return (
                           <React.Fragment key={i}>
                               {/* Mass Attendance */}
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={massStatus || 'H'} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1 rounded text-xs border appearance-none cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(massStatus)}`}
                                   >
                                       <option value="H">H</option>
                                       <option value="P">P</option>
                                       <option value="K">K</option>
                                   </select>
                               </td>
                               {/* Class Attendance */}
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={classStatus || 'H'} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1 rounded text-xs border appearance-none cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(classStatus)}`}
                                   >
                                       <option value="H">H</option>
                                       <option value="P">P</option>
                                       <option value="K">K</option>
                                   </select>
                               </td>
                           </React.Fragment>
                       );
                   })}

                   <td className="p-2 border-r border-slate-200">
                     <input type="text" className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-[11px] py-1 transition-all" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để hiển thị danh sách học viên</td></tr>
               )}
             </tbody>
           </table>
        </div>

        {filteredStudents.length > 0 && (
            <div className="p-4 border-t border-slate-300 bg-slate-50 flex justify-between items-center sticky bottom-0 z-30 shadow-md">
                 <div className="flex gap-4 text-xs">
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-white border border-slate-300 rounded"></span> <span className="text-slate-500">H: Hiện diện</span></div>
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-amber-100 border border-amber-200 rounded"></span> <span className="text-amber-700">P: Vắng có phép</span></div>
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-red-100 border border-red-200 rounded"></span> <span className="text-red-700">K: Vắng không phép</span></div>
                 </div>
                 <button onClick={handleSave} className="px-8 py-2.5 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold flex items-center gap-2 transition-all transform hover:-translate-y-0.5 active:scale-95">
                     <Save size={18}/> Lưu Điểm Danh
                 </button>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        select { text-align-last: center; }
      `}</style>
    </div>
  );
};

