import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // GLOBAL STATE
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'classes':
        return <Classes 
          classes={classes}
          setClasses={setClasses}
          students={students}
          years={years}
          grades={grades}
        />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
          records={records}
          grades={grades}
        />;
      case 'placement':
        return <ClassPlacement 
          students={students}
          setStudents={setStudents}
          classes={classes}
          years={years}
          grades={grades}
        />;
      case 'teachers':
        return <Teachers />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
          grades={grades}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
          grades={grades}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
          grades={grades}
          setGrades={setGrades}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

