  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState(grades[0]?.id || '');

  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  // --- GRADE SORTING LOGIC ---
  const handleGradeDragStart = (e: React.DragEvent, id: string) => {
    setDraggedGradeId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleGradeDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    if (!draggedGradeId || draggedGradeId === targetId) return;

    const sourceIndex = grades.findIndex(g => g.id === draggedGradeId);
    const targetIndex = grades.findIndex(g => g.id === targetId);

    const newGrades = [...grades];
    const [removed] = newGrades.splice(sourceIndex, 1);
    newGrades.splice(targetIndex, 0, removed);

    setGrades(newGrades);
    setDraggedGradeId(null);
  };

  // --- CLASS SORTING LOGIC ---
  const handleClassDragStart = (e: React.DragEvent, id: string) => {
    setDraggedClassId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleClassDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    if (!draggedClassId || draggedClassId === targetId) return;

    const sourceIndex = classes.findIndex(c => c.id === draggedClassId);
    const targetIndex = classes.findIndex(c => c.id === targetId);

    const newClasses = [...classes];
    const [removed] = newClasses.splice(sourceIndex, 1);
    newClasses.splice(targetIndex, 0, removed);

    setClasses(newClasses);
    setDraggedClassId(null);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleAddSaint = () => {
    if (newSaintName) {
      const newSaint: Saint = { id: `s${Date.now()}`, name: newSaintName, gender: newSaintGender };
      setSaints([...saints, newSaint]);
      showToast(`Đã thêm tên thánh "${newSaintName}" thành công!`);
      setNewSaintName('');
    }
  };

  const handleRemoveSaint = (id: string) => {
    const saint = saints.find(s => s.id === id);
    setSaints(saints.filter(s => s.id !== id));
    showToast(`Đã xóa tên thánh "${saint?.name}" thành công!`);
  };

  const handleAddYear = () => {
      if (newYearName) {
          const newId = newYearName.replace(/\s/g, '-');
          const newYear: SchoolYear = { id: newId, name: newYearName, isActive: false };
          setYears([...years, newYear]);
          showToast(`Đã thêm năm học "${newYearName}" thành công!`);
          setNewYearName('');
      }
  };

  const handleSetActiveYear = (id: string) => {
      const year = years.find(y => y.id === id);
      const updatedYears = years.map(y => ({ ...y, isActive: y.id === id }));
      setYears(updatedYears);
      showToast(`Đã đặt "${year?.name}" làm năm học hiện tại!`);
  };

  const handleAddClass = () => {
      if (newClassName && activeYear) {
          const newClass: ClassRoom = { id: `c_${Date.now()}`, name: newClassName, gradeId: newClassGrade, yearId: activeYear.id, mainTeacher: 'Chưa phân công' };
          setClasses([...classes, newClass]);
          showToast(`Đã thêm lớp "${newClassName}" thành công!`);
          setNewClassName('');
      } else {
          alert("Vui lòng nhập tên lớp và đảm bảo có năm học đang kích hoạt.");
      }
  };

  return (
    <div className="p-6 h-screen overflow-y-auto custom-scrollbar relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <h2 className="text-2xl font-bold text-slate-800 mb-6">Cài Đặt Hệ Thống</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Calendar className="text-blue-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Năm Học</h3></div>
          <div className="space-y-4">
            <div><label className="block text-sm font-medium text-slate-700 mb-2">Danh sách năm học</label><div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar border rounded-lg p-2">{years.map(y => (<div key={y.id} className={`flex justify-between items-center p-2 rounded-lg ${y.isActive ? 'bg-blue-50 border border-blue-200' : 'bg-slate-50'}`}><span className={y.isActive ? 'font-bold text-blue-700' : 'text-slate-700'}>{y.name} {y.isActive && '(Hiện tại)'}</span>{!y.isActive && (<button onClick={() => handleSetActiveYear(y.id)} className="text-xs px-2 py-1 bg-white border border-slate-300 rounded hover:bg-slate-100">Đặt làm hiện tại</button>)}</div>))}</div></div>
            <div className="border-t pt-4 mt-4"><h4 className="font-semibold text-sm mb-3">Tạo Năm Học Mới</h4><div className="grid grid-cols-2 gap-4 mb-3"><input type="text" placeholder="Tên năm học (VD: 2024-2025)" className="w-full p-2 border rounded-lg text-sm" value={newYearName} onChange={(e) => setNewYearName(e.target.value)}/><button onClick={handleAddYear} className="flex items-center justify-center gap-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"><Plus size={16}/> Thêm mới</button></div></div>
          </div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Cross className="text-amber-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Tên Thánh</h3></div>
          <div className="space-y-4">
             <div className="flex gap-2"><input type="text" placeholder="Tên Thánh (VD: Đaminh)" className="flex-1 p-2 border rounded-lg text-sm" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-2 border rounded-lg text-sm" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar"><table className="w-full text-left text-sm"><thead className="bg-slate-50 sticky top-0"><tr><th className="p-3">Tên Thánh</th><th className="p-3 w-20">Giới tính</th><th className="p-3 text-right w-16"></th></tr></thead><tbody className="divide-y">{saints.map(s => (<tr key={s.id} className="hover:bg-slate-50"><td className="p-3 font-medium">{s.name}</td><td className="p-3 text-slate-500 text-xs">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</td><td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" onClick={() => handleRemoveSaint(s.id)} /></td></tr>))}</tbody></table></div>
          </div>
        </div>

        {/* Quản lý Khối lớp với tính năng sắp xếp */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Layers className="text-purple-600" /><h3 className="font-bold text-lg text-slate-800">Quản Lý Khối Lớp (Kéo thả để sắp xếp)</h3></div>
          <div className="space-y-4">
             <div className="flex gap-2"><input type="text" placeholder="Tên khối (VD: Khối Vào Đời)" className="flex-1 p-2 border rounded-lg" /><button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar">
                <table className="w-full text-left text-sm">
                    <thead className="bg-slate-50 sticky top-0 z-10">
                        <tr>
                            <th className="p-3 w-8"></th>
                            <th className="p-3">Tên Khối</th>
                            <th className="p-3 text-right">Thao tác</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {grades.map(g => (
                            <tr 
                                key={g.id} 
                                draggable 
                                onDragStart={(e) => handleGradeDragStart(e, g.id)}
                                onDragOver={handleDragOver}
                                onDrop={(e) => handleGradeDrop(e, g.id)}
                                className={`hover:bg-purple-50 group cursor-move transition-colors ${draggedGradeId === g.id ? 'opacity-40 bg-purple-100' : ''}`}
                            >
                                <td className="p-3 text-slate-400 group-hover:text-purple-500"><GripVertical size={16} /></td>
                                <td className="p-3 font-medium">{g.name}</td>
                                <td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" /></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
          </div>
        </div>

        {/* Quản lý Lớp học với tính năng sắp xếp */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-4 border-b pb-4"><Layers className="text-green-600" /><h3 className="font-bold text-lg text-slate-800">Danh Sách Lớp Học ({activeYear?.name})</h3></div>
          <div className="space-y-4">
            <div className="flex gap-2"><input type="text" placeholder="Tên lớp mới" className="flex-1 p-2 border rounded-lg" value={newClassName} onChange={(e) => setNewClassName(e.target.value)} /><select className="p-2 border rounded-lg w-28" value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value)}>{grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select><button onClick={handleAddClass} className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-bold">+</button></div>
            <div className="border rounded-lg overflow-hidden max-h-48 overflow-y-auto custom-scrollbar">
                <table className="w-full text-left text-sm">
                    <thead className="bg-slate-50 sticky top-0 z-10">
                        <tr>
                            <th className="p-3 w-8"></th>
                            <th className="p-3">Tên Lớp</th>
                            <th className="p-3">Khối</th>
                            <th className="p-3 text-right"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y">
                        {classesInActiveYear.length > 0 ? (classesInActiveYear.map(c => {
                            const gradeName = grades.find(g => g.id === c.gradeId)?.name || '---'; 
                            return (
                                <tr 
                                    key={c.id}
                                    draggable
                                    onDragStart={(e) => handleClassDragStart(e, c.id)}
                                    onDragOver={handleDragOver}
                                    onDrop={(e) => handleClassDrop(e, c.id)}
                                    className={`hover:bg-green-50 group cursor-move transition-colors ${draggedClassId === c.id ? 'opacity-40 bg-green-100' : ''}`}
                                >
                                    <td className="p-3 text-slate-400 group-hover:text-green-500"><GripVertical size={16} /></td>
                                    <td className="p-3 font-medium">{c.name}</td>
                                    <td className="p-3 text-slate-500 text-xs">{gradeName}</td>
                                    <td className="p-3 text-right text-red-600 hover:text-red-800 cursor-pointer"><Trash2 size={16} className="ml-auto" /></td>
                                </tr>
                            )})) : (
                                <tr><td colSpan={4} className="p-4 text-center text-slate-500 italic">Chưa có lớp nào trong năm học này</td></tr>
                            )}
                    </tbody>
                </table>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Student, ClassRoom, SchoolYear, Grade } from '../types';
import { CheckCircle2, Info, Save, Calendar, UserCheck, Search } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
}

type AttendanceStatus = 'C' | 'P' | 'K'; // C: Có mặt, P: Phép, K: Không phép

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [toast, setToast] = useState<string | null>(null);

  const [attendanceData, setAttendanceData] = useState<Record<string, AttendanceStatus>>({});

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);

  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleStatusChange = (studentId: string, date: string, type: 'mass' | 'class', status: AttendanceStatus) => {
    const key = `${studentId}-${date}-${type}`;
    setAttendanceData(prev => ({
        ...prev,
        [key]: status
    }));
  };

  const handleSave = () => {
      showToast("Đã lưu dữ liệu điểm danh thành công!");
  };

  const getStatusStyle = (status: AttendanceStatus | undefined) => {
      switch (status) {
          case 'P': return 'bg-amber-100 text-amber-700 border-amber-200 font-bold';
          case 'K': return 'bg-red-100 text-red-700 border-red-200 font-bold';
          case 'C': return 'bg-emerald-50 text-emerald-700 border-emerald-100 font-bold';
          default: return 'bg-white text-slate-300 border-slate-200 opacity-40 hover:opacity-100';
      }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Danh Chuyên Cần</h2>
        <div className="flex items-center gap-2 text-sm text-slate-500 bg-white px-3 py-1.5 rounded-lg border shadow-sm">
            <Calendar size={16} className="text-blue-500" />
            <span>Tháng {selectedMonth.split('-')[1]}/{selectedMonth.split('-')[0]}</span>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center flex-wrap">
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[180px] text-sm focus:ring-2 focus:ring-blue-500 outline-none font-bold text-slate-700" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>

        <div className="flex items-center gap-2 border-l pl-4 ml-2">
            <input type="month" className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-bold text-blue-600 focus:ring-2 focus:ring-blue-500 outline-none" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} />
        </div>
      </div>

      {/* Improved Note Section */}
      <div className="bg-blue-600 text-white p-3 mb-4 flex items-center gap-3 shadow-lg rounded-xl animate-fade-in border-b-4 border-blue-800">
        <div className="bg-white/20 p-1.5 rounded-lg"><Info size={20} className="text-white" /></div>
        <div className="flex flex-col">
            <span className="font-bold text-sm">HƯỚNG DẪN ĐIỂM DANH:</span>
            <span className="text-xs opacity-90">Mặc định ô để trống = <b>Có hiện diện (C)</b>. Chỉ cần chọn <b>P</b> (Vắng có phép) hoặc <b>K</b> (Vắng không phép).</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-100 text-slate-800 text-xs">
                 <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-30 border-b border-r border-slate-300 font-bold">STT</th>
                 <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-100 z-30 border-b border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => {
                    const isEven = idx % 2 === 0;
                    const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50';
                    return (
                        <th key={idx} colSpan={2} className={`p-2 text-center border-b border-r border-slate-300 ${bgClass}`}>
                            <div className="flex flex-col">
                                <span className={`font-bold ${isEven ? 'text-slate-600' : 'text-blue-700'}`}>CN {idx + 1}</span>
                                <span className="text-[10px] font-normal text-slate-400">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                            </div>
                        </th>
                    );
                 })}
                 <th rowSpan={2} className="p-4 text-center border-b border-slate-300 min-w-[150px] font-bold">Ghi chú</th>
               </tr>
               <tr className="text-[10px] uppercase tracking-tighter font-bold bg-slate-50">
                    {sundaysInMonth.map((_, idx) => {
                        const isEven = idx % 2 === 0;
                        const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50/50';
                        return (
                            <React.Fragment key={idx}>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[45px] text-purple-600 ${bgClass}`}>Lễ</th>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[45px] text-blue-600 ${bgClass}`}>Học</th>
                            </React.Fragment>
                        );
                    })}
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-200">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-200">
                   <td className="p-3 text-center text-slate-400 sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 text-xs">{idx + 1}</td>
                   <td className="p-3 sticky left-12 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const isEven = i % 2 === 0;
                       const cellClass = isEven ? 'bg-white group-hover:bg-blue-50/20' : 'bg-blue-50/10 group-hover:bg-blue-50/30';

                       const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const classStatus = attendanceData[`${s.id}-${dateStr}-class`];

                       return (
                           <React.Fragment key={i}>
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={massStatus || 'C'} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1 rounded text-xs border appearance-none cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(massStatus)}`}
                                   >
                                       <option value="C">C</option>
                                       <option value="P">P</option>
                                       <option value="K">K</option>
                                   </select>
                               </td>
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={classStatus || 'C'} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1 rounded text-xs border appearance-none cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(classStatus)}`}
                                   >
                                       <option value="C">C</option>
                                       <option value="P">P</option>
                                       <option value="K">K</option>
                                   </select>
                               </td>
                           </React.Fragment>
                       );
                   })}

                   <td className="p-2 border-r border-slate-200">
                     <input type="text" className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-[11px] py-1 transition-all" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để hiển thị danh sách học viên</td></tr>
               )}
             </tbody>
           </table>
        </div>

        {filteredStudents.length > 0 && (
            <div className="p-4 border-t border-slate-300 bg-slate-50 flex justify-between items-center sticky bottom-0 z-30 shadow-md">
                 <div className="flex gap-4 text-xs">
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-emerald-50 border border-emerald-100 rounded"></span> <span className="text-emerald-700">C: Hiện diện</span></div>
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-amber-100 border border-amber-200 rounded"></span> <span className="text-amber-700">P: Vắng có phép</span></div>
                     <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-red-100 border border-red-200 rounded"></span> <span className="text-red-700">K: Vắng không phép</span></div>
                 </div>
                 <button onClick={handleSave} className="px-8 py-2.5 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold flex items-center gap-2 transition-all transform hover:-translate-y-0.5 active:scale-95">
                     <Save size={18}/> Lưu Điểm Danh
                 </button>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        select { text-align-last: center; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, X, Calendar, Printer, FileSpreadsheet, AlertTriangle, Save, User, MapPin, Phone, Users, CheckCircle2, History, GitMerge, AlertCircle, ScrollText, GraduationCap } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = students.filter(student => {
    const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                        student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

    let validClassIds: string[] = [];
    if (selectedClass !== 'all') {
        validClassIds = [selectedClass];
    } else if (selectedGrade !== 'all') {
        validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
    } else {
        validClassIds = classesInYear.map(c => c.id);
    }

    const matchClass = validClassIds.includes(student.classId);
    return matchSearch && matchClass;
  });

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const handleSaveStudent = () => {
    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }
    showToast(selectedStudent ? "Đã cập nhật thông tin học viên thành công!" : "Đã thêm học viên mới thành công!");
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  // --- DEDUPLICATION LOGIC ---
  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};

      students.forEach(s => {
          // Key based on Name + DOB
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });

      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) {
              duplicates.push({ key, students: groups[key] });
          }
      });

      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      // Keep survivor, delete others
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;

      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);

      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); // Remove processed group from list
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  // --- HISTORY LOGIC ---
  const getStudentHistory = (studentId: string) => {
    const studentRecords = records.filter(r => r.studentId === studentId);

    const history = [];

    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);

        // Find current class
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';

        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }

    history.push({
        year: 'Năm học 2022 - 2023',
        className: 'Khai Tâm 1',
        hk1: 8.5,
        hk2: 9.0,
        final: 8.8,
        rank: 'Giỏi'
    });

    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-3 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={16} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <Printer size={16} /> In DS
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                <FileSpreadsheet size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold"><Plus size={18} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-3 py-2 rounded-lg border border-slate-300 text-sm min-w-[120px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b">
              <tr>
                <th className="p-4 w-12 text-center">STT</th>
                <th className="p-4">Tên Thánh & Họ Tên</th>
                <th className="p-4">Ngày Sinh</th>
                <th className="p-4">Phụ Huynh</th>
                <th className="p-4">Liên Hệ (SĐT)</th>
                <th className="p-4">Lớp</th>
                <th className="p-4">Ghi chú</th>
                <th className="p-4 text-center w-24">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4">
                    <div className="font-bold text-slate-700">{s.saintName}</div>
                    <div className="text-base font-bold text-slate-800">{s.fullName}</div>
                    <div className="text-xs text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'} - {s.id}</div>
                  </td>
                  <td className="p-4">
                    <div className="text-slate-700">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div><span className="text-xs font-semibold text-slate-400">B:</span> {s.fatherName}</div>
                    <div><span className="text-xs font-semibold text-slate-400">M:</span> {s.motherName}</div>
                  </td>
                  <td className="p-4 text-slate-600">
                    <div>{s.fatherPhone}</div>
                    <div>{s.motherPhone}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="p-4 italic text-slate-500 max-w-xs truncate">{s.note}</td>
                  <td className="p-4 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={8} className="p-8 text-center text-slate-400 italic">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-3 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 text-right">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-[90rem] h-[90vh] flex flex-col animate-fade-in overflow-hidden">

            {/* Modal Header */}
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-lg shadow">
                    {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus />}
                 </div>
                 <div>
                    <h3 className="font-bold text-lg text-slate-800">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-xs text-slate-500 font-mono">{selectedStudent.id}</p>}
                 </div>
              </div>
              <div className="flex gap-2">
                <button onClick={closeModal} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition-colors">Đóng</button>
                <button onClick={handleSaveStudent} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md flex items-center gap-2">
                   <Save size={18} /> Lưu Hồ Sơ
                </button>
              </div>
            </div>

            {/* Warning Alert if Duplicate */}
            {realtimeDuplicates.length > 0 && (
                <div className="bg-red-50 border-b border-red-100 p-4 flex items-start gap-3 animate-pulse">
                    <AlertTriangle className="text-red-600 mt-0.5" />
                    <div>
                        <h4 className="font-bold text-red-800 text-sm">Cảnh báo: Dữ liệu có thể bị trùng lặp!</h4>
                        <p className="text-xs text-red-600 mb-1">Hệ thống phát hiện học viên sau có cùng Tên và Ngày sinh:</p>
                        <ul className="text-xs text-red-700 list-disc list-inside">
                            {realtimeDuplicates.map(d => (
                                <li key={d.id}>{d.saintName} <b>{d.fullName}</b> ({d.id}) - Lớp: {getClassName(d.classId)}</li>
                            ))}
                        </ul>
                    </div>
                </div>
            )}

            {/* Tabs */}
            <div className="flex border-b border-slate-200 bg-white">
                <button onClick={() => setModalTab('PROFILE')} className={`px-6 py-3 text-sm font-bold border-b-2 transition-all ${modalTab === 'PROFILE' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Hồ sơ cá nhân</button>
                <button onClick={() => setModalTab('HISTORY')} className={`px-6 py-3 text-sm font-bold border-b-2 transition-all ${modalTab === 'HISTORY' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Lịch sử & Điểm số</button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50/50">
                {modalTab === 'PROFILE' && (
                    <div className="space-y-6 max-w-6xl mx-auto animate-fade-in">

                        {/* 1. THÔNG TIN CHUNG & CÁ NHÂN */}
                        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                            <h4 className="flex items-center gap-2 font-bold text-slate-700 mb-4 pb-2 border-b"><User size={18} className="text-blue-500"/> Thông Tin Cá Nhân</h4>
                            <div className="space-y-4">
                                {/* Row 1: ID, Saint, Name */}
                                <div className="grid grid-cols-1 md:grid-cols-12 gap-3">
                                    <div className="md:col-span-2">
                                        <label className="label-text">Mã học viên</label>
                                        <input className="input-field bg-slate-100 text-slate-500" disabled value={selectedStudent?.id || 'AUTO'} />
                                    </div>
                                    <div className="md:col-span-3 relative">
                                        <label className="label-text">Tên Thánh</label>
                                        <input 
                                          className="input-field" 
                                          value={saintInput} 
                                          onChange={(e) => {
                                              setSaintInput(e.target.value);
                                              setShowSaintSuggestions(true);
                                          }}
                                          onFocus={() => setShowSaintSuggestions(true)}
                                          onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)}
                                          placeholder="Giuse..." 
                                        />
                                        {showSaintSuggestions && (
                                           <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">
                                             {filteredSaints.length > 0 ? (
                                               filteredSaints.map(s => (
                                                 <div 
                                                    key={s.id} 
                                                    className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex justify-between"
                                                    onClick={() => {
                                                      setSaintInput(s.name);
                                                      setShowSaintSuggestions(false);
                                                    }}
                                                  >
                                                    <span>{s.name}</span>
                                                    <span className="text-xs text-slate-400">({s.gender === 'Male' ? 'Nam' : 'Nữ'})</span>
                                                  </div>
                                               ))
                                             ) : (
                                               <div className="p-2 text-xs text-slate-400">Không tìm thấy</div>
                                             )}
                                           </div>
                                        )}
                                    </div>
                                    <div className="md:col-span-7">
                                        <label className="label-text">Họ và Tên</label>
                                        <input 
                                            className="input-field font-bold" 
                                            value={inputName}
                                            onChange={(e) => setInputName(e.target.value)}
                                            placeholder="Nguyễn Văn A" 
                                        />
                                    </div>
                                </div>
                                {/* Row 2: DOB, Gender, Place */}
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                     <div>
                                        <label className="label-text">Ngày tháng năm sinh</label>
                                        <input 
                                            type="date" 
                                            className="input-field" 
                                            value={inputDob}
                                            onChange={(e) => setInputDob(e.target.value)}
                                        />
                                    </div>
                                    <div>
                                       <label className="label-text">Giới tính</label>
                                       <select className="input-field" defaultValue={selectedStudent?.gender || 'Male'}>
                                           <option value="Male">Nam</option>
                                           <option value="Female">Nữ</option>
                                       </select>
                                    </div>
                                    <div>
                                        <label className="label-text">Nơi sinh</label>
                                        <input className="input-field" defaultValue={selectedStudent?.birthPlace} placeholder="Bệnh viện..." />
                                     </div>
                                </div>
                            </div>
                        </div>

                        {/* 2. GIA ĐÌNH & LIÊN HỆ */}
                        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
