import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear, Grade } from '../types';
import { ArrowRight, Search, CheckCircle2, Users, ArrowRightLeft, ArrowUpRight, GraduationCap, Filter, Globe, List } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
}

type Mode = 'TRANSFER' | 'PROMOTION';
type SearchMode = 'CLASS' | 'GLOBAL';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years, grades }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER'); 
  const [searchMode, setSearchMode] = useState<SearchMode>('CLASS');
  const [toast, setToast] = useState<string | null>(null);

  // === FILTER STATE ===
  // Source (Nguồn)
  const [srcYear, setSrcYear] = useState('');
  const [srcGrade, setSrcGrade] = useState('all');
  const [srcClassId, setSrcClassId] = useState('');
  const [srcSearch, setSrcSearch] = useState('');

  // Target (Đích)
  const [tgtYear, setTgtYear] = useState('');
  const [tgtGrade, setTgtGrade] = useState('all');
  const [tgtClassId, setTgtClassId] = useState('');

  // Selection
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Init default years
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;
    setSrcYear(active.id);
    setTgtYear(active.id); 
  }, [years]);

  // Reset selection when source changes
  useEffect(() => {
    setSelectedStudentIds([]);
  }, [srcClassId, searchMode]);

  // Logic to filter Source Classes
  const srcClasses = useMemo(() => {
    return classes.filter(c => c.yearId === srcYear && (srcGrade === 'all' || c.gradeId === srcGrade));
  }, [classes, srcYear, srcGrade]);

  // Logic to filter Target Classes
  const tgtClasses = useMemo(() => {
    return classes.filter(c => c.yearId === tgtYear && (tgtGrade === 'all' || c.gradeId === tgtGrade));
  }, [classes, tgtYear, tgtGrade]);

  // Students in Source
  const srcStudents = useMemo(() => {
    let list: Student[] = [];

    if (searchMode === 'CLASS') {
        if (!srcClassId) return [];
        list = students.filter(s => s.classId === srcClassId);
    } else {
        if (!srcSearch) return [];
        list = students; 
    }

    if (srcSearch) {
        const q = srcSearch.toLowerCase();
        list = list.filter(s => s.fullName.toLowerCase().includes(q) || s.saintName.toLowerCase().includes(q) || s.id.toLowerCase().includes(q));
    }

    return list.slice(0, 100); 
  }, [students, srcClassId, srcSearch, searchMode]);

  // Students in Target Class (for preview)
  const tgtStudents = useMemo(() => {
    if (!tgtClassId) return [];
    return students.filter(s => s.classId === tgtClassId);
  }, [students, tgtClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
        setSelectedStudentIds(srcStudents.map(s => s.id));
    } else {
        setSelectedStudentIds([]);
    }
  };

  const toggleSelect = (id: string) => {
      setSelectedStudentIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const handleExecute = () => {
      if (selectedStudentIds.length === 0) return alert("Chưa chọn học viên nào!");
      if (!tgtClassId) return alert("Chưa chọn lớp đích!");

      const tgtClass = classes.find(c => c.id === tgtClassId);

      if (window.confirm(`Bạn có chắc muốn chuyển ${selectedStudentIds.length} học viên sang lớp ${tgtClass?.name}?`)) {
          const updatedStudents = students.map(s => {
              if (selectedStudentIds.includes(s.id)) {
                  return { ...s, classId: tgtClassId };
              }
              return s;
          });
          setStudents(updatedStudents);
          setToast(`Đã chuyển thành công ${selectedStudentIds.length} học viên!`);
          setSelectedStudentIds([]);
      }
  };

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Chưa xếp lớp';

  return (
    <div className="p-6 h-screen flex flex-col bg-slate-100 relative">
       {/* Toast */}
       {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Điều Chuyển</h2>
            <p className="text-slate-500 text-sm">Quản lý danh sách học viên giữa các lớp</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg shadow-sm border border-slate-200">
            <button 
                onClick={() => setMode('TRANSFER')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'TRANSFER' ? 'bg-blue-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowRightLeft size={16} /> Chuyển Lớp (Trong năm)
            </button>
            <button 
                onClick={() => setMode('PROMOTION')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'PROMOTION' ? 'bg-green-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowUpRight size={16} /> Lên Lớp (Niên khóa mới)
            </button>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="flex flex-1 gap-6 overflow-hidden">

          {/* LEFT: SOURCE */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
              <div className="bg-slate-50 border-b border-slate-200">
                  <div className="flex border-b border-slate-200">
                      <button 
                        onClick={() => setSearchMode('CLASS')}
                        className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'CLASS' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <List size={14}/> Theo Lớp
                      </button>
                      <button 
                         onClick={() => setSearchMode('GLOBAL')}
                         className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'GLOBAL' ? 'bg-white text-purple-600 border-b-2 border-purple-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <Globe size={14}/> Tìm Học Viên
                      </button>
                  </div>

                  <div className="p-4">
                    {searchMode === 'CLASS' ? (
                        <div className="space-y-2">
                             <div className="grid grid-cols-2 gap-2">
                                <select className="input-select" value={srcYear} onChange={e => setSrcYear(e.target.value)}>
                                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                                </select>
                                <select className="input-select" value={srcGrade} onChange={e => setSrcGrade(e.target.value)}>
                                    <option value="all">Tất cả Khối</option>
                                    {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                </select>
                            </div>
                            <select className={`input-select w-full font-bold ${srcClassId ? 'text-slate-800' : 'text-slate-400'}`} value={srcClassId} onChange={e => setSrcClassId(e.target.value)}>
                                <option value="">-- Chọn Lớp Nguồn --</option>
                                {srcClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    ) : (
                        <div className="relative">
                            <input 
                                type="text" 
                                placeholder="Nhập tên học viên để tìm..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border border-purple-300 rounded-lg bg-white focus:ring-2 focus:ring-purple-200 outline-none"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                                autoFocus
                            />
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-purple-400" size={16}/>
                            <div className="text-[10px] text-slate-400 mt-1 italic text-right">*Tìm trong toàn bộ hệ thống</div>
                        </div>
                    )}
                  </div>
              </div>

              {/* Source List */}
              <div className="flex-1 flex flex-col overflow-hidden relative">
                 {searchMode === 'CLASS' && srcClassId && (
                     <div className="p-2 border-b border-slate-100 sticky top-0 bg-white z-10">
                         <div className="relative">
                             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                             <input 
                                type="text" 
                                placeholder="Lọc tên trong lớp này..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border rounded-lg bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-100"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                             />
                         </div>
                     </div>
                 )}

                 <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {(searchMode === 'GLOBAL' && srcSearch) || (searchMode === 'CLASS' && srcClassId) ? (
                         srcStudents.length > 0 ? (
                             <div className="space-y-1">
                                 <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg mb-2">
                                     <input type="checkbox" className="w-4 h-4 rounded cursor-pointer" onChange={handleSelectAll} checked={srcStudents.length > 0 && selectedStudentIds.length === srcStudents.length}/>
                                     <span className="text-sm font-bold text-slate-600">Chọn tất cả ({srcStudents.length})</span>
                                 </div>
                                 {srcStudents.map(s => (
                                     <div 
                                        key={s.id} 
                                        onClick={() => toggleSelect(s.id)}
                                        className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all ${selectedStudentIds.includes(s.id) ? 'bg-blue-50 border-blue-300 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
                                     >
                                         <input type="checkbox" className="w-4 h-4 rounded cursor-pointer" checked={selectedStudentIds.includes(s.id)} onChange={() => toggleSelect(s.id)} />
                                         <div className="flex-1">
                                             <div className="flex justify-between">
                                                <div className="text-sm font-bold text-slate-800">{s.saintName} {s.fullName}</div>
                                                {searchMode === 'GLOBAL' && <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-medium">{getClassName(s.classId)}</span>}
                                             </div>
                                             <div className="text-[10px] text-slate-400 font-mono">{s.id} - {new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                                         </div>
                                     </div>
                                 ))}
                             </div>
                         ) : (
                             <div className="h-full flex flex-col items-center justify-center text-slate-400">
                                 <span className="text-sm italic">Không tìm thấy học viên</span>
                             </div>
                         )
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <GraduationCap size={48} className="mb-2"/>
                             <span className="text-sm font-medium">
                                 {searchMode === 'CLASS' ? 'Vui lòng chọn lớp nguồn' : 'Nhập tên để tìm kiếm'}
                             </span>
                         </div>
                     )}
                 </div>
              </div>
              <div className="p-3 bg-slate-50 border-t border-slate-200 text-xs font-bold text-slate-500 text-right">
                  Đã chọn: {selectedStudentIds.length} / {srcStudents.length}
              </div>
          </div>

          {/* MIDDLE: ACTIONS */}
          <div className="flex flex-col items-center justify-center gap-4">
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
              <button 
                onClick={handleExecute}
                disabled={selectedStudentIds.length === 0 || !tgtClassId}
                className={`w-14 h-14 rounded-full flex items-center justify-center shadow-lg transition-all transform hover:scale-110 active:scale-95 ${selectedStudentIds.length > 0 && tgtClassId ? 'bg-blue-600 text-white cursor-pointer' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                title="Thực hiện chuyển lớp"
              >
                  <ArrowRight size={24} />
              </button>
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
          </div>

          {/* RIGHT: TARGET */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
             <div className={`p-4 border-b border-slate-200 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
                  <div className={`flex items-center gap-2 mb-3 font-bold uppercase text-xs tracking-wider ${mode === 'PROMOTION' ? 'text-green-800' : 'text-blue-800'}`}>
                      <Users size={14}/> Lớp Đích
                  </div>
                  <div className="grid grid-cols-2 gap-2 mb-2">
                      <select className="input-select" value={tgtYear} onChange={e => setTgtYear(e.target.value)}>
                          {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                      </select>
                      <select className="input-select" value={tgtGrade} onChange={e => setTgtGrade(e.target.value)}>
                          <option value="all">Tất cả Khối</option>
                          {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                      </select>
                  </div>
                  <select className={`input-select w-full font-bold ${tgtClassId ? 'text-slate-800' : 'text-slate-400'} ${mode === 'PROMOTION' ? 'focus:ring-green-500' : 'focus:ring-blue-500'}`} value={tgtClassId} onChange={e => setTgtClassId(e.target.value)}>
                      <option value="">-- Chọn Lớp Đích --</option>
                      {tgtClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
              </div>

              {/* Target Preview List */}
              <div className="flex-1 flex flex-col overflow-hidden bg-slate-50/30">
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {tgtClassId ? (
                         <div className="space-y-1">
                             <div className="text-xs font-bold text-slate-400 uppercase p-2">Danh sách hiện tại ({tgtStudents.length})</div>
                             {tgtStudents.map((s, idx) => (
                                 <div key={s.id} className="flex items-center justify-between p-3 bg-white rounded-lg border border-slate-100">
                                     <div className="flex items-center gap-3">
                                         <span className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center text-[10px] text-slate-500 font-bold">{idx + 1}</span>
                                         <div>
                                             <div className="text-sm font-medium text-slate-700">{s.saintName} {s.fullName}</div>
                                         </div>
                                     </div>
                                 </div>
                             ))}
                             {tgtStudents.length === 0 && <div className="p-8 text-center text-sm text-slate-400 italic">Lớp chưa có học viên</div>}
                         </div>
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <Users size={48} className="mb-2"/>
                             <span className="text-sm font-medium">Vui lòng chọn lớp đích</span>
                         </div>
                     )}
                  </div>
              </div>
          </div>

      </div>

      <style>{`
        .input-select {
            width: 100%;
            padding: 0.5rem;
            border-radius: 0.5rem;
            border: 1px solid #cbd5e1;
            font-size: 0.875rem;
            outline: none;
            transition: all 0.2s;
        }
        .input-select:focus {
            border-color: #3b82f6;
            box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
        }
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_TEACHERS } from '../constants';
import { ClassRoom, SchoolYear, Student, Grade } from '../types';
import { Users, User, UserCheck, Edit, X, Save, CheckCircle2, Search } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
    grades: Grade[];
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  const [mainTeacherInput, setMainTeacherInput] = useState('');
  const [showMainTeacherSuggestions, setShowMainTeacherSuggestions] = useState(false);

  const [assistants, setAssistants] = useState<string[]>(['', '', '']);
  const [showAssistSuggestions, setShowAssistSuggestions] = useState<boolean[]>([false, false, false]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  useEffect(() => {
    if (editingClass) {
        const parts = editingClass.assistants ? editingClass.assistants.split(',').map(s => s.trim()) : [];
        setAssistants([parts[0] || '', parts[1] || '', parts[2] || '']);
        setMainTeacherInput(editingClass.mainTeacher || '');
    }
  }, [editingClass]);

  const filteredClasses = useMemo(() => {
      return classes.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [classes, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        const combinedAssistants = assistants
            .map(s => s.trim())
            .filter(s => s !== '')
            .join(', ');

        const finalClassData = { 
            ...editingClass, 
            mainTeacher: mainTeacherInput, 
            assistants: combinedAssistants 
        };

        const updatedClasses = classes.map(c => c.id === editingClass.id ? finalClassData : c);
        setClasses(updatedClasses);
        showToast(`Đã cập nhật thông tin lớp ${editingClass.name} thành công!`);
        setEditingClass(null);
    }
  };

  const sortedTeachers = useMemo(() => {
      return [...MOCK_TEACHERS].sort((a, b) => a.fullName.localeCompare(b.fullName));
  }, []);

  const getFilteredTeachers = (input: string) => {
      if (!input) return sortedTeachers;
      const lowerInput = input.toLowerCase();
      return sortedTeachers.filter(t => 
          t.fullName.toLowerCase().includes(lowerInput) || 
          t.saintName.toLowerCase().includes(lowerInput)
      );
  };

  const filteredMainTeacherSuggestions = useMemo(() => getFilteredTeachers(mainTeacherInput), [mainTeacherInput, sortedTeachers]);

  const updateAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = true;
      setShowAssistSuggestions(newShow);
  };

  const selectAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = false;
      setShowAssistSuggestions(newShow);
  }

  const toggleAssistSuggestion = (index: number, status: boolean) => {
      const newShow = [...showAssistSuggestions];
      newShow[index] = status;
      setShowAssistSuggestions(newShow);
  }

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2 border rounded-lg bg-white font-medium min-w-[150px]"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2 border rounded-lg bg-white min-w-[150px]"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-200">
                         <th className="p-4 w-12 text-center">STT</th>
                         <th className="p-4">Tên Lớp</th>
                         <th className="p-4">Khối</th>
                         <th className="p-4 text-center">Sĩ số</th>
                         <th className="p-4 text-center">Nam</th>
                         <th className="p-4 text-center">Nữ</th>
                         <th className="p-4 text-center">Phòng Học</th>
                         <th className="p-4">GLV Chủ Nhiệm</th>
                         <th className="p-4">GLV Phụ Trách</th>
                         <th className="p-4 w-16 text-center"></th>
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = grades.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50">
                                     <td className="p-4 text-center text-slate-500">{index + 1}</td>
                                     <td className="p-4 font-bold text-slate-800">{c.name}</td>
                                     <td className="p-4 text-slate-600 text-sm">{gradeName}</td>
                                     <td className="p-4 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.male}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.female}</td>
                                     <td className="p-4 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="p-4 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="p-4 text-sm text-slate-600 max-w-xs truncate" title={c.assistants}>{c.assistants || '---'}</td>
                                     <td className="p-4 text-center">
                                         <button onClick={() => handleEditClass(c)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                             <Edit size={16} />
                                         </button>
                                     </td>
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={10} className="p-8 text-center text-slate-400">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-6 justify-end text-sm font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={16}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={16}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={16}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {editingClass && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in flex flex-col max-h-[90vh]">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-lg text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                </div>
                <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg bg-slate-100 text-slate-500" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>

                    <div className="relative">
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Chủ Nhiệm</label>
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full p-2 pl-3 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={mainTeacherInput}
                                onChange={(e) => {
                                    setMainTeacherInput(e.target.value);
                                    setShowMainTeacherSuggestions(true);
                                }}
                                onFocus={() => setShowMainTeacherSuggestions(true)}
                                onBlur={() => setTimeout(() => setShowMainTeacherSuggestions(false), 200)}
                                placeholder="Nhập tên GLV..."
                            />
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        </div>
                        {showMainTeacherSuggestions && (
                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                {filteredMainTeacherSuggestions.length > 0 ? (
                                    filteredMainTeacherSuggestions.map(t => (
                                        <div 
                                            key={t.id}
                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                            onClick={() => {
                                                setMainTeacherInput(`${t.saintName} ${t.fullName}`);
                                                setShowMainTeacherSuggestions(false);
                                            }}
                                        >
                                            <span>{t.saintName} {t.fullName}</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="p-3 text-xs text-slate-400 text-center italic">Không tìm thấy GLV phù hợp</div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                        <label className="block text-sm font-bold text-slate-700 mb-2">GLV Phụ Trách</label>
                        <div className="space-y-3">
                             {assistants.map((val, idx) => {
                                const suggestions = getFilteredTeachers(val);
                                return (
                                    <div key={idx} className="relative">
                                        <div className="relative">
                                            <input 
                                                type="text"
                                                className="w-full p-2 pl-3 pr-8 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm bg-white"
                                                placeholder={`GLV Phụ trách ${idx + 1}`}
                                                value={val}
                                                onChange={(e) => updateAssistant(idx, e.target.value)}
                                                onFocus={() => toggleAssistSuggestion(idx, true)}
                                                onBlur={() => setTimeout(() => toggleAssistSuggestion(idx, false), 200)}
                                            />
                                             <Search className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                                        </div>
                                        {showAssistSuggestions[idx] && (
                                            <div className="absolute z-20 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {suggestions.length > 0 ? (
                                                    suggestions.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                                            onClick={() => selectAssistant(idx, `${t.saintName} ${t.fullName}`)}
                                                        >
                                                            <span>{t.saintName} {t.fullName}</span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="p-2 text-xs text-slate-400 text-center italic">Không tìm thấy</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                             })}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3 mt-auto">
                    <button onClick={() => setEditingClass(null)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium">Hủy</button>
                    <button onClick={handleSaveClass} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, GripVertical, AlertCircle, Info } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const [draggedColId, setDraggedColId] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);
  const [newColTerm, setNewColTerm] = useState<'HK1' | 'HK2'>('HK1');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);

    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term, scores: {}, scorePray: 0, scoreExam: 0, average: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      const termColumns = testColumns.filter(c => c.term === record.term);

      termColumns.forEach(col => {
          if (col.weight > 0) {
              const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = [...records];
     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });

     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight, term: newColTerm }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" vào ${newColTerm} thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    if (window.confirm("Bạn có chắc chắn muốn xóa cột điểm này? Dữ liệu điểm của cột này sẽ bị mất hiển thị.")) {
        setTestColumns(testColumns.filter(c => c.id !== id));
        showToast("Đã xóa cột điểm thành công!");
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedColId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, targetId: string) => {
      e.preventDefault();
      if (!draggedColId || draggedColId === targetId) return;

      const sourceIndex = testColumns.findIndex(c => c.id === draggedColId);
      const targetIndex = testColumns.findIndex(c => c.id === targetId);

      if (sourceIndex === -1 || targetIndex === -1) return;

      const sourceCol = testColumns[sourceIndex];
      const targetCol = testColumns[targetIndex];

      if (sourceCol.term !== targetCol.term) {
          showToast("Chỉ có thể sắp xếp cột trong cùng một Học Kỳ!");
          setDraggedColId(null);
          return;
      }

      const newCols = [...testColumns];
      const [removed] = newCols.splice(sourceIndex, 1);
      newCols.splice(targetIndex, 0, removed);

      setTestColumns(newCols);
      setDraggedColId(null);
  };

  const processedStudentsYear = useMemo(() => {
    return filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;

      return { ...s, avg1, avg2, avgYear: finalAvg, rank: getRank(finalAvg), isPassed: finalAvg >= 5.0 };
    }).sort((a, b) => b.avgYear - a.avgYear).map((s, index) => ({...s, ranking: index + 1}));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const handleExportExcel = () => {
    if (!currentClass) return;
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "\uFEFF"; 

    const headerRow = [
        "STT", "Họ và Tên", "Mã Học Viên",
        ...hk1Columns.map(c => `${c.name} (x${c.weight})`), "TB HK1",
        ...hk2Columns.map(c => `${c.name} (x${c.weight})`), "TB HK2",
        "TB Cả Năm", "Xếp Loại", "Hạng"
    ];
    csvContent += headerRow.join(",") + "\n";

    processedStudentsYear.forEach((s, idx) => {
        const r1 = getRecord(s.id, 'HK1');
        const r2 = getRecord(s.id, 'HK2');
        const hk1Scores = hk1Columns.map(c => r1.scores?.[c.id] || 0);
        const hk2Scores = hk2Columns.map(c => r2.scores?.[c.id] || 0);

        const row = [
            idx + 1,
            `"${s.saintName} ${s.fullName}"`,
            s.id,
            ...hk1Scores,
            s.avg1.toFixed(1),
            ...hk2Scores,
            s.avg2.toFixed(1),
            s.avgYear.toFixed(1),
            s.rank.label,
            s.ranking
        ];
        csvContent += row.join(",") + "\n";
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Bang_Diem_${currentClass.name.replace(/\s/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-300 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[160px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                    <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg border border-slate-300 animate-fade-in shadow-lg absolute right-6 top-24 z-50">
                        <select className="px-2 py-1 border rounded text-sm font-bold text-blue-700" value={newColTerm} onChange={(e) => setNewColTerm(e.target.value as any)}>
                            <option value="HK1">Học Kỳ 1</option>
                            <option value="HK2">Học Kỳ 2</option>
                        </select>
                        <input type="text" placeholder="Tên cột (VD: 15')" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/>
                        <select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}>
                            <option value={0}>x0</option>
                            <option value={1}>x1</option>
                            <option value={2}>x2</option>
                            <option value={3}>x3</option>
                        </select>
                        <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold hover:bg-green-700">OK</button>
                        <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm hover:bg-slate-400">Hủy</button>
                    </div>
                ) : (
                    <button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-bold transition-all"><Plus size={16} /> Thêm Cột</button>
                )}
                </>
            )}
             <button onClick={handleExportExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white border border-green-700 rounded-lg text-sm hover:bg-green-700 font-bold shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-blue-50 border-l-4 border-blue-400 p-3 mb-4 flex items-center gap-2 text-blue-700 text-sm shadow-sm rounded-r-lg">
        <Info size={18} className="shrink-0" />
        <span><b>Lưu ý:</b> Bảng điểm tự động xếp hạng dựa trên <b>Điểm Trung Bình Cả Năm</b>.</span>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-spacing-0">
                    <thead>
                        <tr className="bg-slate-100 text-slate-800 text-sm">
                            <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-20 border-b border-r border-slate-300 font-bold">STT</th>
                            <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-100 z-20 border-b border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                            <th colSpan={hk1Columns.length + 1} className="p-2 text-center bg-blue-100/50 border-b border-r border-blue-200 font-extrabold text-blue-800 tracking-wider">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 1} className="p-2 text-center bg-purple-100/50 border-b border-r border-purple-200 font-extrabold text-purple-800 tracking-wider">HỌC KỲ 2</th>
                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-300 font-bold bg-slate-200 text-slate-800">Cả Năm</th>
                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-300 font-bold bg-slate-200 text-slate-800">Xếp Loại</th>
                            <th rowSpan={2} className="p-4 w-16 text-center border-b border-slate-300 font-bold bg-yellow-50 text-yellow-800">Hạng</th>
                        </tr>
                        <tr className="bg-slate-50 text-slate-600 text-xs">
                             {hk1Columns.map((col) => (
                                <th 
                                    key={col.id}
                                    draggable={true}
                                    onDragStart={(e) => handleDragStart(e, col.id)}
                                    onDragOver={handleDragOver}
                                    onDrop={(e) => handleDrop(e, col.id)}
                                    className={`p-2 w-24 text-center border-b border-r border-slate-300 group relative min-w-[90px] bg-blue-50/30 cursor-move hover:bg-blue-100 transition-colors ${draggedColId === col.id ? 'opacity-40 border-2 border-dashed border-blue-500' : ''}`}
                                    title="Kéo thả để sắp xếp"
                                >
                                    <div className="flex flex-col items-center">
                                        <div className="flex items-center gap-1">
                                            <GripVertical size={10} className="text-slate-400" />
                                            <span className="font-bold text-slate-700">{col.name}</span>
                                        </div>
                                        <span className="text-[10px] text-slate-500 font-normal">Hệ số {col.weight}</span>
                                    </div>
                                    <button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={12} /></button>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-blue-300 font-bold bg-blue-100 text-blue-800">TB HK1</th>
                             {hk2Columns.map((col) => (
                                <th 
                                    key={col.id}
                                    draggable={true}
                                    onDragStart={(e) => handleDragStart(e, col.id)}
                                    onDragOver={handleDragOver}
                                    onDrop={(e) => handleDrop(e, col.id)}
                                    className={`p-2 w-24 text-center border-b border-r border-slate-300 group relative min-w-[90px] bg-purple-50/30 cursor-move hover:bg-purple-100 transition-colors ${draggedColId === col.id ? 'opacity-40 border-2 border-dashed border-purple-500' : ''}`}
                                    title="Kéo thả để sắp xếp"
                                >
                                    <div className="flex flex-col items-center">
                                        <div className="flex items-center gap-1">
                                            <GripVertical size={10} className="text-slate-400" />
                                            <span className="font-bold text-slate-700">{col.name}</span>
                                        </div>
                                        <span className="text-[10px] text-slate-500 font-normal">Hệ số {col.weight}</span>
                                    </div>
                                    <button onClick={() => removeColumn(col.id)} className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-600 transition-opacity" title="Xóa cột"><Trash2 size={12} /></button>
                                </th>
                             ))}
                             <th className="p-2 w-16 text-center border-b border-r border-purple-300 font-bold bg-purple-100 text-purple-800">TB HK2</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                        {processedStudentsYear.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');

                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors">
                                    <td className="p-3 text-center sticky left-0 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 font-medium text-slate-500">{idx + 1}</td>
                                    <td className="p-3 font-medium sticky left-12 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                                        <div className="text-sm text-slate-800">{s.saintName} {s.fullName}</div>
                                    </td>
                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-1 border-r border-slate-300 text-center relative">
                                            <input 
                                                type="number" 
                                                min="0"
                                                max="10"
                                                step="0.1"
                                                value={r1.scores ? (r1.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full h-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-blue-200 text-center font-bold text-blue-700 bg-blue-50">
                                        {(s.avg1 >= 0) ? s.avg1.toFixed(1) : '-'}
                                    </td>
                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-1 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                min="0"
                                                max="10"
                                                step="0.1"
                                                value={r2.scores ? (r2.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} 
                                                className="w-full h-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-purple-200 text-center font-bold text-purple-700 bg-purple-50">
                                        {(s.avg2 >= 0) ? s.avg2.toFixed(1) : '-'}
                                    </td>
                                    <td className="p-3 text-center font-bold text-slate-900 bg-slate-100 border-r border-slate-300">
                                        {s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}
                                    </td>
                                    <td className="p-3 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${s.rank.color}`}>
                                                {s.rank.label}
                                            </span>
                                        )}
                                    </td>
                                    <td className="p-3 text-center font-bold text-yellow-700 bg-yellow-50/50">
                                        {s.ranking}
                                    </td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={20} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {processedStudentsYear.length > 0 && (
                <div className="p-4 border-t border-slate-300 bg-slate-50 text-right sticky bottom-0 z-20 shadow-md">
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-bold transition-all">
                        <Save size={18} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-slate-500">Sĩ số</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                  <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                    <div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div>
                    <span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500">
