                        <input type="number" defaultValue={r.scores?.['col_15m'] || 0} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scores?.['col_45m'] || 0} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scorePray} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                       <td className="p-2 border-l text-center">
                        <input type="number" defaultValue={r.scoreExam} className="w-12 text-center p-1 rounded border border-transparent group-hover:border-slate-300 focus:border-blue-500 outline-none" />
                      </td>
                      <td className="p-4 border-l text-center font-bold text-slate-800">
                        {r.average || '-'}
                      </td>
                      <td className="p-4 border-l text-center">
                         {r.average > 0 && <span className={`px-2 py-1 rounded text-xs font-bold ${rankColor}`}>{rank}</span>}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {activeTab === 'grades' && (
           <div className="p-4 border-t border-slate-200 bg-slate-50 text-right">
             <button className="px-6 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700">Lưu Bảng Điểm</button>
           </div>
        )}
      </div>
    </div>
  );
};

export interface Student {
  id: string; // Mã học viên (Số tự động)
  saintName: string; // Tên Thánh
  fullName: string; // Họ tên
  dob: string; // Ngày tháng năm sinh
  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
  baptismBy?: string; // Do (Linh mục rửa tội)
  baptismSponsor?: string; // Người đỡ đầu Rửa tội
  baptismPlace?: string; // Tại (Nơi rửa tội)

  eucharistDate?: string; // Ngày rước lễ
  eucharistBy?: string; // Do (Linh mục cho rước lễ)
  eucharistPlace?: string; // Tại (Nơi rước lễ)

  confirmationDate?: string; // Ngày thêm sức
  confirmationBy?: string; // Do (ĐGM/Cha ban thêm sức)
  confirmationSponsor?: string; // Người đỡ đầu Thêm sức
  confirmationPlace?: string; // Tại (Nơi thêm sức)

  confirmationOathDate?: string; // Ngày tuyên hứa (Bao đồng)

  note?: string; // Ghi chú
}

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
  educationLevel: string; // Học vấn Giáo Lý (VD: Cấp 1, 2, 3...)
  role: 'ADMIN' | 'GLV'; // Phân quyền
}

export interface Saint {
  id: string;
  name: string;
  gender: 'Male' | 'Female' | 'Both';
}

export interface TermConfig {
  id: string;
  yearId: string;
  term: 'HK1' | 'HK2';
  startDate: string;
  endDate: string;
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  // Dynamic scores stored as key-value pairs
  scores: { [key: string]: number }; 
  scorePray: number; // Điểm kinh (keep separate as it's standard)
  scoreExam: number; // Thi (keep separate)
  // Computed
  average: number;
  // Attendance Sync
  absentP: number; // Vắng có phép
  absentK: number; // Vắng không phép
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
  class: boolean; // Học giáo lý
  classExcused: boolean;
}

export interface ClassRoom {
  id: string;
  name: string; // e.g., Chiên Con 1
  gradeId: string; // Linked to Grade
  yearId: string; // Linked to School Year
  mainTeacher?: string; // GLV Chủ nhiệm
  assistants?: string; // GLV Phụ trách/Phụ tá
  room?: string; // Phòng học
}

export interface Grade {
  id: string;
  name: string; // e.g., Khối Khai Tâm
}

export interface SchoolYear {
  id: string;
  name: string;
  isActive: boolean;
}

export interface Transaction {
  id: string;
  date: string;
  type: 'INCOME' | 'EXPENSE';
  amount: number;
  description: string;
  note?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  type: 'NOTICE' | 'MEETING_MINUTES';
}

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES, MOCK_TERM_CONFIGS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade, TermConfig } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // GLOBAL STATE
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);
  const [termConfigs, setTermConfigs] = useState<TermConfig[]>(MOCK_TERM_CONFIGS);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'classes':
        return <Classes 
          classes={classes}
          setClasses={setClasses}
          students={students}
          years={years}
          grades={grades}
        />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
          records={records}
          grades={grades}
        />;
      case 'placement':
        return <ClassPlacement 
          students={students}
          setStudents={setStudents}
          classes={classes}
          years={years}
          grades={grades}
        />;
      case 'teachers':
        return <Teachers />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
          grades={grades}
          setRecords={setRecords}
          termConfigs={termConfigs}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
          grades={grades}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
          grades={grades}
          setGrades={setGrades}
          termConfigs={termConfigs}
          setTermConfigs={setTermConfigs}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
      />
      <main className="flex-1 ml-64 transition-all duration-300">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Calendar, Layers, Save, Plus, Trash2, Cross, CheckCircle, CheckCircle2, GripVertical, Clock, AlertCircle } from 'lucide-react';
import { Saint, SchoolYear, ClassRoom, Grade, TermConfig } from '../types';

interface SettingsProps {
    years: SchoolYear[];
    setYears: (years: SchoolYear[]) => void;
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    grades: Grade[];
    setGrades: (grades: Grade[]) => void;
    termConfigs: TermConfig[];
    setTermConfigs: (configs: TermConfig[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ years, setYears, classes, setClasses, grades, setGrades, termConfigs, setTermConfigs }) => {
  const [saints, setSaints] = useState<Saint[]>(MOCK_SAINTS);
  const [newSaintName, setNewSaintName] = useState('');
  const [newSaintGender, setNewSaintGender] = useState<'Male'|'Female'>('Male');
  const [toast, setToast] = useState<string | null>(null);

  // Drag states
  const [draggedGradeId, setDraggedGradeId] = useState<string | null>(null);
  const [dragOverGradeId, setDragOverGradeId] = useState<string | null>(null);

  const [draggedClassId, setDraggedClassId] = useState<string | null>(null);
  const [dragOverClassId, setDragOverClassId] = useState<string | null>(null);

  const [activeYearForTerms, setActiveYearForTerms] = useState('');

  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) setActiveYearForTerms(active.id);
    else if (years.length > 0) setActiveYearForTerms(years[0].id);
  }, [years]);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState(grades[0]?.id || '');

  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  // --- TERM CONFIG LOGIC ---
  const hk1Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK1');
  const hk2Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK2');

  const updateTermDate = (term: 'HK1' | 'HK2', field: 'startDate' | 'endDate', value: string) => {
      setTermConfigs(prev => {
          const existingIdx = prev.findIndex(c => c.yearId === activeYearForTerms && c.term === term);
          if (existingIdx > -1) {
              const newConfigs = [...prev];
              newConfigs[existingIdx] = { ...newConfigs[existingIdx], [field]: value };
              return newConfigs;
          } else {
              const newConfig: TermConfig = {
                  id: `term_${Date.now()}`,
                  yearId: activeYearForTerms,
                  term: term,
                  startDate: field === 'startDate' ? value : '',
                  endDate: field === 'endDate' ? value : ''
              };
              return [...prev, newConfig];
          }
      });
  };

  const handleSaveTerms = () => {
      showToast("Đã cập nhật mốc thời gian học kỳ thành công!");
  };

  // --- GRADE SORTING LOGIC ---
  const handleGradeDragStart = (e: React.DragEvent, id: string) => {
    setDraggedGradeId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleGradeDragEnter = (id: string) => {
    if (draggedGradeId && draggedGradeId !== id) {
        setDragOverGradeId(id);
    }
  };

  const handleGradeDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    setDragOverGradeId(null);
    if (!draggedGradeId || draggedGradeId === targetId) return;

    const sourceIndex = grades.findIndex(g => g.id === draggedGradeId);
    const targetIndex = grades.findIndex(g => g.id === targetId);

    const newGrades = [...grades];
    const [removed] = newGrades.splice(sourceIndex, 1);
    newGrades.splice(targetIndex, 0, removed);

    setGrades(newGrades);
    setDraggedGradeId(null);
    showToast("Cập nhật thứ tự Khối lớp thành công!");
  };

  // --- CLASS SORTING LOGIC ---
  const handleClassDragStart = (e: React.DragEvent, id: string) => {
    setDraggedClassId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleClassDragEnter = (id: string) => {
    if (draggedClassId && draggedClassId !== id) {
        setDragOverClassId(id);
    }
  };

  const handleClassDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    setDragOverClassId(null);
    if (!draggedClassId || draggedClassId === targetId) return;

    const sourceIndex = classes.findIndex(c => c.id === draggedClassId);
    const targetIndex = classes.findIndex(c => c.id === targetId);

    const newClasses = [...classes];
    const [removed] = newClasses.splice(sourceIndex, 1);
    newClasses.splice(targetIndex, 0, removed);

    setClasses(newClasses);
    setDraggedClassId(null);
    showToast("Cập nhật thứ tự Lớp học thành công!");
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDragEnd = () => {
    setDraggedGradeId(null);
    setDragOverGradeId(null);
    setDraggedClassId(null);
    setDragOverClassId(null);
  };

  const handleAddSaint = () => {
    if (newSaintName) {
      const newSaint: Saint = { id: `s${Date.now()}`, name: newSaintName, gender: newSaintGender };
      setSaints([...saints, newSaint]);
      showToast(`Đã thêm tên thánh "${newSaintName}" thành công!`);
      setNewSaintName('');
    }
  };

  const handleRemoveSaint = (id: string) => {
    const saint = saints.find(s => s.id === id);
    setSaints(saints.filter(s => s.id !== id));
    showToast(`Đã xóa tên thánh "${saint?.name}" thành công!`);
  };

  const handleAddYear = () => {
      if (newYearName) {
          const newId = newYearName.replace(/\s/g, '-');
          const newYear: SchoolYear = { id: newId, name: newYearName, isActive: false };
          setYears([...years, newYear]);
          showToast(`Đã thêm năm học "${newYearName}" thành công!`);
          setNewYearName('');
      }
  };

  const handleSetActiveYear = (id: string) => {
      const year = years.find(y => y.id === id);
      const updatedYears = years.map(y => ({ ...y, isActive: y.id === id }));
      setYears(updatedYears);
      showToast(`Đã đặt "${year?.name}" làm năm học hiện tại!`);
  };

  const handleAddClass = () => {
      if (newClassName && activeYear) {
          const newClass: ClassRoom = { id: `c_${Date.now()}`, name: newClassName, gradeId: newClassGrade, yearId: activeYear.id, mainTeacher: 'Chưa phân công' };
          setClasses([...classes, newClass]);
          showToast(`Đã thêm lớp "${newClassName}" thành công!`);
          setNewClassName('');
      } else {
          alert("Vui lòng nhập tên lớp và đảm bảo có năm học đang kích hoạt.");
      }
  };

  return (
    <div className="p-6 h-screen overflow-y-auto custom-scrollbar relative bg-slate-50/50">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <h2 className="text-3xl font-bold text-slate-800 mb-8 px-2 border-l-8 border-blue-600">Cài Đặt Hệ Thống</h2>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 mb-8">

        {/* Quản Lý Năm Học */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Calendar className="text-blue-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Năm Học</h3></div>
          <div className="space-y-6">
            <div><label className="block text-sm font-bold text-slate-500 uppercase mb-3">Danh sách niên khóa</label><div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar border rounded-xl p-3 bg-slate-50">{years.map(y => (<div key={y.id} className={`flex justify-between items-center p-3 rounded-lg shadow-sm transition-all ${y.isActive ? 'bg-blue-600 text-white border-blue-500 scale-[1.02]' : 'bg-white border border-slate-200'}`}><span className={y.isActive ? 'font-extrabold' : 'font-medium text-slate-700'}>{y.name} {y.isActive && '(Hiện tại)'}</span>{!y.isActive && (<button onClick={() => handleSetActiveYear(y.id)} className="text-xs px-3 py-1.5 bg-slate-100 border border-slate-300 rounded-md font-bold text-slate-600 hover:bg-slate-200 transition-colors">Đặt làm hiện tại</button>)}</div>))}</div></div>
            <div className="bg-blue-50 p-5 rounded-xl border border-blue-100"><h4 className="font-bold text-blue-800 text-sm mb-4 uppercase">Tạo Năm Học Mới</h4><div className="flex gap-3"><input type="text" placeholder="Tên niên khóa (VD: 2024-2025)" className="flex-1 p-3 border border-blue-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={newYearName} onChange={(e) => setNewYearName(e.target.value)}/><button onClick={handleAddYear} className="flex items-center justify-center gap-2 px-6 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 transition-all shadow-md"><Plus size={18}/> Thêm</button></div></div>
          </div>
        </div>

        {/* Cấu hình Thời gian Học Kỳ */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
            <div className="flex items-center gap-3 mb-6 border-b pb-4"><Clock className="text-rose-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Cấu Hình Thời Gian Học Kỳ</h3></div>
            <div className="space-y-6">
                <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Chọn năm học cấu hình</label>
                    <select 
                        className="w-full p-3 border rounded-xl text-sm font-bold text-slate-700 bg-slate-50"
                        value={activeYearForTerms}
                        onChange={(e) => setActiveYearForTerms(e.target.value)}
                    >
                        {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                    </select>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                        <h4 className="font-bold text-blue-800 text-xs mb-3 uppercase flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> Học Kỳ 1</h4>
                        <div className="space-y-3">
                            <div>
                                <label className="text-[10px] text-blue-600 font-bold uppercase">Bắt đầu</label>
                                <input type="date" className="w-full p-2 text-xs border border-blue-200 rounded-lg outline-none" value={hk1Config?.startDate || ''} onChange={(e) => updateTermDate('HK1', 'startDate', e.target.value)}/>
                            </div>
                            <div>
                                <label className="text-[10px] text-blue-600 font-bold uppercase">Kết thúc</label>
                                <input type="date" className="w-full p-2 text-xs border border-blue-200 rounded-lg outline-none" value={hk1Config?.endDate || ''} onChange={(e) => updateTermDate('HK1', 'endDate', e.target.value)}/>
                            </div>
                        </div>
                    </div>

                    <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                        <h4 className="font-bold text-purple-800 text-xs mb-3 uppercase flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-purple-500"></div> Học Kỳ 2</h4>
                        <div className="space-y-3">
                            <div>
                                <label className="text-[10px] text-purple-600 font-bold uppercase">Bắt đầu</label>
                                <input type="date" className="w-full p-2 text-xs border border-purple-200 rounded-lg outline-none" value={hk2Config?.startDate || ''} onChange={(e) => updateTermDate('HK2', 'startDate', e.target.value)}/>
                            </div>
                            <div>
                                <label className="text-[10px] text-purple-600 font-bold uppercase">Kết thúc</label>
                                <input type="date" className="w-full p-2 text-xs border border-purple-200 rounded-lg outline-none" value={hk2Config?.endDate || ''} onChange={(e) => updateTermDate('HK2', 'endDate', e.target.value)}/>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex items-start gap-2 text-xs text-amber-600 bg-amber-50 p-3 rounded-lg border border-amber-100">
                    <AlertCircle size={16} className="mt-0.5 shrink-0" />
                    <span>Mốc thời gian này sẽ được dùng để tự động phân loại số buổi vắng vào bảng điểm HK1 hoặc HK2.</span>
                </div>

                <button onClick={handleSaveTerms} className="w-full flex items-center justify-center gap-2 py-3 bg-rose-600 text-white rounded-xl font-bold hover:bg-rose-700 shadow-md transition-all uppercase text-sm">
                    <Save size={18}/> Lưu Cấu Hình Thời Gian
                </button>
            </div>
        </div>

        {/* Quản Lý Tên Thánh */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Cross className="text-amber-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Tên Thánh</h3></div>
          <div className="space-y-6">
             <div className="flex gap-3 bg-amber-50 p-4 rounded-xl border border-amber-100"><input type="text" placeholder="Nhập tên thánh..." className="flex-1 p-3 border border-amber-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-amber-500" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-3 border border-amber-200 rounded-xl text-sm bg-white" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-6 py-3 bg-amber-600 text-white rounded-xl hover:bg-amber-700 font-extrabold shadow-md transition-all">+</button></div>
            <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-80 overflow-y-auto custom-scrollbar bg-slate-50"><table className="w-full text-left text-sm"><thead className="bg-slate-100 border-b border-slate-200 sticky top-0 z-10"><tr><th className="p-4 font-bold text-slate-600">Tên Thánh</th><th className="p-4 font-bold text-slate-600 w-24">Giới tính</th><th className="p-4 w-16"></th></tr></thead><tbody className="divide-y divide-slate-200 bg-white">{saints.map(s => (<tr key={s.id} className="hover:bg-amber-50/50 transition-colors"><td className="p-4 font-bold text-slate-700">{s.name}</td><td className="p-4"><span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${s.gender === 'Male' ? 'bg-blue-100 text-blue-700' : 'bg-pink-100 text-pink-700'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td><td className="p-4 text-right"><button onClick={() => handleRemoveSaint(s.id)} className="p-2 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={18} /></button></td></tr>))}</tbody></table></div>
          </div>
        </div>

        {/* Quản lý Khối lớp (Bigger Box with Enhanced Drag UI) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 xl:row-span-2">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Layers className="text-purple-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Khối Lớp (Thứ tự Kéo thả)</h3></div>
          <div className="space-y-6">
             <div className="flex gap-3"><input type="text" placeholder="Tên khối lớp mới..." className="flex-1 p-3 border rounded-xl focus:ring-2 focus:ring-purple-500 outline-none shadow-sm" /><button className="px-6 py-3 bg-purple-600 text-white rounded-xl hover:bg-purple-700 font-extrabold shadow-md transition-all uppercase text-sm tracking-widest">Thêm Khối</button></div>
            <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-[600px] overflow-y-auto custom-scrollbar shadow-inner bg-slate-50 p-1">
                <table className="w-full text-left text-sm border-separate border-spacing-y-2">
                    <thead className="bg-slate-100 border-b border-slate-200 sticky top-0 z-10">
                        <tr>
                            <th className="p-4 w-14"></th>
                            <th className="p-4 font-extrabold text-slate-600 uppercase tracking-tighter">Tên Khối Lớp</th>
                            <th className="p-4 text-right w-24"></th>
                        </tr>
                    </thead>
                    <tbody className="bg-transparent">
                        {grades.map(g => {
                            const isDragging = draggedGradeId === g.id;
                            const isOver = dragOverGradeId === g.id;

                            return (
                                <tr 
                                    key={g.id} 
                                    draggable 
                                    onDragStart={(e) => handleGradeDragStart(e, g.id)}
                                    onDragOver={handleDragOver}
                                    onDragEnter={() => handleGradeDragEnter(g.id)}
                                    onDragEnd={handleDragEnd}
                                    onDrop={(e) => handleGradeDrop(e, g.id)}
                                    className={`group transition-all duration-200 ${
                                        isDragging ? 'opacity-30 scale-95 cursor-grabbing border-2 border-dashed border-purple-500' : 'cursor-grab bg-white shadow-sm border border-transparent'
                                    } ${
                                        isOver ? 'ring-4 ring-purple-400 ring-inset bg-purple-50 translate-x-2' : ''
                                    } hover:shadow-md rounded-xl overflow-hidden`}
                                >
                                    <td className="p-5 text-slate-300 group-hover:text-purple-500 transition-colors rounded-l-xl"><GripVertical size={24} /></td>
                                    <td className="p-5 font-black text-slate-800 text-lg uppercase tracking-tight">{g.name}</td>
                                    <td className="p-5 text-right rounded-r-xl"><button className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={22} /></button></td>
                                </tr>
                            )
                        })}
                    </tbody>
                </table>
            </div>
          </div>
        </div>

        {/* Quản lý Lớp học (Bigger Box with Enhanced Drag UI) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 xl:row-span-2">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Layers className="text-emerald-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Danh Sách Lớp Học ({activeYear?.name})</h3></div>
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 bg-emerald-50 p-5 rounded-xl border border-emerald-100">
                <input type="text" placeholder="Tên lớp (VD: Chiên Con 3)..." className="p-3 border border-emerald-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 text-sm shadow-sm" value={newClassName} onChange={(e) => setNewClassName(e.target.value)} />
                <div className="flex gap-2">
                    <select className="flex-1 p-3 border border-emerald-200 rounded-xl bg-white text-sm shadow-sm font-bold text-emerald-800" value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value)}>{grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
                    <button onClick={handleAddClass} className="px-6 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 font-extrabold transition-all shadow-md">+</button>
                </div>
            </div>
            <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-[600px] overflow-y-auto custom-scrollbar shadow-inner bg-slate-50 p-1">
                <table className="w-full text-left text-sm border-separate border-spacing-y-2">
                    <thead className="bg-slate-100 border-b border-slate-200 sticky top-0 z-10">
                        <tr>
                            <th className="p-4 w-14"></th>
                            <th className="p-4 font-extrabold text-slate-600 uppercase tracking-tighter">Tên Lớp</th>
                            <th className="p-4 font-extrabold text-slate-600 uppercase tracking-tighter">Thuộc Khối</th>
                            <th className="p-4 w-16"></th>
                        </tr>
                    </thead>
                    <tbody className="bg-transparent">
                        {classesInActiveYear.length > 0 ? (classesInActiveYear.map(c => {
                            const gradeName = grades.find(g => g.id === c.gradeId)?.name || '---'; 
                            const isDragging = draggedClassId === c.id;
                            const isOver = dragOverClassId === c.id;

                            return (
                                <tr 
                                    key={c.id}
                                    draggable
                                    onDragStart={(e) => handleClassDragStart(e, c.id)}
                                    onDragOver={handleDragOver}
                                    onDragEnter={() => handleClassDragEnter(c.id)}
                                    onDragEnd={handleDragEnd}
                                    onDrop={(e) => handleClassDrop(e, c.id)}
                                    className={`group transition-all duration-200 ${
                                        isDragging ? 'opacity-30 scale-95 cursor-grabbing border-2 border-dashed border-emerald-500' : 'cursor-grab bg-white shadow-sm border border-transparent'
                                    } ${
                                        isOver ? 'ring-4 ring-emerald-400 ring-inset bg-emerald-50 translate-x-2' : ''
                                    } hover:shadow-md rounded-xl overflow-hidden`}
                                >
                                    <td className="p-5 text-slate-300 group-hover:text-emerald-500 transition-colors rounded-l-xl"><GripVertical size={24} /></td>
                                    <td className="p-5 font-black text-slate-800 text-lg">{c.name}</td>
                                    <td className="p-5 font-bold text-emerald-600/70">{gradeName}</td>
                                    <td className="p-5 text-right rounded-r-xl"><button className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={22} /></button></td>
                                </tr>
                            )})) : (
                                <tr><td colSpan={4} className="p-12 text-center text-slate-400 italic font-medium">Niên khóa này chưa có lớp học nào được tạo.</td></tr>
                            )}
                    </tbody>
                </table>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }

        /* Custom styles for dragging ghost image */
        tr[draggable="true"] {
            user-select: none;
        }

        .cursor-grab { cursor: grab; }
        .cursor-grabbing { cursor: grabbing; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, AcademicRecord, TermConfig } from '../types';
import { CheckCircle2, Info, Save, Calendar, UserCheck, Search } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    termConfigs: TermConfig[];
}

type AttendanceStatus = 'P' | 'K' | ''; // Trống = Hiện diện, P: Phép, K: Không phép

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years, grades, setRecords, termConfigs }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [toast, setToast] = useState<string | null>(null);

  const [attendanceData, setAttendanceData] = useState<Record<string, AttendanceStatus>>({});

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);

  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleStatusChange = (studentId: string, date: string, type: 'mass' | 'class', status: AttendanceStatus) => {
    const key = `${studentId}-${date}-${type}`;
    setAttendanceData(prev => ({
        ...prev,
        [key]: status
    }));
  };

  const handleSave = () => {
      // Improved Sync logic using Term Configs
      const [yearStr, monthStr] = selectedMonth.split('-');
      const monthDateStr = `${selectedMonth}-15`; // Pick a mid-month date to check

      let term: 'HK1' | 'HK2' = 'HK1'; // Default

      const config1 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK1');
      const config2 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK2');

      if (config1 && monthDateStr >= config1.startDate && monthDateStr <= config1.endDate) {
          term = 'HK1';
      } else if (config2 && monthDateStr >= config2.startDate && monthDateStr <= config2.endDate) {
          term = 'HK2';
      } else {
          // Fallback to legacy month-based logic if no config found
          const m = parseInt(monthStr);
          term = (m >= 9 || m <= 1) ? 'HK1' : 'HK2';
      }

      setRecords(prev => {
          const newRecords = [...prev];

          filteredStudents.forEach(student => {
              let currentP = 0;
              let currentK = 0;

              sundaysInMonth.forEach(sunday => {
                  const dateStr = sunday.toISOString().split('T')[0];
                  // Mass absences
                  const massStatus = attendanceData[`${student.id}-${dateStr}-mass`];
                  if (massStatus === 'P') currentP++;
                  else if (massStatus === 'K') currentK++;

                  // Class absences
                  const classStatus = attendanceData[`${student.id}-${dateStr}-class`];
                  if (classStatus === 'P') currentP++;
                  else if (classStatus === 'K') currentK++;
              });

              const existingIdx = newRecords.findIndex(r => r.studentId === student.id && r.term === term);
              if (existingIdx > -1) {
                  newRecords[existingIdx] = {
                      ...newRecords[existingIdx],
                      absentP: (newRecords[existingIdx].absentP || 0) + currentP,
                      absentK: (newRecords[existingIdx].absentK || 0) + currentK
                  };
              } else {
                  newRecords.push({
                      studentId: student.id,
                      term: term,
                      scores: {},
                      scorePray: 0,
                      scoreExam: 0,
                      average: 0,
                      absentP: currentP,
                      absentK: currentK
                  });
              }
          });

          return newRecords;
      });

      showToast(`Đã lưu & đồng bộ vắng mặt vào ${term === 'HK1' ? 'Học kỳ 1' : 'Học kỳ 2'} thành công!`);
  };

  const getStatusStyle = (status: AttendanceStatus | undefined) => {
      switch (status) {
          case 'P': return 'bg-amber-500 text-white border-amber-600 font-black shadow-inner';
          case 'K': return 'bg-red-600 text-white border-red-700 font-black shadow-inner';
          default: return 'bg-white text-transparent border-slate-200 hover:border-blue-300';
      }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Danh Chuyên Cần</h2>
        <div className="flex items-center gap-2 text-sm text-slate-500 bg-white px-3 py-1.5 rounded-lg border shadow-sm">
            <Calendar size={16} className="text-blue-500" />
            <span>Tháng {selectedMonth.split('-')[1]}/{selectedMonth.split('-')[0]}</span>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center flex-wrap">
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[180px] text-sm focus:ring-2 focus:ring-blue-500 outline-none font-bold text-slate-700" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>

        <div className="flex items-center gap-2 border-l pl-4 ml-2">
            <input type="month" className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-bold text-blue-600 focus:ring-2 focus:ring-blue-500 outline-none" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} />
        </div>
      </div>

      <div className="bg-blue-600 text-white p-4 mb-4 flex items-center gap-3 shadow-lg rounded-xl animate-fade-in border-b-4 border-blue-800">
        <div className="bg-white/20 p-2 rounded-lg"><Info size={24} className="text-white" /></div>
        <div className="flex flex-col">
            <span className="font-extrabold text-sm tracking-wide uppercase">QUY ƯỚC ĐIỂM DANH:</span>
            <span className="text-sm opacity-95">Mặc định ô để <b>TRỐNG = HIỆN DIỆN</b>. Chỉ cần chọn <b>P</b> hoặc <b>K</b> nếu em vắng.</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-100 text-slate-800 text-xs">
                 <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-30 border-b border-r border-slate-300 font-bold">STT</th>
                 <th rowSpan={2} className="p-4 min-w-[220px] sticky left-12 bg-slate-100 z-30 border-b border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => {
                    const isEven = idx % 2 === 0;
                    const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50';
                    return (
                        <th key={idx} colSpan={2} className={`p-2 text-center border-b border-r border-slate-300 ${bgClass}`}>
                            <div className="flex flex-col">
                                <span className={`font-bold ${isEven ? 'text-slate-600' : 'text-blue-700'}`}>CN {idx + 1}</span>
                                <span className="text-[10px] font-normal text-slate-400">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                            </div>
                        </th>
                    );
                 })}
                 <th rowSpan={2} className="p-4 text-center border-b border-slate-300 min-w-[150px] font-bold">Ghi chú</th>
               </tr>
               <tr className="text-[10px] uppercase tracking-tighter font-bold bg-slate-50">
                    {sundaysInMonth.map((_, idx) => {
                        const isEven = idx % 2 === 0;
                        const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50/50';
                        return (
                            <React.Fragment key={idx}>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[50px] text-purple-600 ${bgClass}`}>Lễ</th>
                                <th className={`p-1.5 text-center border-b border-r border-slate-300 min-w-[50px] text-blue-600 ${bgClass}`}>Học</th>
                            </React.Fragment>
                        );
                    })}
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-200">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-200">
                   <td className="p-3 text-center text-slate-400 sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 text-xs font-bold">{idx + 1}</td>
                   <td className="p-3 sticky left-12 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const isEven = i % 2 === 0;
                       const cellClass = isEven ? 'bg-white group-hover:bg-blue-50/20' : 'bg-blue-50/10 group-hover:bg-blue-50/30';

                       const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const classStatus = attendanceData[`${s.id}-${dateStr}-class`];

                       return (
                           <React.Fragment key={i}>
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={massStatus || ''} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1.5 rounded text-xs border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(massStatus)}`}
                                   >
                                       <option value="" className="bg-white text-slate-300">-</option>
                                       <option value="P" className="bg-amber-500 text-white font-bold">P (Vắng phép)</option>
                                       <option value="K" className="bg-red-600 text-white font-bold">K (Không phép)</option>
                                   </select>
                               </td>
                               <td className={`p-1 border-r border-slate-200 text-center ${cellClass}`}>
                                   <select 
                                      value={classStatus || ''} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1.5 rounded text-xs border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(classStatus)}`}
                                   >
                                       <option value="" className="bg-white text-slate-300">-</option>
                                       <option value="P" className="bg-amber-500 text-white font-bold">P (Vắng phép)</option>
                                       <option value="K" className="bg-red-600 text-white font-bold">K (Không phép)</option>
                                   </select>
                               </td>
                           </React.Fragment>
                       );
                   })}

                   <td className="p-2 border-r border-slate-200">
                     <input type="text" className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-[11px] py-1 transition-all" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để hiển thị danh sách học viên</td></tr>
               )}
             </tbody>
           </table>
        </div>

        {filteredStudents.length > 0 && (
            <div className="p-4 border-t border-slate-300 bg-slate-100 flex justify-between items-center sticky bottom-0 z-30 shadow-inner">
                 <div className="flex gap-6 text-sm">
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-white border border-slate-300 rounded shadow-sm"></span> <span className="text-slate-600">Ô trống: Hiện diện</span></div>
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-amber-500 border border-amber-600 rounded shadow-sm text-[10px] flex items-center justify-center font-black text-white">P</span> <span className="text-amber-700 font-bold">Vắng có phép</span></div>
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-red-600 border border-red-700 rounded shadow-sm text-[10px] flex items-center justify-center font-black text-white">K</span> <span className="text-red-700 font-bold">Vắng không phép</span></div>
                 </div>
                 <button onClick={handleSave} className="px-10 py-3 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold flex items-center gap-2 transition-all transform hover:-translate-y-1 active:scale-95">
                     <Save size={20}/> Lưu Điểm Danh
                 </button>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
