import React, { useState } from 'react';
import { MOCK_TEACHERS, MOCK_SAINTS } from '../constants';
import { Teacher } from '../types';
import { Search, Plus, Edit, Trash2, X, AlertTriangle, Check } from 'lucide-react';

export const Teachers: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [selectedTeacher, setSelectedTeacher] = useState<Teacher | null>(null);

  // Delete Confirmation State
  const [teacherToDelete, setTeacherToDelete] = useState<Teacher | null>(null);

  // Saint Selector State
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [saintInput, setSaintInput] = useState('');

  const filteredTeachers = MOCK_TEACHERS.filter(t => {
    return t.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
           t.saintName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  const filteredSaints = MOCK_SAINTS.filter(s => 
    s.name.toLowerCase().includes(saintInput.toLowerCase())
  );

  const openTeacherDetail = (teacher: Teacher) => {
    setSelectedTeacher(teacher);
    setSaintInput(teacher.saintName);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedTeacher(null);
    setSaintInput('');
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedTeacher(null);
    setShowSaintSuggestions(false);
  };

  const handleDeleteTeacher = () => {
    if (teacherToDelete) {
        alert(`Đã xóa Giáo Lý Viên: ${teacherToDelete.fullName}`);
        // In a real app, you would call an API here
        setTeacherToDelete(null);
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Quản Lý Giáo Lý Viên</h2>
        <button 
          onClick={handleAddNew}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm"
        >
          <Plus size={18} /> Thêm Mới
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Tìm theo Tên Thánh, Họ tên..." 
            className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-300">
                <th className="p-4 font-semibold w-16 text-center">STT</th>
                <th className="p-4 font-semibold w-24">Mã GLV</th>
                <th className="p-4 font-semibold">Tên Thánh & Họ Tên</th>
                <th className="p-4 font-semibold">Vai trò</th>
                <th className="p-4 font-semibold">Liên Hệ</th>
                <th className="p-4 font-semibold">Học Vấn GL</th>
                <th className="p-4 font-semibold text-center">Thao tác</th>
              </tr>
            </thead>
            <tbody className="">
              {filteredTeachers.map((t, index) => (
                <tr key={t.id} className="hover:bg-slate-50 transition-colors border-b border-slate-200">
                  <td className="p-4 text-center text-slate-500">{index + 1}</td>
                  <td className="p-4 font-mono text-xs text-slate-500">{t.id}</td>
                  <td className="p-4">
                    <div className="font-semibold text-slate-800">{t.saintName} {t.fullName}</div>
                    <div className="text-xs text-slate-500">{new Date(t.dob).toLocaleDateString('vi-VN')} - {t.birthPlace}</div>
                  </td>
                  <td className="p-4">
                    {t.role === 'ADMIN' ? (
                        <span className="px-2 py-1 bg-red-100 text-red-700 text-xs rounded-full font-bold">Quản Trị</span>
                    ) : (
                        <span className="px-2 py-1 bg-blue-50 text-blue-700 text-xs rounded-full font-medium">Giáo Lý Viên</span>
                    )}
                  </td>
                  <td className="p-4 text-sm text-slate-600">
                    <div>{t.phone}</div>
                    <div className="text-xs text-blue-600">{t.email}</div>
                  </td>
                  <td className="p-4 text-sm text-slate-700">
                    <span className="px-2 py-1 bg-purple-50 text-purple-700 text-xs rounded-full font-medium">
                      {t.educationLevel}
                    </span>
                  </td>
                  <td className="p-4">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => openTeacherDetail(t)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg">
                        <Edit size={18} />
                      </button>
                      <button 
                        onClick={() => setTeacherToDelete(t)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {(showModal || selectedTeacher) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl overflow-hidden flex flex-col">
            <div className="p-6 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <h3 className="text-xl font-bold text-slate-800">
                {selectedTeacher ? 'Cập Nhật Hồ Sơ GLV' : 'Thêm Giáo Lý Viên'}
              </h3>
              <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto custom-scrollbar">
               <div className="space-y-4">
                   <div className="grid grid-cols-2 gap-4">
                       <div>
                           <label className="block text-xs font-semibold text-slate-500 mb-1">Mã GLV</label>
                           <input type="text" disabled defaultValue={selectedTeacher?.id || 'AUTO'} className="w-full p-2 border rounded-md bg-slate-100" />
                       </div>
                       <div>
                           <label className="block text-xs font-semibold text-slate-500 mb-1">Quyền hạn</label>
                           <select className="w-full p-2 border rounded-md" defaultValue={selectedTeacher?.role || 'GLV'}>
                               <option value="GLV">Giáo Lý Viên</option>
                               <option value="ADMIN">Quản Trị Viên (Admin)</option>
                           </select>
                       </div>
                    </div>
                   <div className="grid grid-cols-2 gap-4">
                      {/* Saint Name Selector */}
                      <div className="relative">
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Tên Thánh</label>
                         <input 
                            type="text" 
                            className="w-full p-2 border rounded-md" 
                            placeholder="Nhập và chọn tên thánh"
                            value={saintInput}
                            onChange={(e) => {
                              setSaintInput(e.target.value);
                              setShowSaintSuggestions(true);
                            }}
                            onFocus={() => setShowSaintSuggestions(true)}
                            onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)}
                         />
                         {showSaintSuggestions && (
                           <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">
                             {filteredSaints.length > 0 ? (
                               filteredSaints.map(s => (
                                 <div 
                                    key={s.id} 
                                    className="p-2 hover:bg-blue-50 cursor-pointer text-sm"
                                    onClick={() => {
                                      setSaintInput(s.name);
                                      setShowSaintSuggestions(false);
                                    }}
                                  >
                                    {s.name} <span className="text-xs text-slate-400">({s.gender === 'Male' ? 'Nam' : 'Nữ'})</span>
                                  </div>
                               ))
                             ) : (
                               <div className="p-2 text-xs text-slate-400">Không tìm thấy</div>
                             )}
                           </div>
                         )}
                      </div>
                      <div>
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Họ và Tên</label>
                         <input type="text" defaultValue={selectedTeacher?.fullName} className="w-full p-2 border rounded-md" />
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Ngày sinh</label>
                         <input type="date" defaultValue={selectedTeacher?.dob} className="w-full p-2 border rounded-md" />
                      </div>
                      <div>
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Nơi sinh</label>
                         <input type="text" defaultValue={selectedTeacher?.birthPlace} className="w-full p-2 border rounded-md" />
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Số điện thoại</label>
                         <input type="text" defaultValue={selectedTeacher?.phone} className="w-full p-2 border rounded-md" />
                      </div>
                      <div>
                         <label className="block text-xs font-semibold text-slate-500 mb-1">Email</label>
                         <input type="email" defaultValue={selectedTeacher?.email} className="w-full p-2 border rounded-md" />
                      </div>
                   </div>
                   <div>
                       <label className="block text-xs font-semibold text-slate-500 mb-1">Địa chỉ</label>
                       <input type="text" defaultValue={selectedTeacher?.address} className="w-full p-2 border rounded-md" />
                   </div>
                   <div>
                       <label className="block text-xs font-semibold text-slate-500 mb-1">Học vấn Giáo Lý</label>
                       <select className="w-full p-2 border rounded-md" defaultValue={selectedTeacher?.educationLevel}>
                           <option value="">-- Chọn --</option>
                           <option value="TNTT Cấp 1">TNTT Cấp 1</option>
                           <option value="TNTT Cấp 2">TNTT Cấp 2</option>
                           <option value="TNTT Cấp 3">TNTT Cấp 3</option>
                           <option value="GLV Cấp 1">GLV Cấp 1</option>
                           <option value="GLV Cấp 2">GLV Cấp 2</option>
                           <option value="GLV Cấp 3">GLV Cấp 3</option>
                       </select>
                   </div>
               </div>
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
              <button onClick={closeModal} className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-100">Hủy</button>
              <button onClick={closeModal} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">Lưu Thông Tin</button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {teacherToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
            <div className="flex items-center gap-3 text-red-600 mb-4">
              <div className="p-3 bg-red-100 rounded-full">
                <AlertTriangle size={24} />
              </div>
              <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa</h3>
            </div>

            <p className="text-slate-600 mb-6 leading-relaxed">
              Bạn có chắc chắn muốn xóa Giáo Lý Viên <span className="font-bold text-slate-800">{teacherToDelete.saintName} {teacherToDelete.fullName}</span> không? 
              <br/><span className="text-sm italic text-red-500">Hành động này không thể hoàn tác.</span>
            </p>

            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setTeacherToDelete(null)} 
                className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 font-medium transition-colors"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleDeleteTeacher} 
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-medium shadow-sm transition-colors"
              >
                Xóa Vĩnh Viễn
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_TEACHERS } from '../constants';
import { ClassRoom, SchoolYear, Student, Grade } from '../types';
import { Users, User, UserCheck, Edit, X, Save, CheckCircle2, Search } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
    grades: Grade[];
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  const [mainTeacherInput, setMainTeacherInput] = useState('');
  const [showMainTeacherSuggestions, setShowMainTeacherSuggestions] = useState(false);

  const [assistants, setAssistants] = useState<string[]>(['', '', '']);
  const [showAssistSuggestions, setShowAssistSuggestions] = useState<boolean[]>([false, false, false]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  useEffect(() => {
    if (editingClass) {
        const parts = editingClass.assistants ? editingClass.assistants.split(',').map(s => s.trim()) : [];
        setAssistants([parts[0] || '', parts[1] || '', parts[2] || '']);
        setMainTeacherInput(editingClass.mainTeacher || '');
    }
  }, [editingClass]);

  const filteredClasses = useMemo(() => {
      return classes.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [classes, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        const combinedAssistants = assistants
            .map(s => s.trim())
            .filter(s => s !== '')
            .join(', ');

        const finalClassData = { 
            ...editingClass, 
            mainTeacher: mainTeacherInput, 
            assistants: combinedAssistants 
        };

        const updatedClasses = classes.map(c => c.id === editingClass.id ? finalClassData : c);
        setClasses(updatedClasses);
        showToast(`Đã cập nhật thông tin lớp ${editingClass.name} thành công!`);
        setEditingClass(null);
    }
  };

  const sortedTeachers = useMemo(() => {
      return [...MOCK_TEACHERS].sort((a, b) => a.fullName.localeCompare(b.fullName));
  }, []);

  const getFilteredTeachers = (input: string) => {
      if (!input) return sortedTeachers;
      const lowerInput = input.toLowerCase();
      return sortedTeachers.filter(t => 
          t.fullName.toLowerCase().includes(lowerInput) || 
          t.saintName.toLowerCase().includes(lowerInput)
      );
  };

  const filteredMainTeacherSuggestions = useMemo(() => getFilteredTeachers(mainTeacherInput), [mainTeacherInput, sortedTeachers]);

  const updateAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = true;
      setShowAssistSuggestions(newShow);
  };

  const selectAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = false;
      setShowAssistSuggestions(newShow);
  }

  const toggleAssistSuggestion = (index: number, status: boolean) => {
      const newShow = [...showAssistSuggestions];
      newShow[index] = status;
      setShowAssistSuggestions(newShow);
  }

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2 border rounded-lg bg-white font-medium min-w-[150px]"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2 border rounded-lg bg-white min-w-[150px]"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-300">
                         <th className="p-4 w-12 text-center">STT</th>
                         <th className="p-4">Tên Lớp</th>
                         <th className="p-4">Khối</th>
                         <th className="p-4 text-center">Sĩ số</th>
                         <th className="p-4 text-center">Nam</th>
                         <th className="p-4 text-center">Nữ</th>
                         <th className="p-4 text-center">Phòng Học</th>
                         <th className="p-4">GLV Chủ Nhiệm</th>
                         <th className="p-4">GLV Phụ Trách</th>
                         <th className="p-4 w-16 text-center"></th>
                     </tr>
                 </thead>
                 <tbody className="">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = grades.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50 border-b border-slate-200">
                                     <td className="p-4 text-center text-slate-500">{index + 1}</td>
                                     <td className="p-4 font-bold text-slate-800">{c.name}</td>
                                     <td className="p-4 text-slate-600 text-sm">{gradeName}</td>
                                     <td className="p-4 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.male}</td>
                                     <td className="p-4 text-center text-slate-600">{stats.female}</td>
                                     <td className="p-4 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="p-4 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="p-4 text-sm text-slate-600 max-w-xs truncate" title={c.assistants}>{c.assistants || '---'}</td>
                                     <td className="p-4 text-center">
                                         <button onClick={() => handleEditClass(c)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                             <Edit size={16} />
                                         </button>
                                     </td>
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={10} className="p-8 text-center text-slate-400">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-6 justify-end text-sm font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={16}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={16}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={16}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {editingClass && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in flex flex-col max-h-[90vh]">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-lg text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                </div>
                <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg bg-slate-100 text-slate-500" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>

                    <div className="relative">
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Chủ Nhiệm</label>
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full p-2 pl-3 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={mainTeacherInput}
                                onChange={(e) => {
                                    setMainTeacherInput(e.target.value);
                                    setShowMainTeacherSuggestions(true);
                                }}
                                onFocus={() => setShowMainTeacherSuggestions(true)}
                                onBlur={() => setTimeout(() => setShowMainTeacherSuggestions(false), 200)}
                                placeholder="Nhập tên GLV..."
                            />
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        </div>
                        {showMainTeacherSuggestions && (
                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                {filteredMainTeacherSuggestions.length > 0 ? (
                                    filteredMainTeacherSuggestions.map(t => (
                                        <div 
                                            key={t.id}
                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                            onClick={() => {
                                                setMainTeacherInput(`${t.saintName} ${t.fullName}`);
                                                setShowMainTeacherSuggestions(false);
                                            }}
                                        >
                                            <span>{t.saintName} {t.fullName}</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="p-3 text-xs text-slate-400 text-center italic">Không tìm thấy GLV phù hợp</div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                        <label className="block text-sm font-bold text-slate-700 mb-2">GLV Phụ Trách</label>
                        <div className="space-y-3">
                             {assistants.map((val, idx) => {
                                const suggestions = getFilteredTeachers(val);
                                return (
                                    <div key={idx} className="relative">
                                        <div className="relative">
                                            <input 
                                                type="text"
                                                className="w-full p-2 pl-3 pr-8 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm bg-white"
                                                placeholder={`GLV Phụ trách ${idx + 1}`}
                                                value={val}
                                                onChange={(e) => updateAssistant(idx, e.target.value)}
                                                onFocus={() => toggleAssistSuggestion(idx, true)}
                                                onBlur={() => setTimeout(() => toggleAssistSuggestion(idx, false), 200)}
                                            />
                                             <Search className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                                        </div>
                                        {showAssistSuggestions[idx] && (
                                            <div className="absolute z-20 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {suggestions.length > 0 ? (
                                                    suggestions.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                                            onClick={() => selectAssistant(idx, `${t.saintName} ${t.fullName}`)}
                                                        >
                                                            <span>{t.saintName} {t.fullName}</span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="p-2 text-xs text-slate-400 text-center italic">Không tìm thấy</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                             })}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3 mt-auto">
                    <button onClick={() => setEditingClass(null)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium">Hủy</button>
                    <button onClick={handleSaveClass} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Calendar, Layers, Save, Plus, Trash2, Cross, CheckCircle, CheckCircle2, GripVertical, Clock, AlertCircle } from 'lucide-react';
import { Saint, SchoolYear, ClassRoom, Grade, TermConfig } from '../types';

interface SettingsProps {
    years: SchoolYear[];
    setYears: (years: SchoolYear[]) => void;
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    grades: Grade[];
    setGrades: (grades: Grade[]) => void;
    termConfigs: TermConfig[];
    setTermConfigs: (configs: TermConfig[]) => void;
}

export const Settings: React.FC<SettingsProps> = ({ years, setYears, classes, setClasses, grades, setGrades, termConfigs, setTermConfigs }) => {
  const [saints, setSaints] = useState<Saint[]>(MOCK_SAINTS);
  const [newSaintName, setNewSaintName] = useState('');
  const [newSaintGender, setNewSaintGender] = useState<'Male'|'Female'>('Male');
  const [toast, setToast] = useState<string | null>(null);

  // Drag states
  const [draggedGradeId, setDraggedGradeId] = useState<string | null>(null);
  const [dragOverGradeId, setDragOverGradeId] = useState<string | null>(null);

  const [draggedClassId, setDraggedClassId] = useState<string | null>(null);
  const [dragOverClassId, setDragOverClassId] = useState<string | null>(null);

  const [activeYearForTerms, setActiveYearForTerms] = useState('');

  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) setActiveYearForTerms(active.id);
    else if (years.length > 0) setActiveYearForTerms(years[0].id);
  }, [years]);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState(grades[0]?.id || '');

  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  // --- TERM CONFIG LOGIC ---
  const hk1Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK1');
  const hk2Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK2');

  const updateTermDate = (term: 'HK1' | 'HK2', field: 'startDate' | 'endDate', value: string) => {
      setTermConfigs(prev => {
          const existingIdx = prev.findIndex(c => c.yearId === activeYearForTerms && c.term === term);
          if (existingIdx > -1) {
              const newConfigs = [...prev];
              newConfigs[existingIdx] = { ...newConfigs[existingIdx], [field]: value };
              return newConfigs;
          } else {
              const newConfig: TermConfig = {
                  id: `term_${Date.now()}`,
                  yearId: activeYearForTerms,
                  term: term,
                  startDate: field === 'startDate' ? value : '',
                  endDate: field === 'endDate' ? value : ''
              };
              return [...prev, newConfig];
          }
      });
  };

  const handleSaveTerms = () => {
      showToast("Đã cập nhật mốc thời gian học kỳ thành công!");
  };

  // --- GRADE SORTING LOGIC ---
  const handleGradeDragStart = (e: React.DragEvent, id: string) => {
    setDraggedGradeId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleGradeDragEnter = (id: string) => {
    if (draggedGradeId && draggedGradeId !== id) {
        setDragOverGradeId(id);
    }
  };

  const handleGradeDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    setDragOverGradeId(null);
    if (!draggedGradeId || draggedGradeId === targetId) return;

    const sourceIndex = grades.findIndex(g => g.id === draggedGradeId);
    const targetIndex = grades.findIndex(g => g.id === targetId);

    const newGrades = [...grades];
    const [removed] = newGrades.splice(sourceIndex, 1);
    newGrades.splice(targetIndex, 0, removed);

    setGrades(newGrades);
    setDraggedGradeId(null);
    showToast("Cập nhật thứ tự Khối lớp thành công!");
  };

  // --- CLASS SORTING LOGIC ---
  const handleClassDragStart = (e: React.DragEvent, id: string) => {
    setDraggedClassId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleClassDragEnter = (id: string) => {
    if (draggedClassId && draggedClassId !== id) {
        setDragOverClassId(id);
    }
  };

  const handleClassDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    setDragOverClassId(null);
    if (!draggedClassId || draggedClassId === targetId) return;

    const sourceIndex = classes.findIndex(c => c.id === draggedClassId);
    const targetIndex = classes.findIndex(c => c.id === targetId);

    const newClasses = [...classes];
    const [removed] = newClasses.splice(sourceIndex, 1);
    newClasses.splice(targetIndex, 0, removed);

    setClasses(newClasses);
    setDraggedClassId(null);
    showToast("Cập nhật thứ tự Lớp học thành công!");
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDragEnd = () => {
    setDraggedGradeId(null);
    setDragOverGradeId(null);
    setDraggedClassId(null);
    setDragOverClassId(null);
  };

  const handleAddSaint = () => {
    if (newSaintName) {
      const newSaint: Saint = { id: `s${Date.now()}`, name: newSaintName, gender: newSaintGender };
      setSaints([...saints, newSaint]);
      showToast(`Đã thêm tên thánh "${newSaintName}" thành công!`);
      setNewSaintName('');
    }
  };

  const handleRemoveSaint = (id: string) => {
    const saint = saints.find(s => s.id === id);
    setSaints(saints.filter(s => s.id !== id));
    showToast(`Đã xóa tên thánh "${saint?.name}" thành công!`);
  };

  const handleAddYear = () => {
      if (newYearName) {
          const newId = newYearName.replace(/\s/g, '-');
          const newYear: SchoolYear = { id: newId, name: newYearName, isActive: false };
          setYears([...years, newYear]);
          showToast(`Đã thêm năm học "${newYearName}" thành công!`);
          setNewYearName('');
      }
  };

  const handleSetActiveYear = (id: string) => {
      const year = years.find(y => y.id === id);
      const updatedYears = years.map(y => ({ ...y, isActive: y.id === id }));
      setYears(updatedYears);
      showToast(`Đã đặt "${year?.name}" làm năm học hiện tại!`);
  };

  const handleAddClass = () => {
      if (newClassName && activeYear) {
          const newClass: ClassRoom = { id: `c_${Date.now()}`, name: newClassName, gradeId: newClassGrade, yearId: activeYear.id, mainTeacher: 'Chưa phân công' };
          setClasses([...classes, newClass]);
          showToast(`Đã thêm lớp "${newClassName}" thành công!`);
          setNewClassName('');
      } else {
          alert("Vui lòng nhập tên lớp và đảm bảo có năm học đang kích hoạt.");
      }
  };

  return (
    <div className="p-6 h-screen overflow-y-auto custom-scrollbar relative bg-slate-50/50">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <h2 className="text-3xl font-bold text-slate-800 mb-8 px-2 border-l-8 border-blue-600">Cài Đặt Hệ Thống</h2>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 mb-8">

        {/* Quản Lý Năm Học */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Calendar className="text-blue-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Năm Học</h3></div>
          <div className="space-y-6">
            <div><label className="block text-sm font-bold text-slate-500 uppercase mb-3">Danh sách niên khóa</label><div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar border rounded-xl p-3 bg-slate-50">{years.map(y => (<div key={y.id} className={`flex justify-between items-center p-3 rounded-lg shadow-sm transition-all border-b border-slate-200 last:border-0 ${y.isActive ? 'bg-blue-600 text-white border-blue-500 scale-[1.02]' : 'bg-white'}`}><span className={y.isActive ? 'font-extrabold' : 'font-medium text-slate-700'}>{y.name} {y.isActive && '(Hiện tại)'}</span>{!y.isActive && (<button onClick={() => handleSetActiveYear(y.id)} className="text-xs px-3 py-1.5 bg-slate-100 border border-slate-300 rounded-md font-bold text-slate-600 hover:bg-slate-200 transition-colors">Đặt làm hiện tại</button>)}</div>))}</div></div>
            <div className="bg-blue-50 p-5 rounded-xl border border-blue-100"><h4 className="font-bold text-blue-800 text-sm mb-4 uppercase">Tạo Năm Học Mới</h4><div className="flex gap-3"><input type="text" placeholder="Tên niên khóa (VD: 2024-2025)" className="flex-1 p-3 border border-blue-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={newYearName} onChange={(e) => setNewYearName(e.target.value)}/><button onClick={handleAddYear} className="flex items-center justify-center gap-2 px-6 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 transition-all shadow-md"><Plus size={18}/> Thêm</button></div></div>
          </div>
        </div>

        {/* Cấu hình Thời gian Học Kỳ */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
            <div className="flex items-center gap-3 mb-6 border-b pb-4"><Clock className="text-rose-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Cấu Hình Thời Gian Học Kỳ</h3></div>
            <div className="space-y-6">
                <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Chọn năm học cấu hình</label>
                    <select 
                        className="w-full p-3 border rounded-xl text-sm font-bold text-slate-700 bg-slate-50"
                        value={activeYearForTerms}
                        onChange={(e) => setActiveYearForTerms(e.target.value)}
                    >
                        {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                    </select>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                        <h4 className="font-bold text-blue-800 text-xs mb-3 uppercase flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> Học Kỳ 1</h4>
                        <div className="space-y-3">
                            <div>
                                <label className="text-[10px] text-blue-600 font-bold uppercase">Bắt đầu</label>
                                <input type="date" className="w-full p-2 text-xs border border-blue-200 rounded-lg outline-none" value={hk1Config?.startDate || ''} onChange={(e) => updateTermDate('HK1', 'startDate', e.target.value)}/>
                            </div>
                            <div>
                                <label className="text-[10px] text-blue-600 font-bold uppercase">Kết thúc</label>
                                <input type="date" className="w-full p-2 text-xs border border-blue-200 rounded-lg outline-none" value={hk1Config?.endDate || ''} onChange={(e) => updateTermDate('HK1', 'endDate', e.target.value)}/>
                            </div>
                        </div>
                    </div>

                    <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                        <h4 className="font-bold text-purple-800 text-xs mb-3 uppercase flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-purple-500"></div> Học Kỳ 2</h4>
                        <div className="space-y-3">
                            <div>
                                <label className="text-[10px] text-purple-600 font-bold uppercase">Bắt đầu</label>
                                <input type="date" className="w-full p-2 text-xs border border-purple-200 rounded-lg outline-none" value={hk2Config?.startDate || ''} onChange={(e) => updateTermDate('HK2', 'startDate', e.target.value)}/>
                            </div>
                            <div>
                                <label className="text-[10px] text-purple-600 font-bold uppercase">Kết thúc</label>
                                <input type="date" className="w-full p-2 text-xs border border-purple-200 rounded-lg outline-none" value={hk2Config?.endDate || ''} onChange={(e) => updateTermDate('HK2', 'endDate', e.target.value)}/>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex items-start gap-2 text-xs text-amber-600 bg-amber-50 p-3 rounded-lg border border-amber-100">
                    <AlertCircle size={16} className="mt-0.5 shrink-0" />
                    <span>Mốc thời gian này sẽ được dùng để tự động phân loại số buổi vắng vào bảng điểm HK1 hoặc HK2.</span>
                </div>

                <button onClick={handleSaveTerms} className="w-full flex items-center justify-center gap-2 py-3 bg-rose-600 text-white rounded-xl font-bold hover:bg-rose-700 shadow-md transition-all uppercase text-sm">
                    <Save size={18}/> Lưu Cấu Hình Thời Gian
                </button>
            </div>
        </div>

        {/* Quản Lý Tên Thánh */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Cross className="text-amber-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Tên Thánh</h3></div>
          <div className="space-y-6">
             <div className="flex gap-3 bg-amber-50 p-4 rounded-xl border border-amber-100"><input type="text" placeholder="Nhập tên thánh..." className="flex-1 p-3 border border-amber-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-amber-500" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-3 border border-amber-200 rounded-xl text-sm bg-white" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-6 py-3 bg-amber-600 text-white rounded-xl hover:bg-amber-700 font-extrabold shadow-md transition-all">+</button></div>
            <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-80 overflow-y-auto custom-scrollbar bg-slate-50"><table className="w-full text-left text-sm border-collapse"><thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10"><tr><th className="p-4 font-bold text-slate-600">Tên Thánh</th><th className="p-4 font-bold text-slate-600 w-24">Giới tính</th><th className="p-4 w-16"></th></tr></thead><tbody className="bg-white">{saints.map(s => (<tr key={s.id} className="hover:bg-amber-50/50 transition-colors border-b border-slate-200"><td className="p-4 font-bold text-slate-700">{s.name}</td><td className="p-4"><span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${s.gender === 'Male' ? 'bg-blue-100 text-blue-700' : 'bg-pink-100 text-pink-700'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td><td className="p-4 text-right"><button onClick={() => handleRemoveSaint(s.id)} className="p-2 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={18} /></button></td></tr>))}</tbody></table></div>
          </div>
        </div>

        {/* Quản lý Khối lớp (Normalized Typography + Added Borders) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 xl:row-span-2">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Layers className="text-purple-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Khối Lớp (Thứ tự Kéo thả)</h3></div>
          <div className="space-y-6">
             <div className="flex gap-3"><input type="text" placeholder="Tên khối lớp mới..." className="flex-1 p-3 border rounded-xl focus:ring-2 focus:ring-purple-500 outline-none shadow-sm text-sm" /><button className="px-6 py-3 bg-purple-600 text-white rounded-xl hover:bg-purple-700 font-bold shadow-md transition-all uppercase text-xs tracking-widest">Thêm Khối</button></div>
            <div className="border border-slate-300 rounded-2xl overflow-hidden max-h-[600px] overflow-y-auto custom-scrollbar shadow-inner bg-slate-50 p-1">
                <table className="w-full text-left text-sm border-separate border-spacing-y-2">
                    <thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10">
                        <tr>
                            <th className="p-4 w-14"></th>
                            <th className="p-4 font-bold text-slate-600 uppercase tracking-tighter text-xs">Tên Khối Lớp</th>
                            <th className="p-4 text-right w-24"></th>
                        </tr>
                    </thead>
                    <tbody className="bg-transparent">
                        {grades.map(g => {
                            const isDragging = draggedGradeId === g.id;
                            const isOver = dragOverGradeId === g.id;

                            return (
                                <tr 
                                    key={g.id} 
                                    draggable 
                                    onDragStart={(e) => handleGradeDragStart(e, g.id)}
                                    onDragOver={handleDragOver}
                                    onDragEnter={() => handleGradeDragEnter(g.id)}
                                    onDragEnd={handleDragEnd}
                                    onDrop={(e) => handleGradeDrop(e, g.id)}
                                    className={`group transition-all duration-200 border-b border-slate-200 ${
                                        isDragging ? 'opacity-30 scale-95 cursor-grabbing border-2 border-dashed border-purple-500' : 'cursor-grab bg-white shadow-sm'
                                    } ${
                                        isOver ? 'ring-4 ring-purple-400 ring-inset bg-purple-50 translate-x-2' : ''
                                    } hover:shadow-md rounded-xl overflow-hidden`}
                                >
                                    <td className="p-3 text-slate-300 group-hover:text-purple-500 transition-colors rounded-l-xl border-b border-slate-200"><GripVertical size={20} /></td>
                                    <td className="p-3 font-bold text-slate-800 text-sm uppercase tracking-tight border-b border-slate-200">{g.name}</td>
                                    <td className="p-3 text-right rounded-r-xl border-b border-slate-200"><button className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={18} /></button></td>
                                </tr>
                            )
                        })}
                    </tbody>
                </table>
            </div>
          </div>
        </div>

        {/* Quản lý Lớp học (Normalized Typography + Added Borders) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 xl:row-span-2">
          <div className="flex items-center gap-3 mb-6 border-b pb-4"><Layers className="text-emerald-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Danh Sách Lớp Học ({activeYear?.name})</h3></div>
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 bg-emerald-50 p-5 rounded-xl border border-emerald-100">
                <input type="text" placeholder="Tên lớp (VD: Chiên Con 3)..." className="p-3 border border-emerald-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 text-sm shadow-sm" value={newClassName} onChange={(e) => setNewClassName(e.target.value)} />
                <div className="flex gap-2">
                    <select className="flex-1 p-3 border border-emerald-200 rounded-xl bg-white text-sm shadow-sm font-bold text-emerald-800" value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value)}>{grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select>
                    <button onClick={handleAddClass} className="px-6 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 font-bold transition-all shadow-md text-xl">+</button>
                </div>
            </div>
            <div className="border border-slate-300 rounded-2xl overflow-hidden max-h-[600px] overflow-y-auto custom-scrollbar shadow-inner bg-slate-50 p-1">
                <table className="w-full text-left text-sm border-separate border-spacing-y-2">
                    <thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10">
                        <tr>
                            <th className="p-4 w-14"></th>
                            <th className="p-4 font-bold text-slate-600 uppercase tracking-tighter text-xs">Tên Lớp</th>
                            <th className="p-4 font-bold text-slate-600 uppercase tracking-tighter text-xs">Thuộc Khối</th>
                            <th className="p-4 w-16"></th>
                        </tr>
                    </thead>
                    <tbody className="bg-transparent">
                        {classesInActiveYear.length > 0 ? (classesInActiveYear.map(c => {
                            const gradeName = grades.find(g => g.id === c.gradeId)?.name || '---'; 
                            const isDragging = draggedClassId === c.id;
                            const isOver = dragOverClassId === c.id;

                            return (
                                <tr 
                                    key={c.id}
                                    draggable
                                    onDragStart={(e) => handleClassDragStart(e, c.id)}
                                    onDragOver={handleDragOver}
                                    onDragEnter={() => handleClassDragEnter(c.id)}
                                    onDragEnd={handleDragEnd}
                                    onDrop={(e) => handleClassDrop(e, c.id)}
                                    className={`group transition-all duration-200 border-b border-slate-200 ${
                                        isDragging ? 'opacity-30 scale-95 cursor-grabbing border-2 border-dashed border-emerald-500' : 'cursor-grab bg-white shadow-sm'
                                    } ${
                                        isOver ? 'ring-4 ring-emerald-400 ring-inset bg-emerald-50 translate-x-2' : ''
                                    } hover:shadow-md rounded-xl overflow-hidden`}
                                >
                                    <td className="p-3 text-slate-300 group-hover:text-emerald-500 transition-colors rounded-l-xl border-b border-slate-200"><GripVertical size={20} /></td>
                                    <td className="p-3 font-bold text-slate-800 text-sm border-b border-slate-200">{c.name}</td>
                                    <td className="p-3 font-semibold text-emerald-600/70 text-xs border-b border-slate-200">{gradeName}</td>
                                    <td className="p-3 text-right rounded-r-xl border-b border-slate-200"><button className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={18} /></button></td>
                                </tr>
                            )})) : (
                                <tr><td colSpan={4} className="p-12 text-center text-slate-400 italic font-medium">Niên khóa này chưa có lớp học nào được tạo.</td></tr>
                            )}
                    </tbody>
                </table>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }

        /* Custom styles for dragging ghost image */
        tr[draggable="true"] {
            user-select: none;
        }

        .cursor-grab { cursor: grab; }
        .cursor-grabbing { cursor: grabbing; }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { Wallet, TrendingUp, TrendingDown, Plus, Minus, PieChart as PieChartIcon, FileSpreadsheet } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Transaction } from '../types';

interface FinanceProps {
    transactions: Transaction[];
    setTransactions: (t: Transaction[]) => void;
}

export const Finance: React.FC<FinanceProps> = ({ transactions, setTransactions }) => {
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [note, setNote] = useState('');
  const [type, setType] = useState<'INCOME'|'EXPENSE'>('INCOME');

  const totalIncome = transactions.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const data = [
    { name: 'Tổng Thu', value: totalIncome },
    { name: 'Tổng Chi', value: totalExpense },
  ];
  const COLORS = ['#10b981', '#ef4444'];

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
  };

  const handleAddTransaction = () => {
      if (!amount || !description) return alert("Vui lòng nhập số tiền và nội dung");

      const newTx: Transaction = {
          id: `T${Date.now()}`,
          date: new Date().toISOString().split('T')[0],
          type: type,
          amount: parseFloat(amount),
          description: description,
          note: note
      };

      setTransactions([newTx, ...transactions]);

      // Reset form
      setAmount('');
      setDescription('');
      setNote('');
  };

  const handleExportExcel = () => {
    // Generate CSV content
    const headers = ["ID", "Ngày", "Loại", "Số tiền", "Nội dung", "Ghi chú"];
    const rows = transactions.map(t => [
      t.id,
      t.date,
      t.type === 'INCOME' ? 'THU' : 'CHI',
      t.amount,
      `"${t.description}"`, // Quote strings to handle commas
      `"${t.note || ''}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "so_quy_giao_ly.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen overflow-y-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Thủ Quỹ & Tài Chính</h2>
        <button 
          onClick={handleExportExcel}
          className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg shadow hover:bg-green-700 transition-colors"
        >
          <FileSpreadsheet size={18} /> Xuất Excel
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Wallet className="absolute right-4 top-4 opacity-20 w-24 h-24" />
          <p className="text-blue-100 mb-1">Tổng quỹ hiện tại</p>
          <h3 className="text-3xl font-bold">{formatCurrency(balance)}</h3>
          <p className="text-xs text-blue-200 mt-4 opacity-80">Cập nhật lần cuối: Hôm nay</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-green-100 rounded-lg text-green-600">
               <TrendingUp size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Thu (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalIncome)}</h3>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 rounded-lg text-red-600">
               <TrendingDown size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Chi (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalExpense)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Form and Chart */}
        <div className="lg:col-span-1 space-y-8">
            {/* Chart */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-80 flex flex-col">
              <div className="flex items-center gap-2 mb-2">
                <PieChartIcon className="text-slate-400" size={20} />
                <h3 className="font-bold text-lg text-slate-800">Biểu Đồ Thu Chi</h3>
              </div>
              <div className="flex-1 w-full h-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={data}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {data.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => formatCurrency(value as number)} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Transaction Form */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h3 className="font-bold text-lg mb-4 text-slate-800">Tạo Giao Dịch Mới</h3>
            <div className="space-y-4">
                <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
                <button 
                    onClick={() => setType('INCOME')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'INCOME' ? 'bg-white text-green-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Plus size={16}/> Thu
                </button>
                <button 
                    onClick={() => setType('EXPENSE')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'EXPENSE' ? 'bg-white text-red-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Minus size={16}/> Chi
                </button>
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Số tiền (VND)</label>
                <input 
                    type="number" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="0" 
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nội dung <span className="text-red-500">*</span></label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="VD: Thu tiền sách..." 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
                <textarea 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24" 
                    placeholder="..." 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                ></textarea>
                </div>

                <button 
                    onClick={handleAddTransaction}
                    className="w-full py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 shadow-lg shadow-blue-200"
                >
                Lưu Giao Dịch
                </button>
            </div>
            </div>
        </div>

        {/* History Table with Bottom Borders */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
          <div className="p-4 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-lg text-slate-800">Lịch Sử Giao Dịch</h3>
            <button className="text-sm text-blue-600 hover:underline">Xem báo cáo chi tiết</button>
          </div>
          <div className="overflow-x-auto max-h-[800px] custom-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-white shadow-sm border-b border-slate-200">
                <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                  <th className="p-4">Ngày</th>
                  <th className="p-4">Nội dung</th>
                  <th className="p-4 text-right">Số tiền</th>
                  <th className="p-4 text-center">Loại</th>
                </tr>
              </thead>
              <tbody className="">
                {transactions.map((t) => (
                  <tr key={t.id} className="hover:bg-slate-50 border-b border-slate-200">
                    <td className="p-4 text-slate-500 text-sm">{t.date}</td>
