            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, AcademicRecord, TermConfig } from '../types';
import { CheckCircle2, Info, Save, Calendar, UserCheck, Search } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    termConfigs: TermConfig[];
}

type AttendanceStatus = 'P' | 'K' | ''; // Trống = Hiện diện, P: Phép, K: Không phép

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years, grades, setRecords, termConfigs }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [toast, setToast] = useState<string | null>(null);

  const [attendanceData, setAttendanceData] = useState<Record<string, AttendanceStatus>>({});

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);

  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleStatusChange = (studentId: string, date: string, type: 'mass' | 'class', status: AttendanceStatus) => {
    const key = `${studentId}-${date}-${type}`;
    setAttendanceData(prev => ({
        ...prev,
        [key]: status
    }));
  };

  const handleSave = () => {
      // Improved Sync logic using Term Configs
      const [yearStr, monthStr] = selectedMonth.split('-');
      const monthDateStr = `${selectedMonth}-15`; // Pick a mid-month date to check

      let term: 'HK1' | 'HK2' = 'HK1'; // Default

      const config1 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK1');
      const config2 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK2');

      if (config1 && monthDateStr >= config1.startDate && monthDateStr <= config1.endDate) {
          term = 'HK1';
      } else if (config2 && monthDateStr >= config2.startDate && monthDateStr <= config2.endDate) {
          term = 'HK2';
      } else {
          // Fallback to legacy month-based logic if no config found
          const m = parseInt(monthStr);
          term = (m >= 9 || m <= 1) ? 'HK1' : 'HK2';
      }

      setRecords(prev => {
          const newRecords = [...prev];

          filteredStudents.forEach(student => {
              let currentP = 0;
              let currentK = 0;

              sundaysInMonth.forEach(sunday => {
                  const dateStr = sunday.toISOString().split('T')[0];
                  // Mass absences
                  const massStatus = attendanceData[`${student.id}-${dateStr}-mass`];
                  if (massStatus === 'P') currentP++;
                  else if (massStatus === 'K') currentK++;

                  // Class absences
                  const classStatus = attendanceData[`${student.id}-${dateStr}-class`];
                  if (classStatus === 'P') currentP++;
                  else if (classStatus === 'K') currentK++;
              });

              const existingIdx = newRecords.findIndex(r => r.studentId === student.id && r.term === term);
              if (existingIdx > -1) {
                  newRecords[existingIdx] = {
                      ...newRecords[existingIdx],
                      absentP: (newRecords[existingIdx].absentP || 0) + currentP,
                      absentK: (newRecords[existingIdx].absentK || 0) + currentK
                  };
              } else {
                  newRecords.push({
                      studentId: student.id,
                      term: term,
                      scores: {},
                      scorePray: 0,
                      scoreExam: 0,
                      average: 0,
                      absentP: currentP,
                      absentK: currentK
                  });
              }
          });

          return newRecords;
      });

      showToast(`Đã lưu & đồng bộ vắng mặt vào ${term === 'HK1' ? 'Học kỳ 1' : 'Học kỳ 2'} thành công!`);
  };

  const getStatusStyle = (status: AttendanceStatus | undefined) => {
      switch (status) {
          case 'P': return 'bg-amber-500 text-white border-amber-600 font-black shadow-inner';
          case 'K': return 'bg-red-600 text-white border-red-700 font-black shadow-inner';
          default: return 'bg-white text-transparent border-slate-300 hover:border-blue-300';
      }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Điểm Danh Chuyên Cần</h2>
        <div className="flex items-center gap-2 text-sm text-slate-500 bg-white px-3 py-1.5 rounded-lg border shadow-sm">
            <Calendar size={16} className="text-blue-500" />
            <span>Tháng {selectedMonth.split('-')[1]}/{selectedMonth.split('-')[0]}</span>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center flex-wrap">
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
        <select className="px-3 py-2 border rounded-lg min-w-[180px] text-sm focus:ring-2 focus:ring-blue-500 outline-none font-bold text-slate-700" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>

        <div className="flex items-center gap-2 border-l pl-4 ml-2">
            <input type="month" className="px-3 py-2 border rounded-lg text-sm bg-slate-50 font-bold text-blue-600 focus:ring-2 focus:ring-blue-500 outline-none" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} />
        </div>
      </div>

      <div className="bg-blue-600 text-white p-4 mb-4 flex items-center gap-3 shadow-lg rounded-xl animate-fade-in border-b-4 border-blue-800">
        <div className="bg-white/20 p-2 rounded-lg"><Info size={24} className="text-white" /></div>
        <div className="flex flex-col">
            <span className="font-extrabold text-sm tracking-wide uppercase">QUY ƯỚC ĐIỂM DANH:</span>
            <span className="text-sm opacity-95">Mặc định ô để <b>TRỐNG = HIỆN DIỆN</b>. Chỉ cần chọn <b>P</b> hoặc <b>K</b> nếu em vắng.</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-100 text-slate-800 text-xs">
                 <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-30 border-b border-r border-slate-400 font-bold">STT</th>
                 <th rowSpan={2} className="p-4 min-w-[220px] sticky left-12 bg-slate-100 z-30 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => {
                    const isEven = idx % 2 === 0;
                    const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50';
                    return (
                        <th key={idx} colSpan={2} className={`p-2 text-center border-b border-r border-slate-400 ${bgClass}`}>
                            <div className="flex flex-col">
                                <span className={`font-bold ${isEven ? 'text-slate-600' : 'text-blue-700'}`}>CN {idx + 1}</span>
                                <span className="text-[10px] font-normal text-slate-500">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                            </div>
                        </th>
                    );
                 })}
                 <th rowSpan={2} className="p-4 text-center border-b border-slate-400 min-w-[150px] font-bold">Ghi chú</th>
               </tr>
               <tr className="text-[10px] uppercase tracking-tighter font-bold bg-slate-50">
                    {sundaysInMonth.map((_, idx) => {
                        const isEven = idx % 2 === 0;
                        const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50/50';
                        return (
                            <React.Fragment key={idx}>
                                <th className={`p-1.5 text-center border-b border-r border-slate-400 min-w-[50px] text-purple-600 ${bgClass}`}>Lễ</th>
                                <th className={`p-1.5 text-center border-b border-r border-slate-400 min-w-[50px] text-blue-600 ${bgClass}`}>Học</th>
                            </React.Fragment>
                        );
                    })}
               </tr>
             </thead>
             <tbody className="">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-300">
                   <td className="p-3 text-center text-slate-500 sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-300 text-xs font-bold">{idx + 1}</td>
                   <td className="p-3 sticky left-12 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const isEven = i % 2 === 0;
                       const cellClass = isEven ? 'bg-white group-hover:bg-blue-50/20' : 'bg-blue-50/10 group-hover:bg-blue-50/30';

                       const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const classStatus = attendanceData[`${s.id}-${dateStr}-class`];

                       return (
                           <React.Fragment key={i}>
                               <td className={`p-1 border-r border-slate-300 text-center ${cellClass}`}>
                                   <select 
                                      value={massStatus || ''} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1.5 rounded text-xs border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(massStatus)}`}
                                   >
                                       <option value="" className="bg-white text-slate-300">-</option>
                                       <option value="P" className="bg-amber-500 text-white font-bold">P (Vắng phép)</option>
                                       <option value="K" className="bg-red-600 text-white font-bold">K (Không phép)</option>
                                   </select>
                               </td>
                               <td className={`p-1 border-r border-slate-300 text-center ${cellClass}`}>
                                   <select 
                                      value={classStatus || ''} 
                                      onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                      className={`w-full text-center py-1.5 rounded text-xs border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none transition-all ${getStatusStyle(classStatus)}`}
                                   >
                                       <option value="" className="bg-white text-slate-300">-</option>
                                       <option value="P" className="bg-amber-500 text-white font-bold">P (Vắng phép)</option>
                                       <option value="K" className="bg-red-600 text-white font-bold">K (Không phép)</option>
                                   </select>
                               </td>
                           </React.Fragment>
                       );
                   })}

                   <td className="p-2 border-r border-slate-300">
                     <input type="text" className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-[11px] py-1 transition-all" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để hiển thị danh sách học viên</td></tr>
               )}
             </tbody>
           </table>
        </div>

        {filteredStudents.length > 0 && (
            <div className="p-4 border-t border-slate-300 bg-slate-100 flex justify-between items-center sticky bottom-0 z-30 shadow-inner">
                 <div className="flex gap-6 text-sm">
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-white border border-slate-300 rounded shadow-sm"></span> <span className="text-slate-600">Ô trống: Hiện diện</span></div>
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-amber-500 border border-amber-600 rounded shadow-sm text-[10px] flex items-center justify-center font-black text-white">P</span> <span className="text-amber-700 font-bold">Vắng có phép</span></div>
                     <div className="flex items-center gap-2 font-medium"><span className="w-5 h-5 bg-red-600 border border-red-700 rounded shadow-sm text-[10px] flex items-center justify-center font-black text-white">K</span> <span className="text-red-700 font-bold">Vắng không phép</span></div>
                 </div>
                 <button onClick={handleSave} className="px-10 py-3 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold flex items-center gap-2 transition-all transform hover:-translate-y-1 active:scale-95">
                     <Save size={20}/> Lưu Điểm Danh
                 </button>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        select { text-align-last: center; -webkit-appearance: none; -moz-appearance: none; appearance: none; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, GripVertical, AlertCircle, Info } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const [draggedColId, setDraggedColId] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);
  const [newColTerm, setNewColTerm] = useState<'HK1' | 'HK2'>('HK1');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass);
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);

    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      const termColumns = testColumns.filter(c => c.term === record.term);

      termColumns.forEach(col => {
          if (col.weight > 0) {
              const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = [...records];
     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });

     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight, term: newColTerm }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" vào ${newColTerm} thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    if (window.confirm("Bạn có chắc chắn muốn xóa cột điểm này? Dữ liệu điểm của cột này sẽ bị mất hiển thị.")) {
        setTestColumns(testColumns.filter(c => c.id !== id));
        showToast("Đã xóa cột điểm thành công!");
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedColId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, targetId: string) => {
      e.preventDefault();
      if (!draggedColId || draggedColId === targetId) return;

      const sourceIndex = testColumns.findIndex(c => c.id === draggedColId);
      const targetIndex = testColumns.findIndex(c => c.id === targetId);

      if (sourceIndex === -1 || targetIndex === -1) return;

      const sourceCol = testColumns[sourceIndex];
      const targetCol = testColumns[targetIndex];

      if (sourceCol.term !== targetCol.term) {
          showToast("Chỉ có thể sắp xếp cột trong cùng một Học Kỳ!");
          setDraggedColId(null);
          return;
      }

      const newCols = [...testColumns];
      const [removed] = newCols.splice(sourceIndex, 1);
      newCols.splice(targetIndex, 0, removed);

      setTestColumns(newCols);
      setDraggedColId(null);
  };

  const processedStudentsYear = useMemo(() => {
    return filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;

      return { 
        ...s, 
        avg1, 
        avg2, 
        avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
      };
    }).sort((a, b) => b.avgYear - a.avgYear).map((s, index) => ({...s, ranking: index + 1}));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const handleExportExcel = () => {
    if (!currentClass) return;
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "\uFEFF"; 

    const headerRow = [
        "STT", "Họ và Tên", "Mã Học Viên",
        ...hk1Columns.map(c => `${c.name} (x${c.weight})`), "Vắng P (HK1)", "Vắng K (HK1)", "TB HK1",
        ...hk2Columns.map(c => `${c.name} (x${c.weight})`), "Vắng P (HK2)", "Vắng K (HK2)", "TB HK2",
        "TB Cả Năm", "Xếp Loại", "Hạng"
    ];
    csvContent += headerRow.join(",") + "\n";

    processedStudentsYear.forEach((s, idx) => {
        const r1 = getRecord(s.id, 'HK1');
        const r2 = getRecord(s.id, 'HK2');
        const hk1Scores = hk1Columns.map(c => r1.scores?.[c.id] || 0);
        const hk2Scores = hk2Columns.map(c => r2.scores?.[c.id] || 0);

        const row = [
            idx + 1,
            `"${s.saintName} ${s.fullName}"`,
            s.id,
            ...hk1Scores,
            s.absentP1,
            s.absentK1,
            s.avg1.toFixed(1),
            ...hk2Scores,
            s.absentP2,
            s.absentK2,
            s.avg2.toFixed(1),
            s.avgYear.toFixed(1),
            s.rank.label,
            s.ranking
        ];
        csvContent += row.join(",") + "\n";
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Bang_Diem_${currentClass.name.replace(/\s/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-300 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[160px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                    <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg border border-slate-300 animate-fade-in shadow-lg absolute right-6 top-24 z-50">
                        <select className="px-2 py-1 border rounded text-sm font-bold text-blue-700" value={newColTerm} onChange={(e) => setNewColTerm(e.target.value as any)}>
                            <option value="HK1">Học Kỳ 1</option>
                            <option value="HK2">Học Kỳ 2</option>
                        </select>
                        <input type="text" placeholder="Tên cột (VD: 15')" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/>
                        <select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}>
                            <option value={0}>x0</option>
                            <option value={1}>x1</option>
                            <option value={2}>x2</option>
                            <option value={3}>x3</option>
                        </select>
                        <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold hover:bg-green-700">OK</button>
                        <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm hover:bg-slate-400">Hủy</button>
                    </div>
                ) : (
                    <button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-bold transition-all"><Plus size={16} /> Thêm Cột</button>
                )}
                </>
            )}
             <button onClick={handleExportExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white border border-green-700 rounded-lg text-sm hover:bg-green-700 font-bold shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-amber-50 border-l-4 border-amber-500 p-4 mb-4 flex items-center gap-3 text-amber-900 text-sm shadow-sm rounded-r-lg">
        <div className="bg-amber-200 p-1.5 rounded-full"><Info size={20} className="text-amber-700" /></div>
        <div className="flex flex-col">
            <span className="font-bold">ĐỒNG BỘ CHUYÊN CẦN:</span>
            <span>Số buổi <b>Vắng P (Có phép)</b> và <b>Vắng K (Không phép)</b> được đồng bộ tự động khi bạn nhấn "Lưu Điểm Danh" ở tab Chuyên Cần.</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-separate border-spacing-0">
                    <thead>
                        <tr className="bg-slate-100 text-slate-800 text-sm">
                            <th rowSpan={2} className="p-4 w-12 text-center sticky left-0 bg-slate-100 z-20 border-b border-r border-slate-400 font-bold">STT</th>
                            <th rowSpan={2} className="p-4 min-w-[200px] sticky left-12 bg-slate-100 z-20 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                            <th colSpan={hk1Columns.length + 2 + 1} className="p-2 text-center bg-blue-100/50 border-b border-r border-blue-400 font-extrabold text-blue-800 tracking-wider">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 2 + 1} className="p-2 text-center bg-purple-100/50 border-b border-r border-purple-400 font-extrabold text-purple-800 tracking-wider">HỌC KỲ 2</th>
                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-400 font-bold bg-slate-200 text-slate-800">Cả Năm</th>
                            <th rowSpan={2} className="p-4 w-24 text-center border-b border-slate-400 font-bold bg-slate-200 text-slate-800">Xếp Loại</th>
                            <th rowSpan={2} className="p-4 w-16 text-center border-b border-slate-400 font-bold bg-yellow-50 text-yellow-800">Hạng</th>
                        </tr>
                        <tr className="bg-slate-50 text-slate-600 text-xs">
                             {hk1Columns.map((col) => (
                                <th key={col.id} className="p-2 w-24 text-center border-b border-r border-slate-400 bg-blue-50/30">
                                    <span className="font-bold">{col.name}</span>
                                </th>
                             ))}
                             <th className="p-2 w-12 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700">P</th>
                             <th className="p-2 w-12 text-center border-b border-r border-red-300 bg-red-50 text-red-700">K</th>
                             <th className="p-2 w-16 text-center border-b border-r border-blue-400 font-bold bg-blue-100 text-blue-800">TB HK1</th>

                             {hk2Columns.map((col) => (
                                <th key={col.id} className="p-2 w-24 text-center border-b border-r border-slate-400 bg-purple-50/30">
                                    <span className="font-bold">{col.name}</span>
                                </th>
                             ))}
                             <th className="p-2 w-12 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700">P</th>
                             <th className="p-2 w-12 text-center border-b border-r border-red-300 bg-red-50 text-red-700">K</th>
                             <th className="p-2 w-16 text-center border-b border-r border-purple-400 font-bold bg-purple-100 text-purple-800">TB HK2</th>
                        </tr>
                    </thead>
                    <tbody className="">
                        {processedStudentsYear.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');

                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-300">
                                    <td className="p-3 text-center sticky left-0 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 font-medium text-slate-500">{idx + 1}</td>
                                    <td className="p-3 font-medium sticky left-12 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                                        <div className="text-sm text-slate-800">{s.saintName} {s.fullName}</div>
                                    </td>
                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-1 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r1.scores ? (r1.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/30">{s.absentP1}</td>
                                    <td className="p-3 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/30">{s.absentK1}</td>
                                    <td className="p-3 border-r border-blue-400 text-center font-bold text-blue-700 bg-blue-50">
                                        {(s.avg1 >= 0) ? s.avg1.toFixed(1) : '-'}
                                    </td>
                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-1 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r2.scores ? (r2.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} 
                                                className="w-full text-center p-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="p-3 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/30">{s.absentP2}</td>
                                    <td className="p-3 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/30">{s.absentK2}</td>
                                    <td className="p-3 border-r border-purple-400 text-center font-bold text-purple-700 bg-purple-50">
                                        {(s.avg2 >= 0) ? s.avg2.toFixed(1) : '-'}
                                    </td>
                                    <td className="p-3 text-center font-bold text-slate-900 bg-slate-100 border-r border-slate-300">
                                        {s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}
                                    </td>
                                    <td className="p-3 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${s.rank.color}`}>
                                                {s.rank.label}
                                            </span>
                                        )}
                                    </td>
                                    <td className="p-3 text-center font-bold text-yellow-700 bg-yellow-50/50">
                                        {s.ranking}
                                    </td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={30} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {processedStudentsYear.length > 0 && (
                <div className="p-4 border-t border-slate-300 bg-slate-100 text-right sticky bottom-0 z-20 shadow-md">
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-8 py-3 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold transition-all transform hover:-translate-y-1 active:scale-95">
                        <Save size={20} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-slate-500">Sĩ số</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                  <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                    <div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div>
                    <span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-300">
                        {passedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-green-50/30 border-b border-slate-200">
                            <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-bold text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
                <div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden">
                   {/* Similar failed students list */}
                </div>
              </div>
            </div>
        )}
      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

export interface Student {
  id: string; // Mã học viên (Số tự động)
  saintName: string; // Tên Thánh
  fullName: string; // Họ tên
  dob: string; // Ngày tháng năm sinh
  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
  baptismBy?: string; // Do (Linh mục rửa tội)
  baptismSponsor?: string; // Người đỡ đầu Rửa tội
  baptismPlace?: string; // Tại (Nơi rửa tội)

  eucharistDate?: string; // Ngày rước lễ
  eucharistBy?: string; // Do (Linh mục cho rước lễ)
  eucharistPlace?: string; // Tại (Nơi rước lễ)

  confirmationDate?: string; // Ngày thêm sức
  confirmationBy?: string; // Do (ĐGM/Cha ban thêm sức)
  confirmationSponsor?: string; // Người đỡ đầu Thêm sức
  confirmationPlace?: string; // Tại (Nơi thêm sức)

  confirmationOathDate?: string; // Ngày tuyên hứa (Bao đồng)

  note?: string; // Ghi chú
}

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
  educationLevel: string; // Học vấn Giáo Lý (VD: Cấp 1, 2, 3...)
  role: 'ADMIN' | 'GLV'; // Phân quyền
}

export interface Saint {
  id: string;
  name: string;
  gender: 'Male' | 'Female' | 'Both';
}

export interface TermConfig {
  id: string;
  yearId: string;
  term: 'HK1' | 'HK2';
  startDate: string;
  endDate: string;
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  // Dynamic scores stored as key-value pairs
  scores: { [key: string]: number }; 
  scorePray: number; // Điểm kinh (keep separate as it's standard)
  scoreExam: number; // Thi (keep separate)
  // Computed
  average: number;
  // Attendance Sync
  absentP: number; // Vắng có phép
  absentK: number; // Vắng không phép
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
  class: boolean; // Học giáo lý
  classExcused: boolean;
}

export interface ClassRoom {
  id: string;
  name: string; // e.g., Chiên Con 1
  gradeId: string; // Linked to Grade
  yearId: string; // Linked to School Year
  mainTeacher?: string; // GLV Chủ nhiệm
  assistants?: string; // GLV Phụ trách/Phụ tá
  room?: string; // Phòng học
}

export interface Grade {
  id: string;
  name: string; // e.g., Khối Khai Tâm
}

export interface SchoolYear {
  id: string;
  name: string;
  isActive: boolean;
}

export interface Transaction {
  id: string;
  date: string;
  type: 'INCOME' | 'EXPENSE';
  amount: number;
  description: string;
  note?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  type: 'NOTICE' | 'MEETING_MINUTES';
}

export interface InventoryItem {
  id: string;
  name: string;
  category: 'BOOK' | 'UNIFORM' | 'SCARF' | 'OTHER';
  quantity: number;
  minQuantity: number; // Threshold for low stock alert
  unit: string; // e.g., Cuốn, Cái, Bộ
  price: number; // Unit price (Estimates)
  note?: string;
}

import React, { useState, useMemo } from 'react';
import { InventoryItem } from '../types';
import { Package, Search, Plus, Minus, AlertTriangle, Edit, Trash2, CheckCircle2, History, TrendingUp, AlertCircle, Shirt, Book, Hexagon } from 'lucide-react';

interface InventoryProps {
    items: InventoryItem[];
    setItems: (items: InventoryItem[]) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ items, setItems }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [toast, setToast] = useState<string | null>(null);

  // Modals
  const [showItemModal, setShowItemModal] = useState(false);
  const [showAdjustModal, setShowAdjustModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);

  // Form States
  const [newItemName, setNewItemName] = useState('');
  const [newItemCategory, setNewItemCategory] = useState<'BOOK' | 'UNIFORM' | 'SCARF' | 'OTHER'>('BOOK');
  const [newItemQty, setNewItemQty] = useState(0);
  const [newItemMin, setNewItemMin] = useState(10);
  const [newItemUnit, setNewItemUnit] = useState('Cái');
  const [newItemPrice, setNewItemPrice] = useState(0);

  const [adjustQty, setAdjustQty] = useState(1);
  const [adjustType, setAdjustType] = useState<'IMPORT' | 'EXPORT'>('IMPORT');
  const [adjustReason, setAdjustReason] = useState('');

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCat = filterCategory === 'all' || item.category === filterCategory;
      return matchSearch && matchCat;
    });
  }, [items, searchTerm, filterCategory]);

  const stats = useMemo(() => {
    const totalItems = items.length;
    const totalQty = items.reduce((acc, i) => acc + i.quantity, 0);
    const lowStock = items.filter(i => i.quantity <= i.minQuantity).length;
    const totalValue = items.reduce((acc, i) => acc + (i.quantity * i.price), 0);
    return { totalItems, totalQty, lowStock, totalValue };
  }, [items]);

  const formatCurrency = (val: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(val);

  const handleOpenEdit = (item: InventoryItem) => {
    setSelectedItem(item);
    setNewItemName(item.name);
    setNewItemCategory(item.category);
    setNewItemQty(item.quantity);
    setNewItemMin(item.minQuantity);
    setNewItemUnit(item.unit);
    setNewItemPrice(item.price);
    setShowItemModal(true);
  };

  const handleOpenAdd = () => {
    setSelectedItem(null);
    setNewItemName('');
    setNewItemCategory('BOOK');
    setNewItemQty(0);
    setNewItemMin(10);
    setNewItemUnit('Cái');
    setNewItemPrice(0);
    setShowItemModal(true);
  };

  const handleSaveItem = () => {
    if (!newItemName) return alert('Vui lòng nhập tên vật tư');

    if (selectedItem) {
        // Edit
        const updated = items.map(i => i.id === selectedItem.id ? {
            ...i,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty, // Allow manual override of qty here too
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: newItemPrice
        } : i);
        setItems(updated);
        showToast('Đã cập nhật thông tin vật tư!');
    } else {
        // Add
        const newItem: InventoryItem = {
            id: `INV${Date.now()}`,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty,
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: newItemPrice
        };
        setItems([...items, newItem]);
        showToast('Đã thêm vật tư mới thành công!');
    }
    setShowItemModal(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Bạn có chắc muốn xóa vật tư này không?")) {
          setItems(items.filter(i => i.id !== id));
          showToast('Đã xóa vật tư!');
      }
  };

  const handleOpenAdjust = (item: InventoryItem) => {
      setSelectedItem(item);
      setAdjustQty(1);
      setAdjustType('IMPORT');
      setAdjustReason('');
      setShowAdjustModal(true);
  };

  const handleExecuteAdjust = () => {
      if (!selectedItem) return;
      if (adjustQty <= 0) return alert("Số lượng phải lớn hơn 0");

      const delta = adjustType === 'IMPORT' ? adjustQty : -adjustQty;
      const newQty = selectedItem.quantity + delta;

      if (newQty < 0) return alert("Không thể xuất quá số lượng tồn kho!");

      const updated = items.map(i => i.id === selectedItem.id ? { ...i, quantity: newQty } : i);
      setItems(updated);

      // In a real app, we would log a Transaction record here too (Income/Expense)
      showToast(`Đã ${adjustType === 'IMPORT' ? 'nhập' : 'xuất'} kho thành công!`);
      setShowAdjustModal(false);
  };

  const getCategoryLabel = (cat: string) => {
      switch(cat) {
          case 'BOOK': return { label: 'Sách', icon: <Book size={14}/>, color: 'text-blue-600 bg-blue-50 border-blue-200' };
          case 'UNIFORM': return { label: 'Đồng phục', icon: <Shirt size={14}/>, color: 'text-indigo-600 bg-indigo-50 border-indigo-200' };
          case 'SCARF': return { label: 'Khăn quàng', icon: <Hexagon size={14}/>, color: 'text-orange-600 bg-orange-50 border-orange-200' };
          default: return { label: 'Khác', icon: <Package size={14}/>, color: 'text-slate-600 bg-slate-50 border-slate-200' };
      }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-100/50">
      {/* Toast */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Kho & Vật Tư</h2>
            <p className="text-slate-500 text-sm">Quản lý sách, đồng phục và tài sản chung</p>
        </div>
        <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold transition-all">
            <Plus size={18} /> Thêm Mới
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-blue-100 text-blue-600 rounded-full"><Package size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Danh Mục</div>
                  <div className="text-xl font-bold text-slate-800">{stats.totalItems}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-emerald-100 text-emerald-600 rounded-full"><TrendingUp size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Giá Trị</div>
                  <div className="text-xl font-bold text-slate-800">{new Intl.NumberFormat('vi-VN', {notation: "compact", compactDisplay: "short"}).format(stats.totalValue)}₫</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-amber-100 text-amber-600 rounded-full"><AlertTriangle size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Sắp Hết Hàng</div>
                  <div className={`text-xl font-bold ${stats.lowStock > 0 ? 'text-amber-600' : 'text-slate-800'}`}>{stats.lowStock}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
               {/* Placeholder or Total Qty */}
               <div className="p-3 bg-purple-100 text-purple-600 rounded-full"><History size={20}/></div>
               <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Số Lượng</div>
                  <div className="text-xl font-bold text-slate-800">{stats.totalQty}</div>
               </div>
          </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-4 items-center">
         <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Tìm tên vật tư, mã..." 
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
            />
         </div>
         <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             {['all', 'BOOK', 'UNIFORM', 'SCARF', 'OTHER'].map(cat => (
                 <button 
                    key={cat}
                    onClick={() => setFilterCategory(cat)}
                    className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all border ${filterCategory === cat ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                 >
                     {cat === 'all' ? 'Tất cả' : cat === 'BOOK' ? 'Sách' : cat === 'UNIFORM' ? 'Đồng phục' : cat === 'SCARF' ? 'Khăn' : 'Khác'}
                 </button>
             ))}
         </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
          <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 text-slate-600 text-xs uppercase sticky top-0 z-10">
                      <tr>
                          <th className="p-4 w-16 text-center border-b border-slate-300">#</th>
                          <th className="p-4 border-b border-slate-300">Tên Vật Tư</th>
                          <th className="p-4 border-b border-slate-300">Phân Loại</th>
                          <th className="p-4 text-right border-b border-slate-300">Đơn Giá</th>
                          <th className="p-4 text-center border-b border-slate-300">Tồn Kho</th>
                          <th className="p-4 text-center border-b border-slate-300">Trạng Thái</th>
                          <th className="p-4 text-center border-b border-slate-300 w-32">Thao Tác</th>
                      </tr>
                  </thead>
                  <tbody className="text-sm">
                      {filteredItems.map((item, idx) => {
                          const catInfo = getCategoryLabel(item.category);
                          const isLowStock = item.quantity <= item.minQuantity;
                          return (
                              <tr key={item.id} className="hover:bg-slate-50 border-b border-slate-200 last:border-0 transition-colors">
                                  <td className="p-4 text-center text-slate-400 font-mono text-xs">{idx + 1}</td>
                                  <td className="p-4">
                                      <div className="font-bold text-slate-800">{item.name}</div>
                                      <div className="text-[10px] text-slate-400 font-mono">{item.id}</div>
                                  </td>
                                  <td className="p-4">
                                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold border ${catInfo.color}`}>
                                          {catInfo.icon} {catInfo.label}
                                      </span>
                                  </td>
                                  <td className="p-4 text-right font-medium text-slate-600">{formatCurrency(item.price)}</td>
                                  <td className="p-4 text-center">
                                      <span className={`text-base font-bold ${isLowStock ? 'text-red-600' : 'text-slate-800'}`}>{item.quantity}</span>
                                      <span className="text-xs text-slate-400 ml-1">{item.unit}</span>
                                  </td>
                                  <td className="p-4 text-center">
                                      {item.quantity === 0 ? (
                                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">Hết hàng</span>
                                      ) : isLowStock ? (
                                        <div className="flex items-center justify-center gap-1 text-amber-600 font-bold text-xs">
                                            <AlertCircle size={14}/> Sắp hết
                                        </div>
                                      ) : (
                                          <span className="text-green-600 font-bold text-xs">Sẵn sàng</span>
                                      )}
                                  </td>
                                  <td className="p-4 text-center">
                                      <div className="flex justify-center gap-1">
                                          <button onClick={() => handleOpenAdjust(item)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Nhập/Xuất kho">
                                              <History size={18}/>
                                          </button>
                                          <button onClick={() => handleOpenEdit(item)} className="p-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors" title="Chỉnh sửa">
                                              <Edit size={18}/>
                                          </button>
                                          <button onClick={() => handleDelete(item.id)} className="p-2 text-red-500 hover:bg-red-100 rounded-lg transition-colors" title="Xóa">
                                              <Trash2 size={18}/>
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      })}
                      {filteredItems.length === 0 && (
                          <tr><td colSpan={7} className="p-12 text-center text-slate-400 italic">Không tìm thấy vật tư nào</td></tr>
                      )}
                  </tbody>
              </table>
          </div>
      </div>

      {/* Add/Edit Modal */}
      {showItemModal && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-lg animate-scale-in overflow-hidden">
                  <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                      <h3 className="font-bold text-lg text-slate-800">{selectedItem ? 'Cập Nhật Vật Tư' : 'Thêm Vật Tư Mới'}</h3>
                      <button onClick={() => setShowItemModal(false)}><div className="p-1 hover:bg-slate-200 rounded-full"><Minus size={20} className="rotate-45"/></div></button>
                  </div>
                  <div className="p-6 space-y-4">
                      <div>
                          <label className="label-text">Tên vật tư <span className="text-red-500">*</span></label>
                          <input type="text" className="input-field font-bold" value={newItemName} onChange={e => setNewItemName(e.target.value)} placeholder="VD: Sách Khai Tâm..." autoFocus />
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Phân loại</label>
                              <select className="input-field" value={newItemCategory} onChange={e => setNewItemCategory(e.target.value as any)}>
                                  <option value="BOOK">Sách Giáo Lý</option>
                                  <option value="SCARF">Khăn Quàng</option>
                                  <option value="UNIFORM">Đồng Phục</option>
                                  <option value="OTHER">Khác</option>
                              </select>
                          </div>
                          <div>
                              <label className="label-text">Đơn vị tính</label>
                              <input type="text" className="input-field" value={newItemUnit} onChange={e => setNewItemUnit(e.target.value)} placeholder="Cái, Cuốn..." />
                          </div>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Số lượng ban đầu</label>
                              <input type="number" className="input-field" value={newItemQty} onChange={e => setNewItemQty(Number(e.target.value))} />
                          </div>
                          <div>
                              <label className="label-text">Đơn giá (VNĐ)</label>
                              <input type="number" className="input-field" value={newItemPrice} onChange={e => setNewItemPrice(Number(e.target.value))} />
                          </div>
                      </div>
                      <div>
                          <label className="label-text text-amber-600">Mức báo sắp hết hàng (Min)</label>
                          <input type="number" className="input-field border-amber-200 focus:border-amber-500" value={newItemMin} onChange={e => setNewItemMin(Number(e.target.value))} />
                          <p className="text-[10px] text-slate-400 mt-1">Hệ thống sẽ cảnh báo khi số lượng thấp hơn mức này.</p>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowItemModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleSaveItem} className="btn-primary">Lưu Thông Tin</button>
                  </div>
              </div>
          </div>
      )}

      {/* Adjust Stock Modal */}
      {showAdjustModal && selectedItem && (
           <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-scale-in overflow-hidden">
                   <div className="p-4 border-b border-slate-200 bg-slate-50">
                      <h3 className="font-bold text-lg text-slate-800">Điều Chỉnh Kho</h3>
                      <p className="text-xs text-slate-500">{selectedItem.name} (Hiện có: {selectedItem.quantity})</p>
                   </div>
                   <div className="p-6 space-y-6">
                       <div className="flex p-1 bg-slate-100 rounded-lg">
                           <button onClick={() => setAdjustType('IMPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'IMPORT' ? 'bg-white shadow text-green-600' : 'text-slate-500'}`}>NHẬP KHO (+)</button>
                           <button onClick={() => setAdjustType('EXPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'EXPORT' ? 'bg-white shadow text-red-600' : 'text-slate-500'}`}>XUẤT KHO (-)</button>
                       </div>

                       <div className="text-center">
                           <label className="label-text mb-2">Số lượng {adjustType === 'IMPORT' ? 'nhập thêm' : 'xuất đi'}</label>
                           <div className="flex items-center justify-center gap-4">
                               <button onClick={() => setAdjustQty(Math.max(1, adjustQty - 1))} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Minus size={20}/></button>
                               <input type="number" className="w-24 text-center text-3xl font-bold text-slate-800 border-b-2 border-slate-200 focus:border-blue-500 outline-none pb-1" value={adjustQty} onChange={e => setAdjustQty(Number(e.target.value))} />
                               <button onClick={() => setAdjustQty(adjustQty + 1)} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Plus size={20}/></button>
                           </div>
                       </div>

                       <div>
                           <label className="label-text">Lý do / Ghi chú</label>
                           <input type="text" className="input-field" placeholder="VD: Bán cho học viên, Mua thêm..." value={adjustReason} onChange={e => setAdjustReason(e.target.value)} />
                       </div>

                       <div className="bg-slate-50 p-3 rounded-lg text-center">
                           <span className="text-xs text-slate-500">Tồn kho sau điều chỉnh</span>
                           <div className="text-xl font-bold text-blue-600">
                               {selectedItem.quantity} {adjustType === 'IMPORT' ? '+' : '-'} {adjustQty} = {adjustType === 'IMPORT' ? selectedItem.quantity + adjustQty : selectedItem.quantity - adjustQty}
                           </div>
                       </div>
                   </div>
                   <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowAdjustModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleExecuteAdjust} className={`btn-primary ${adjustType === 'EXPORT' ? 'bg-red-600 hover:bg-red-700' : 'bg-green-600 hover:bg-green-700'}`}>Xác Nhận</button>
                  </div>
              </div>
           </div>
      )}

      <style>{`
        .label-text { display: block; font-size: 0.75rem; font-weight: 700; color: #64748b; margin-bottom: 0.25rem; text-transform: uppercase; }
        .input-field { width: 100%; padding: 0.6rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.5rem; outline: none; transition: all 0.2s; font-size: 0.9rem; }
        .input-field:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
        .btn-primary { padding: 0.5rem 1rem; background-color: #2563eb; color: white; border-radius: 0.5rem; font-weight: 700; font-size: 0.875rem; transition: background-color 0.2s; box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); }
        .btn-primary:hover { background-color: #1d4ed8; }
        .btn-secondary { padding: 0.5rem 1rem; background-color: white; color: #374151; border: 1px solid #d1d5db; border-radius: 0.5rem; font-weight: 600; font-size: 0.875rem; transition: background-color 0.2s; }
        .btn-secondary:hover { background-color: #f3f4f6; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

