export interface Student {
  id: string; // Mã học viên (Số tự động)
  saintName: string; // Tên Thánh
  fullName: string; // Họ tên
  dob: string; // Ngày tháng năm sinh
  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;
  status: 'ACTIVE' | 'TRANSFERRED' | 'DROPPED'; // Tình trạng: Đang học | Chuyển xứ | Nghỉ học

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
  baptismBy?: string; // Do (Linh mục rửa tội)
  baptismSponsor?: string; // Người đỡ đầu Rửa tội
  baptismPlace?: string; // Tại (Nơi rửa tội)

  eucharistDate?: string; // Ngày rước lễ
  eucharistBy?: string; // Do (Linh mục cho rước lễ)
  eucharistPlace?: string; // Tại (Nơi rước lễ)

  confirmationDate?: string; // Ngày thêm sức
  confirmationBy?: string; // Do (ĐGM/Cha ban thêm sức)
  confirmationSponsor?: string; // Người đỡ đầu Thêm sức
  confirmationPlace?: string; // Tại (Nơi thêm sức)

  confirmationOathDate?: string; // Ngày tuyên hứa (Bao đồng)

  note?: string; // Ghi chú
}

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
  educationLevel: string; // Học vấn Giáo Lý (VD: Cấp 1, 2, 3...)
  role: 'ADMIN' | 'GLV'; // Phân quyền
}

export interface Saint {
  id: string;
  name: string;
  gender: 'Male' | 'Female' | 'Both';
}

export interface TermConfig {
  id: string;
  yearId: string;
  term: 'HK1' | 'HK2';
  startDate: string;
  endDate: string;
}

export interface AcademicRecord {
  studentId: string;
  term: 'HK1' | 'HK2';
  // Dynamic scores stored as key-value pairs
  scores: { [key: string]: number }; 
  scorePray: number; // Điểm kinh (keep separate as it's standard)
  scoreExam: number; // Thi (keep separate)
  // Computed
  average: number;
  // Attendance Sync
  absentP: number; // Vắng có phép
  absentK: number; // Vắng không phép
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  mass: boolean; // Đi lễ
  massExcused: boolean; // Có phép
