import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_TEACHERS } from '../constants';
import { ClassRoom, SchoolYear, Student, Grade } from '../types';
import { Users, User, UserCheck, Edit, X, Save, CheckCircle2, Search } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
    grades: Grade[];
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  const [mainTeacherInput, setMainTeacherInput] = useState('');
  const [showMainTeacherSuggestions, setShowMainTeacherSuggestions] = useState(false);

  const [assistants, setAssistants] = useState<string[]>(['', '', '']);
  const [showAssistSuggestions, setShowAssistSuggestions] = useState<boolean[]>([false, false, false]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  useEffect(() => {
    if (editingClass) {
        const parts = editingClass.assistants ? editingClass.assistants.split(',').map(s => s.trim()) : [];
        setAssistants([parts[0] || '', parts[1] || '', parts[2] || '']);
        setMainTeacherInput(editingClass.mainTeacher || '');
    }
  }, [editingClass]);

  const filteredClasses = useMemo(() => {
      return classes.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [classes, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        const combinedAssistants = assistants
            .map(s => s.trim())
            .filter(s => s !== '')
            .join(', ');

        const finalClassData = { 
            ...editingClass, 
            mainTeacher: mainTeacherInput, 
            assistants: combinedAssistants 
        };

        const updatedClasses = classes.map(c => c.id === editingClass.id ? finalClassData : c);
        setClasses(updatedClasses);
        showToast(`Đã cập nhật thông tin lớp ${editingClass.name} thành công!`);
        setEditingClass(null);
    }
  };

  const sortedTeachers = useMemo(() => {
      return [...MOCK_TEACHERS].sort((a, b) => a.fullName.localeCompare(b.fullName));
  }, []);

  const getFilteredTeachers = (input: string) => {
      if (!input) return sortedTeachers;
      const lowerInput = input.toLowerCase();
      return sortedTeachers.filter(t => 
          t.fullName.toLowerCase().includes(lowerInput) || 
          t.saintName.toLowerCase().includes(lowerInput)
      );
  };

  const filteredMainTeacherSuggestions = useMemo(() => getFilteredTeachers(mainTeacherInput), [mainTeacherInput, sortedTeachers]);

  const updateAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = true;
      setShowAssistSuggestions(newShow);
  };

  const selectAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = false;
      setShowAssistSuggestions(newShow);
  }

  const toggleAssistSuggestion = (index: number, status: boolean) => {
      const newShow = [...showAssistSuggestions];
      newShow[index] = status;
      setShowAssistSuggestions(newShow);
  }

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2 border rounded-lg bg-white font-medium min-w-[150px]"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2 border rounded-lg bg-white min-w-[150px]"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-sm border-b border-slate-300">
                         <th className="px-3 py-2 w-12 text-center font-bold">STT</th>
                         <th className="px-3 py-2 font-bold">Tên Lớp</th>
                         <th className="px-3 py-2 font-bold">Khối</th>
                         <th className="px-3 py-2 text-center font-bold">Sĩ số</th>
                         <th className="px-3 py-2 text-center font-bold">Nam</th>
                         <th className="px-3 py-2 text-center font-bold">Nữ</th>
                         <th className="px-3 py-2 text-center font-bold">Phòng Học</th>
                         <th className="px-3 py-2 font-bold">GLV Chủ Nhiệm</th>
                         <th className="px-3 py-2 font-bold">GLV Phụ Trách</th>
                         <th className="px-3 py-2 w-16 text-center"></th>
                     </tr>
                 </thead>
                 <tbody className="">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = grades.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50 border-b border-slate-200 text-sm text-slate-700">
                                     <td className="px-3 py-2 text-center text-slate-500">{index + 1}</td>
                                     <td className="px-3 py-2 font-bold text-slate-800">{c.name}</td>
                                     <td className="px-3 py-2 text-slate-600">{gradeName}</td>
                                     <td className="px-3 py-2 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="px-3 py-2 text-center text-slate-600">{stats.male}</td>
                                     <td className="px-3 py-2 text-center text-slate-600">{stats.female}</td>
                                     <td className="px-3 py-2 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="px-3 py-2 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="px-3 py-2 text-slate-600 max-w-xs truncate" title={c.assistants}>{c.assistants || '---'}</td>
                                     <td className="px-3 py-2 text-center">
                                         <button onClick={() => handleEditClass(c)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                             <Edit size={16} />
                                         </button>
                                     </td>
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={10} className="p-8 text-center text-slate-400">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-3 bg-slate-50 border-t border-slate-200 flex gap-6 justify-end text-sm font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={16}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={16}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={16}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {editingClass && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in flex flex-col max-h-[90vh]">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-lg text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                </div>
                <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg bg-slate-100 text-slate-500" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>

                    <div className="relative">
                        <label className="block text-sm font-bold text-slate-700 mb-1">GLV Chủ Nhiệm</label>
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full p-2 pl-3 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={mainTeacherInput}
                                onChange={(e) => {
                                    setMainTeacherInput(e.target.value);
                                    setShowMainTeacherSuggestions(true);
                                }}
                                onFocus={() => setShowMainTeacherSuggestions(true)}
                                onBlur={() => setTimeout(() => setShowMainTeacherSuggestions(false), 200)}
                                placeholder="Nhập tên GLV..."
                            />
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        </div>
                        {showMainTeacherSuggestions && (
                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                {filteredMainTeacherSuggestions.length > 0 ? (
                                    filteredMainTeacherSuggestions.map(t => (
                                        <div 
                                            key={t.id}
                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                            onClick={() => {
                                                setMainTeacherInput(`${t.saintName} ${t.fullName}`);
                                                setShowMainTeacherSuggestions(false);
                                            }}
                                        >
                                            <span>{t.saintName} {t.fullName}</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="p-3 text-xs text-slate-400 text-center italic">Không tìm thấy GLV phù hợp</div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                        <label className="block text-sm font-bold text-slate-700 mb-2">GLV Phụ Trách</label>
                        <div className="space-y-3">
                             {assistants.map((val, idx) => {
                                const suggestions = getFilteredTeachers(val);
                                return (
                                    <div key={idx} className="relative">
                                        <div className="relative">
                                            <input 
                                                type="text"
                                                className="w-full p-2 pl-3 pr-8 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm bg-white"
                                                placeholder={`GLV Phụ trách ${idx + 1}`}
                                                value={val}
                                                onChange={(e) => updateAssistant(idx, e.target.value)}
                                                onFocus={() => toggleAssistSuggestion(idx, true)}
                                                onBlur={() => setTimeout(() => toggleAssistSuggestion(idx, false), 200)}
                                            />
                                             <Search className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                                        </div>
                                        {showAssistSuggestions[idx] && (
                                            <div className="absolute z-20 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {suggestions.length > 0 ? (
                                                    suggestions.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex items-center justify-between border-b border-slate-50 last:border-0"
                                                            onClick={() => selectAssistant(idx, `${t.saintName} ${t.fullName}`)}
                                                        >
                                                            <span>{t.saintName} {t.fullName}</span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="p-2 text-xs text-slate-400 text-center italic">Không tìm thấy</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                             })}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3 mt-auto">
                    <button onClick={() => setEditingClass(null)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium">Hủy</button>
                    <button onClick={handleSaveClass} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, GripVertical, AlertCircle, Info } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const [draggedColId, setDraggedColId] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);
  const [newColTerm, setNewColTerm] = useState<'HK1' | 'HK2'>('HK1');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  // Only show ACTIVE students in grades list
  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);

    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        let updatedRecord;
        const newRecords = [...prev];
        if (existingIndex > -1) {
            const oldRec = prev[existingIndex];
            updatedRecord = { ...oldRec };
            updatedRecord.scores = { ...updatedRecord.scores, [field]: numValue };
            newRecords[existingIndex] = updatedRecord;
            return newRecords;
        } else {
             updatedRecord = { studentId, term: term, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 };
             updatedRecord.scores = { [field]: numValue };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;

      const termColumns = testColumns.filter(c => c.term === record.term);

      termColumns.forEach(col => {
          if (col.weight > 0) {
              const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = [...records];
     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });

     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight, term: newColTerm }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" vào ${newColTerm} thành công!`);
    }
  };

  const removeColumn = (id: string) => {
    if (window.confirm("Bạn có chắc chắn muốn xóa cột điểm này? Dữ liệu điểm của cột này sẽ bị mất hiển thị.")) {
        setTestColumns(testColumns.filter(c => c.id !== id));
        showToast("Đã xóa cột điểm thành công!");
    }
  };

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedColId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, targetId: string) => {
      e.preventDefault();
      if (!draggedColId || draggedColId === targetId) return;

      const sourceIndex = testColumns.findIndex(c => c.id === draggedColId);
      const targetIndex = testColumns.findIndex(c => c.id === targetId);

      if (sourceIndex === -1 || targetIndex === -1) return;

      const sourceCol = testColumns[sourceIndex];
      const targetCol = testColumns[targetIndex];

      if (sourceCol.term !== targetCol.term) {
          showToast("Chỉ có thể sắp xếp cột trong cùng một Học Kỳ!");
          setDraggedColId(null);
          return;
      }

      const newCols = [...testColumns];
      const [removed] = newCols.splice(sourceIndex, 1);
      newCols.splice(targetIndex, 0, removed);

      setTestColumns(newCols);
      setDraggedColId(null);
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.length > 0 ? parts[parts.length - 1] : '';
      const lastName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
      return { firstName, lastName };
  };

  const processedStudentsYear = useMemo(() => {
    // 1. Calculate averages and basic stats
    let list = filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;

      return { 
        ...s, 
        avg1, 
        avg2, 
        avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
        nameForSort: s.fullName.split(' ').pop() || ''
      };
    });

    // 2. Assign Rank (Ranking) based on Score DESC
    // Sort temporary list by avgYear Descending to find rank index
    const sortedByScore = [...list].sort((a, b) => b.avgYear - a.avgYear);
    const rankedMap = new Map();
    sortedByScore.forEach((s, index) => {
        rankedMap.set(s.id, index + 1);
    });

    // 3. Sort Final List by Name A-Z (Vietnamese)
    const finalList = list.map(s => ({
        ...s,
        ranking: rankedMap.get(s.id)
    })).sort((a, b) => {
        return a.nameForSort.localeCompare(b.nameForSort, 'vi');
    });

    return finalList;
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const handleExportExcel = () => {
    if (!currentClass) return;
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "\uFEFF"; 

    const headerRow = [
        "STT", "Mã HV", "Tên Thánh", "Họ Đệm", "Tên",
        ...hk1Columns.map(c => `${c.name} (x${c.weight})`), "Vắng P (HK1)", "Vắng K (HK1)", "TB HK1",
        ...hk2Columns.map(c => `${c.name} (x${c.weight})`), "Vắng P (HK2)", "Vắng K (HK2)", "TB HK2",
        "TB Cả Năm", "Xếp Loại", "Hạng"
    ];
    csvContent += headerRow.join(",") + "\n";

    processedStudentsYear.forEach((s, idx) => {
        const r1 = getRecord(s.id, 'HK1');
        const r2 = getRecord(s.id, 'HK2');
        const hk1Scores = hk1Columns.map(c => r1.scores?.[c.id] || 0);
        const hk2Scores = hk2Columns.map(c => r2.scores?.[c.id] || 0);
        const { firstName, lastName } = splitName(s.fullName);

        const row = [
            idx + 1,
            s.id,
            s.saintName,
            lastName,
            firstName,
            ...hk1Scores,
            s.absentP1,
            s.absentK1,
            s.avg1.toFixed(1),
            ...hk2Scores,
            s.absentP2,
            s.absentK2,
            s.avg2.toFixed(1),
            s.avgYear.toFixed(1),
            s.rank.label,
            s.ranking
        ];
        csvContent += row.join(",") + "\n";
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Bang_Diem_${currentClass.name.replace(/\s/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-300 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[140px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-2 border border-slate-300 rounded-lg min-w-[160px] text-sm focus:ring-2 focus:ring-blue-500 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <>
                {showAddColumn ? (
                    <div className="flex items-center gap-2 bg-slate-100 p-2 rounded-lg border border-slate-300 animate-fade-in shadow-lg absolute right-6 top-24 z-50">
                        <select className="px-2 py-1 border rounded text-sm font-bold text-blue-700" value={newColTerm} onChange={(e) => setNewColTerm(e.target.value as any)}>
                            <option value="HK1">Học Kỳ 1</option>
                            <option value="HK2">Học Kỳ 2</option>
                        </select>
                        <input type="text" placeholder="Tên cột (VD: 15')" className="px-2 py-1 border rounded text-sm w-32" value={newColName} onChange={(e) => setNewColName(e.target.value)}/>
                        <select className="px-2 py-1 border rounded text-sm" value={newColWeight} onChange={(e) => setNewColWeight(Number(e.target.value))}>
                            <option value={0}>x0</option>
                            <option value={1}>x1</option>
                            <option value={2}>x2</option>
                            <option value={3}>x3</option>
                        </select>
                        <button onClick={addColumn} className="px-3 py-1 bg-green-600 text-white rounded text-sm font-bold hover:bg-green-700">OK</button>
                        <button onClick={() => setShowAddColumn(false)} className="px-3 py-1 bg-slate-300 text-slate-700 rounded text-sm hover:bg-slate-400">Hủy</button>
                    </div>
                ) : (
                    <button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 border border-blue-200 rounded-lg hover:bg-blue-100 text-sm font-bold transition-all"><Plus size={16} /> Thêm Cột</button>
                )}
                </>
            )}
             <button onClick={handleExportExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white border border-green-700 rounded-lg text-sm hover:bg-green-700 font-bold shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-amber-50 border-l-4 border-amber-500 p-4 mb-4 flex items-center gap-3 text-amber-900 text-sm shadow-sm rounded-r-lg">
        <div className="bg-amber-200 p-1.5 rounded-full"><Info size={20} className="text-amber-700" /></div>
        <div className="flex flex-col">
            <span className="font-bold">ĐỒNG BỘ CHUYÊN CẦN:</span>
            <span>Số buổi <b>Vắng P (Có phép)</b> và <b>Vắng K (Không phép)</b> được đồng bộ tự động khi bạn nhấn "Lưu Điểm Danh" ở tab Chuyên Cần.</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-separate border-spacing-0">
                    <thead>
                        <tr className="bg-slate-100 text-slate-800 text-sm">
                            <th rowSpan={2} className="px-3 py-2 w-12 text-center sticky left-0 bg-slate-100 z-20 border-b border-r border-slate-400 font-bold text-sm">STT</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[120px] sticky left-12 bg-slate-100 z-20 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold text-sm">Tên Thánh</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[120px] sticky left-[168px] bg-slate-100 z-20 border-b border-r border-slate-400 font-bold text-sm">Họ và Tên Đệm</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[80px] sticky left-[288px] bg-slate-100 z-20 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold text-sm">Tên</th>
                            <th colSpan={hk1Columns.length + 2 + 1} className="p-1.5 text-center bg-blue-100/50 border-b border-r border-blue-400 font-extrabold text-blue-800 tracking-wider text-xs">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 2 + 1} className="p-1.5 text-center bg-purple-100/50 border-b border-r border-purple-400 font-extrabold text-purple-800 tracking-wider text-xs">HỌC KỲ 2</th>
                            <th rowSpan={2} className="px-3 py-2 w-20 text-center border-b border-slate-400 font-bold bg-slate-200 text-slate-800 text-sm">Cả Năm</th>
                            <th rowSpan={2} className="px-3 py-2 w-20 text-center border-b border-slate-400 font-bold bg-slate-200 text-slate-800 text-sm">Xếp Loại</th>
                            <th rowSpan={2} className="px-3 py-2 w-12 text-center border-b border-slate-400 font-bold bg-yellow-50 text-yellow-800 text-sm">Hạng</th>
                        </tr>
                        <tr className="bg-slate-50 text-slate-600 text-[11px]">
                             {hk1Columns.map((col) => (
                                <th key={col.id} className="px-2 py-1 w-20 text-center border-b border-r border-slate-400 bg-blue-50/30">
                                    <span className="font-bold">{col.name}</span>
                                </th>
                             ))}
