                                    <td className="px-3 py-1.5 sticky left-[168px] bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 text-slate-800 text-sm truncate">{lastName}</td>
                                    <td className="px-3 py-1.5 font-bold sticky left-[288px] bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] text-slate-800 text-sm truncate">{firstName}</td>

                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-0 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r1.scores ? (r1.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full text-center py-1.5 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="px-2 py-1 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/30 text-sm">{s.absentP1}</td>
                                    <td className="px-2 py-1 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/30 text-sm">{s.absentK1}</td>
                                    <td className="px-2 py-1 border-r border-blue-400 text-center font-bold text-blue-700 bg-blue-50 text-sm">
                                        {(s.avg1 >= 0) ? s.avg1.toFixed(1) : '-'}
                                    </td>
                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-0 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r2.scores ? (r2.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} 
                                                className="w-full text-center py-1.5 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
                                    ))}
                                    <td className="px-2 py-1 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/30 text-sm">{s.absentP2}</td>
                                    <td className="px-2 py-1 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/30 text-sm">{s.absentK2}</td>
                                    <td className="px-2 py-1 border-r border-purple-400 text-center font-bold text-purple-700 bg-purple-50 text-sm">
                                        {(s.avg2 >= 0) ? s.avg2.toFixed(1) : '-'}
                                    </td>
                                    <td className="px-2 py-1 text-center font-bold text-slate-900 bg-slate-100 border-r border-slate-300 text-sm">
                                        {s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}
                                    </td>
                                    <td className="px-2 py-1 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && (
                                            <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold uppercase ${s.rank.color}`}>
                                                {s.rank.label}
                                            </span>
                                        )}
                                    </td>
                                    <td className="px-2 py-1 text-center font-bold text-yellow-700 bg-yellow-50/50 text-sm">
                                        {s.ranking}
                                    </td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={30} className="p-12 text-center text-slate-400 italic bg-slate-50">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {processedStudentsYear.length > 0 && (
                <div className="p-4 border-t border-slate-300 bg-slate-100 text-right sticky bottom-0 z-20 shadow-md">
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 ml-auto px-8 py-3 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold transition-all transform hover:-translate-y-1 active:scale-95 text-sm">
                        <Save size={20} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm mb-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-500 flex items-center gap-2"><UserCheck size={18} />GLV Phụ Trách: <span className="font-semibold text-slate-700">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-slate-500">Sĩ số</div>
                    <div className="text-2xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                  <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                    <div className="flex items-center gap-2"><CheckCircle2 className="text-green-600" /><h4 className="font-bold text-green-800">Danh Sách Lên Lớp</h4></div>
                    <span className="px-3 py-1 bg-white text-green-700 rounded-full text-xs font-bold border border-green-200">{passedStudents.length} em</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-300">
                        {passedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-green-50/30 border-b border-slate-200">
                            <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-bold text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                <div className="bg-white rounded-xl border border-red-200 shadow-sm overflow-hidden">
                   <div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center">
                    <div className="flex items-center gap-2"><XCircle className="text-red-600" /><h4 className="font-bold text-red-800">Danh Sách Chưa Đạt</h4></div>
                    <span className="px-3 py-1 bg-white text-red-700 rounded-full text-xs font-bold border border-red-200">{failedStudents.length} em</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB Cả Năm</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-300">
                        {failedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-red-50/30 border-b border-slate-200">
                            <td className="p-3 font-medium text-slate-700">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-bold text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-bold text-slate-800">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[10px] font-bold ${s.rank.color}`}>{s.rank.label}</span></td>
