import React, { useState, useMemo } from 'react';
import { InventoryItem } from '../types';
import { Package, Search, Plus, Minus, AlertTriangle, Edit, Trash2, CheckCircle2, History, TrendingUp, AlertCircle, Shirt, Book, Hexagon } from 'lucide-react';

interface InventoryProps {
    items: InventoryItem[];
    setItems: (items: InventoryItem[]) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ items, setItems }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [toast, setToast] = useState<string | null>(null);

  // Modals
  const [showItemModal, setShowItemModal] = useState(false);
  const [showAdjustModal, setShowAdjustModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);

  // Form States
  const [newItemName, setNewItemName] = useState('');
  const [newItemCategory, setNewItemCategory] = useState<'BOOK' | 'UNIFORM' | 'SCARF' | 'OTHER'>('BOOK');
  const [newItemQty, setNewItemQty] = useState(0);
  const [newItemMin, setNewItemMin] = useState(10);
  const [newItemUnit, setNewItemUnit] = useState('Cái');
  const [newItemPriceStr, setNewItemPriceStr] = useState('0'); // Format as string for dots

  const [adjustQty, setAdjustQty] = useState(1);
  const [adjustType, setAdjustType] = useState<'IMPORT' | 'EXPORT'>('IMPORT');
  const [adjustReason, setAdjustReason] = useState('');

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Helper to format string with dots: 1000000 -> 1.000.000
  const formatNumberWithDots = (val: string) => {
    const rawValue = val.replace(/\D/g, ''); // Remove non-digits
    return rawValue.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCat = filterCategory === 'all' || item.category === filterCategory;
      return matchSearch && matchCat;
    });
  }, [items, searchTerm, filterCategory]);

  const stats = useMemo(() => {
    const totalItems = items.length;
    const totalQty = items.reduce((acc, i) => acc + i.quantity, 0);
    const lowStock = items.filter(i => i.quantity <= i.minQuantity).length;
    const totalValue = items.reduce((acc, i) => acc + (i.quantity * i.price), 0);
    return { totalItems, totalQty, lowStock, totalValue };
  }, [items]);

  const formatCurrency = (val: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(val);

  const handleOpenEdit = (item: InventoryItem) => {
    setSelectedItem(item);
    setNewItemName(item.name);
    setNewItemCategory(item.category);
    setNewItemQty(item.quantity);
    setNewItemMin(item.minQuantity);
    setNewItemUnit(item.unit);
    setNewItemPriceStr(formatNumberWithDots(item.price.toString()));
    setShowItemModal(true);
  };

  const handleOpenAdd = () => {
    setSelectedItem(null);
    setNewItemName('');
    setNewItemCategory('BOOK');
    setNewItemQty(0);
    setNewItemMin(10);
    setNewItemUnit('Cái');
    setNewItemPriceStr('0');
    setShowItemModal(true);
  };

  const handleSaveItem = () => {
    if (!newItemName) return alert('Vui lòng nhập tên vật tư');

    const rawPrice = parseInt(newItemPriceStr.replace(/\./g, ''), 10) || 0;

    if (selectedItem) {
        const updated = items.map(i => i.id === selectedItem.id ? {
            ...i,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty,
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: rawPrice
        } : i);
        setItems(updated);
        showToast('Đã cập nhật thông tin vật tư!');
    } else {
        const newItem: InventoryItem = {
            id: `INV${Date.now()}`,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty,
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: rawPrice
        };
        setItems([...items, newItem]);
        showToast('Đã thêm vật tư mới thành công!');
    }
    setShowItemModal(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Bạn có chắc muốn xóa vật tư này không?")) {
          setItems(items.filter(i => i.id !== id));
          showToast('Đã xóa vật tư!');
      }
  };

  const handleOpenAdjust = (item: InventoryItem) => {
      setSelectedItem(item);
      setAdjustQty(1);
      setAdjustType('IMPORT');
      setAdjustReason('');
      setShowAdjustModal(true);
  };

  const handleExecuteAdjust = () => {
      if (!selectedItem) return;
      if (adjustQty <= 0) return alert("Số lượng phải lớn hơn 0");

      const delta = adjustType === 'IMPORT' ? adjustQty : -adjustQty;
      const newQty = selectedItem.quantity + delta;

      if (newQty < 0) return alert("Không thể xuất quá số lượng tồn kho!");

      const updated = items.map(i => i.id === selectedItem.id ? { ...i, quantity: newQty } : i);
      setItems(updated);
      showToast(`Đã ${adjustType === 'IMPORT' ? 'nhập' : 'xuất'} kho thành công!`);
      setShowAdjustModal(false);
  };

  const getCategoryLabel = (cat: string) => {
      switch(cat) {
          case 'BOOK': return { label: 'Sách', icon: <Book size={14}/>, color: 'text-blue-600 bg-blue-50 border-blue-200' };
          case 'UNIFORM': return { label: 'Đồng phục', icon: <Shirt size={14}/>, color: 'text-indigo-600 bg-indigo-50 border-indigo-200' };
          case 'SCARF': return { label: 'Khăn quàng', icon: <Hexagon size={14}/>, color: 'text-orange-600 bg-orange-50 border-orange-200' };
          default: return { label: 'Khác', icon: <Package size={14}/>, color: 'text-slate-600 bg-slate-50 border-slate-200' };
      }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-100/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Kho & Vật Tư</h2>
            <p className="text-slate-500 text-sm">Quản lý sách, đồng phục và tài sản chung</p>
        </div>
        <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold transition-all">
            <Plus size={18} /> Thêm Mới
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-blue-100 text-blue-600 rounded-full"><Package size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Danh Mục</div>
                  <div className="text-xl font-bold text-slate-800">{stats.totalItems}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-emerald-100 text-emerald-600 rounded-full"><TrendingUp size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Giá Trị</div>
                  <div className="text-xl font-bold text-slate-800">{formatCurrency(stats.totalValue)}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-3 bg-amber-100 text-amber-600 rounded-full"><AlertTriangle size={20}/></div>
              <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Sắp Hết Hàng</div>
                  <div className={`text-xl font-bold ${stats.lowStock > 0 ? 'text-amber-600' : 'text-slate-800'}`}>{stats.lowStock}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
               <div className="p-3 bg-purple-100 text-purple-600 rounded-full"><History size={20}/></div>
               <div>
                  <div className="text-xs text-slate-500 font-bold uppercase">Tổng Số Lượng</div>
                  <div className="text-xl font-bold text-slate-800">{stats.totalQty}</div>
               </div>
          </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-4 items-center">
         <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Tìm tên vật tư, mã..." 
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
            />
         </div>
         <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             {['all', 'BOOK', 'UNIFORM', 'SCARF', 'OTHER'].map(cat => (
                 <button 
                    key={cat}
                    onClick={() => setFilterCategory(cat)}
                    className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all border ${filterCategory === cat ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                 >
                     {cat === 'all' ? 'Tất cả' : cat === 'BOOK' ? 'Sách' : cat === 'UNIFORM' ? 'Đồng phục' : cat === 'SCARF' ? 'Khăn' : 'Khác'}
                 </button>
             ))}
         </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
          <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 text-slate-600 text-xs uppercase sticky top-0 z-10">
                      <tr>
                          <th className="px-3 py-2 w-16 text-center border-b border-slate-300">#</th>
                          <th className="px-3 py-2 border-b border-slate-300">Tên Vật Tư</th>
                          <th className="px-3 py-2 border-b border-slate-300">Phân Loại</th>
                          <th className="px-3 py-2 text-right border-b border-slate-300">Đơn Giá</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300">Tồn Kho</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300">Trạng Thái</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300 w-32">Thao Tác</th>
                      </tr>
                  </thead>
                  <tbody className="text-sm">
                      {filteredItems.map((item, idx) => {
                          const catInfo = getCategoryLabel(item.category);
                          const isLowStock = item.quantity <= item.minQuantity;
                          return (
                              <tr key={item.id} className="hover:bg-slate-50 border-b border-slate-200 last:border-0 transition-colors">
                                  <td className="px-3 py-2 text-center text-slate-400 font-mono text-xs">{idx + 1}</td>
                                  <td className="px-3 py-2">
                                      <div className="font-bold text-slate-800">{item.name}</div>
                                      <div className="text-[10px] text-slate-400 font-mono">{item.id}</div>
                                  </td>
                                  <td className="px-3 py-2">
                                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold border ${catInfo.color}`}>
                                          {catInfo.icon} {catInfo.label}
                                      </span>
                                  </td>
                                  <td className="px-3 py-2 text-right font-bold text-slate-600">{formatCurrency(item.price)}</td>
                                  <td className="px-3 py-2 text-center">
                                      <span className={`text-base font-bold ${isLowStock ? 'text-red-600' : 'text-slate-800'}`}>{item.quantity}</span>
                                      <span className="text-xs text-slate-400 ml-1">{item.unit}</span>
                                  </td>
                                  <td className="px-3 py-2 text-center">
                                      {item.quantity === 0 ? (
                                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">Hết hàng</span>
                                      ) : isLowStock ? (
                                        <div className="flex items-center justify-center gap-1 text-amber-600 font-bold text-xs">
                                            <AlertCircle size={14}/> Sắp hết
                                        </div>
                                      ) : (
                                          <span className="text-green-600 font-bold text-xs">Sẵn sàng</span>
                                      )}
                                  </td>
                                  <td className="px-3 py-2 text-center">
                                      <div className="flex justify-center gap-1">
                                          <button onClick={() => handleOpenAdjust(item)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Nhập/Xuất kho">
                                              <History size={16}/>
                                          </button>
                                          <button onClick={() => handleOpenEdit(item)} className="p-1.5 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors" title="Chỉnh sửa">
                                              <Edit size={16}/>
                                          </button>
                                          <button onClick={() => handleDelete(item.id)} className="p-1.5 text-red-500 hover:bg-red-100 rounded-lg transition-colors" title="Xóa">
                                              <Trash2 size={16}/>
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {showItemModal && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-lg animate-scale-in overflow-hidden">
                  <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                      <h3 className="font-bold text-lg text-slate-800">{selectedItem ? 'Cập Nhật Vật Tư' : 'Thêm Vật Tư Mới'}</h3>
                      <button onClick={() => setShowItemModal(false)}><div className="p-1 hover:bg-slate-200 rounded-full"><Minus size={20} className="rotate-45"/></div></button>
                  </div>
                  <div className="p-6 space-y-4">
                      <div>
                          <label className="label-text">Tên vật tư <span className="text-red-500">*</span></label>
                          <input type="text" className="input-field font-bold" value={newItemName} onChange={e => setNewItemName(e.target.value)} placeholder="VD: Sách Khai Tâm..." autoFocus />
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Phân loại</label>
                              <select className="input-field" value={newItemCategory} onChange={e => setNewItemCategory(e.target.value as any)}>
                                  <option value="BOOK">Sách Giáo Lý</option>
                                  <option value="SCARF">Khăn Quàng</option>
                                  <option value="UNIFORM">Đồng Phục</option>
                                  <option value="OTHER">Khác</option>
                              </select>
                          </div>
                          <div>
                              <label className="label-text">Đơn vị tính</label>
                              <input type="text" className="input-field" value={newItemUnit} onChange={e => setNewItemUnit(e.target.value)} placeholder="Cái, Cuốn..." />
                          </div>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Số lượng ban đầu</label>
                              <input type="number" className="input-field" value={newItemQty} onChange={e => setNewItemQty(Number(e.target.value))} />
                          </div>
                          <div>
                              <label className="label-text">Đơn giá (VNĐ)</label>
                              <input 
                                type="text" 
                                className="input-field font-mono font-bold text-blue-700" 
                                value={newItemPriceStr} 
                                onChange={e => setNewItemPriceStr(formatNumberWithDots(e.target.value))} 
                              />
                          </div>
                      </div>
                      <div>
                          <label className="label-text text-amber-600">Mức báo sắp hết hàng (Min)</label>
                          <input type="number" className="input-field border-amber-200 focus:border-amber-500" value={newItemMin} onChange={e => setNewItemMin(Number(e.target.value))} />
                          <p className="text-[10px] text-slate-400 mt-1">Hệ thống sẽ cảnh báo khi số lượng thấp hơn mức này.</p>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowItemModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleSaveItem} className="btn-primary">Lưu Thông Tin</button>
                  </div>
              </div>
          </div>
      )}

      {showAdjustModal && selectedItem && (
           <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-scale-in overflow-hidden">
                   <div className="p-4 border-b border-slate-200 bg-slate-50">
                      <h3 className="font-bold text-lg text-slate-800">Điều Chỉnh Kho</h3>
                      <p className="text-xs text-slate-500">{selectedItem.name} (Hiện có: {selectedItem.quantity})</p>
                   </div>
                   <div className="p-6 space-y-6">
                       <div className="flex p-1 bg-slate-100 rounded-lg">
                           <button onClick={() => setAdjustType('IMPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'IMPORT' ? 'bg-white shadow text-green-600' : 'text-slate-500'}`}>NHẬP KHO (+)</button>
                           <button onClick={() => setAdjustType('EXPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'EXPORT' ? 'bg-white shadow text-red-600' : 'text-slate-500'}`}>XUẤT KHO (-)</button>
                       </div>

                       <div className="text-center">
                           <label className="label-text mb-2">Số lượng {adjustType === 'IMPORT' ? 'nhập thêm' : 'xuất đi'}</label>
                           <div className="flex items-center justify-center gap-4">
                               <button onClick={() => setAdjustQty(Math.max(1, adjustQty - 1))} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Minus size={20}/></button>
                               <input type="number" className="w-24 text-center text-3xl font-bold text-slate-800 border-b-2 border-slate-200 focus:border-blue-500 outline-none pb-1" value={adjustQty} onChange={e => setAdjustQty(Number(e.target.value))} />
                               <button onClick={() => setAdjustQty(adjustQty + 1)} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Plus size={20}/></button>
                           </div>
                       </div>

                       <div>
                           <label className="label-text">Lý do / Ghi chú</label>
                           <input type="text" className="input-field" placeholder="VD: Bán cho học viên, Mua thêm..." value={adjustReason} onChange={e => setAdjustReason(e.target.value)} />
                       </div>

                       <div className="bg-slate-50 p-3 rounded-lg text-center">
                           <span className="text-xs text-slate-500">Tồn kho sau điều chỉnh</span>
                           <div className="text-xl font-bold text-blue-600">
                               {selectedItem.quantity} {adjustType === 'IMPORT' ? '+' : '-'} {adjustQty} = {adjustType === 'IMPORT' ? selectedItem.quantity + adjustQty : selectedItem.quantity - adjustQty}
                           </div>
                       </div>
                   </div>
                   <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowAdjustModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleExecuteAdjust} className={`btn-primary ${adjustType === 'EXPORT' ? 'bg-red-600 hover:bg-red-700' : 'bg-green-600 hover:bg-green-700'}`}>Xác Nhận</button>
                  </div>
              </div>
           </div>
      )}

      <style>{`
        .label-text { display: block; font-size: 0.75rem; font-weight: 700; color: #64748b; margin-bottom: 0.25rem; text-transform: uppercase; }
        .input-field { width: 100%; padding: 0.6rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.5rem; outline: none; transition: all 0.2s; font-size: 0.9rem; }
        .input-field:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
        .btn-primary { padding: 0.5rem 1rem; background-color: #2563eb; color: white; border-radius: 0.5rem; font-weight: 700; font-size: 0.875rem; transition: background-color 0.2s; box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); }
        .btn-primary:hover { background-color: #1d4ed8; }
        .btn-secondary { padding: 0.5rem 1rem; background-color: white; color: #374151; border: 1px solid #d1d5db; border-radius: 0.5rem; font-weight: 600; font-size: 0.875rem; transition: background-color 0.2s; }
        .btn-secondary:hover { background-color: #f3f4f6; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { Wallet, TrendingUp, TrendingDown, Plus, Minus, PieChart as PieChartIcon, FileSpreadsheet } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Transaction } from '../types';

interface FinanceProps {
    transactions: Transaction[];
    setTransactions: (t: Transaction[]) => void;
}

export const Finance: React.FC<FinanceProps> = ({ transactions, setTransactions }) => {
  const [amountStr, setAmountStr] = useState(''); // Store formatted string for input
  const [description, setDescription] = useState('');
  const [note, setNote] = useState('');
  const [type, setType] = useState<'INCOME'|'EXPENSE'>('INCOME');

  const totalIncome = transactions.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const data = [
    { name: 'Tổng Thu', value: totalIncome },
    { name: 'Tổng Chi', value: totalExpense },
  ];
  const COLORS = ['#10b981', '#ef4444'];

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
  };

  // Helper to format string with dots: 1000000 -> 1.000.000
  const formatNumberWithDots = (val: string) => {
    const rawValue = val.replace(/\D/g, ''); // Remove non-digits
    return rawValue.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setAmountStr(formatNumberWithDots(e.target.value));
  };

  const handleAddTransaction = () => {
      const rawAmount = parseInt(amountStr.replace(/\./g, ''), 10);
      if (!rawAmount || !description) return alert("Vui lòng nhập số tiền và nội dung");

      const newTx: Transaction = {
          id: `T${Date.now()}`,
          date: new Date().toISOString().split('T')[0],
          type: type,
          amount: rawAmount,
          description: description,
          note: note
      };

      setTransactions([newTx, ...transactions]);

      // Reset form
      setAmountStr('');
      setDescription('');
      setNote('');
  };

  const handleExportExcel = () => {
    const headers = ["ID", "Ngày", "Loại", "Số tiền", "Nội dung", "Ghi chú"];
    const rows = transactions.map(t => [
      t.id,
      t.date,
      t.type === 'INCOME' ? 'THU' : 'CHI',
      t.amount,
      `"${t.description}"`, 
      `"${t.note || ''}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "so_quy_giao_ly.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 h-screen overflow-y-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Thủ Quỹ & Tài Chính</h2>
        <button 
          onClick={handleExportExcel}
          className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg shadow hover:bg-green-700 transition-colors"
        >
          <FileSpreadsheet size={18} /> Xuất Excel
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Wallet className="absolute right-4 top-4 opacity-20 w-24 h-24" />
          <p className="text-blue-100 mb-1">Tổng quỹ hiện tại</p>
          <h3 className="text-3xl font-bold">{formatCurrency(balance)}</h3>
          <p className="text-xs text-blue-200 mt-4 opacity-80">Cập nhật lần cuối: Hôm nay</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-green-100 rounded-lg text-green-600">
               <TrendingUp size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Thu (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalIncome)}</h3>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 rounded-lg text-red-600">
               <TrendingDown size={20} />
            </div>
            <p className="text-slate-500 font-medium">Tổng Chi (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-bold text-slate-800">{formatCurrency(totalExpense)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-8">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-80 flex flex-col">
              <div className="flex items-center gap-2 mb-2">
                <PieChartIcon className="text-slate-400" size={20} />
                <h3 className="font-bold text-lg text-slate-800">Biểu Đồ Thu Chi</h3>
              </div>
              <div className="flex-1 w-full h-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={data}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {data.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => formatCurrency(value as number)} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h3 className="font-bold text-lg mb-4 text-slate-800">Tạo Giao Dịch Mới</h3>
            <div className="space-y-4">
                <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
                <button 
                    onClick={() => setType('INCOME')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'INCOME' ? 'bg-white text-green-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Plus size={16}/> Thu
                </button>
                <button 
                    onClick={() => setType('EXPENSE')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-medium flex justify-center gap-2 items-center transition-all ${type === 'EXPENSE' ? 'bg-white text-red-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Minus size={16}/> Chi
                </button>
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Số tiền (VNĐ)</label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-mono font-bold text-blue-700" 
                    placeholder="0" 
                    value={amountStr}
                    onChange={handleAmountChange}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nội dung <span className="text-red-500">*</span></label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="VD: Thu tiền sách..." 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
                <textarea 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24" 
                    placeholder="..." 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                ></textarea>
                </div>

                <button 
                    onClick={handleAddTransaction}
                    className="w-full py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-lg shadow-blue-200"
                >
                Lưu Giao Dịch
                </button>
            </div>
            </div>
        </div>

        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
          <div className="p-4 border-b border-slate-200 flex justify-between items-center">
            <h3 className="font-bold text-lg text-slate-800">Lịch Sử Giao Dịch</h3>
          </div>
          <div className="overflow-x-auto max-h-[800px] custom-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-white shadow-sm border-b border-slate-200">
                <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider">
                  <th className="px-3 py-2">Ngày</th>
                  <th className="px-3 py-2">Nội dung</th>
                  <th className="px-3 py-2 text-right">Số tiền</th>
                  <th className="px-3 py-2 text-center">Loại</th>
                </tr>
              </thead>
              <tbody className="">
                {transactions.map((t) => (
                  <tr key={t.id} className="hover:bg-slate-50 border-b border-slate-200 text-sm">
                    <td className="px-3 py-2 text-slate-500 text-sm">{t.date}</td>
                    <td className="px-3 py-2">
                      <div className="font-medium text-slate-800">{t.description}</div>
                      <div className="text-xs text-slate-400">{t.note}</div>
                    </td>
                    <td className="px-3 py-2 text-right font-mono font-bold text-slate-700">
                      {formatCurrency(t.amount)}
                    </td>
                    <td className="px-3 py-2 text-center">
                       {t.type === 'INCOME' ? (
                         <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-xs font-bold">THU</span>
                       ) : (
                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">CHI</span>
                       )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, X, Calendar, Printer, FileSpreadsheet, AlertTriangle, Save, User, MapPin, Phone, Users, CheckCircle2, History, GitMerge, AlertCircle, ScrollText, GraduationCap } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else if (selectedGrade !== 'all') {
            validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
        } else {
            validClassIds = classesInYear.map(c => c.id);
        }

        const matchClass = validClassIds.includes(student.classId);
        return matchSearch && matchClass;
    });

    // Sort by First Name (Vietnamese locale)
    return list.sort((a, b) => {
        const nameA = a.fullName.split(' ').pop() || '';
        const nameB = b.fullName.split(' ').pop() || '';
        return nameA.localeCompare(nameB, 'vi');
    });
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const getStatusBadge = (status: Student['status']) => {
      switch (status) {
          case 'ACTIVE': return <span className="px-2 py-1 rounded text-xs font-bold bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
          case 'TRANSFERRED': return <span className="px-2 py-1 rounded text-xs font-bold bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
          case 'DROPPED': return <span className="px-2 py-1 rounded text-xs font-bold bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
          default: return null;
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.length > 0 ? parts[parts.length - 1] : '';
      const lastName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
      return { firstName, lastName };
  };

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const generateNextId = (yearId: string) => {
      const prefix = yearId.slice(2, 4); 
      const yearStudents = students.filter(s => s.id.startsWith(prefix));
      let nextNum = 1;
      if (yearStudents.length > 0) {
          const nums = yearStudents
            .map(s => parseInt(s.id.slice(2)))
            .filter(n => !isNaN(n));
          if (nums.length > 0) nextNum = Math.max(...nums) + 1;
      }
      return `${prefix}${nextNum.toString().padStart(4, '0')}`;
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) {
        alert("Vui lòng nhập đầy đủ Tên Thánh, Họ Tên và Ngày sinh.");
        return;
    }

    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? {
            ...s,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            status: inputStatus
        } : s));
        showToast("Đã cập nhật thông tin học viên thành công!");
    } else {
        const newId = generateNextId(selectedYear);
        const newStudent: Student = {
            id: newId,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''),
            status: inputStatus,
            birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: ''
        };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên mới thành công! Mã số: ${newId}`);
    }
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) duplicates.push({ key, students: groups[key] });
      });
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  const getStudentHistory = (studentId: string) => {
    const studentRecords = records.filter(r => r.studentId === studentId);
    const history = [];
    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';
        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }
    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-3xl font-bold text-slate-800">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-4 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={18} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm font-medium">
                <Printer size={18} /> In DS
            </button>
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm font-medium">
                <FileSpreadsheet size={18} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-md font-bold text-sm"><Plus size={20} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-3 items-center">
            <select className="px-4 py-2.5 rounded-lg border border-slate-300 text-base font-medium min-w-[140px]" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2.5 rounded-lg border border-slate-300 text-base font-medium min-w-[140px]" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2.5 rounded-lg border border-slate-300 text-base font-medium min-w-[180px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-11 pr-4 py-2.5 rounded-lg border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-base" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse text-sm">
            <thead className="bg-slate-50 text-slate-700 font-bold sticky top-0 z-10 shadow-sm border-b border-slate-300 text-base">
              <tr>
                <th className="px-4 py-3 w-14 text-center">#</th>
                <th className="px-4 py-3 w-32">Tên Thánh</th>
                <th className="px-4 py-3 min-w-[180px]">Họ và Tên Đệm</th>
                <th className="px-4 py-3 w-28">Tên</th>
                <th className="px-4 py-3 w-32">Ngày Sinh</th>
                <th className="px-4 py-3 w-32">SĐT</th>
                <th className="px-4 py-3 w-36">Lớp</th>
                <th className="px-4 py-3 w-32 text-center">Tình Trạng</th>
                <th className="px-4 py-3 text-center w-28">Thao tác</th>
              </tr>
            </thead>
            <tbody className="text-base text-slate-700">
              {filteredStudents.map((s, index) => {
                const { firstName, lastName } = splitName(s.fullName);
                return (
                <tr key={s.id} className="hover:bg-slate-50 transition-colors border-b border-slate-200">
                  <td className="px-4 py-3 text-center text-slate-500">{index + 1}</td>
                  <td className="px-4 py-3 font-bold text-slate-700">{s.saintName}</td>
                  <td className="px-4 py-3 text-slate-800">{lastName}</td>
                  <td className="px-4 py-3 font-bold text-slate-800">{firstName}</td>
                  <td className="px-4 py-3">
                    <div className="text-slate-700">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                    <div className="text-xs text-slate-400 font-mono tracking-tighter">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</div>
                  </td>
                  <td className="px-4 py-3 text-slate-700 text-sm font-medium">{s.fatherPhone || s.motherPhone || ''}</td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-sm font-bold whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    {getStatusBadge(s.status)}
                  </td>
                  <td className="px-4 py-3 text-center">
                     <div className="flex justify-center gap-1">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={18} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="Xóa"><Trash2 size={18} /></button>
                     </div>
                  </td>
                </tr>
              )})}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={9} className="p-10 text-center text-slate-400 italic text-lg">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-4 border-t border-slate-200 bg-slate-50 text-sm text-slate-500 text-right font-medium">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {/* Modals */}
      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-[90rem] h-[90vh] flex flex-col animate-fade-in overflow-hidden">

            <div className="px-8 py-5 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-4">
                 <div className="w-12 h-12 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-xl shadow">
                    {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus />}
                 </div>
                 <div>
                    <h3 className="font-bold text-xl text-slate-800">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-sm text-slate-500 font-mono">{selectedStudent.id}</p>}
                 </div>
              </div>
              <div className="flex gap-3">
                <button onClick={closeModal} className="px-6 py-2.5 text-slate-600 hover:bg-slate-200 rounded-lg font-bold text-base transition-colors">Đóng</button>
                <button onClick={handleSaveStudent} className="px-6 py-2.5 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md flex items-center gap-2 text-base">
                   <Save size={20} /> Lưu Hồ Sơ
                </button>
              </div>
            </div>

            {realtimeDuplicates.length > 0 && (
                <div className="bg-red-50 border-b border-red-100 p-4 flex items-start gap-3 animate-pulse">
                    <AlertTriangle className="text-red-600 mt-0.5" />
                    <div>
                        <h4 className="font-bold text-red-800 text-base">Cảnh báo: Dữ liệu có thể bị trùng lặp!</h4>
                        <p className="text-sm text-red-600 mb-1">Hệ thống phát hiện học viên sau có cùng Tên và Ngày sinh:</p>
                        <ul className="text-sm text-red-700 list-disc list-inside">
                            {realtimeDuplicates.map(d => (
                                <li key={d.id}>{d.saintName} <b>{d.fullName}</b> ({d.id}) - Lớp: {getClassName(d.classId)}</li>
                            ))}
                        </ul>
                    </div>
                </div>
            )}

            <div className="flex border-b border-slate-200 bg-white">
                <button onClick={() => setModalTab('PROFILE')} className={`px-8 py-4 text-base font-bold border-b-2 transition-all ${modalTab === 'PROFILE' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Hồ sơ cá nhân</button>
                <button onClick={() => setModalTab('HISTORY')} className={`px-8 py-4 text-base font-bold border-b-2 transition-all ${modalTab === 'HISTORY' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Lịch sử & Điểm số</button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 bg-slate-50/50">
                {modalTab === 'PROFILE' && (
                    <div className="space-y-8 max-w-6xl mx-auto animate-fade-in">

                        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                            <h4 className="flex items-center gap-2 font-bold text-lg text-slate-700 mb-6 pb-3 border-b"><User size={22} className="text-blue-500"/> Thông Tin Cá Nhân</h4>
                            <div className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                                    <div className="md:col-span-2">
                                        <label className="label-text">Mã học viên</label>
                                        <input className="input-field bg-slate-100 text-slate-600 font-mono font-bold" disabled value={selectedStudent?.id || 'AUTO'} />
                                    </div>
                                    <div className="md:col-span-3">
                                        <label className="label-text">Tình trạng</label>
                                        <select 
                                            className="input-field font-bold text-blue-700" 
                                            value={inputStatus} 
                                            onChange={(e) => setInputStatus(e.target.value as any)}
                                        >
                                            <option value="ACTIVE">Đang học</option>
                                            <option value="TRANSFERRED">Chuyển xứ</option>
                                            <option value="DROPPED">Nghỉ học</option>
                                        </select>
                                    </div>
                                    <div className="md:col-span-3 relative">
                                        <label className="label-text">Tên Thánh</label>
                                        <input 
                                          className="input-field" 
                                          value={saintInput} 
                                          onChange={(e) => {
                                              setSaintInput(e.target.value);
                                              setShowSaintSuggestions(true);
                                          }}
                                          onFocus={() => setShowSaintSuggestions(true)}
                                          onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)}
                                          placeholder="Giuse..." 
                                        />
                                        {showSaintSuggestions && (
                                           <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-md shadow-lg max-h-40 overflow-y-auto mt-1">
                                             {filteredSaints.length > 0 ? (
