        <div className="bg-amber-200 p-2 rounded-full"><Info size={24} className="text-amber-700" /></div>
        <div className="flex flex-col">
            <span className="font-bold">ĐỒNG BỘ CHUYÊN CẦN:</span>
            <span>Số buổi <b>Vắng P (Có phép)</b> và <b>Vắng K (Không phép)</b> được đồng bộ tự động khi bạn nhấn "Lưu Điểm Danh" ở tab Chuyên Cần.</span>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse border-separate border-spacing-0">
                    <thead>
                        <tr className="bg-slate-100 text-slate-800 text-sm">
                            <th rowSpan={2} className="px-3 py-2 w-14 text-center sticky left-0 bg-slate-100 z-20 border-b border-r border-slate-400 font-bold text-sm">STT</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[140px] sticky left-14 bg-slate-100 z-20 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold text-sm">Tên Thánh</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[160px] sticky left-[196px] bg-slate-100 z-20 border-b border-r border-slate-400 font-bold text-sm">Họ và Tên Đệm</th>
                            <th rowSpan={2} className="px-3 py-2 min-w-[100px] sticky left-[356px] bg-slate-100 z-20 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold text-sm">Tên</th>
                            <th colSpan={hk1Columns.length + 2 + 1} className="p-2 text-center bg-blue-100/50 border-b border-r border-blue-400 font-extrabold text-blue-800 tracking-wider text-xs">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 2 + 1} className="p-2 text-center bg-purple-100/50 border-b border-r border-purple-400 font-extrabold text-purple-800 tracking-wider text-xs">HỌC KỲ 2</th>
