                            <th rowSpan={2} className="px-3 py-2 w-24 text-center border-b border-slate-400 font-bold bg-slate-200 text-slate-800 text-sm">Xếp Loại</th>
                            <th rowSpan={2} className="px-3 py-2 w-14 text-center border-b border-slate-400 font-bold bg-yellow-50 text-yellow-800 text-sm">Hạng</th>
                        </tr>
                        <tr className="bg-slate-50 text-slate-600 text-xs">
                             {hk1Columns.map((col) => (
                                <th key={col.id} className="px-2 py-1 w-20 text-center border-b border-r border-slate-400 bg-blue-50/30">
                                    <span className="font-bold">{col.name}</span>
                                </th>
                             ))}
                             <th className="px-2 py-1 w-10 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700">P</th>
                             <th className="px-2 py-1 w-10 text-center border-b border-r border-red-300 bg-red-50 text-red-700">K</th>
                             <th className="px-2 py-1 w-16 text-center border-b border-r border-blue-400 font-bold bg-blue-100 text-blue-800">TB 1</th>

                             {hk2Columns.map((col) => (
                                <th key={col.id} className="px-2 py-1 w-20 text-center border-b border-r border-slate-400 bg-purple-50/30">
                                    <span className="font-bold">{col.name}</span>
                                </th>
                             ))}
                             <th className="px-2 py-1 w-10 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700">P</th>
                             <th className="px-2 py-1 w-10 text-center border-b border-r border-red-300 bg-red-50 text-red-700">K</th>
                             <th className="px-2 py-1 w-16 text-center border-b border-r border-purple-400 font-bold bg-purple-100 text-purple-800">TB 2</th>
