                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');
                                const { firstName, lastName } = splitName(s.fullName);

                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-300 text-base">
                                    <td className="px-3 py-2 text-center sticky left-0 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 font-medium text-slate-500 text-sm">{idx + 1}</td>
                                    <td className="px-3 py-2 font-bold sticky left-14 bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 text-slate-800 text-sm truncate">{s.saintName}</td>
                                    <td className="px-3 py-2 sticky left-[196px] bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 text-slate-800 text-sm truncate">{lastName}</td>
                                    <td className="px-3 py-2 font-bold sticky left-[356px] bg-white group-hover:bg-blue-50/30 z-10 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] text-slate-800 text-sm truncate">{firstName}</td>

                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-0 border-r border-slate-300 text-center">
                                            <input 
                                                type="number" 
                                                value={r1.scores ? (r1.scores[col.id] ?? '') : ''} 
                                                onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} 
                                                className="w-full text-center py-2 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm" 
                                                placeholder="0.0"
                                            />
                                        </td>
