                        <Save size={22} /> Lưu Bảng Điểm
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 bg-slate-50">
              <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm mb-8">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-2xl font-bold text-slate-800 uppercase mb-2">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-600 flex items-center gap-2 text-lg"><UserCheck size={22} />GLV Phụ Trách: <span className="font-semibold text-slate-800">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div>
                  </div>
                  <div className="text-right">
                    <div className="text-base text-slate-500">Sĩ số</div>
                    <div className="text-3xl font-bold text-slate-800">{filteredStudents.length} em</div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white rounded-xl border border-green-200 shadow-sm overflow-hidden">
                  <div className="p-5 bg-green-50 border-b border-green-100 flex justify-between items-center">
                    <div className="flex items-center gap-3"><CheckCircle2 className="text-green-600 w-6 h-6" /><h4 className="font-bold text-xl text-green-800">Danh Sách Lên Lớp</h4></div>
                    <span className="px-4 py-1.5 bg-white text-green-700 rounded-full text-sm font-bold border border-green-200">{passedStudents.length} em</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-base">
                      <thead className="bg-slate-50 text-slate-500">
