              <span className="font-bold text-lg">{toast}</span>
           </div>
        </div>
      )}

      {/* Header Tabs */}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1.5 rounded-xl border border-slate-300 shadow-inner">
           <button onClick={() => setViewMode('config')} className={`px-6 py-2.5 rounded-lg text-base font-bold flex items-center gap-2 transition-all ${viewMode === 'config' ? 'bg-white shadow text-rose-600' : 'text-slate-600 hover:text-slate-800'}`}><SettingsIcon size={20}/> Cấu hình hệ số</button>
           <button onClick={() => setViewMode('entry')} className={`px-6 py-2.5 rounded-lg text-base font-bold flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={20}/> Nhập điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-6 py-2.5 rounded-lg text-base font-bold flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-emerald-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={20}/> Thống kê</button>
        </div>
      </div>

      {/* Cấu hình giống ảnh mẫu */}
      {viewMode === 'config' ? (
        <div className="bg-white rounded-xl shadow-lg border border-slate-300 overflow-hidden animate-fade-in max-w-5xl mx-auto w-full">
            {/* Top Bar Cấu hình */}
            <div className="p-6 bg-slate-50 border-b border-slate-200 grid grid-cols-2 gap-8">
                <div className="flex items-center gap-4">
                    <span className="font-bold text-slate-700 flex items-center gap-2"><div className="w-5 h-5 bg-slate-800 rounded flex items-center justify-center text-[10px] text-white">📅</div> Học Kỳ</span>
                    <select 
                        className="flex-1 p-3 border border-slate-300 rounded-lg bg-white text-lg font-bold text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
                        value={selectedTerm}
                        onChange={(e) => setSelectedTerm(e.target.value as any)}
                    >
                        <option value="HK1">Học kỳ I</option>
                        <option value="HK2">Học kỳ II</option>
                    </select>
                </div>
                <div className="flex items-center gap-4">
                    <span className="font-bold text-slate-700 flex items-center gap-2"><div className="w-5 h-5 bg-slate-800 rounded flex items-center justify-center text-[10px] text-white">🎓</div> Khối/Ngành</span>
                    <div className="flex-1 p-3 border border-slate-300 rounded-lg bg-slate-100 text-lg font-bold text-slate-600">
                        {currentGradeName}
                    </div>
                </div>
            </div>

            {/* Table Cấu hình */}
            <table className="w-full border-collapse">
                <thead className="bg-slate-100 text-slate-800 text-base border-b border-slate-300">
                    <tr>
                        <th className="p-4 text-center font-bold text-rose-700 border-r border-slate-300 w-1/3">Cột điểm</th>
                        <th className="p-4 text-center font-bold border-r border-slate-300 w-1/3">Số cột điểm</th>
                        <th className="p-4 text-center font-bold w-1/3">Hệ số tính</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200">
                    {scoreConfigs.map((row) => (
                        <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                            <td className="p-3 border-r border-slate-200">
                                <input 
                                    type="text" 
                                    className="w-full p-2.5 border border-slate-200 rounded text-center text-lg focus:ring-2 focus:ring-blue-300 outline-none"
                                    value={row.label}
                                    onChange={(e) => updateConfig(row.id, 'label', e.target.value)}
                                />
                            </td>
                            <td className="p-3 border-r border-slate-200">
                                <input 
                                    type="number" 
                                    className="w-full p-2.5 border border-slate-200 rounded text-center text-lg font-bold text-blue-700 focus:ring-2 focus:ring-blue-300 outline-none"
                                    value={row.count}
                                    onChange={(e) => updateConfig(row.id, 'count', parseInt(e.target.value) || 0)}
                                />
                            </td>
                            <td className="p-3">
                                <input 
                                    type="number" 
                                    className="w-full p-2.5 border border-slate-200 rounded text-center text-lg font-bold text-emerald-700 focus:ring-2 focus:ring-blue-300 outline-none"
                                    value={row.weight}
                                    onChange={(e) => updateConfig(row.id, 'weight', parseInt(e.target.value) || 0)}
                                />
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
            <div className="p-6 bg-slate-50 border-t border-slate-200 flex justify-end gap-4">
                 <button onClick={() => setViewMode('entry')} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-bold text-lg shadow-lg hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-2">
                    <Save size={22}/> Lưu cấu hình & Vào sổ điểm
                 </button>
            </div>
        </div>
      ) : (
        <>
            {/* Bộ lọc cho Nhập điểm / Thống kê */}
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-wrap gap-4 items-center">
                <div className="flex items-center gap-3">
                    <span className="font-bold text-slate-500 text-sm uppercase">Niên khóa:</span>
                    <select className="p-2.5 border rounded-lg text-base font-bold outline-none focus:ring-2 focus:ring-blue-400" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                        {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                    </select>
                </div>
                <div className="flex items-center gap-3">
                    <span className="font-bold text-slate-500 text-sm uppercase">Lớp:</span>
                    <select className="p-2.5 border rounded-lg text-base font-bold text-blue-700 outline-none focus:ring-2 focus:ring-blue-400 min-w-[200px]" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
                        {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                </div>
                <div className="flex items-center gap-3 ml-auto">
                    <button className="px-5 py-2.5 bg-green-600 text-white rounded-xl font-bold text-base shadow hover:bg-green-700 flex items-center gap-2">
                        <Download size={20}/> Xuất Excel
                    </button>
                </div>
            </div>

            {viewMode === 'entry' ? (
                <div className="bg-white rounded-2xl shadow-lg border border-slate-300 flex-1 overflow-hidden flex flex-col">
                    <div className="overflow-x-auto custom-scrollbar flex-1">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-slate-100 text-slate-700 text-base border-b-2 border-slate-300">
                                    <th className="px-4 py-4 w-16 text-center font-bold sticky left-0 bg-slate-100 z-20">#</th>
                                    <th className="px-4 py-4 min-w-[250px] font-bold sticky left-16 bg-slate-100 z-20 shadow-[2px_0_5px_rgba(0,0,0,0.05)] border-r border-slate-200 text-lg">Học Viên</th>
                                    {activeColumns.map(col => (
                                        <th key={col.id} className="px-4 py-4 text-center font-bold border-r border-slate-200 text-rose-700 bg-rose-50/30">
                                            {col.label} <span className="text-[10px] text-slate-400 block font-normal">(x{col.weight})</span>
                                        </th>
                                    ))}
                                    <th className="px-4 py-4 text-center font-bold text-blue-800 bg-blue-50/50 min-w-[100px] text-lg">ĐTB {selectedTerm}</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredStudents.map((s, idx) => {
                                    const r = getRecord(s.id);
                                    return (
                                        <tr key={s.id} className="hover:bg-blue-50/30 border-b border-slate-100 transition-colors">
                                            <td className="px-4 py-3 text-center text-slate-400 font-bold sticky left-0 bg-white z-10">{idx + 1}</td>
                                            <td className="px-4 py-3 sticky left-16 bg-white z-10 border-r border-slate-100">
