                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const mStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const cStatus = attendanceData[`${s.id}-${dateStr}-class`];
