        <select className="px-3 py-2 border rounded-lg text-sm min-w-[180px] font-bold text-slate-700" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
