import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Save, Table, ListChecks, Download, Settings as SettingsIcon, Info } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface ScoreConfigRow {
    id: string;
    label: string;
    count: number;
    weight: number;
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedTerm, setSelectedTerm] = useState<'HK1' | 'HK2'>('HK1');
  const [viewMode, setViewMode] = useState<'entry' | 'config' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  // Cấu hình cột điểm theo ảnh mẫu
  const [scoreConfigs, setScoreConfigs] = useState<ScoreConfigRow[]>([
    { id: '1', label: 'Đầu giờ', count: 1, weight: 1 },
    { id: '2', label: '15 phút', count: 1, weight: 1 },
    { id: '3', label: '45 phút', count: 0, weight: 1 },
    { id: '4', label: 'Khảo kinh', count: 0, weight: 1 },
    { id: '5', label: 'Thi', count: 0, weight: 1 },
    { id: '6', label: 'BÀI THI 1', count: 0, weight: 1 },
    { id: '7', label: 'BÀI THI 2', count: 0, weight: 1 },
  ]);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const currentClass = classes.find(c => c.id === selectedClass);
  const currentGradeName = grades.find(g => g.id === currentClass?.gradeId)?.name || 'Chưa chọn';

  const availableClasses = useMemo(() => {
    const list = classes.filter(c => c.yearId === selectedYear);
    if (selectedGrade === 'all') return list;
    return list.filter(c => c.gradeId === selectedGrade);
  }, [classes, selectedYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      }
  }, [availableClasses]);

  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');

  const getRecord = (studentId: string) => {
    return records.find(r => r.studentId === studentId && r.term === selectedTerm) || {
      studentId, term: selectedTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, field: string, value: string) => {
    const numValue = value === '' ? 0 : parseFloat(value);
    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === selectedTerm);
        const newRecords = [...prev];
        if (existingIndex > -1) {
            newRecords[existingIndex] = { 
                ...newRecords[existingIndex], 
                scores: { ...newRecords[existingIndex].scores, [field]: numValue } 
            };
        } else {
            newRecords.push({
                studentId, term: selectedTerm, scores: { [field]: numValue }, 
                scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
            });
        }
        return newRecords;
    });
  };

  const updateConfig = (id: string, field: keyof ScoreConfigRow, value: any) => {
      setScoreConfigs(prev => prev.map(row => row.id === id ? { ...row, [field]: value } : row));
  };

  const activeColumns = scoreConfigs.filter(c => c.count > 0);

  return (
    <div className="p-6 h-screen flex flex-col bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-fade-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
