import React, { useState, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Calendar, Layers, Save, Plus, Trash2, Cross, CheckCircle, CheckCircle2, GripVertical, Clock, AlertCircle } from 'lucide-react';
import { Saint, SchoolYear, ClassRoom, Grade, TermConfig } from '../types';

interface SettingsProps {
    years: SchoolYear[];
    // Use React.Dispatch<React.SetStateAction<T>> to support functional updates (prev => ...)
    setYears: React.Dispatch<React.SetStateAction<SchoolYear[]>>;
    classes: ClassRoom[];
    setClasses: React.Dispatch<React.SetStateAction<ClassRoom[]>>;
    grades: Grade[];
    setGrades: React.Dispatch<React.SetStateAction<Grade[]>>;
    termConfigs: TermConfig[];
    setTermConfigs: React.Dispatch<React.SetStateAction<TermConfig[]>>;
}

export const Settings: React.FC<SettingsProps> = ({ years, setYears, classes, setClasses, grades, setGrades, termConfigs, setTermConfigs }) => {
  const [saints, setSaints] = useState<Saint[]>(MOCK_SAINTS);
  const [newSaintName, setNewSaintName] = useState('');
  const [newSaintGender, setNewSaintGender] = useState<'Male'|'Female'>('Male');
  const [toast, setToast] = useState<string | null>(null);

  // Drag states
  const [draggedGradeId, setDraggedGradeId] = useState<string | null>(null);
  const [dragOverGradeId, setDragOverGradeId] = useState<string | null>(null);

  const [draggedClassId, setDraggedClassId] = useState<string | null>(null);
  const [dragOverClassId, setDragOverClassId] = useState<string | null>(null);

  const [activeYearForTerms, setActiveYearForTerms] = useState('');

  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) setActiveYearForTerms(active.id);
    else if (years.length > 0) setActiveYearForTerms(years[0].id);
  }, [years]);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [newYearName, setNewYearName] = useState('');
  const [newClassName, setNewClassName] = useState('');
  const [newClassGrade, setNewClassGrade] = useState(grades[0]?.id || '');

  const activeYear = years.find(y => y.isActive);
  const classesInActiveYear = classes.filter(c => c.yearId === activeYear?.id);

  // --- TERM CONFIG LOGIC ---
  const hk1Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK1');
  const hk2Config = termConfigs.find(c => c.yearId === activeYearForTerms && c.term === 'HK2');

  const updateTermDate = (term: 'HK1' | 'HK2', field: 'startDate' | 'endDate', value: string) => {
      // Fix: Now setTermConfigs accepts a functional update because of the updated prop type
      setTermConfigs(prev => {
          const existingIdx = prev.findIndex(c => c.yearId === activeYearForTerms && c.term === term);
          if (existingIdx > -1) {
              const newConfigs = [...prev];
              newConfigs[existingIdx] = { ...newConfigs[existingIdx], [field]: value };
              return newConfigs;
          } else {
              const newConfig: TermConfig = {
                  id: `term_${Date.now()}`,
                  yearId: activeYearForTerms,
                  term: term,
                  startDate: field === 'startDate' ? value : '',
                  endDate: field === 'endDate' ? value : ''
              };
              return [...prev, newConfig];
          }
      });
  };

  const handleSaveTerms = () => {
      showToast("Đã cập nhật mốc thời gian học kỳ thành công!");
  };

  // --- GRADE SORTING LOGIC ---
  const handleGradeDragStart = (e: React.DragEvent, id: string) => {
    setDraggedGradeId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleGradeDragEnter = (id: string) => {
    if (draggedGradeId && draggedGradeId !== id) {
        setDragOverGradeId(id);
    }
  };

  const handleGradeDrop = (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    setDragOverGradeId(null);
    if (!draggedGradeId || draggedGradeId === targetId) return;

    const sourceIndex = grades.findIndex(g => g.id === draggedGradeId);
    const targetIndex = grades.findIndex(g => g.id === targetId);

    const newGrades = [...grades];
    const [removed] = newGrades.splice(sourceIndex, 1);
    newGrades.splice(targetIndex, 0, removed);

    setGrades(newGrades);
    setDraggedGradeId(null);
    showToast("Cập nhật thứ tự Khối lớp thành công!");
  };

  // --- CLASS SORTING LOGIC ---
  const handleClassDragStart = (e: React.DragEvent, id: string) => {
    setDraggedClassId(id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleClassDragEnter = (id: string) => {
    if (draggedClassId && draggedClassId !== id) {
        setDragOverClassId(id);
