        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Trash2, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, GripVertical, AlertCircle, Info } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);

  const [draggedColId, setDraggedColId] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  const [showAddColumn, setShowAddColumn] = useState(false);
  const [newColName, setNewColName] = useState('');
  const [newColWeight, setNewColWeight] = useState(1);
  const [newColTerm, setNewColTerm] = useState<'HK1' | 'HK2'>('HK1');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  // Only show ACTIVE students in grades list
  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);
    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        const newRecords = [...prev];
        if (existingIndex > -1) {
            newRecords[existingIndex] = { ...prev[existingIndex], scores: { ...prev[existingIndex].scores, [field]: numValue } };
            return newRecords;
        } else {
             const updatedRecord = { studentId, term: term, scores: { [field]: numValue }, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 };
             return [...newRecords, updatedRecord];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      const termColumns = testColumns.filter(c => c.term === record.term);
      termColumns.forEach(col => {
          if (col.weight > 0) {
              const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
              totalScore += score * col.weight;
              totalWeight += col.weight;
          }
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = [...records];
     filteredStudents.forEach(s => {
        ['HK1', 'HK2'].forEach(term => {
             const t = term as 'HK1' | 'HK2';
             const idx = updatedRecords.findIndex(r => r.studentId === s.id && r.term === t);
             if (idx > -1) {
                 updatedRecords[idx] = { ...updatedRecords[idx], average: calculateAvg(updatedRecords[idx]) };
             }
        });
     });
     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm và tính trung bình cho lớp ${currentClass?.name} thành công!`);
  };

  const getRank = (avg: number) => {
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const addColumn = () => {
    if (newColName) {
      const newId = `col_${Date.now()}`;
      setTestColumns([...testColumns, { id: newId, name: newColName, weight: newColWeight, term: newColTerm }]);
      setNewColName('');
      setShowAddColumn(false);
      showToast(`Đã thêm cột điểm "${newColName}" vào ${newColTerm} thành công!`);
    }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.length > 0 ? parts[parts.length - 1] : '';
      const lastName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
      return { firstName, lastName };
  };

  const processedStudentsYear = useMemo(() => {
    let list = filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;
      return { 
        ...s, 
        avg1, 
        avg2, 
        avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
        nameForSort: s.fullName.split(' ').pop() || ''
      };
    });
    const sortedByScore = [...list].sort((a, b) => b.avgYear - a.avgYear);
    const rankedMap = new Map();
    sortedByScore.forEach((s, index) => { rankedMap.set(s.id, index + 1); });
    return list.map(s => ({ ...s, ranking: rankedMap.get(s.id) })).sort((a, b) => a.nameForSort.localeCompare(b.nameForSort, 'vi'));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  return (
    <div className="p-6 h-screen flex flex-col relative bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1.5 rounded-lg border border-slate-300 shadow-sm">
           <button onClick={() => setViewMode('entry')} className={`px-5 py-2.5 rounded-md text-base font-bold flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={20}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-5 py-2.5 rounded-md text-base font-bold flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={20}/> Thống Kê</button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-300 mb-6 flex justify-between items-center flex-wrap gap-4">
        <div className="flex gap-4 items-center flex-wrap">
          <select className="px-4 py-2.5 border border-slate-300 rounded-lg min-w-[150px] text-lg font-bold bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-4 py-2.5 border border-slate-300 rounded-lg min-w-[180px] text-lg font-bold bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-4 py-2.5 border border-slate-300 rounded-lg min-w-[220px] text-lg font-bold bg-slate-50 text-blue-800 outline-none focus:ring-2 focus:ring-blue-500" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-3">
            {viewMode === 'entry' && (
                <button onClick={() => setShowAddColumn(true)} className="flex items-center gap-2 px-6 py-2.5 bg-blue-50 text-blue-600 border border-blue-200 rounded-xl hover:bg-blue-100 text-sm font-black uppercase transition-all shadow-sm"><Plus size={20} /> Thêm Cột</button>
            )}
             <button className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white border border-green-700 rounded-xl text-sm hover:bg-green-700 font-black uppercase shadow-md transition-all"><Download size={20}/> Xuất Excel</button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar flex-1">
                <table className="w-full text-left border-collapse border-separate border-spacing-0 table-auto">
                    <thead>
                        <tr className="bg-slate-100 text-slate-700 font-black sticky top-0 z-40 shadow-sm border-b-2 border-slate-300 uppercase tracking-tighter">
                            <th rowSpan={2} className="px-3 py-4 w-12 text-center sticky left-0 bg-slate-100 z-50 border-b border-r border-slate-300 text-xs">#</th>
                            <th rowSpan={2} className="px-3 py-4 w-28 sticky left-12 bg-slate-100 z-50 border-b border-r border-slate-300 text-sm">Mã HV</th>
                            <th rowSpan={2} className="px-3 py-4 w-32 sticky left-[160px] bg-slate-100 z-50 border-b border-r border-slate-300 text-sm">Tên Thánh</th>
                            <th rowSpan={2} className="px-3 py-4 w-44 sticky left-[288px] bg-slate-100 z-50 border-b border-r border-slate-300 text-sm">Họ & Tên Đệm</th>
                            <th rowSpan={2} className="px-3 py-4 w-32 sticky left-[464px] bg-slate-100 z-50 border-b border-r border-slate-300 shadow-[2px_0_5px_rgba(0,0,0,0.1)] text-sm">Tên</th>
                            <th colSpan={hk1Columns.length + 3} className="p-3 text-center bg-blue-100/50 border-b border-r border-blue-400 font-black text-blue-800 tracking-wider text-xs">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 3} className="p-3 text-center bg-purple-100/50 border-b border-r border-purple-400 font-black text-purple-800 tracking-wider text-xs">HỌC KỲ 2</th>
                            <th rowSpan={2} className="px-3 py-4 w-24 text-center border-b border-slate-400 font-black bg-slate-200 text-slate-800 text-sm">Cả Năm</th>
                            <th rowSpan={2} className="px-3 py-4 w-24 text-center border-b border-slate-400 font-black bg-slate-200 text-slate-800 text-sm">Xếp Loại</th>
                            <th rowSpan={2} className="px-3 py-4 w-14 text-center border-b border-slate-400 font-black bg-yellow-50 text-yellow-800 text-sm">Hạng</th>
                        </tr>
                        <tr className="bg-slate-50 text-slate-600 font-bold uppercase tracking-widest sticky top-[52px] z-40">
                             {hk1Columns.map((col) => (
                                <th key={col.id} className="px-2 py-2 w-20 text-center border-b border-r border-slate-300 bg-blue-50/30 text-[10px]">{col.name} <span className="text-[8px] opacity-50 block">(x{col.weight})</span></th>
                             ))}
                             <th className="px-2 py-2 w-10 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700 text-[9px]">P</th>
                             <th className="px-2 py-2 w-10 text-center border-b border-r border-red-300 bg-red-50 text-red-700 text-[9px]">K</th>
                             <th className="px-2 py-2 w-16 text-center border-b border-r border-blue-400 font-black bg-blue-100 text-blue-800 text-[10px]">TB 1</th>
                             {hk2Columns.map((col) => (
                                <th key={col.id} className="px-2 py-2 w-20 text-center border-b border-r border-slate-300 bg-purple-50/30 text-[10px]">{col.name} <span className="text-[8px] opacity-50 block">(x{col.weight})</span></th>
                             ))}
                             <th className="px-2 py-2 w-10 text-center border-b border-r border-amber-300 bg-amber-50 text-amber-700 text-[9px]">P</th>
                             <th className="px-2 py-2 w-10 text-center border-b border-r border-red-300 bg-red-50 text-red-700 text-[9px]">K</th>
                             <th className="px-2 py-2 w-16 text-center border-b border-r border-purple-400 font-black bg-purple-100 text-purple-800 text-[10px]">TB 2</th>
                        </tr>
                    </thead>
                    <tbody className="text-xl">
                        {processedStudentsYear.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');
                                const { firstName, lastName } = splitName(s.fullName);
                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-200">
                                    <td className="px-3 py-4 text-center sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 font-bold text-slate-400 text-sm">{idx + 1}</td>
                                    <td className="px-3 py-4 sticky left-12 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-100 font-mono font-bold text-slate-500 text-lg">{s.id}</td>
                                    <td className="px-3 py-4 font-bold sticky left-[160px] bg-white group-hover:bg-slate-50 z-20 border-r border-slate-100 text-slate-700 text-lg">{s.saintName}</td>
                                    <td className="px-3 py-4 sticky left-[288px] bg-white group-hover:bg-slate-50 z-20 border-r border-slate-100 text-slate-800 text-xl">{lastName}</td>
                                    <td className="px-3 py-4 font-bold sticky left-[464px] bg-white group-hover:bg-slate-50 z-20 border-r border-slate-200 shadow-[2px_0_5px_rgba(0,0,0,0.05)] text-slate-900 text-xl">{firstName}</td>
                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-0 border-r border-slate-200 text-center">
                                            <input type="number" value={r1.scores ? (r1.scores[col.id] ?? '') : ''} onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} className="w-full text-center py-4 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold text-lg" placeholder="-" />
                                        </td>
                                    ))}
                                    <td className="px-2 py-4 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/20 text-lg">{s.absentP1}</td>
                                    <td className="px-2 py-4 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/20 text-lg">{s.absentK1}</td>
                                    <td className="px-2 py-4 border-r border-blue-400 text-center font-black text-blue-700 bg-blue-50 text-lg">{(s.avg1 >= 0) ? s.avg1.toFixed(1) : '-'}</td>
                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-0 border-r border-slate-200 text-center">
                                            <input type="number" value={r2.scores ? (r2.scores[col.id] ?? '') : ''} onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} className="w-full text-center py-4 border-0 bg-transparent focus:bg-white focus:ring-2 focus:ring-purple-500 outline-none transition-all font-bold text-lg" placeholder="-" />
                                        </td>
                                    ))}
                                    <td className="px-2 py-4 border-r border-amber-300 text-center font-bold text-amber-600 bg-amber-50/20 text-lg">{s.absentP2}</td>
                                    <td className="px-2 py-4 border-r border-red-300 text-center font-bold text-red-600 bg-red-50/20 text-lg">{s.absentK2}</td>
                                    <td className="px-2 py-4 border-r border-purple-400 text-center font-black text-purple-700 bg-purple-50 text-lg">{(s.avg2 >= 0) ? s.avg2.toFixed(1) : '-'}</td>
                                    <td className="px-2 py-4 text-center font-black text-slate-900 bg-slate-100 border-r border-slate-300 text-xl">{s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}</td>
                                    <td className="px-2 py-4 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && <span className={`px-3 py-1.5 rounded-lg text-xs font-black uppercase tracking-tight shadow-sm ${s.rank.color}`}>{s.rank.label}</span>}
                                    </td>
                                    <td className="px-2 py-4 text-center font-black text-yellow-700 bg-yellow-50/50 text-xl">{s.ranking}</td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={40} className="p-20 text-center text-slate-400 italic bg-slate-50 text-xl">Vui lòng chọn lớp để xem bảng điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {processedStudentsYear.length > 0 && (
                <div className="p-6 border-t border-slate-300 bg-slate-100 text-right sticky bottom-0 z-20 shadow-inner">
                    <button onClick={handleSaveGrades} className="flex items-center gap-3 ml-auto px-12 py-4 bg-blue-600 text-white rounded-2xl shadow-xl hover:bg-blue-700 font-black uppercase tracking-widest transition-all transform hover:-translate-y-1 active:scale-95 text-lg">
                        <Save size={24} /> LƯU BẢNG ĐIỂM
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50">
              <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-xl mb-10">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-3xl font-black text-slate-800 uppercase mb-3 tracking-tight">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-600 flex items-center gap-3 text-xl font-bold"><UserCheck size={26} className="text-blue-600" />GLV Phụ Trách: <span className="text-slate-900">{currentClass?.mainTeacher || 'Chưa cập nhật'}</span></div>
                  </div>
                  <div className="text-right bg-blue-600 text-white p-6 rounded-2xl shadow-lg">
                    <div className="text-sm font-bold opacity-80 uppercase tracking-widest">Sĩ số</div>
                    <div className="text-4xl font-black">{filteredStudents.length} em</div>
