                        ))}
                      </tbody>
                  </table>
                </div>
                <div className="bg-white rounded-2xl border border-red-200 shadow-sm overflow-hidden flex flex-col h-fit">
                   <div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center">
                    <h4 className="font-bold text-lg text-red-800 uppercase">Chưa Đạt ({failedStudents.length})</h4>
                  </div>
                  <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-[9px]">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {failedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-red-50/50">
                            <td className="p-3 font-bold text-slate-800 text-xs">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-black text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-black text-slate-900">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${s.rank.color}`}>{s.rank.label}</span></td>
                          </tr>
                        ))}
                        {failedStudents.length === 0 && <tr><td colSpan={4} className="p-10 text-center text-slate-400 italic">Không có dữ liệu</td></tr>}
                      </tbody>
                  </table>
                </div>
              </div>
            </div>
        )}
      </div>

      {/* Score Configuration Modal */}
      {isConfigModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-scale-in">
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                <div className="flex items-center gap-2">
                    <Settings2 className="text-blue-600" />
                    <h3 className="text-xl font-bold text-slate-800">Cấu hình Cột điểm & Hệ số</h3>
                </div>
                <button onClick={() => setIsConfigModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-blue-200">
                            <h4 className="font-bold text-blue-700 uppercase tracking-wider text-sm">Học Kỳ 1</h4>
                            <button onClick={() => addConfigColumn('HK1')} className="text-[10px] flex items-center gap-1 font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded hover:bg-blue-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-3">
                            {hk1Columns.map(col => (
                                <div key={col.id} className="flex gap-2 items-center bg-blue-50/50 p-2 rounded-lg border border-blue-100">
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateConfigColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col">
                                        <span className="text-[8px] font-bold text-blue-400 uppercase">Hệ số</span>
                                        <select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateConfigColumn(col.id, 'weight', Number(e.target.value))}>
                                            <option value={1}>x1</option>
                                            <option value={2}>x2</option>
                                            <option value={3}>x3</option>
                                            <option value={4}>x4</option>
                                        </select>
                                    </div>
                                    <button onClick={() => removeConfigColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-purple-200">
                            <h4 className="font-bold text-purple-700 uppercase tracking-wider text-sm">Học Kỳ 2</h4>
                            <button onClick={() => addConfigColumn('HK2')} className="text-[10px] flex items-center gap-1 font-bold text-purple-600 bg-purple-50 px-2 py-1 rounded hover:bg-purple-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-3">
                            {hk2Columns.map(col => (
                                <div key={col.id} className="flex gap-2 items-center bg-purple-50/50 p-2 rounded-lg border border-purple-100">
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateConfigColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col">
                                        <span className="text-[8px] font-bold text-purple-400 uppercase">Hệ số</span>
                                        <select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateConfigColumn(col.id, 'weight', Number(e.target.value))}>
                                            <option value={1}>x1</option>
                                            <option value={2}>x2</option>
                                            <option value={3}>x3</option>
                                            <option value={4}>x4</option>
                                        </select>
                                    </div>
                                    <button onClick={() => removeConfigColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                <button onClick={() => setIsConfigModalOpen(false)} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-xl shadow hover:bg-blue-700 transition-colors">Hoàn tất</button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }

        .custom-scrollbar::-webkit-scrollbar {
            height: 10px;
            width: 8px;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, Settings2, Trash2, X } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

// Cấu hình độ rộng cố định cho các cột (Pixel)
const COL_WIDTHS = {
    index: 40,
    studentInfo: 280, // Gộp Tên thánh + Họ tên
    score: 60,
    absent: 35,
    avg: 50,
    final: 60,
    rank: 80,
    ranking: 50
};

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);
  const [isConfigModalOpen, setIsConfigModalOpen] = useState(false);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);
    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        const newRecords = [...prev];
        if (existingIndex > -1) {
            newRecords[existingIndex] = { ...prev[existingIndex], scores: { ...prev[existingIndex].scores, [field]: numValue } };
            return newRecords;
        } else {
             return [...newRecords, { studentId, term, scores: { [field]: numValue }, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 }];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      const termColumns = testColumns.filter(c => c.term === record.term);
      termColumns.forEach(col => {
          const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
          totalScore += score * col.weight;
          totalWeight += col.weight;
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = records.map(r => {
         const student = filteredStudents.find(s => s.id === r.studentId);
         if (student) {
            return { ...r, average: calculateAvg(r) };
         }
         return r;
     });
     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm lớp ${currentClass?.name}!`);
  };

  const getRank = (avg: number) => {
    if (avg === 0) return { label: '-', color: 'text-slate-400 bg-slate-50' };
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const processedStudentsYear = useMemo(() => {
    let list = filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;
      return { 
        ...s, 
        avg1, avg2, avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
        nameForSort: s.fullName.split(' ').pop() || ''
      };
    });
    const sortedByScore = [...list].sort((a, b) => b.avgYear - a.avgYear);
    const rankedMap = new Map();
    sortedByScore.forEach((s, index) => { rankedMap.set(s.id, index + 1); });
    return list.map(s => ({ ...s, ranking: rankedMap.get(s.id) })).sort((a, b) => a.nameForSort.localeCompare(b.nameForSort, 'vi'));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const addConfigColumn = (term: 'HK1' | 'HK2') => {
      setTestColumns([...testColumns, { id: `col_${Date.now()}`, name: 'Cột mới', weight: 1, term }]);
  };

  const removeConfigColumn = (id: string) => setTestColumns(testColumns.filter(c => c.id !== id));

  const updateConfigColumn = (id: string, field: keyof TestColumn, value: any) => {
      setTestColumns(testColumns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-5 py-3 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast}</span>
           </div>
        </div>
      )}

      {/* Header Section */}
      <div className="flex justify-between items-center mb-5">
        <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-5 flex justify-between items-center flex-wrap gap-3">
        <div className="flex gap-3 items-center flex-wrap">
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 text-blue-800 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <button onClick={() => setIsConfigModalOpen(true)} className="flex items-center gap-2 px-4 py-1.5 bg-slate-100 text-slate-700 border border-slate-300 rounded-lg hover:bg-slate-200 text-xs font-bold transition-all"><Settings2 size={16} /> Cấu hình điểm</button>
            )}
             <button className="flex items-center gap-2 px-4 py-1.5 bg-green-600 text-white border border-green-700 rounded-lg text-xs hover:bg-green-700 font-bold uppercase shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-white rounded-xl shadow-md border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar flex-1 relative">
                <table className="w-full text-left border-collapse table-fixed" style={{ minWidth: '100%' }}>
                    <thead>
                        {/* Header Row 1 */}
                        <tr className="bg-slate-100 text-slate-700 font-bold sticky top-0 z-50 uppercase tracking-tighter text-[10px]">
                            <th style={{ width: COL_WIDTHS.index }} className="px-2 py-3 text-center sticky left-0 bg-slate-100 z-[51] border-b border-r border-slate-300">#</th>
                            <th style={{ width: COL_WIDTHS.studentInfo }} className="px-4 py-3 sticky left-[40px] bg-slate-100 z-[51] border-b border-r border-slate-400 shadow-[2px_0_4px_rgba(0,0,0,0.1)]">Họ và Tên Học Viên</th>

                            <th colSpan={hk1Columns.length + 3} className="p-2 text-center bg-blue-100/60 border-b border-r border-blue-300 text-blue-800 border-t border-t-blue-400">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 3} className="p-2 text-center bg-purple-100/60 border-b border-r border-purple-300 text-purple-800 border-t border-t-purple-400">HỌC KỲ 2</th>

                            <th style={{ width: COL_WIDTHS.final }} className="px-2 py-3 text-center border-b border-r border-slate-300 bg-slate-200">Cả Năm</th>
                            <th style={{ width: COL_WIDTHS.rank }} className="px-2 py-3 text-center border-b border-r border-slate-300 bg-slate-200">Xếp Loại</th>
                            <th style={{ width: COL_WIDTHS.ranking }} className="px-2 py-3 text-center border-b border-slate-300 bg-yellow-50 text-yellow-800">Hạng</th>
                        </tr>
                        {/* Header Row 2 */}
                        <tr className="bg-slate-50 text-slate-500 font-bold uppercase sticky top-[40px] z-[49] text-[9px]">
                             <th className="sticky left-0 bg-slate-50 z-[50] border-b border-r border-slate-300"></th>
                             <th className="sticky left-[40px] bg-slate-50 z-[50] border-b border-r border-slate-400 shadow-[2px_0_4px_rgba(0,0,0,0.1)]"></th>

                             {hk1Columns.map((col) => (
                                <th key={col.id} style={{ width: COL_WIDTHS.score }} className="px-1 py-1.5 text-center border-b border-r border-slate-200 bg-blue-50/40">{col.name}</th>
                             ))}
                             <th style={{ width: COL_WIDTHS.absent }} className="px-1 py-1.5 text-center border-b border-r border-amber-200 bg-amber-50 text-amber-700">P</th>
                             <th style={{ width: COL_WIDTHS.absent }} className="px-1 py-1.5 text-center border-b border-r border-red-200 bg-red-50 text-red-700">K</th>
                             <th style={{ width: COL_WIDTHS.avg }} className="px-1 py-1.5 text-center border-b border-r border-blue-300 font-black bg-blue-100/80 text-blue-900">TB</th>

                             {hk2Columns.map((col) => (
                                <th key={col.id} style={{ width: COL_WIDTHS.score }} className="px-1 py-1.5 text-center border-b border-r border-slate-200 bg-purple-50/40">{col.name}</th>
                             ))}
                             <th style={{ width: COL_WIDTHS.absent }} className="px-1 py-1.5 text-center border-b border-r border-amber-200 bg-amber-50 text-amber-700">P</th>
                             <th style={{ width: COL_WIDTHS.absent }} className="px-1 py-1.5 text-center border-b border-r border-red-200 bg-red-50 text-red-700">K</th>
                             <th style={{ width: COL_WIDTHS.avg }} className="px-1 py-1.5 text-center border-b border-r border-purple-300 font-black bg-purple-100/80 text-purple-900">TB</th>

                             <th className="border-b border-r border-slate-200"></th>
                             <th className="border-b border-r border-slate-200"></th>
                             <th className="border-b border-slate-200"></th>
                        </tr>
                    </thead>
                    <tbody className="text-xs bg-white divide-y divide-slate-200">
                        {processedStudentsYear.length > 0 ? (
                            processedStudentsYear.map((s, idx) => {
                                const r1 = getRecord(s.id, 'HK1');
                                const r2 = getRecord(s.id, 'HK2');
                                return (
                                <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors">
                                    <td className="px-2 py-2 text-center sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-300 text-slate-400 font-bold">{idx + 1}</td>
                                    <td className="px-4 py-2 sticky left-[40px] bg-white group-hover:bg-slate-50 z-20 border-r border-slate-400 shadow-[2px_0_4px_rgba(0,0,0,0.05)] text-slate-900 truncate">
                                        <span className="font-bold text-slate-500 mr-2">{s.saintName}</span>
                                        <span className="font-bold">{s.fullName}</span>
                                    </td>

                                    {hk1Columns.map(col => (
                                        <td key={`hk1-${col.id}`} className="p-0 border-r border-slate-200 text-center">
                                            <input type="number" step="0.1" value={r1.scores ? (r1.scores[col.id] ?? '') : ''} onChange={(e) => handleScoreChange(s.id, 'HK1', col.id, e.target.value)} className="w-full text-center h-full py-2 bg-transparent focus:bg-white focus:ring-1 focus:ring-blue-500 outline-none font-bold text-slate-700" placeholder="-" />
                                        </td>
                                    ))}
                                    <td className="px-1 py-2 border-r border-amber-200 text-center font-bold text-amber-600 bg-amber-50/20">{s.absentP1}</td>
                                    <td className="px-1 py-2 border-r border-red-200 text-center font-bold text-red-600 bg-red-50/20">{s.absentK1}</td>
                                    <td className="px-1 py-2 border-r border-blue-300 text-center font-black text-blue-800 bg-blue-50/60">{s.avg1 > 0 ? s.avg1.toFixed(1) : '-'}</td>

                                    {hk2Columns.map(col => (
                                        <td key={`hk2-${col.id}`} className="p-0 border-r border-slate-200 text-center">
                                            <input type="number" step="0.1" value={r2.scores ? (r2.scores[col.id] ?? '') : ''} onChange={(e) => handleScoreChange(s.id, 'HK2', col.id, e.target.value)} className="w-full text-center h-full py-2 bg-transparent focus:bg-white focus:ring-1 focus:ring-purple-500 outline-none font-bold text-slate-700" placeholder="-" />
                                        </td>
                                    ))}
                                    <td className="px-1 py-2 border-r border-amber-200 text-center font-bold text-amber-600 bg-amber-50/20">{s.absentP2}</td>
                                    <td className="px-1 py-2 border-r border-red-200 text-center font-bold text-red-600 bg-red-50/20">{s.absentK2}</td>
                                    <td className="px-1 py-2 border-r border-purple-300 text-center font-black text-purple-800 bg-purple-50/60">{s.avg2 > 0 ? s.avg2.toFixed(1) : '-'}</td>

                                    <td className="px-1 py-2 text-center font-black text-slate-900 bg-slate-100 border-r border-slate-300 text-sm">{s.avgYear > 0 ? s.avgYear.toFixed(1) : '-'}</td>
                                    <td className="px-1 py-2 text-center border-r border-slate-300">
                                        {s.avgYear > 0 && <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase shadow-sm ${s.rank.color}`}>{s.rank.label}</span>}
                                    </td>
                                    <td className="px-1 py-2 text-center font-black text-yellow-700 bg-yellow-50/40">{s.ranking}</td>
                                </tr>
                                );
                            })
                        ) : (
                            <tr><td colSpan={40} className="p-20 text-center text-slate-400 italic bg-slate-50 text-sm">Vui lòng chọn lớp để hiển thị sổ điểm</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
            {processedStudentsYear.length > 0 && (
                <div className="p-3 border-t border-slate-300 bg-slate-100 text-right sticky bottom-0 z-30 flex justify-between items-center shadow-inner">
                    <p className="text-xs text-slate-500 font-medium italic">* Nhấn Lưu Bảng Điểm để cập nhật kết quả trung bình & hạng.</p>
                    <button onClick={handleSaveGrades} className="flex items-center gap-2 px-8 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700 font-bold uppercase tracking-wider transition-all active:scale-95 text-xs">
                        <Save size={16} /> LƯU BẢNG ĐIỂM
                    </button>
                </div>
            )}
        </>
        ) : (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm mb-6 flex justify-between items-center">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 uppercase mb-1">Tổng Kết Lớp: {currentClass?.name || '---'}</h3>
                    <div className="text-slate-600 flex items-center gap-2 text-sm font-medium"><UserCheck size={18} className="text-blue-600" />GLV Phụ Trách: {currentClass?.mainTeacher || '---'}</div>
                  </div>
                  <div className="text-right bg-blue-600 text-white px-5 py-3 rounded-xl shadow-md">
                    <div className="text-[10px] font-bold opacity-80 uppercase tracking-widest">Sĩ số</div>
                    <div className="text-2xl font-black">{filteredStudents.length} em</div>
                  </div>
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                <div className="bg-white rounded-2xl border border-green-200 shadow-sm overflow-hidden flex flex-col h-fit">
                  <div className="p-4 bg-green-50 border-b border-green-100 flex justify-between items-center">
                    <h4 className="font-bold text-lg text-green-800 uppercase">Lên Lớp ({passedStudents.length})</h4>
                  </div>
                  <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-[9px]">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {passedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-green-50/50">
                            <td className="p-3 font-bold text-slate-800 text-xs">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-black text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-black text-slate-900">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${s.rank.color}`}>{s.rank.label}</span></td>
                          </tr>
                        ))}
                      </tbody>
                  </table>
                </div>
                <div className="bg-white rounded-2xl border border-red-200 shadow-sm overflow-hidden flex flex-col h-fit">
                   <div className="p-4 bg-red-50 border-b border-red-100 flex justify-between items-center">
                    <h4 className="font-bold text-lg text-red-800 uppercase">Chưa Đạt ({failedStudents.length})</h4>
                  </div>
                  <table className="w-full text-sm">
                      <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-[9px]">
                        <tr><th className="p-3 text-left">Học Viên</th><th className="p-3 text-center">Hạng</th><th className="p-3 text-center">ĐTB</th><th className="p-3 text-center">Xếp loại</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {failedStudents.map(s => (
                          <tr key={s.id} className="hover:bg-red-50/50">
                            <td className="p-3 font-bold text-slate-800 text-xs">{s.saintName} {s.fullName}</td>
                            <td className="p-3 text-center font-black text-yellow-600">{s.ranking}</td>
                            <td className="p-3 text-center font-black text-slate-900">{s.avgYear.toFixed(1)}</td>
                            <td className="p-3 text-center"><span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${s.rank.color}`}>{s.rank.label}</span></td>
                          </tr>
                        ))}
                        {failedStudents.length === 0 && <tr><td colSpan={4} className="p-10 text-center text-slate-400 italic">Không có dữ liệu</td></tr>}
                      </tbody>
                  </table>
                </div>
              </div>
            </div>
        )}
      </div>

      {/* Score Configuration Modal */}
      {isConfigModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-scale-in">
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                <div className="flex items-center gap-2">
                    <Settings2 className="text-blue-600" />
                    <h3 className="text-xl font-bold text-slate-800">Cấu hình Cột điểm & Hệ số</h3>
                </div>
                <button onClick={() => setIsConfigModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-blue-200">
                            <h4 className="font-bold text-blue-700 uppercase tracking-wider text-sm">Học Kỳ 1</h4>
                            <button onClick={() => addConfigColumn('HK1')} className="text-[10px] flex items-center gap-1 font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded hover:bg-blue-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-3">
                            {hk1Columns.map(col => (
                                <div key={col.id} className="flex gap-2 items-center bg-blue-50/50 p-2 rounded-lg border border-blue-100">
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateConfigColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col">
                                        <span className="text-[8px] font-bold text-blue-400 uppercase">Hệ số</span>
                                        <select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateConfigColumn(col.id, 'weight', Number(e.target.value))}>
                                            <option value={1}>x1</option>
                                            <option value={2}>x2</option>
                                            <option value={3}>x3</option>
                                            <option value={4}>x4</option>
                                        </select>
                                    </div>
                                    <button onClick={() => removeConfigColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-purple-200">
                            <h4 className="font-bold text-purple-700 uppercase tracking-wider text-sm">Học Kỳ 2</h4>
                            <button onClick={() => addConfigColumn('HK2')} className="text-[10px] flex items-center gap-1 font-bold text-purple-600 bg-purple-50 px-2 py-1 rounded hover:bg-purple-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-3">
                            {hk2Columns.map(col => (
                                <div key={col.id} className="flex gap-2 items-center bg-purple-50/50 p-2 rounded-lg border border-purple-100">
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateConfigColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col">
                                        <span className="text-[8px] font-bold text-purple-400 uppercase">Hệ số</span>
                                        <select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateConfigColumn(col.id, 'weight', Number(e.target.value))}>
                                            <option value={1}>x1</option>
                                            <option value={2}>x2</option>
                                            <option value={3}>x3</option>
                                            <option value={4}>x4</option>
                                        </select>
                                    </div>
                                    <button onClick={() => removeConfigColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                <button onClick={() => setIsConfigModalOpen(false)} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-xl shadow hover:bg-blue-700 transition-colors">Hoàn tất</button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }

        .custom-scrollbar::-webkit-scrollbar {
            height: 10px;
            width: 8px;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, Settings2, Trash2, X } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

// Cấu hình độ rộng cố định cho các cột (Pixel)
const COL_WIDTHS = {
    index: 40,
    studentInfo: 280, // Gộp Tên thánh + Họ tên
    score: 60,
    absent: 35,
    avg: 50,
    final: 60,
    rank: 85,
    ranking: 50
};

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);
  const [isConfigModalOpen, setIsConfigModalOpen] = useState(false);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);
    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        const newRecords = [...prev];
        if (existingIndex > -1) {
            newRecords[existingIndex] = { ...prev[existingIndex], scores: { ...prev[existingIndex].scores, [field]: numValue } };
            return newRecords;
        } else {
             return [...newRecords, { studentId, term, scores: { [field]: numValue }, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 }];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      const termColumns = testColumns.filter(c => c.term === record.term);
      termColumns.forEach(col => {
          const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
          totalScore += score * col.weight;
          totalWeight += col.weight;
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = records.map(r => {
         const student = filteredStudents.find(s => s.id === r.studentId);
         if (student) {
            return { ...r, average: calculateAvg(r) };
         }
         return r;
     });
     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm lớp ${currentClass?.name}!`);
  };

  const getRank = (avg: number) => {
    if (avg === 0) return { label: '-', color: 'text-slate-400 bg-slate-50' };
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const processedStudentsYear = useMemo(() => {
    let list = filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;
      return { 
        ...s, 
        avg1, avg2, avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
        nameForSort: s.fullName.split(' ').pop() || ''
      };
    });
    const sortedByScore = [...list].sort((a, b) => b.avgYear - a.avgYear);
    const rankedMap = new Map();
    sortedByScore.forEach((s, index) => { rankedMap.set(s.id, index + 1); });
    return list.map(s => ({ ...s, ranking: rankedMap.get(s.id) })).sort((a, b) => a.nameForSort.localeCompare(b.nameForSort, 'vi'));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const addConfigColumn = (term: 'HK1' | 'HK2') => {
      setTestColumns([...testColumns, { id: `col_${Date.now()}`, name: 'Cột mới', weight: 1, term }]);
  };

  const removeConfigColumn = (id: string) => setTestColumns(testColumns.filter(c => c.id !== id));

  const updateConfigColumn = (id: string, field: keyof TestColumn, value: any) => {
      setTestColumns(testColumns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-5 py-3 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast}</span>
           </div>
        </div>
      )}

      {/* Header Section */}
      <div className="flex justify-between items-center mb-5">
        <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300">
           <button onClick={() => setViewMode('entry')} className={`px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> Sổ Điểm</button>
           <button onClick={() => setViewMode('summary')} className={`px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> Thống Kê</button>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-5 flex justify-between items-center flex-wrap gap-3">
        <div className="flex gap-3 items-center flex-wrap">
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
          <select className="px-3 py-1.5 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 text-blue-800 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
        <div className="flex items-center gap-2">
            {viewMode === 'entry' && (
                <button onClick={() => setIsConfigModalOpen(true)} className="flex items-center gap-2 px-4 py-1.5 bg-slate-100 text-slate-700 border border-slate-300 rounded-lg hover:bg-slate-200 text-xs font-bold transition-all"><Settings2 size={16} /> Cấu hình điểm</button>
            )}
             <button className="flex items-center gap-2 px-4 py-1.5 bg-green-600 text-white border border-green-700 rounded-lg text-xs hover:bg-green-700 font-bold uppercase shadow-sm transition-all"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-white rounded-xl shadow-md border border-slate-300 flex-1 overflow-hidden flex flex-col">
        {viewMode === 'entry' ? (
        <>
            <div className="overflow-x-auto custom-scrollbar flex-1 relative">
                <table className="w-full text-left border-collapse table-fixed" style={{ minWidth: '100%' }}>
                    <thead>
                        {/* Header Row 1 */}
                        <tr className="bg-slate-100 text-slate-700 font-bold sticky top-0 z-50 uppercase tracking-tighter text-xs">
                            <th style={{ width: COL_WIDTHS.index }} className="px-2 py-3 text-center sticky left-0 bg-slate-100 z-[51] border-b border-r border-slate-300">#</th>
                            <th style={{ width: COL_WIDTHS.studentInfo }} className="px-4 py-3 sticky left-[40px] bg-slate-100 z-[51] border-b border-r border-slate-400 shadow-[2px_0_4px_rgba(0,0,0,0.1)]">Họ và Tên Học Viên</th>

                            <th colSpan={hk1Columns.length + 3} className="p-2 text-center bg-blue-100/60 border-b border-r border-blue-300 text-blue-800 border-t border-t-blue-400">HỌC KỲ 1</th>
                            <th colSpan={hk2Columns.length + 3} className="p-2 text-center bg-purple-100/60 border-b border-r border-purple-300 text-purple-800 border-t border-t-purple-400">HỌC KỲ 2</th>

                            <th style={{ width: COL_WIDTHS.final }} className="px-2 py-3 text-center border-b border-r border-slate-300 bg-slate-200">Cả Năm</th>
