                                                 <div className="md:col-span-2"><label className="label-text-mini">Tại (Nhà thờ/Giáo xứ)</label><input className="input-field-mini text-[11px]" defaultValue={selectedStudent?.confirmationPlace} placeholder="Tên giáo xứ" /></div>
