import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';
import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, CheckCircle2, FileSpreadsheet, AlertTriangle, Save, User, History, GitMerge, AlertCircle, ScrollText } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else if (selectedGrade !== 'all') {
            validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
        } else {
            validClassIds = classesInYear.map(c => c.id);
        }

        const matchClass = validClassIds.includes(student.classId);
        return matchSearch && matchClass;
    });

    // Sort by First Name (Vietnamese locale)
    return list.sort((a, b) => {
        const nameA = a.fullName.split(' ').pop() || '';
        const nameB = b.fullName.split(' ').pop() || '';
        return nameA.localeCompare(nameB, 'vi');
    });
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const getStatusBadge = (status: Student['status']) => {
      switch (status) {
          case 'ACTIVE': return <span className="px-3 py-1 rounded text-sm font-bold bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
          case 'TRANSFERRED': return <span className="px-3 py-1 rounded text-sm font-bold bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
          case 'DROPPED': return <span className="px-3 py-1 rounded text-sm font-bold bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
          default: return null;
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.length > 0 ? parts[parts.length - 1] : '';
      const lastName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
      return { firstName, lastName };
  };

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const generateNextId = (yearId: string) => {
      const prefix = yearId.slice(2, 4); 
      const yearStudents = students.filter(s => s.id.startsWith(prefix));
      let nextNum = 1;
      if (yearStudents.length > 0) {
          const nums = yearStudents
            .map(s => parseInt(s.id.slice(2)))
            .filter(n => !isNaN(n));
          if (nums.length > 0) nextNum = Math.max(...nums) + 1;
      }
      return `${prefix}${nextNum.toString().padStart(4, '0')}`;
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) {
        alert("Vui lòng nhập đầy đủ Tên Thánh, Họ Tên và Ngày sinh.");
        return;
    }

    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? {
            ...s,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            status: inputStatus
        } : s));
        showToast("Đã cập nhật thông tin học viên thành công!");
    } else {
        const newId = generateNextId(selectedYear);
        const newStudent: Student = {
            id: newId,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''),
            status: inputStatus,
            birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: ''
        };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên mới thành công! Mã số: ${newId}`);
    }
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) duplicates.push({ key, students: groups[key] });
      });
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  const getStudentHistory = (studentId: string) => {
    const studentRecords = records.filter(r => r.studentId === studentId);
    const history = [];
    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';
        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }
    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-4 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={18} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm font-bold">
                <FileSpreadsheet size={18} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg font-bold text-base transition-all active:scale-95"><Plus size={20} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center text-lg">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[140px] bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[140px] bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[180px] bg-slate-50 text-blue-800 outline-none focus:ring-2 focus:ring-blue-500" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-lg" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse table-fixed">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b-2 border-slate-300 uppercase tracking-tight text-sm">
              <tr>
                <th className="px-4 py-3 w-14 text-center">#</th>
                <th className="px-4 py-3 w-28">Mã HV</th>
                <th className="px-4 py-3 w-32">Tên Thánh</th>
                <th className="px-4 py-3 w-44">Họ & Tên Đệm</th>
                <th className="px-4 py-3 w-28">Tên</th>
                <th className="px-4 py-3 w-36 text-center">Ngày Sinh</th>
                <th className="px-4 py-3 w-52 text-center">SĐT Liên Hệ</th>
                <th className="px-4 py-3 w-36">Lớp</th>
                <th className="px-4 py-3 w-32 text-center">Tình Trạng</th>
                <th className="px-4 py-3 text-center w-28">Thao tác</th>
              </tr>
            </thead>
            <tbody className="text-lg text-slate-800 divide-y divide-slate-100">
              {filteredStudents.map((s, index) => {
                const { firstName, lastName } = splitName(s.fullName);
                return (
                <tr key={s.id} className="hover:bg-blue-50 transition-colors border-b border-slate-100">
                  <td className="px-4 py-2.5 text-center text-slate-500 font-bold text-sm">{index + 1}</td>
                  <td className="px-4 py-2.5 font-mono text-base font-bold text-slate-500">{s.id}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-700">{s.saintName}</td>
                  <td className="px-4 py-2.5 text-slate-700">{lastName}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-900">{firstName}</td>
                  <td className="px-4 py-2.5 text-center">
                    <div className="text-base font-medium">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                    <div className="text-xs text-slate-400 font-mono tracking-tighter">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</div>
                  </td>
                  <td className="px-4 py-2.5 text-base leading-relaxed font-medium text-blue-800 bg-blue-50/10 text-center">
                    <div className="flex flex-col gap-1">
                        {s.fatherPhone && <span className="whitespace-nowrap">B: {s.fatherPhone}</span>}
                        {s.motherPhone && <span className="whitespace-nowrap">M: {s.motherPhone}</span>}
                        {!s.fatherPhone && !s.motherPhone && <span className="text-slate-300 font-normal">---</span>}
                    </div>
                  </td>
                  <td className="px-4 py-2.5">
                    <span className="px-2.5 py-1 bg-blue-600 text-white rounded-lg text-xs font-black whitespace-nowrap uppercase tracking-tight shadow-sm">{getClassName(s.classId)}</span>
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    {getStatusBadge(s.status)}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => openStudentDetail(s)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Sửa / Chi tiết"><Edit size={20} /></button>
                        <button onClick={() => setStudentToDelete(s)} className="p-2 text-red-600 hover:bg-red-100 rounded-lg transition-colors" title="Xóa"><Trash2 size={20} /></button>
                     </div>
                  </td>
                </tr>
              )})}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={10} className="p-12 text-center text-slate-400 italic text-xl">Không tìm thấy học viên nào phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="p-4 border-t border-slate-200 bg-slate-50 text-right font-bold">
          Tổng số: {filteredStudents.length} học viên
        </div>
      </div>

      {/* Modals */}
      {(showModal || selectedStudent) && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-[90rem] h-[92vh] flex flex-col animate-fade-in overflow-hidden border border-slate-300">

            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold text-lg shadow">
                    {selectedStudent ? selectedStudent.fullName.charAt(0) : <Plus size={20}/>}
                 </div>
                 <div>
                    <h3 className="font-bold text-lg text-slate-800">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-xs text-slate-500 font-mono tracking-tighter">{selectedStudent.id}</p>}
                 </div>
              </div>
              <div className="flex gap-2">
                <button onClick={closeModal} className="px-5 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-bold text-sm transition-colors border border-slate-200">Đóng</button>
                <button onClick={handleSaveStudent} className="px-5 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md flex items-center gap-2 text-sm transition-all active:scale-95">
                   <Save size={18} /> Lưu Hồ Sơ
                </button>
              </div>
            </div>

            {realtimeDuplicates.length > 0 && (
                <div className="bg-red-50 border-b border-red-100 p-3 flex items-start gap-3 animate-pulse">
                    <AlertTriangle size={18} className="text-red-600 mt-0.5" />
                    <div>
                        <h4 className="font-bold text-red-800 text-sm">Phát hiện dữ liệu trùng lặp!</h4>
                        <p className="text-xs text-red-600">Hệ thống phát hiện học viên sau có cùng Tên và Ngày sinh:</p>
                        <div className="flex flex-wrap gap-2 mt-1">
                            {realtimeDuplicates.map(d => (
                                <span key={d.id} className="text-[10px] bg-white px-2 py-0.5 rounded border border-red-200 text-red-700">{d.saintName} <b>{d.fullName}</b> ({d.id}) - Lớp: {getClassName(d.classId)}</span>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            <div className="flex border-b border-slate-200 bg-white">
                <button onClick={() => setModalTab('PROFILE')} className={`px-6 py-3 text-sm font-black border-b-2 uppercase tracking-wide transition-all ${modalTab === 'PROFILE' ? 'border-blue-600 text-blue-600 bg-blue-50/30' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Thông tin cá nhân & Bí tích</button>
                <button onClick={() => setModalTab('HISTORY')} className={`px-6 py-3 text-sm font-black border-b-2 uppercase tracking-wide transition-all ${modalTab === 'HISTORY' ? 'border-blue-600 text-blue-600 bg-blue-50/30' : 'border-transparent text-slate-500 hover:bg-slate-50'}`}>Quá trình học tập</button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-5 bg-slate-50/30">
                {modalTab === 'PROFILE' && (
                    <div className="max-w-[85rem] mx-auto animate-fade-in">
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-start">

                            {/* CỘT 1: THÔNG TIN CÁ NHÂN & GIA ĐÌNH */}
                            <div className="space-y-6">
                                {/* Khối: Thông tin cá nhân */}
                                <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                                    <h4 className="flex items-center gap-2 font-black text-base text-slate-600 mb-5 pb-2 border-b uppercase tracking-wider"><User size={18} className="text-blue-500"/> Thông tin cá nhân</h4>
                                    <div className="grid grid-cols-1 md:grid-cols-12 gap-5">
                                        <div className="md:col-span-3">
                                            <label className="label-text-mini">Mã học viên</label>
                                            <input className="input-field-mini bg-slate-100 text-slate-600 font-mono font-bold" disabled value={selectedStudent?.id || 'AUTO'} />
                                        </div>
                                        <div className="md:col-span-3">
                                            <label className="label-text-mini">Tình trạng</label>
                                            <select className="input-field-mini font-bold text-blue-700" value={inputStatus} onChange={(e) => setInputStatus(e.target.value as any)}>
                                                <option value="ACTIVE">Đang học</option>
                                                <option value="TRANSFERRED">Chuyển xứ</option>
                                                <option value="DROPPED">Nghỉ học</option>
                                            </select>
                                        </div>
                                        <div className="md:col-span-6 relative">
                                            <label className="label-text-mini">Tên Thánh</label>
                                            <input className="input-field-mini font-bold" value={saintInput} onChange={(e) => {setSaintInput(e.target.value); setShowSaintSuggestions(true);}} onFocus={() => setShowSaintSuggestions(true)} onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)} placeholder="Giuse..." />
                                            {showSaintSuggestions && (
                                               <div className="absolute z-10 w-full bg-white border border-slate-200 rounded shadow-xl max-h-40 overflow-y-auto mt-1">
                                                 {filteredSaints.length > 0 ? (filteredSaints.map(s => (<div key={s.id} className="p-2 hover:bg-blue-50 cursor-pointer text-sm flex justify-between border-b last:border-0" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}><span>{s.name}</span><span className="text-[10px] text-slate-400">({s.gender === 'Male' ? 'Nam' : 'Nữ'})</span></div>))) : (<div className="p-2 text-xs text-slate-400">Không tìm thấy</div>)}
                                               </div>
                                            )}
                                        </div>
                                        <div className="md:col-span-12">
                                            <label className="label-text-mini">Họ và Tên Học Viên</label>
                                            <input className="input-field-mini font-black text-slate-800" value={inputName} onChange={(e) => setInputName(e.target.value)} placeholder="Nguyễn Văn A" />
                                        </div>
                                        <div className="md:col-span-4">
                                            <label className="label-text-mini">Ngày sinh</label>
                                            <input type="date" className="input-field-mini font-medium" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                        </div>
                                        <div className="md:col-span-3">
                                           <label className="label-text-mini">Giới tính</label>
                                           <select className="input-field-mini font-medium" value={inputGender} onChange={(e) => setInputGender(e.target.value as 'Male' | 'Female')}>
                                               <option value="Male">Nam</option>
                                               <option value="Female">Nữ</option>
                                           </select>
                                        </div>
                                        <div className="md:col-span-5">
                                            <label className="label-text-mini">Nơi sinh</label>
                                            <input className="input-field-mini font-medium" defaultValue={selectedStudent?.birthPlace} placeholder="Bệnh viện..." />
                                         </div>
                                    </div>
                                </div>

                                {/* Khối: Gia Đình & Liên Hệ */}
                                <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                                    <h4 className="flex items-center gap-2 font-black text-base text-slate-600 mb-5 pb-2 border-b uppercase tracking-wider"><User size={18} className="text-orange-500"/> Gia đình & Liên hệ</h4>
                                    <div className="space-y-4">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <div><label className="label-text-mini">Tên bố</label><input className="input-field-mini font-bold" defaultValue={selectedStudent?.fatherName} placeholder="Họ tên bố" /></div>
                                            <div><label className="label-text-mini">Sđt bố</label><input className="input-field-mini font-mono font-bold" defaultValue={selectedStudent?.fatherPhone} placeholder="09..." /></div>
                                        </div>
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <div><label className="label-text-mini">Tên mẹ</label><input className="input-field-mini font-bold" defaultValue={selectedStudent?.motherName} placeholder="Họ tên mẹ" /></div>
                                            <div><label className="label-text-mini">Sđt mẹ</label><input className="input-field-mini font-mono font-bold" defaultValue={selectedStudent?.motherPhone} placeholder="09..." /></div>
                                        </div>
                                        <div><label className="label-text-mini">Địa chỉ thường trú</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.address} placeholder="Số nhà, đường, phường, quận..." /></div>
                                        <div><label className="label-text-mini">Thuộc Giáo Họ / Giáo Xứ</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.parish} placeholder="Tên giáo họ..." /></div>
                                    </div>
                                </div>

                                {/* Khối: Ghi Chú Đặc Biệt */}
                                <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                                    <h4 className="flex items-center gap-2 font-black text-base text-slate-600 mb-4 pb-2 border-b uppercase tracking-wider"><AlertCircle size={18} className="text-slate-500"/> Ghi chú học viên</h4>
                                     <textarea className="input-field-mini h-20 resize-none text-base bg-slate-50 p-3" defaultValue={selectedStudent?.note} placeholder="Ghi chú thêm về học viên..." />
                                </div>
                            </div>

                            {/* CỘT 2: HỒ SƠ BÍ TÍCH */}
                            <div className="space-y-6">
                                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm h-full">
                                    <h4 className="flex items-center gap-2 font-black text-base text-slate-600 mb-6 pb-2 border-b uppercase tracking-wider"><ScrollText size={20} className="text-purple-500"/> Hồ sơ Bí tích</h4>
                                    <div className="space-y-5">
                                         {/* Bí tích: Rửa Tội */}
                                         <div className="p-5 rounded-lg bg-blue-50/50 border border-blue-100 relative overflow-hidden">
                                             <div className="absolute top-0 right-0 w-1.5 bg-blue-400 h-full opacity-50"></div>
                                             <h5 className="font-black text-blue-700 mb-4 uppercase text-xs flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> 1. Bí tích Rửa Tội</h5>
                                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                 <div><label className="label-text-mini">Ngày lãnh nhận</label><input type="date" className="input-field-mini font-medium" defaultValue={selectedStudent?.baptismDate} /></div>
                                                 <div><label className="label-text-mini">Linh mục ban</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.baptismBy} placeholder="Tên linh mục" /></div>
                                                 <div className="md:col-span-2"><label className="label-text-mini">Người đỡ đầu</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.baptismSponsor} placeholder="Tên người đỡ đầu" /></div>
                                                 <div className="md:col-span-2"><label className="label-text-mini">Tại (Nhà thờ/Giáo xứ)</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.baptismPlace} placeholder="Tên giáo xứ" /></div>
                                             </div>
                                         </div>

                                         {/* Bí tích: Rước Lễ Lần Đầu */}
                                         <div className="p-5 rounded-lg bg-green-50/50 border border-green-100 relative overflow-hidden">
                                             <div className="absolute top-0 right-0 w-1.5 bg-green-400 h-full opacity-50"></div>
                                             <h5 className="font-black text-green-700 mb-4 uppercase text-xs flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-green-500"></div> 2. Rước Lễ Lần Đầu</h5>
                                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                 <div><label className="label-text-mini">Ngày lãnh nhận</label><input type="date" className="input-field-mini font-medium" defaultValue={selectedStudent?.eucharistDate} /></div>
                                                 <div><label className="label-text-mini">Linh mục ban</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.eucharistBy} placeholder="Tên linh mục" /></div>
                                                 <div className="md:col-span-2"><label className="label-text-mini">Tại (Nhà thờ/Giáo xứ)</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.eucharistPlace} placeholder="Tên giáo xứ" /></div>
                                             </div>
                                         </div>

                                         {/* Bí tích: Thêm Sức */}
                                         <div className="p-5 rounded-lg bg-red-50/50 border border-red-100 relative overflow-hidden">
                                             <div className="absolute top-0 right-0 w-1.5 bg-red-400 h-full opacity-50"></div>
                                             <h5 className="font-black text-red-700 mb-4 uppercase text-xs flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-red-500"></div> 3. Bí tích Thêm Sức</h5>
                                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                 <div><label className="label-text-mini">Ngày lãnh nhận</label><input type="date" className="input-field-mini font-medium" defaultValue={selectedStudent?.confirmationDate} /></div>
                                                 <div><label className="label-text-mini">Cha/ĐGM ban</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.confirmationBy} placeholder="Tên người ban" /></div>
                                                 <div className="md:col-span-2"><label className="label-text-mini">Người đỡ đầu</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.confirmationSponsor} placeholder="Tên người đỡ đầu" /></div>
                                                 <div className="md:col-span-2"><label className="label-text-mini">Tại (Nhà thờ/Giáo xứ)</label><input className="input-field-mini font-medium" defaultValue={selectedStudent?.confirmationPlace} placeholder="Tên giáo xứ" /></div>
                                             </div>
                                         </div>

                                         {/* Tuyên hứa: Bao Đồng */}
                                         <div className="p-5 rounded-lg bg-amber-50/50 border border-amber-100 relative overflow-hidden">
                                             <div className="absolute top-0 right-0 w-1.5 bg-amber-400 h-full opacity-50"></div>
                                             <h5 className="font-black text-amber-700 mb-4 uppercase text-xs flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div> 4. Tuyên Hứa / Bao Đồng</h5>
                                             <div><label className="label-text-mini">Ngày tuyên hứa</label><input type="date" className="input-field-mini font-medium" defaultValue={selectedStudent?.confirmationOathDate} /></div>
                                         </div>
                                    </div>
                                </div>
                            </div>

                        </div>
                    </div>
                )}

                {modalTab === 'HISTORY' && (
                    <div className="animate-fade-in space-y-4">
                        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                            <h4 className="flex items-center gap-2 font-black text-sm text-slate-600 mb-6 pb-2 border-b uppercase tracking-wider"><History size={18} className="text-orange-500"/> Quá trình học Giáo lý</h4>
                            {selectedStudent ? (
                                <table className="w-full text-sm text-left border-collapse">
                                    <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] font-black border-b border-slate-200">
                                        <tr>
                                            <th className="p-3">Năm Học</th>
                                            <th className="p-3">Lớp</th>
                                            <th className="p-3 text-center">HKI</th>
                                            <th className="p-3 text-center">HKII</th>
                                            <th className="p-3 text-center">Cả Năm</th>
                                            <th className="p-3 text-center">Xếp Loại</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y">
                                        {getStudentHistory(selectedStudent.id).map((h, idx) => (
                                            <tr key={idx} className="hover:bg-slate-50 transition-colors">
                                                <td className="p-3 font-bold text-slate-700">{h.year}</td>
                                                <td className="p-3"><span className="px-2 py-0.5 bg-blue-100 text-blue-800 rounded text-[10px] font-black uppercase">{h.className}</span></td>
                                                <td className="p-3 text-center font-medium text-slate-600">{h.hk1}</td>
                                                <td className="p-3 text-center font-medium text-slate-600">{h.hk2}</td>
                                                <td className="p-3 text-center font-black text-slate-900">{h.final}</td>
                                                <td className="p-3 text-center">
                                                    <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase shadow-sm ${h.rank === 'Giỏi' ? 'bg-green-100 text-green-700' : h.rank === 'Khá' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                                        {h.rank}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            ) : (
                                <div className="text-center p-10 text-slate-400 italic text-sm">Hồ sơ mới chưa có lịch sử học tập.</div>
                            )}
                        </div>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        .label-text-mini { display: block; font-size: 0.75rem; font-weight: 800; color: #64748b; margin-bottom: 0.35rem; text-transform: uppercase; letter-spacing: 0.05em; }
        .input-field-mini { width: 100%; padding: 0.55rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.65rem; outline: none; transition: all 0.2s; font-size: 0.95rem; background-color: #ffffff; }
        .input-field-mini:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1); }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, CheckCircle2, FileSpreadsheet, AlertTriangle, Save, User, History, GitMerge, AlertCircle, ScrollText } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Hierarchical Filters
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Set default active year
  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');

  // Saint Autocomplete State
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning state in Modal
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Watch for input changes to detect duplicates
  useEffect(() => {
    if (!showModal) return;

    if (inputName && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Reset inputs when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else if (selectedGrade !== 'all') {
            validClassIds = classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id);
        } else {
            validClassIds = classesInYear.map(c => c.id);
        }

        const matchClass = validClassIds.includes(student.classId);
        return matchSearch && matchClass;
    });

    // Sort by First Name (Vietnamese locale)
    return list.sort((a, b) => {
        const nameA = a.fullName.split(' ').pop() || '';
        const nameB = b.fullName.split(' ').pop() || '';
        return nameA.localeCompare(nameB, 'vi');
    });
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Unknown';

  const getStatusBadge = (status: Student['status']) => {
      switch (status) {
          case 'ACTIVE': return <span className="px-3 py-1 rounded text-sm font-bold bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
          case 'TRANSFERRED': return <span className="px-3 py-1 rounded text-sm font-bold bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
          case 'DROPPED': return <span className="px-3 py-1 rounded text-sm font-bold bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
          default: return null;
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.length > 0 ? parts[parts.length - 1] : '';
      const lastName = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
      return { firstName, lastName };
  };

  const openStudentDetail = (student: Student) => {
    setSelectedStudent(student);
    setShowModal(true);
  };

  const handleAddNew = () => {
    setSelectedStudent(null);
    setShowModal(true);
  }

  const closeModal = () => {
    setShowModal(false);
    setSelectedStudent(null);
    setRealtimeDuplicates([]);
    setShowSaintSuggestions(false);
  };

  const generateNextId = (yearId: string) => {
      const prefix = yearId.slice(2, 4); 
      const yearStudents = students.filter(s => s.id.startsWith(prefix));
      let nextNum = 1;
      if (yearStudents.length > 0) {
          const nums = yearStudents
            .map(s => parseInt(s.id.slice(2)))
            .filter(n => !isNaN(n));
          if (nums.length > 0) nextNum = Math.max(...nums) + 1;
      }
      return `${prefix}${nextNum.toString().padStart(4, '0')}`;
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) {
        alert("Vui lòng nhập đầy đủ Tên Thánh, Họ Tên và Ngày sinh.");
        return;
    }

    if (realtimeDuplicates.length > 0) {
        if (!window.confirm("Cảnh báo: Dữ liệu đang bị trùng lặp. Bạn có chắc chắn muốn lưu không?")) {
            return;
        }
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? {
            ...s,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            status: inputStatus
        } : s));
        showToast("Đã cập nhật thông tin học viên thành công!");
    } else {
        const newId = generateNextId(selectedYear);
        const newStudent: Student = {
            id: newId,
            fullName: inputName,
            dob: inputDob,
            saintName: saintInput,
            gender: inputGender,
            classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''),
            status: inputStatus,
            birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: ''
        };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên mới thành công! Mã số: ${newId}`);
    }
    closeModal();
  };

  const handleDeleteStudent = () => {
    if (studentToDelete) {
      setStudents(students.filter(s => s.id !== studentToDelete.id));
      showToast(`Đã xóa hồ sơ em ${studentToDelete.fullName} thành công!`);
      setStudentToDelete(null);
    }
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates: DuplicateGroup[] = [];
      Object.keys(groups).forEach(key => {
          if (groups[key].length > 1) duplicates.push({ key, students: groups[key] });
      });
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Bạn có chắc muốn giữ lại học viên ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  const getStudentHistory = (studentId: string) => {
    const studentRecords = records.filter(r => r.studentId === studentId);
    const history = [];
    if (studentRecords.length > 0) {
        const hk1 = studentRecords.find(r => r.term === 'HK1');
        const hk2 = studentRecords.find(r => r.term === 'HK2');
        const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);
        const currentClass = classes.find(c => c.id === (selectedStudent?.classId || ''));
        const currentYearName = years.find(y => y.id === currentClass?.yearId)?.name || 'Hiện tại';
        history.push({
            year: currentYearName,
            className: currentClass?.name || '---',
            hk1: hk1?.average || '-',
            hk2: hk2?.average || '-',
            final: avg > 0 ? avg.toFixed(1) : '-',
            rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
        });
    }
    return history;
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-4 py-2 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg hover:bg-amber-100 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={18} /> Rà soát trùng
            </button>
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm font-bold">
                <FileSpreadsheet size={18} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg font-bold text-base transition-all active:scale-95"><Plus size={20} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center text-lg">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[140px] bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[140px] bg-slate-50 outline-none focus:ring-2 focus:ring-blue-500" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <div className="text-slate-300">/</div>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold min-w-[180px] bg-slate-50 text-blue-800 outline-none focus:ring-2 focus:ring-blue-500" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all text-lg" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse table-fixed">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b-2 border-slate-300 uppercase tracking-tight text-sm">
              <tr>
                <th className="px-4 py-3 w-14 text-center">#</th>
                <th className="px-4 py-3 w-28">Mã HV</th>
                <th className="px-4 py-3 w-32">Tên Thánh</th>
                <th className="px-4 py-3 w-44">Họ & Tên Đệm</th>
                <th className="px-4 py-3 w-28">Tên</th>
                <th className="px-4 py-3 w-36 text-left">Ngày Sinh</th>
                <th className="px-4 py-3 w-52 text-left">SĐT Liên Hệ</th>
                <th className="px-4 py-3 w-36">Lớp</th>
                <th className="px-4 py-3 w-32 text-center">Tình Trạng</th>
                <th className="px-4 py-3 text-center w-28">Thao tác</th>
              </tr>
            </thead>
            <tbody className="text-lg text-slate-800 divide-y divide-slate-100">
              {filteredStudents.map((s, index) => {
                const { firstName, lastName } = splitName(s.fullName);
                return (
                <tr key={s.id} className="hover:bg-blue-50 transition-colors border-b border-slate-100">
                  <td className="px-4 py-2.5 text-center text-slate-500 font-bold text-sm">{index + 1}</td>
                  <td className="px-4 py-2.5 font-mono text-base font-bold text-slate-500">{s.id}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-700">{s.saintName}</td>
