import { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, CheckCircle2, FileSpreadsheet, AlertTriangle, Save, User, History, GitMerge, AlertCircle, ScrollText, X, Check } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time warning for duplicates
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  useEffect(() => {
    if (!showModal) return;

    if (inputName.trim().length > 2 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);

  const handleGradeChange = (gradeId: string) => {
    setSelectedGrade(gradeId);
    setSelectedClass('all'); 
  };

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds = selectedClass !== 'all' ? [selectedClass] : (selectedGrade !== 'all' ? classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id) : classesInYear.map(c => c.id));
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đủ Tên Thánh, Họ Tên và Ngày sinh.");

    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        if (!window.confirm("CẢNH BÁO: Thông tin này có thể bị trùng với học viên đã có. Bạn có chắc chắn muốn tạo mới không?")) return;
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? { ...s, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, status: inputStatus } : s));
        showToast("Cập nhật thành công!");
    } else {
        const prefix = selectedYear.slice(2, 4);
        const nextNum = (Math.max(...students.filter(s => s.id.startsWith(prefix)).map(s => parseInt(s.id.slice(2))), 0) + 1).toString().padStart(4, '0');
        const newId = `${prefix}${nextNum}`;
        const newStudent: Student = { id: newId, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''), status: inputStatus, birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: '' };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên ${newId}`);
    }
    setShowModal(false);
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Hệ thống sẽ giữ lại bản ghi ID: ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng khác. Tiếp tục?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  const getStudentHistory = (studentId: string) => {
    const studentRecords = records.filter(r => r.studentId === studentId);
    if (studentRecords.length === 0) return [];
    const hk1 = studentRecords.find(r => r.term === 'HK1');
    const hk2 = studentRecords.find(r => r.term === 'HK2');
    const avg = (hk1?.average && hk2?.average) ? (hk1.average + hk2.average) / 2 : (hk1?.average || hk2?.average || 0);
    const currentClass = classes.find(c => c.id === (students.find(s => s.id === studentId)?.classId || ''));
    return [{
        year: years.find(y => y.id === currentClass?.yearId)?.name || 'N/A',
        className: currentClass?.name || '---',
        hk1: hk1?.average || '-', hk2: hk2?.average || '-',
        final: avg > 0 ? avg.toFixed(1) : '-',
        rank: avg >= 8 ? 'Giỏi' : (avg >= 6.5 ? 'Khá' : (avg >= 5 ? 'TB' : 'Yếu'))
    }];
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
             <button onClick={scanDuplicates} className="flex items-center gap-2 px-4 py-2 bg-white border border-amber-300 text-amber-700 rounded-lg hover:bg-amber-50 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={18} /> Rà soát trùng
            </button>
            <button onClick={() => setShowModal(true)} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg font-bold transition-all active:scale-95"><Plus size={20} /> Thêm Mới</button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center text-lg">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none" value={selectedGrade} onChange={(e) => handleGradeChange(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse table-fixed">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b border-slate-300 uppercase text-xs">
              <tr>
                <th className="px-4 py-3 w-12 text-center">#</th>
                <th className="px-4 py-3 w-24">Mã</th>
                <th className="px-4 py-3 w-32">Tên Thánh</th>
                <th className="px-4 py-3">Họ Tên</th>
                <th className="px-4 py-3 w-32 text-left">Ngày Sinh</th>
                <th className="px-4 py-3 w-40 text-left">SĐT</th>
                <th className="px-4 py-3 w-32">Lớp</th>
                <th className="px-4 py-3 text-center w-24">Tình Trạng</th>
                <th className="px-4 py-3 text-center w-20">Sửa</th>
              </tr>
            </thead>
            <tbody className="text-base text-slate-800 divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-blue-50 transition-colors">
                  <td className="px-4 py-2.5 text-center text-slate-400 font-bold text-xs">{index + 1}</td>
                  <td className="px-4 py-2.5 font-mono text-sm font-bold text-slate-500">{s.id}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-700">{s.saintName}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-900">{s.fullName}</td>
                  <td className="px-4 py-2.5 text-left">
                    <div>{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                    <div className="text-[10px] text-slate-400 uppercase font-black">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</div>
                  </td>
                  <td className="px-4 py-2.5 text-blue-800 font-medium text-xs">
                    {s.fatherPhone || s.motherPhone || '---'}
                  </td>
                  <td className="px-4 py-2.5">
                    <span className="px-2 py-0.5 bg-blue-100 text-blue-800 rounded text-[10px] font-black uppercase whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <div className={`w-3 h-3 rounded-full mx-auto ${s.status === 'ACTIVE' ? 'bg-green-500' : (s.status === 'TRANSFERRED' ? 'bg-amber-500' : 'bg-red-500')}`} title={s.status}></div>
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg"><Edit size={18} /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* ADD/EDIT MODAL */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden border border-slate-300 animate-scale-in">
            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold shadow-lg">
                    {selectedStudent ? <User size={20}/> : <Plus size={20}/>}
                 </div>
                 <h3 className="font-black text-xl text-slate-800 uppercase tracking-tight">{selectedStudent ? 'Hồ Sơ Học Viên' : 'Thêm Học Viên Mới'}</h3>
              </div>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={24}/></button>
            </div>

            {/* DUPLICATE WARNING BOX */}
            {realtimeDuplicates.length > 0 && (
                <div className="m-4 bg-red-50 border-2 border-red-200 p-4 rounded-xl flex items-start gap-4 animate-pulse shadow-md">
                    <div className="p-2 bg-red-100 rounded-full text-red-600"><AlertTriangle size={24} /></div>
                    <div className="flex-1">
                        <h4 className="font-black text-red-800 uppercase text-sm mb-1 tracking-wider">Cảnh báo: Phát hiện học viên trùng lặp!</h4>
                        <p className="text-sm text-red-700 mb-2">Hệ thống phát hiện các học viên sau có cùng <b>Họ tên</b> và <b>Ngày sinh</b>:</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {realtimeDuplicates.map(d => (
                                <div key={d.id} className="bg-white/80 p-2 rounded-lg border border-red-100 text-xs flex justify-between items-center">
                                    <div><span className="font-bold text-red-900">{d.saintName} {d.fullName}</span> <span className="text-slate-500">({d.id})</span></div>
                                    <div className="px-2 py-0.5 bg-slate-100 rounded font-bold text-slate-600">{getClassName(d.classId)}</div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            <div className="flex border-b border-slate-200 bg-white">
                <button onClick={() => setModalTab('PROFILE')} className={`px-6 py-4 text-xs font-black uppercase tracking-widest transition-all ${modalTab === 'PROFILE' ? 'border-b-4 border-blue-600 text-blue-600 bg-blue-50/30' : 'text-slate-400 hover:bg-slate-50'}`}>Thông tin & Bí tích</button>
                <button onClick={() => setModalTab('HISTORY')} className={`px-6 py-4 text-xs font-black uppercase tracking-widest transition-all ${modalTab === 'HISTORY' ? 'border-b-4 border-blue-600 text-blue-600 bg-blue-50/30' : 'text-slate-400 hover:bg-slate-50'}`}>Lịch sử học tập</button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 bg-slate-50/30 custom-scrollbar">
                {modalTab === 'PROFILE' ? (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        <div className="space-y-6">
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest"><User size={14}/> Thông tin cơ bản</h4>
                                <div className="grid grid-cols-12 gap-5">
                                    <div className="col-span-12 md:col-span-4 relative">
                                        <label className="label-mini">Tên Thánh</label>
                                        <input className="input-mini font-bold" value={saintInput} onChange={(e) => {setSaintInput(e.target.value); setShowSaintSuggestions(true);}} onFocus={() => setShowSaintSuggestions(true)} onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)} placeholder="Giuse..." />
                                        {showSaintSuggestions && (
                                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded shadow-xl max-h-40 overflow-y-auto mt-1">
                                                {filteredSaints.map(s => (<div key={s.id} className="p-2 hover:bg-blue-50 cursor-pointer text-xs flex justify-between border-b" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}><span>{s.name}</span><span className="text-[9px] text-slate-400">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></div>))}
                                            </div>
                                        )}
                                    </div>
                                    <div className="col-span-12 md:col-span-8">
                                        <label className="label-mini">Họ và Tên</label>
                                        <input className="input-mini font-black text-slate-800" value={inputName} onChange={(e) => setInputName(e.target.value)} placeholder="NGUYỄN VĂN A" />
                                    </div>
                                    <div className="col-span-6 md:col-span-6">
                                        <label className="label-mini">Ngày sinh</label>
                                        <input type="date" className="input-mini font-bold" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                    </div>
                                    <div className="col-span-6 md:col-span-6">
                                        <label className="label-mini">Giới tính</label>
                                        <select className="input-mini font-bold" value={inputGender} onChange={(e) => setInputGender(e.target.value as any)}>
                                            <option value="Male">Nam</option>
                                            <option value="Female">Nữ</option>
                                        </select>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                             <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest"><ScrollText size={14}/> Bí Tích</h4>
                             <div className="space-y-6">
                                 <div className="p-4 rounded-xl bg-blue-50/50 border border-blue-100">
                                     <h5 className="font-black text-[10px] text-blue-600 uppercase mb-3">1. Bí tích Rửa Tội</h5>
                                     <div className="grid grid-cols-2 gap-4">
                                         <div><label className="label-mini">Ngày nhận</label><input type="date" className="input-mini" /></div>
                                         <div><label className="label-mini">Người đỡ đầu</label><input className="input-mini" placeholder="..." /></div>
                                     </div>
                                 </div>
                                 <div className="p-4 rounded-xl bg-green-50/50 border border-green-100">
                                     <h5 className="font-black text-[10px] text-green-600 uppercase mb-3">2. Rước Lễ Lần Đầu</h5>
                                     <div className="grid grid-cols-2 gap-4">
                                         <div><label className="label-mini">Ngày nhận</label><input type="date" className="input-mini" /></div>
                                         <div><label className="label-mini">Tại Giáo xứ</label><input className="input-mini" placeholder="..." /></div>
                                     </div>
                                 </div>
                             </div>
                        </div>
                    </div>
                ) : (
                    <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm min-h-[300px] flex flex-col items-center justify-center text-slate-400 italic">
                        <History size={48} className="mb-4 opacity-20"/>
                        <p>Dữ liệu lịch sử đang được tải hoặc chưa có sẵn cho học viên này.</p>
                    </div>
                )}
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-100 flex justify-end gap-3">
                <button onClick={() => setShowModal(false)} className="px-6 py-2.5 bg-white border border-slate-300 text-slate-600 rounded-xl font-bold hover:bg-slate-50 transition-all">Hủy bỏ</button>
                <button onClick={handleSaveStudent} className="px-10 py-2.5 bg-blue-600 text-white rounded-xl font-black shadow-lg hover:bg-blue-700 transition-all flex items-center gap-2 uppercase tracking-widest text-sm">
                    <Save size={18}/> Lưu hồ sơ
                </button>
            </div>
          </div>
        </div>
      )}

      {/* DEDUPLICATION MODAL */}
      {showDedupModal && (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
           <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col overflow-hidden border-4 border-amber-400">
              <div className="p-6 bg-amber-400 flex justify-between items-center">
                 <div className="flex items-center gap-3 text-amber-950">
                    <GitMerge size={28}/>
                    <div>
                        <h3 className="font-black text-xl uppercase tracking-tighter">Báo cáo rà soát trùng lặp</h3>
                        <p className="text-xs font-bold opacity-80 uppercase tracking-widest">Phát hiện {duplicateGroups.length} nhóm thông tin trùng</p>
                    </div>
                 </div>
                 <button onClick={() => setShowDedupModal(false)} className="p-2 hover:bg-amber-500 rounded-full transition-colors text-amber-950"><X size={24}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50">
                 {duplicateGroups.length > 0 ? (
                     <div className="space-y-8">
                         {duplicateGroups.map((group, gIdx) => (
                             <div key={group.key} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                                 <div className="px-4 py-2 bg-slate-100 border-b border-slate-200 flex justify-between items-center">
                                     <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nhóm trùng #{gIdx + 1}: {group.key.replace('|', ' sinh ngày ')}</span>
                                     <span className="px-2 py-0.5 bg-amber-100 text-amber-700 rounded-full text-[9px] font-black uppercase">{group.students.length} bản ghi</span>
                                 </div>
                                 <div className="divide-y divide-slate-100">
                                     {group.students.map(s => (
                                         <div key={s.id} className="p-4 flex justify-between items-center hover:bg-blue-50/30 transition-colors">
                                             <div className="flex items-center gap-4">
                                                 <div className="text-xs font-mono font-bold text-slate-400">{s.id}</div>
                                                 <div>
                                                     <div className="font-black text-slate-800 uppercase text-sm">{s.saintName} {s.fullName}</div>
                                                     <div className="text-[10px] text-slate-500 font-bold uppercase tracking-tight">Lớp: {getClassName(s.classId)}</div>
                                                 </div>
                                             </div>
                                             <button 
                                                onClick={() => handleMerge(group.key, s.id)}
                                                className="px-4 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 shadow-sm flex items-center gap-1 transition-all"
                                             >
                                                <Check size={12}/> Giữ lại bản ghi này
                                             </button>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         ))}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                        <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-4"><Check size={48}/></div>
                        <h4 className="font-black uppercase tracking-widest">Dữ liệu sạch!</h4>
                        <p className="text-sm italic">Không phát hiện học viên nào bị trùng thông tin.</p>
                     </div>
                 )}
              </div>
              <div className="p-4 bg-slate-100 border-t border-slate-200 text-center">
                 <p className="text-[10px] text-slate-500 font-bold italic uppercase">* Khi chọn "Giữ lại", hệ thống sẽ giữ học viên đó và xóa tất cả các học viên còn lại trong nhóm trùng này.</p>
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
        .label-mini { display: block; font-size: 0.65rem; font-weight: 900; color: #94a3b8; margin-bottom: 0.25rem; text-transform: uppercase; letter-spacing: 0.05em; }
        .input-mini { width: 100%; padding: 0.65rem 0.85rem; border: 1.5px solid #e2e8f0; border-radius: 0.85rem; outline: none; transition: all 0.2s; font-size: 0.9rem; background-color: #ffffff; }
        .input-mini:focus { border-color: #3b82f6; box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1); }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, CheckCircle2, FileSpreadsheet, AlertTriangle, Save, User, History, GitMerge, AlertCircle, ScrollText, X, Check, Phone } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Deduplication State
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time duplicate check
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  useEffect(() => {
    if (!showModal) return;
    if (inputName.trim().length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === inputName.trim().toLowerCase() && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds = selectedClass !== 'all' ? [selectedClass] : (selectedGrade !== 'all' ? classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id) : classesInYear.map(c => c.id));
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ các trường bắt buộc.");
    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        if (!window.confirm("Thông tin này đã tồn tại trong hệ thống. Bạn có chắc chắn muốn tạo thêm hồ sơ mới?")) return;
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? { ...s, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, status: inputStatus } : s));
        showToast("Cập nhật thành công!");
    } else {
        const prefix = selectedYear.slice(2, 4);
        const yearStudents = students.filter(s => s.id.startsWith(prefix));
        const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
        const newId = `${prefix}${nextNum}`;
        const newStudent: Student = { 
            id: newId, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, 
            classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''), 
            status: inputStatus, birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: '' 
        };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên ${newId}`);
    }
    setShowModal(false);
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Xác nhận giữ lại bản ghi ${survivorId} và xóa ${idsToDelete.length} bản ghi trùng?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp dữ liệu thành công!`);
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200">ĐANG HỌC</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200">CHUYỂN XỨ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200">NGHỈ HỌC</span>;
        default: return null;
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Quản Lý Học Viên</h2>
        <div className="flex gap-2">
            <button onClick={scanDuplicates} className="flex items-center gap-2 px-4 py-2 bg-white border border-amber-300 text-amber-700 rounded-lg hover:bg-amber-50 text-sm font-bold shadow-sm transition-all">
                <GitMerge size={18} /> Rà soát trùng
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg font-bold transition-all active:scale-95">
                <Plus size={20} /> Thêm Mới
            </button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên học viên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse table-fixed">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b border-slate-300 uppercase text-[11px] tracking-wider">
              <tr>
                <th className="px-4 py-3 w-12 text-center">#</th>
                <th className="px-4 py-3 w-24">Mã</th>
                <th className="px-4 py-3 w-36">Tên Thánh</th>
                <th className="px-4 py-3">Họ Tên</th>
                <th className="px-4 py-3 w-32 text-left">Ngày Sinh</th>
                <th className="px-4 py-3 w-24 text-left">Giới Tính</th>
                <th className="px-4 py-3 w-44 text-left">SĐT Liên Hệ</th>
                <th className="px-4 py-3 w-32">Lớp</th>
                <th className="px-4 py-3 text-center w-28">Tình Trạng</th>
                <th className="px-4 py-3 text-center w-20">Sửa</th>
              </tr>
            </thead>
            <tbody className="text-base text-slate-800 divide-y divide-slate-100">
              {filteredStudents.map((s, index) => (
                <tr key={s.id} className="hover:bg-blue-50 transition-colors">
                  <td className="px-4 py-2.5 text-center text-slate-400 font-bold text-xs">{index + 1}</td>
                  <td className="px-4 py-2.5 font-mono text-sm font-bold text-slate-500">{s.id}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-700 uppercase tracking-tighter">{s.saintName}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-900">{s.fullName}</td>
                  <td className="px-4 py-2.5 text-left font-medium">
                    {new Date(s.dob).toLocaleDateString('vi-VN')}
                  </td>
                  <td className="px-4 py-2.5 text-left">
                    <span className={`text-[11px] font-black uppercase ${s.gender === 'Male' ? 'text-blue-600' : 'text-pink-600'}`}>
                        {s.gender === 'Male' ? 'Nam' : 'Nữ'}
                    </span>
                  </td>
                  <td className="px-4 py-2.5 text-left">
                    <div className="flex flex-col gap-0.5 text-xs font-bold text-blue-700">
                        {s.fatherPhone && <span className="whitespace-nowrap">B: {s.fatherPhone}</span>}
                        {s.motherPhone && <span className="whitespace-nowrap">M: {s.motherPhone}</span>}
                        {!s.fatherPhone && !s.motherPhone && <span className="text-slate-300">---</span>}
                    </div>
                  </td>
                  <td className="px-4 py-2.5">
                    <span className="px-2 py-0.5 bg-blue-600 text-white rounded text-[10px] font-black uppercase whitespace-nowrap">{getClassName(s.classId)}</span>
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    {getStatusBadge(s.status)}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg transition-all" title="Xem & Sửa"><Edit size={18} /></button>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr><td colSpan={10} className="p-20 text-center text-slate-400 italic font-medium">Không tìm thấy dữ liệu phù hợp.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL HỒ SƠ 2 CỘT */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-6xl h-[90vh] flex flex-col overflow-hidden border border-slate-300 animate-scale-in">

            <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold shadow-lg">
                    {selectedStudent ? <User size={22}/> : <Plus size={22}/>}
                 </div>
                 <div>
                    <h3 className="font-black text-xl text-slate-800 uppercase tracking-tight">{selectedStudent ? 'Chi tiết Hồ Sơ' : 'Thêm Học Viên Mới'}</h3>
                    {selectedStudent && <p className="text-[10px] font-mono text-slate-500 uppercase tracking-widest font-bold">Mã số: {selectedStudent.id}</p>}
                 </div>
              </div>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400"><X size={24}/></button>
            </div>

            {/* CẢNH BÁO TRÙNG THỜI GIAN THỰC */}
            {realtimeDuplicates.length > 0 && (
                <div className="mx-6 mt-4 bg-red-50 border-2 border-red-200 p-4 rounded-xl flex items-start gap-4 animate-pulse shadow-md">
                    <div className="p-2 bg-red-100 rounded-full text-red-600"><AlertTriangle size={24} /></div>
                    <div className="flex-1">
                        <h4 className="font-black text-red-800 uppercase text-xs mb-1 tracking-wider">Cảnh báo: Dữ liệu bị trùng lặp!</h4>
                        <p className="text-sm text-red-700 mb-2">Hệ thống phát hiện học viên sau có cùng <b>Họ tên</b> và <b>Ngày sinh</b>:</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {realtimeDuplicates.map(d => (
                                <div key={d.id} className="bg-white/80 p-2 rounded-lg border border-red-100 text-xs flex justify-between items-center">
                                    <div><span className="font-bold text-red-950 uppercase">{d.saintName} {d.fullName}</span> <span className="text-slate-400">({d.id})</span></div>
                                    <div className="px-2 py-0.5 bg-slate-100 rounded-md font-black text-[9px] text-slate-600 uppercase">{getClassName(d.classId)}</div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            <div className="flex border-b border-slate-200 bg-white">
                <button onClick={() => setModalTab('PROFILE')} className={`px-8 py-4 text-xs font-black uppercase tracking-widest transition-all ${modalTab === 'PROFILE' ? 'border-b-4 border-blue-600 text-blue-600 bg-blue-50/30' : 'text-slate-400 hover:bg-slate-50'}`}>Hồ sơ cá nhân</button>
                <button onClick={() => setModalTab('HISTORY')} className={`px-8 py-4 text-xs font-black uppercase tracking-widest transition-all ${modalTab === 'HISTORY' ? 'border-b-4 border-blue-600 text-blue-600 bg-blue-50/30' : 'text-slate-400 hover:bg-slate-50'}`}>Lịch sử học tập</button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 bg-slate-50/30 custom-scrollbar">
                {modalTab === 'PROFILE' ? (
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

                        {/* CỘT 1: THÔNG TIN CÁ NHÂN & GIA ĐÌNH */}
                        <div className="lg:col-span-7 space-y-6">

                            {/* Block: Thông tin cá nhân */}
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest border-b pb-2"><User size={14} className="text-blue-500"/> 1. Thông tin học viên</h4>
                                <div className="grid grid-cols-12 gap-5">
                                    <div className="col-span-12 md:col-span-4 relative">
                                        <label className="label-mini">Tên Thánh <span className="text-red-500">*</span></label>
                                        <input className="input-mini font-bold" value={saintInput} onChange={(e) => {setSaintInput(e.target.value); setShowSaintSuggestions(true);}} onFocus={() => setShowSaintSuggestions(true)} onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)} placeholder="Giuse..." />
                                        {showSaintSuggestions && (
                                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-xl shadow-2xl max-h-40 overflow-y-auto mt-1 border-t-4 border-t-blue-600">
                                                {filteredSaints.map(s => (<div key={s.id} className="p-2.5 hover:bg-blue-50 cursor-pointer text-xs flex justify-between border-b last:border-0" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}><span>{s.name}</span><span className="text-[9px] text-slate-400 font-bold uppercase">{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></div>))}
                                            </div>
                                        )}
                                    </div>
                                    <div className="col-span-12 md:col-span-8">
                                        <label className="label-mini">Họ và Tên <span className="text-red-500">*</span></label>
                                        <input className="input-mini font-black text-slate-800" value={inputName} onChange={(e) => setInputName(e.target.value)} placeholder="NGUYỄN VĂN A" />
                                    </div>
                                    <div className="col-span-6 md:col-span-5">
                                        <label className="label-mini">Ngày sinh <span className="text-red-500">*</span></label>
                                        <input type="date" className="input-mini font-bold" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                    </div>
                                    <div className="col-span-6 md:col-span-3">
                                        <label className="label-mini">Giới tính</label>
                                        <select className="input-mini font-bold" value={inputGender} onChange={(e) => setInputGender(e.target.value as any)}>
                                            <option value="Male">Nam</option>
                                            <option value="Female">Nữ</option>
                                        </select>
                                    </div>
                                    <div className="col-span-12 md:col-span-4">
                                        <label className="label-mini">Tình trạng</label>
                                        <select className="input-mini font-black text-blue-700" value={inputStatus} onChange={(e) => setInputStatus(e.target.value as any)}>
                                            <option value="ACTIVE">ĐANG HỌC</option>
                                            <option value="TRANSFERRED">CHUYỂN XỨ</option>
                                            <option value="DROPPED">NGHỈ HỌC</option>
                                        </select>
                                    </div>
                                    <div className="col-span-12">
                                        <label className="label-mini">Nơi sinh</label>
                                        <input className="input-mini" defaultValue={selectedStudent?.birthPlace} placeholder="Xã/Huyện/Tỉnh..." />
                                    </div>
                                </div>
                            </div>

                            {/* Block: Gia đình & Liên hệ */}
                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest border-b pb-2"><Phone size={14} className="text-orange-500"/> 2. Gia đình & Liên hệ</h4>
                                <div className="space-y-4">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div><label className="label-mini">Họ tên Bố</label><input className="input-mini font-bold" defaultValue={selectedStudent?.fatherName} /></div>
                                        <div><label className="label-mini">SĐT Bố</label><input className="input-mini font-mono font-bold text-blue-700" defaultValue={selectedStudent?.fatherPhone} placeholder="09xxxx" /></div>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div><label className="label-mini">Họ tên Mẹ</label><input className="input-mini font-bold" defaultValue={selectedStudent?.motherName} /></div>
                                        <div><label className="label-mini">SĐT Mẹ</label><input className="input-mini font-mono font-bold text-blue-700" defaultValue={selectedStudent?.motherPhone} placeholder="09xxxx" /></div>
                                    </div>
                                    <div><label className="label-mini">Thuộc Giáo họ</label><input className="input-mini" defaultValue={selectedStudent?.parish} /></div>
                                    <div><label className="label-mini">Địa chỉ thường trú</label><input className="input-mini" defaultValue={selectedStudent?.address} placeholder="Số nhà, đường, thôn/xóm..." /></div>
                                </div>
                            </div>

                            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-4 flex items-center gap-2 tracking-widest border-b pb-2"><AlertCircle size={14} className="text-slate-400"/> 3. Ghi chú</h4>
                                <textarea className="input-mini h-20 resize-none" defaultValue={selectedStudent?.note} placeholder="Sức khỏe, hoàn cảnh đặc biệt..." />
                            </div>

                        </div>

                        {/* CỘT 2: HỒ SƠ BÍ TÍCH */}
                        <div className="lg:col-span-5 space-y-6">
                            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm h-full">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest border-b pb-2"><ScrollText size={16} className="text-purple-500"/> Hồ sơ Bí tích</h4>

                                <div className="space-y-6">
                                    {/* 1. Rửa tội */}
                                    <div className="p-4 rounded-xl bg-blue-50/50 border border-blue-100 relative">
                                        <div className="absolute top-0 right-0 w-1 h-full bg-blue-400 rounded-r-xl opacity-40"></div>
                                        <h5 className="font-black text-[11px] text-blue-700 uppercase mb-4 flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div> 1. Bí tích Rửa Tội</h5>
                                        <div className="grid grid-cols-1 gap-4">
                                            <div className="grid grid-cols-2 gap-3">
                                                <div><label className="label-mini text-[9px]">Ngày nhận</label><input type="date" className="input-mini py-1.5 text-xs font-bold" defaultValue={selectedStudent?.baptismDate} /></div>
                                                <div><label className="label-mini text-[9px]">Linh mục ban</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.baptismBy} /></div>
                                            </div>
                                            <div><label className="label-mini text-[9px]">Người đỡ đầu</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.baptismSponsor} /></div>
                                            <div><label className="label-mini text-[9px]">Tại Giáo xứ</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.baptismPlace} /></div>
                                        </div>
                                    </div>

                                    {/* 2. Rước lễ */}
                                    <div className="p-4 rounded-xl bg-green-50/50 border border-green-100 relative">
                                        <div className="absolute top-0 right-0 w-1 h-full bg-green-400 rounded-r-xl opacity-40"></div>
                                        <h5 className="font-black text-[11px] text-green-700 uppercase mb-4 flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div> 2. Rước Lễ Lần Đầu</h5>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div><label className="label-mini text-[9px]">Ngày nhận</label><input type="date" className="input-mini py-1.5 text-xs font-bold" defaultValue={selectedStudent?.eucharistDate} /></div>
                                            <div><label className="label-mini text-[9px]">Linh mục ban</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.eucharistBy} /></div>
                                        </div>
                                    </div>

                                    {/* 3. Thêm sức */}
                                    <div className="p-4 rounded-xl bg-rose-50/50 border border-rose-100 relative">
                                        <div className="absolute top-0 right-0 w-1 h-full bg-rose-400 rounded-r-xl opacity-40"></div>
                                        <h5 className="font-black text-[11px] text-rose-700 uppercase mb-4 flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-rose-500"></div> 3. Bí tích Thêm Sức</h5>
                                        <div className="grid grid-cols-1 gap-4">
                                            <div className="grid grid-cols-2 gap-3">
                                                <div><label className="label-mini text-[9px]">Ngày nhận</label><input type="date" className="input-mini py-1.5 text-xs font-bold" defaultValue={selectedStudent?.confirmationDate} /></div>
                                                <div><label className="label-mini text-[9px]">Cha/ĐGM ban</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.confirmationBy} /></div>
                                            </div>
                                            <div><label className="label-mini text-[9px]">Người đỡ đầu</label><input className="input-mini py-1.5 text-xs" defaultValue={selectedStudent?.confirmationSponsor} /></div>
                                        </div>
                                    </div>

                                    {/* 4. Bao đồng */}
                                    <div className="p-4 rounded-xl bg-amber-50/50 border border-amber-100 relative">
                                        <div className="absolute top-0 right-0 w-1 h-full bg-amber-400 rounded-r-xl opacity-40"></div>
                                        <h5 className="font-black text-[11px] text-amber-700 uppercase mb-3 flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div> 4. Tuyên Hứa / Bao Đồng</h5>
                                        <div><label className="label-mini text-[9px]">Ngày tuyên hứa</label><input type="date" className="input-mini py-1.5 text-xs font-bold" defaultValue={selectedStudent?.confirmationOathDate} /></div>
                                    </div>
                                </div>
                            </div>
                        </div>

                    </div>
                ) : (
                    <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col items-center justify-center text-slate-400 italic">
                        <History size={48} className="mb-4 opacity-10"/>
                        <p className="text-lg">Lịch sử học tập đang được cập nhật cho niên khóa tiếp theo.</p>
                    </div>
                )}
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                <button onClick={() => setShowModal(false)} className="px-8 py-2.5 bg-white border border-slate-300 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-all text-sm">Hủy bỏ</button>
                <button onClick={handleSaveStudent} className="px-12 py-2.5 bg-blue-600 text-white rounded-xl font-black shadow-lg hover:bg-blue-700 transition-all flex items-center gap-2 uppercase tracking-widest text-sm active:scale-95">
                    <Save size={18}/> Lưu hồ sơ
                </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL RÀ SOÁT TRÙNG */}
      {showDedupModal && (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
           <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col overflow-hidden border-4 border-amber-400">
              <div className="p-6 bg-amber-400 flex justify-between items-center shadow-lg">
                 <div className="flex items-center gap-4 text-amber-950">
                    <div className="p-2 bg-white/30 rounded-xl"><GitMerge size={32}/></div>
                    <div>
                        <h3 className="font-black text-2xl uppercase tracking-tighter leading-tight">Rà soát dữ liệu trùng lặp</h3>
                        <p className="text-xs font-bold opacity-80 uppercase tracking-widest">Phát hiện {duplicateGroups.length} trường hợp nghi vấn</p>
                    </div>
                 </div>
                 <button onClick={() => setShowDedupModal(false)} className="p-2 hover:bg-amber-500 rounded-full transition-colors text-amber-950 bg-white/20"><X size={24}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50">
                 {duplicateGroups.length > 0 ? (
                     <div className="space-y-8">
                         {duplicateGroups.map((group, gIdx) => (
                             <div key={group.key} className="bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden transition-all hover:shadow-xl">
                                 <div className="px-4 py-3 bg-slate-100 border-b border-slate-200 flex justify-between items-center">
                                     <div className="flex items-center gap-3">
                                         <span className="w-8 h-8 rounded-full bg-amber-200 flex items-center justify-center font-black text-amber-800 text-sm">#{gIdx + 1}</span>
                                         <span className="text-xs font-black text-slate-500 uppercase tracking-widest">{group.key.replace('|', ' • SINH NGÀY ')}</span>
                                     </div>
                                     <span className="px-3 py-1 bg-amber-500 text-white rounded-full text-[10px] font-black uppercase shadow-sm">{group.students.length} BẢN GHI TRÙNG</span>
                                 </div>
                                 <div className="divide-y divide-slate-100">
                                     {group.students.map(s => (
                                         <div key={s.id} className="p-4 flex justify-between items-center hover:bg-blue-50/50 transition-colors group">
                                             <div className="flex items-center gap-5">
                                                 <div className="text-xs font-mono font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded border border-slate-200">{s.id}</div>
                                                 <div>
                                                     <div className="font-black text-slate-800 uppercase text-base group-hover:text-blue-700 transition-colors">{s.saintName} {s.fullName}</div>
                                                     <div className="flex gap-4 mt-1">
                                                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-tight flex items-center gap-1"><History size={10}/> Lớp: {getClassName(s.classId)}</div>
                                                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-tight flex items-center gap-1"><Phone size={10}/> SĐT: {s.fatherPhone || s.motherPhone || 'N/A'}</div>
                                                     </div>
                                                 </div>
                                             </div>
                                             <button 
                                                onClick={() => handleMerge(group.key, s.id)}
                                                className="px-5 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 shadow-md hover:shadow-blue-200 flex items-center gap-2 transition-all active:scale-95"
                                             >
                                                <Check size={14}/> GIỮ LẠI
                                             </button>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         ))}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60 animate-fade-in">
                        <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 border-4 border-emerald-50 shadow-inner"><Check size={56}/></div>
                        <h4 className="font-black text-xl uppercase tracking-widest text-slate-600">Dữ liệu hoàn toàn sạch!</h4>
                        <p className="text-base italic mt-2">Không phát hiện bất kỳ học viên nào bị trùng lặp thông tin.</p>
                     </div>
                 )}
              </div>
              <div className="p-5 bg-slate-100 border-t border-slate-200 text-center">
                 <p className="text-[11px] text-slate-500 font-bold italic uppercase tracking-tighter">* CHÚ Ý: Khi nhấn "GIỮ LẠI", hệ thống sẽ lưu bản ghi đó và xóa vĩnh viễn các bản ghi còn lại trong nhóm trùng này.</p>
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
        .label-mini { display: block; font-size: 0.65rem; font-weight: 900; color: #94a3b8; margin-bottom: 0.25rem; text-transform: uppercase; letter-spacing: 0.05em; }
        .input-mini { width: 100%; padding: 0.7rem 1rem; border: 1.5px solid #e2e8f0; border-radius: 0.85rem; outline: none; transition: all 0.2s; font-size: 0.9rem; background-color: #ffffff; }
        .input-mini:focus { border-color: #3b82f6; box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1); }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade } from '../types';
import { Search, Plus, Edit, Trash2, CheckCircle2, FileSpreadsheet, AlertTriangle, Save, User, History, GitMerge, AlertCircle, ScrollText, X, Check, Phone, Fingerprint } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Deduplication States
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // Input States for Modal
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time duplicate check (Logic: Name + DOB)
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  useEffect(() => {
    if (!showModal) return;
    const cleanName = inputName.trim().toLowerCase();
    if (cleanName.length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === cleanName && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
          } else {
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds = selectedClass !== 'all' ? [selectedClass] : (selectedGrade !== 'all' ? classesInYear.filter(c => c.gradeId === selectedGrade).map(c => c.id) : classesInYear.map(c => c.id));
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, selectedGrade, classesInYear]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ các trường bắt buộc (Dấu *).");

    // Check duplicates before final save
    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        const confirmSave = window.confirm(`Hệ thống phát hiện ${realtimeDuplicates.length} học viên có cùng Họ tên và Ngày sinh. Bạn có chắc chắn muốn tạo thêm hồ sơ mới này không?`);
        if (!confirmSave) return;
    }

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? { ...s, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, status: inputStatus } : s));
        showToast("Đã cập nhật hồ sơ thành công!");
    } else {
        const prefix = selectedYear.slice(2, 4);
        const yearStudents = students.filter(s => s.id.startsWith(prefix));
        const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
        const newId = `${prefix}${nextNum}`;
        const newStudent: Student = { 
            id: newId, fullName: inputName, dob: inputDob, saintName: saintInput, gender: inputGender, 
            classId: selectedClass !== 'all' ? selectedClass : (availableClasses[0]?.id || ''), 
            status: inputStatus, birthPlace: '', fatherName: '', motherName: '', fatherPhone: '', motherPhone: '', parish: '', address: '' 
        };
        setStudents(prev => [...prev, newStudent]);
        showToast(`Đã thêm học viên mới: ${newId}`);
    }
    setShowModal(false);
  };

  // ADVANCED DEDUPLICATION LOGIC
  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      students.forEach(s => {
          // Identify key: Trimmed Lowercase Name + DOB
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups)
          .filter(([_, list]) => list.length > 1)
          .map(([key, list]) => ({ key, students: list }));

      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;

      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      const survivor = group.students.find(s => s.id === survivorId);

      if (window.confirm(`Xác nhận giữ lại hồ sơ [${survivor?.fullName} - ${survivorId}] và xóa vĩnh viễn ${idsToDelete.length} bản ghi trùng lặp khác?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp và làm sạch dữ liệu thành công!`);

          if (duplicateGroups.length <= 1) {
              setShowDedupModal(false);
          }
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200">ĐANG HỌC</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200">CHUYỂN XỨ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200">NGHỈ HỌC</span>;
        default: return null;
    }
  };

  return (
    <div className="p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className={`text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={24} />
              <span className="font-bold text-lg">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">QUẢN LÝ HỌC VIÊN</h2>
            <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200 uppercase tracking-widest">{students.length} hồ sơ</div>
        </div>
        <div className="flex gap-2">
            <button onClick={scanDuplicates} className="flex items-center gap-2 px-5 py-2.5 bg-white border border-amber-400 text-amber-700 rounded-xl hover:bg-amber-50 text-sm font-black shadow-sm transition-all active:scale-95 group">
                <GitMerge size={18} className="group-hover:rotate-12 transition-transform" /> RÀ SOÁT TRÙNG
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase tracking-wide text-sm">
                <Plus size={20} /> Thêm Mới
            </button>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-wrap gap-2 items-center">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
              <option value="all">Tất cả Khối</option>
              {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
            </select>
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
              <option value="all">Tất cả Lớp</option>
              {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm nhanh theo Tên Thánh, Họ tên học viên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
        <div className="overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse table-fixed">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b border-slate-300 uppercase text-[11px] tracking-wider">
              <tr>
                <th className="px-4 py-4 w-12 text-center">#</th>
                <th className="px-4 py-4 w-24">Mã</th>
