import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { Inventory } from './components/Inventory';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES, MOCK_TERM_CONFIGS, MOCK_INVENTORY } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade, TermConfig, InventoryItem } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // GLOBAL STATE
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);
  const [termConfigs, setTermConfigs] = useState<TermConfig[]>(MOCK_TERM_CONFIGS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'classes':
        return <Classes 
          classes={classes}
          setClasses={setClasses}
          students={students}
          years={years}
          grades={grades}
        />;
      case 'students':
        return <Students 
          students={students} 
          setStudents={setStudents} 
          classes={classes}
          years={years}
          records={records}
          grades={grades}
        />;
      case 'placement':
        return <ClassPlacement 
          students={students}
          setStudents={setStudents}
          classes={classes}
          years={years}
          grades={grades}
        />;
      case 'teachers':
        return <Teachers />;
      case 'attendance':
        return <Attendance 
          students={students}
          classes={classes}
          years={years}
          grades={grades}
          setRecords={setRecords}
          termConfigs={termConfigs}
        />;
      case 'grades':
        return <Grades 
          students={students}
          classes={classes}
          years={years}
          records={records}
          setRecords={setRecords}
          grades={grades}
        />;
      case 'inventory':
        return <Inventory 
          items={inventory}
          setItems={setInventory}
        />;
      case 'finance':
        return <Finance 
           transactions={transactions}
           setTransactions={setTransactions}
        />;
      case 'settings':
        return <Settings 
          years={years}
          setYears={setYears}
          classes={classes}
          setClasses={setClasses}
          grades={grades}
          setGrades={setGrades}
          termConfigs={termConfigs}
          setTermConfigs={setTermConfigs}
        />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
      />
      <main 
        className={`flex-1 transition-all duration-300 ease-in-out ${
          isSidebarCollapsed ? 'ml-20' : 'ml-64'
        }`}
      >
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

