                                    <div className="col-span-6 md:col-span-5">
                                        <label className="label-mini">Ngày sinh <span className="text-rose-500">*</span></label>
                                        <input type="date" className="input-mini font-black text-blue-800" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                    </div>
                                    <div className="col-span-6 md:col-span-3">
                                        <label className="label-mini">Giới tính</label>
                                        <select className="input-mini font-bold" value={inputGender} onChange={(e) => setInputGender(e.target.value as any)}>
                                            <option value="Male">Nam</option>
                                            <option value="Female">Nữ</option>
                                        </select>
                                    </div>
                                    <div className="col-span-12 md:col-span-4">
                                        <label className="label-mini">Tình trạng</label>
