                                    <div className="col-span-12">
                                        <label className="label-mini">Nơi sinh</label>
                                        <input className="input-mini" defaultValue={selectedStudent?.birthPlace} placeholder="Nơi sinh..." />
                                    </div>
                                </div>
                            </div>

                            <div className="bg-white p-4 md:p-6 rounded-2xl md:rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-4 flex items-center gap-2 tracking-widest border-b pb-3"><Phone size={16} className="text-orange-500"/> 2. GIA ĐÌNH</h4>
                                <div className="space-y-4">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="bg-slate-50 p-3 rounded-xl"><label className="label-mini">Họ tên Bố</label><input className="input-mini" defaultValue={selectedStudent?.fatherName} /></div>
                                        <div className="bg-slate-50 p-3 rounded-xl"><label className="label-mini">SĐT Bố</label><input className="input-mini font-mono font-bold" defaultValue={selectedStudent?.fatherPhone} placeholder="09xx..." /></div>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="bg-slate-50 p-3 rounded-xl"><label className="label-mini">Họ tên Mẹ</label><input className="input-mini" defaultValue={selectedStudent?.motherName} /></div>
                                        <div className="bg-slate-50 p-3 rounded-xl"><label className="label-mini">SĐT Mẹ</label><input className="input-mini font-mono font-bold" defaultValue={selectedStudent?.motherPhone} placeholder="09xx..." /></div>
                                    </div>
                                    <div><label className="label-mini">Địa chỉ</label><input className="input-mini" defaultValue={selectedStudent?.address} /></div>
                                </div>
                            </div>
                        </div>

                        <div className="lg:col-span-5 space-y-6">
                            <div className="bg-white p-4 md:p-7 rounded-2xl md:rounded-3xl border border-slate-200 shadow-sm">
                                <h4 className="font-black text-xs uppercase text-slate-400 mb-6 flex items-center gap-2 tracking-widest border-b pb-4"><ScrollText size={18} className="text-purple-500"/> HỒ SƠ BÍ TÍCH</h4>
                                <div className="space-y-6">
                                    <div className="p-4 rounded-2xl bg-blue-50/40 border border-blue-100">
                                        <h5 className="font-black text-[12px] text-blue-700 uppercase mb-3">1. Rửa Tội</h5>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div><label className="label-mini text-[10px]">Ngày</label><input type="date" className="input-mini py-1 text-sm" defaultValue={selectedStudent?.baptismDate} /></div>
                                            <div><label className="label-mini text-[10px]">Linh mục</label><input className="input-mini py-1 text-sm" defaultValue={selectedStudent?.baptismBy} /></div>
                                        </div>
                                    </div>
                                    <div className="p-4 rounded-2xl bg-emerald-50/40 border border-emerald-100">
                                        <h5 className="font-black text-[12px] text-emerald-700 uppercase mb-3">2. Rước Lễ</h5>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div><label className="label-mini text-[10px]">Ngày</label><input type="date" className="input-mini py-1 text-sm" defaultValue={selectedStudent?.eucharistDate} /></div>
                                            <div><label className="label-mini text-[10px]">Linh mục</label><input className="input-mini py-1 text-sm" defaultValue={selectedStudent?.eucharistBy} /></div>
                                        </div>
                                    </div>
                                     <div className="p-4 rounded-2xl bg-rose-50/40 border border-rose-100">
                                        <h5 className="font-black text-[12px] text-rose-700 uppercase mb-3">3. Thêm Sức</h5>
                                        <div className="grid grid-cols-2 gap-3">
                                            <div><label className="label-mini text-[10px]">Ngày</label><input type="date" className="input-mini py-1 text-sm" defaultValue={selectedStudent?.confirmationDate} /></div>
                                            <div><label className="label-mini text-[10px]">ĐGM/Cha</label><input className="input-mini py-1 text-sm" defaultValue={selectedStudent?.confirmationBy} /></div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                    </div>
                ) : (
                    <div className="bg-white p-8 md:p-12 rounded-3xl border border-slate-200 shadow-sm min-h-[300px] flex flex-col items-center justify-center text-slate-400 italic text-center">
                        <History size={48} className="mb-4 opacity-10"/>
                        <p className="text-sm font-bold text-slate-300">LỊCH SỬ HỌC TẬP</p>
                        <p className="text-xs mt-2">Dữ liệu đang cập nhật...</p>
                    </div>
                )}
            </div>

            <div className="p-4 md:p-8 border-t border-slate-200 bg-white flex justify-end gap-3 md:gap-4">
                <button onClick={() => setShowModal(false)} className="px-6 py-3 bg-white border border-slate-300 text-slate-600 rounded-2xl font-black hover:bg-slate-100 text-xs uppercase tracking-widest">Hủy</button>
                <button onClick={handleSaveStudent} className="px-8 md:px-16 py-3 bg-blue-600 text-white rounded-2xl font-black shadow-xl hover:bg-blue-700 flex items-center gap-2 uppercase tracking-widest text-xs active:scale-95">
                    <Save size={16}/> Lưu
                </button>
            </div>
          </div>
        </div>
      )}

      {/* DEDUP MODAL RESPONSIVE FIX */}
      {showDedupModal && (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex items-center justify-center p-2 md:p-4 backdrop-blur-lg animate-fade-in">
           <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden border-4 md:border-8 border-amber-400">
              <div className="p-4 md:p-8 bg-amber-400 flex justify-between items-center shadow-xl">
                 <div className="flex items-center gap-3 md:gap-5 text-amber-950">
                    <div className="p-2 md:p-3 bg-white/40 rounded-2xl"><GitMerge size={24} className="md:w-10 md:h-10"/></div>
                    <div>
                        <h3 className="font-black text-lg md:text-3xl uppercase tracking-tighter leading-tight">Rà soát trùng lặp</h3>
                        <p className="text-[10px] md:text-sm font-black opacity-80 uppercase tracking-widest">Phát hiện {duplicateGroups.length} nhóm</p>
                    </div>
                 </div>
                 <button onClick={() => setShowDedupModal(false)} className="p-2 hover:bg-amber-500 rounded-full transition-colors text-amber-950 bg-white/20"><X size={24}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-4 md:p-10 custom-scrollbar bg-slate-50/50">
                 {duplicateGroups.length > 0 ? (
                     <div className="space-y-6 md:space-y-12">
                         {duplicateGroups.map((group, gIdx) => (
                             <div key={group.key} className="bg-white rounded-2xl md:rounded-[2rem] shadow-lg border-2 border-amber-100 overflow-hidden">
                                 <div className="px-4 py-3 md:px-6 md:py-4 bg-amber-50 border-b border-amber-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-2">
                                     <div className="flex items-center gap-3 md:gap-4">
                                         <span className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-amber-200 flex items-center justify-center font-black text-amber-800 text-sm md:text-lg shadow-sm border border-amber-300">#{gIdx + 1}</span>
                                         <span className="text-xs md:text-sm font-black text-slate-600 uppercase tracking-wider">
                                             {group.key.split('|')[0]} <span className="hidden md:inline mx-3 opacity-30">•</span> <br className="md:hidden"/>
                                             <span className="text-blue-800 font-black">{new Date(group.key.split('|')[1]).toLocaleDateString('vi-VN')}</span>
                                         </span>
                                     </div>
                                 </div>
                                 <div className="divide-y divide-slate-100">
                                     {group.students.map(s => (
                                         <div key={s.id} className="p-4 md:p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 hover:bg-blue-50/50 transition-colors">
                                             <div className="flex items-center gap-4 md:gap-6 w-full">
                                                 <div className="text-xs font-mono font-black text-slate-400 bg-slate-100 px-2 py-1 md:px-3 md:py-1.5 rounded-xl border border-slate-200">ID: {s.id}</div>
                                                 <div className="flex-1">
                                                     <div className="font-black text-slate-800 uppercase text-sm md:text-lg leading-tight mb-1">{s.saintName} {s.fullName}</div>
                                                     <div className="text-[10px] md:text-[11px] text-slate-500 font-black uppercase tracking-tight">LỚP: {getClassName(s.classId)}</div>
                                                 </div>
                                             </div>
                                             <button 
                                                onClick={() => handleMerge(group.key, s.id)}
                                                className="w-full md:w-auto px-6 py-2 md:px-8 md:py-3 bg-blue-600 text-white rounded-xl md:rounded-2xl text-[10px] md:text-[11px] font-black uppercase tracking-widest hover:bg-blue-700 shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95"
                                             >
                                                <Check size={14} strokeWidth={4}/> GIỮ LẠI
                                             </button>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         ))}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                        <div className="w-20 h-20 md:w-28 md:h-28 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 border-8 border-emerald-50 shadow-inner"><Check size={40} strokeWidth={3}/></div>
                        <h4 className="font-black text-lg md:text-2xl uppercase tracking-widest text-slate-600">DỮ LIỆU SẠCH</h4>
                     </div>
                 )}
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }

        .label-mini { display: block; font-size: 0.65rem; font-weight: 900; color: #94a3b8; margin-bottom: 0.35rem; text-transform: uppercase; letter-spacing: 0.08em; }
        .input-mini { width: 100%; padding: 0.6rem 1rem; border: 2px solid #f1f5f9; border-radius: 1rem; outline: none; transition: all 0.2s; font-size: 0.9rem; background-color: #ffffff; color: #1e293b; }
        .input-mini:focus { border-color: #3b82f6; background-color: #fff; box-shadow: 0 4px 12px -4px rgba(59, 130, 246, 0.2); }
