};

import React, { useState } from 'react';
import { Wallet, TrendingUp, TrendingDown, Plus, Minus, PieChart as PieChartIcon, FileSpreadsheet, Calendar, AlignLeft, Banknote } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Transaction } from '../types';

interface FinanceProps {
    transactions: Transaction[];
    setTransactions: (t: Transaction[]) => void;
}

export const Finance: React.FC<FinanceProps> = ({ transactions, setTransactions }) => {
  const [amountStr, setAmountStr] = useState(''); // Store formatted string for input
  const [description, setDescription] = useState('');
  const [note, setNote] = useState('');
  const [type, setType] = useState<'INCOME'|'EXPENSE'>('INCOME');

  const totalIncome = transactions.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const data = [
    { name: 'Tổng Thu', value: totalIncome },
    { name: 'Tổng Chi', value: totalExpense },
  ];
  const COLORS = ['#10b981', '#ef4444'];

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
  };

  // Helper to format string with dots: 1000000 -> 1.000.000
  const formatNumberWithDots = (val: string) => {
    const rawValue = val.replace(/\D/g, ''); // Remove non-digits
    return rawValue.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setAmountStr(formatNumberWithDots(e.target.value));
  };

  const handleAddTransaction = () => {
      const rawAmount = parseInt(amountStr.replace(/\./g, ''), 10);
      if (!rawAmount || !description) return alert("Vui lòng nhập số tiền và nội dung");

      const newTx: Transaction = {
          id: `T${Date.now()}`,
          date: new Date().toISOString().split('T')[0],
          type: type,
          amount: rawAmount,
          description: description,
          note: note
      };

      setTransactions([newTx, ...transactions]);

      // Reset form
      setAmountStr('');
      setDescription('');
      setNote('');
  };

  const handleExportExcel = () => {
    const headers = ["ID", "Ngày", "Loại", "Số tiền", "Nội dung", "Ghi chú"];
    const rows = transactions.map(t => [
      t.id,
      t.date,
      t.type === 'INCOME' ? 'THU' : 'CHI',
      t.amount,
      `"${t.description}"`, 
      `"${t.note || ''}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "so_quy_giao_ly.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-4 md:p-6 h-screen overflow-y-auto bg-slate-50">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">Thủ Quỹ & Tài Chính</h2>
        <button 
          onClick={handleExportExcel}
          className="flex items-center gap-2 px-3 py-2 bg-green-600 text-white rounded-lg shadow hover:bg-green-700 transition-colors text-sm font-bold"
        >
          <FileSpreadsheet size={16} /> <span className="hidden md:inline">Xuất Excel</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 mb-8">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Wallet className="absolute right-4 top-4 opacity-20 w-24 h-24" />
          <p className="text-blue-100 mb-1 text-sm font-bold uppercase tracking-wider">Tổng quỹ hiện tại</p>
          <h3 className="text-3xl font-black tracking-tight">{formatCurrency(balance)}</h3>
          <p className="text-[10px] text-blue-200 mt-4 opacity-80 uppercase font-bold tracking-widest">Cập nhật: Hôm nay</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col justify-center">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-green-100 rounded-lg text-green-600">
               <TrendingUp size={20} />
            </div>
            <p className="text-slate-500 font-bold text-xs uppercase tracking-wider">Tổng Thu (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-black text-slate-800">{formatCurrency(totalIncome)}</h3>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col justify-center">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 rounded-lg text-red-600">
               <TrendingDown size={20} />
            </div>
            <p className="text-slate-500 font-bold text-xs uppercase tracking-wider">Tổng Chi (Năm nay)</p>
          </div>
          <h3 className="text-2xl font-black text-slate-800">{formatCurrency(totalExpense)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6 md:space-y-8">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-80 flex flex-col">
              <div className="flex items-center gap-2 mb-2">
                <PieChartIcon className="text-slate-400" size={20} />
                <h3 className="font-bold text-lg text-slate-800">Biểu Đồ Thu Chi</h3>
              </div>
              <div className="flex-1 w-full h-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={data}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {data.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => formatCurrency(value as number)} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h3 className="font-bold text-lg mb-4 text-slate-800">Tạo Giao Dịch Mới</h3>
            <div className="space-y-4">
                <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
                <button 
                    onClick={() => setType('INCOME')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-bold flex justify-center gap-2 items-center transition-all ${type === 'INCOME' ? 'bg-white text-green-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Plus size={16}/> Thu
                </button>
                <button 
                    onClick={() => setType('EXPENSE')}
                    className={`flex-1 py-2 rounded-md shadow text-sm font-bold flex justify-center gap-2 items-center transition-all ${type === 'EXPENSE' ? 'bg-white text-red-600' : 'text-slate-500 hover:bg-white/50'}`}
                >
                    <Minus size={16}/> Chi
                </button>
                </div>

                <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Số tiền (VNĐ)</label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-mono font-bold text-blue-700" 
                    placeholder="0" 
                    value={amountStr}
                    onChange={handleAmountChange}
                />
                </div>

                <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Nội dung <span className="text-red-500">*</span></label>
                <input 
                    type="text" 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-medium" 
                    placeholder="VD: Thu tiền sách..." 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                </div>

                <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Ghi chú</label>
                <textarea 
                    className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-20 text-sm" 
                    placeholder="..." 
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                ></textarea>
                </div>

                <button 
                    onClick={handleAddTransaction}
                    className="w-full py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 uppercase text-sm tracking-wider"
                >
                Lưu Giao Dịch
                </button>
            </div>
            </div>
        </div>

        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit flex flex-col">
          <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50/50">
            <h3 className="font-bold text-lg text-slate-800">Lịch Sử Giao Dịch</h3>
          </div>

          {/* MOBILE: CARD LIST */}
          <div className="md:hidden p-4 space-y-3 max-h-[600px] overflow-y-auto">
             {transactions.map(t => (
                 <div key={t.id} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex flex-col gap-2 relative">
                     <div className={`absolute top-4 right-4 text-xs font-black px-2 py-1 rounded ${t.type === 'INCOME' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                         {t.type === 'INCOME' ? '+ THU' : '- CHI'}
                     </div>
                     <div className="text-[10px] text-slate-400 font-bold flex items-center gap-1">
                         <Calendar size={12}/> {t.date}
                     </div>
                     <div className="pr-16">
                         <h4 className="font-bold text-slate-800 text-sm">{t.description}</h4>
                         {t.note && <p className="text-xs text-slate-500 italic mt-0.5">{t.note}</p>}
                     </div>
                     <div className="pt-2 mt-1 border-t border-slate-50 flex items-center gap-2">
                         <div className="p-1.5 rounded-full bg-slate-100 text-slate-500"><Banknote size={16}/></div>
                         <span className={`text-lg font-mono font-black ${t.type === 'INCOME' ? 'text-green-600' : 'text-red-600'}`}>
                             {formatCurrency(t.amount)}
                         </span>
                     </div>
                 </div>
             ))}
          </div>

          {/* DESKTOP: TABLE */}
          <div className="hidden md:block overflow-x-auto max-h-[800px] custom-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-white shadow-sm border-b border-slate-200 z-10">
                <tr className="bg-slate-50 text-slate-600 text-xs uppercase tracking-wider font-bold">
                  <th className="px-4 py-3">Ngày</th>
                  <th className="px-4 py-3">Nội dung</th>
                  <th className="px-4 py-3 text-right">Số tiền</th>
                  <th className="px-4 py-3 text-center">Loại</th>
                </tr>
              </thead>
              <tbody className="">
                {transactions.map((t) => (
                  <tr key={t.id} className="hover:bg-slate-50 border-b border-slate-100 text-sm last:border-0">
                    <td className="px-4 py-3 text-slate-500 text-sm font-medium whitespace-nowrap">{t.date}</td>
                    <td className="px-4 py-3">
                      <div className="font-bold text-slate-800 text-sm">{t.description}</div>
                      <div className="text-xs text-slate-400 mt-0.5">{t.note}</div>
                    </td>
                    <td className="px-4 py-3 text-right font-mono font-bold text-slate-700 text-base">
                      {formatCurrency(t.amount)}
                    </td>
                    <td className="px-4 py-3 text-center">
                       {t.type === 'INCOME' ? (
                         <span className="px-2 py-1 bg-green-100 text-green-700 rounded text-[10px] font-black uppercase">Thu</span>
                       ) : (
                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-[10px] font-black uppercase">Chi</span>
                       )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { InventoryItem } from '../types';
import { Package, Search, Plus, Minus, AlertTriangle, Edit, Trash2, CheckCircle2, History, TrendingUp, AlertCircle, Shirt, Book, Hexagon } from 'lucide-react';

interface InventoryProps {
    items: InventoryItem[];
    setItems: (items: InventoryItem[]) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ items, setItems }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [toast, setToast] = useState<string | null>(null);

  // Modals
  const [showItemModal, setShowItemModal] = useState(false);
  const [showAdjustModal, setShowAdjustModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);

  // Form States
  const [newItemName, setNewItemName] = useState('');
  const [newItemCategory, setNewItemCategory] = useState<'BOOK' | 'UNIFORM' | 'SCARF' | 'OTHER'>('BOOK');
  const [newItemQty, setNewItemQty] = useState(0);
  const [newItemMin, setNewItemMin] = useState(10);
  const [newItemUnit, setNewItemUnit] = useState('Cái');
  const [newItemPriceStr, setNewItemPriceStr] = useState('0'); // Format as string for dots

  const [adjustQty, setAdjustQty] = useState(1);
  const [adjustType, setAdjustType] = useState<'IMPORT' | 'EXPORT'>('IMPORT');
  const [adjustReason, setAdjustReason] = useState('');

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Helper to format string with dots: 1000000 -> 1.000.000
  const formatNumberWithDots = (val: string) => {
    const rawValue = val.replace(/\D/g, ''); // Remove non-digits
    return rawValue.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCat = filterCategory === 'all' || item.category === filterCategory;
      return matchSearch && matchCat;
    });
  }, [items, searchTerm, filterCategory]);

  const stats = useMemo(() => {
    const totalItems = items.length;
    const totalQty = items.reduce((acc, i) => acc + i.quantity, 0);
    const lowStock = items.filter(i => i.quantity <= i.minQuantity).length;
    const totalValue = items.reduce((acc, i) => acc + (i.quantity * i.price), 0);
    return { totalItems, totalQty, lowStock, totalValue };
  }, [items]);

  const formatCurrency = (val: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(val);

  const handleOpenEdit = (item: InventoryItem) => {
    setSelectedItem(item);
    setNewItemName(item.name);
    setNewItemCategory(item.category);
    setNewItemQty(item.quantity);
    setNewItemMin(item.minQuantity);
    setNewItemUnit(item.unit);
    setNewItemPriceStr(formatNumberWithDots(item.price.toString()));
    setShowItemModal(true);
  };

  const handleOpenAdd = () => {
    setSelectedItem(null);
    setNewItemName('');
    setNewItemCategory('BOOK');
    setNewItemQty(0);
    setNewItemMin(10);
    setNewItemUnit('Cái');
    setNewItemPriceStr('0');
    setShowItemModal(true);
  };

  const handleSaveItem = () => {
    if (!newItemName) return alert('Vui lòng nhập tên vật tư');

    const rawPrice = parseInt(newItemPriceStr.replace(/\./g, ''), 10) || 0;

    if (selectedItem) {
        const updated = items.map(i => i.id === selectedItem.id ? {
            ...i,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty,
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: rawPrice
        } : i);
        setItems(updated);
        showToast('Đã cập nhật thông tin vật tư!');
    } else {
        const newItem: InventoryItem = {
            id: `INV${Date.now()}`,
            name: newItemName,
            category: newItemCategory,
            quantity: newItemQty,
            minQuantity: newItemMin,
            unit: newItemUnit,
            price: rawPrice
        };
        setItems([...items, newItem]);
        showToast('Đã thêm vật tư mới thành công!');
    }
    setShowItemModal(false);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Bạn có chắc muốn xóa vật tư này không?")) {
          setItems(items.filter(i => i.id !== id));
          showToast('Đã xóa vật tư!');
      }
  };

  const handleOpenAdjust = (item: InventoryItem) => {
      setSelectedItem(item);
      setAdjustQty(1);
      setAdjustType('IMPORT');
      setAdjustReason('');
      setShowAdjustModal(true);
  };

  const handleExecuteAdjust = () => {
      if (!selectedItem) return;
      if (adjustQty <= 0) return alert("Số lượng phải lớn hơn 0");

      const delta = adjustType === 'IMPORT' ? adjustQty : -adjustQty;
      const newQty = selectedItem.quantity + delta;

      if (newQty < 0) return alert("Không thể xuất quá số lượng tồn kho!");

      const updated = items.map(i => i.id === selectedItem.id ? { ...i, quantity: newQty } : i);
      setItems(updated);
      showToast(`Đã ${adjustType === 'IMPORT' ? 'nhập' : 'xuất'} kho thành công!`);
      setShowAdjustModal(false);
  };

  const getCategoryLabel = (cat: string) => {
      switch(cat) {
          case 'BOOK': return { label: 'Sách', icon: <Book size={14}/>, color: 'text-blue-600 bg-blue-50 border-blue-200' };
          case 'UNIFORM': return { label: 'Đồng phục', icon: <Shirt size={14}/>, color: 'text-indigo-600 bg-indigo-50 border-indigo-200' };
          case 'SCARF': return { label: 'Khăn quàng', icon: <Hexagon size={14}/>, color: 'text-orange-600 bg-orange-50 border-orange-200' };
          default: return { label: 'Khác', icon: <Package size={14}/>, color: 'text-slate-600 bg-slate-50 border-slate-200' };
      }
  };

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-100/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Kho & Vật Tư</h2>
            <p className="text-slate-500 text-sm">Quản lý sách, đồng phục và tài sản chung</p>
        </div>
        <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm font-bold transition-all text-sm">
            <Plus size={18} /> <span className="hidden sm:inline">Thêm Mới</span>
        </button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4 mb-6">
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-2 md:p-3 bg-blue-100 text-blue-600 rounded-full"><Package size={20}/></div>
              <div>
                  <div className="text-[10px] md:text-xs text-slate-500 font-bold uppercase">Tổng Danh Mục</div>
                  <div className="text-lg md:text-xl font-bold text-slate-800">{stats.totalItems}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-2 md:p-3 bg-emerald-100 text-emerald-600 rounded-full"><TrendingUp size={20}/></div>
              <div>
                  <div className="text-[10px] md:text-xs text-slate-500 font-bold uppercase">Tổng Giá Trị</div>
                  <div className="text-lg md:text-xl font-bold text-slate-800">{formatCurrency(stats.totalValue)}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
              <div className="p-2 md:p-3 bg-amber-100 text-amber-600 rounded-full"><AlertTriangle size={20}/></div>
              <div>
                  <div className="text-[10px] md:text-xs text-slate-500 font-bold uppercase">Sắp Hết Hàng</div>
                  <div className={`text-lg md:text-xl font-bold ${stats.lowStock > 0 ? 'text-amber-600' : 'text-slate-800'}`}>{stats.lowStock}</div>
              </div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center gap-3">
               <div className="p-2 md:p-3 bg-purple-100 text-purple-600 rounded-full"><History size={20}/></div>
               <div>
                  <div className="text-[10px] md:text-xs text-slate-500 font-bold uppercase">Tổng Số Lượng</div>
                  <div className="text-lg md:text-xl font-bold text-slate-800">{stats.totalQty}</div>
               </div>
          </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-4 items-center">
         <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Tìm tên vật tư, mã..." 
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
            />
         </div>
         <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0 hide-scrollbar">
             {['all', 'BOOK', 'UNIFORM', 'SCARF', 'OTHER'].map(cat => (
                 <button 
                    key={cat}
                    onClick={() => setFilterCategory(cat)}
                    className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all border ${filterCategory === cat ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                 >
                     {cat === 'all' ? 'Tất cả' : cat === 'BOOK' ? 'Sách' : cat === 'UNIFORM' ? 'Đồng phục' : cat === 'SCARF' ? 'Khăn' : 'Khác'}
                 </button>
             ))}
         </div>
      </div>

      <div className="bg-white md:rounded-xl md:shadow-sm md:border md:border-slate-300 flex-1 overflow-hidden flex flex-col bg-transparent">

          {/* MOBILE: CARD VIEW */}
          <div className="md:hidden overflow-y-auto h-full space-y-3 pb-20">
              {filteredItems.map(item => {
                  const catInfo = getCategoryLabel(item.category);
                  const isLowStock = item.quantity <= item.minQuantity;
                  return (
                      <div key={item.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-3">
                          <div className="flex justify-between items-start">
                              <div className="flex items-start gap-3">
                                  <div className={`p-2 rounded-lg border ${catInfo.color}`}>
                                      {catInfo.icon}
                                  </div>
                                  <div>
                                      <h3 className="font-bold text-slate-800 text-sm">{item.name}</h3>
                                      <span className="text-[10px] text-slate-400 font-mono">{item.id}</span>
                                  </div>
                              </div>
                              <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-[10px] font-bold uppercase ${isLowStock ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'}`}>
                                  {isLowStock ? 'Sắp hết' : 'Sẵn sàng'}
                              </span>
                          </div>

                          <div className="flex justify-between items-end border-t border-slate-50 pt-3">
                               <div>
                                   <div className="text-[10px] text-slate-500 font-bold uppercase">Tồn kho</div>
                                   <div className={`text-xl font-bold ${isLowStock ? 'text-red-600' : 'text-slate-800'}`}>
                                       {item.quantity} <span className="text-xs text-slate-400 font-normal">{item.unit}</span>
                                   </div>
                               </div>
                               <div className="text-right">
                                   <div className="text-[10px] text-slate-500 font-bold uppercase">Đơn giá</div>
                                   <div className="text-sm font-mono font-bold text-blue-600">{formatCurrency(item.price)}</div>
                               </div>
                          </div>

                          <div className="flex gap-2 mt-1">
                              <button onClick={() => handleOpenAdjust(item)} className="flex-1 py-2 text-xs font-bold bg-slate-50 text-blue-600 rounded-lg border border-slate-200 hover:bg-blue-50">Nhập/Xuất</button>
                              <button onClick={() => handleOpenEdit(item)} className="p-2 text-slate-500 bg-slate-50 border border-slate-200 rounded-lg"><Edit size={16}/></button>
                          </div>
                      </div>
                  );
              })}
          </div>

          {/* DESKTOP: TABLE VIEW */}
          <div className="hidden md:block overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 text-slate-600 text-xs uppercase sticky top-0 z-10">
                      <tr>
                          <th className="px-3 py-2 w-16 text-center border-b border-slate-300">#</th>
                          <th className="px-3 py-2 border-b border-slate-300">Tên Vật Tư</th>
                          <th className="px-3 py-2 border-b border-slate-300">Phân Loại</th>
                          <th className="px-3 py-2 text-right border-b border-slate-300">Đơn Giá</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300">Tồn Kho</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300">Trạng Thái</th>
                          <th className="px-3 py-2 text-center border-b border-slate-300 w-32">Thao Tác</th>
                      </tr>
                  </thead>
                  <tbody className="text-sm">
                      {filteredItems.map((item, idx) => {
                          const catInfo = getCategoryLabel(item.category);
                          const isLowStock = item.quantity <= item.minQuantity;
                          return (
                              <tr key={item.id} className="hover:bg-slate-50 border-b border-slate-200 last:border-0 transition-colors">
                                  <td className="px-3 py-2 text-center text-slate-400 font-mono text-xs">{idx + 1}</td>
                                  <td className="px-3 py-2">
                                      <div className="font-bold text-slate-800">{item.name}</div>
                                      <div className="text-[10px] text-slate-400 font-mono">{item.id}</div>
                                  </td>
                                  <td className="px-3 py-2">
                                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold border ${catInfo.color}`}>
                                          {catInfo.icon} {catInfo.label}
                                      </span>
                                  </td>
                                  <td className="px-3 py-2 text-right font-bold text-slate-600">{formatCurrency(item.price)}</td>
                                  <td className="px-3 py-2 text-center">
                                      <span className={`text-base font-bold ${isLowStock ? 'text-red-600' : 'text-slate-800'}`}>{item.quantity}</span>
                                      <span className="text-xs text-slate-400 ml-1">{item.unit}</span>
                                  </td>
                                  <td className="px-3 py-2 text-center">
                                      {item.quantity === 0 ? (
                                          <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">Hết hàng</span>
                                      ) : isLowStock ? (
                                        <div className="flex items-center justify-center gap-1 text-amber-600 font-bold text-xs">
                                            <AlertCircle size={14}/> Sắp hết
                                        </div>
                                      ) : (
                                          <span className="text-green-600 font-bold text-xs">Sẵn sàng</span>
                                      )}
                                  </td>
                                  <td className="px-3 py-2 text-center">
                                      <div className="flex justify-center gap-1">
                                          <button onClick={() => handleOpenAdjust(item)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Nhập/Xuất kho">
                                              <History size={16}/>
                                          </button>
                                          <button onClick={() => handleOpenEdit(item)} className="p-1.5 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors" title="Chỉnh sửa">
                                              <Edit size={16}/>
                                          </button>
                                          <button onClick={() => handleDelete(item.id)} className="p-1.5 text-red-500 hover:bg-red-100 rounded-lg transition-colors" title="Xóa">
                                              <Trash2 size={16}/>
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {showItemModal && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-lg animate-scale-in overflow-hidden">
                  <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                      <h3 className="font-bold text-lg text-slate-800">{selectedItem ? 'Cập Nhật Vật Tư' : 'Thêm Vật Tư Mới'}</h3>
                      <button onClick={() => setShowItemModal(false)}><div className="p-1 hover:bg-slate-200 rounded-full"><Minus size={20} className="rotate-45"/></div></button>
                  </div>
                  <div className="p-6 space-y-4 overflow-y-auto max-h-[80vh]">
                      <div>
                          <label className="label-text">Tên vật tư <span className="text-red-500">*</span></label>
                          <input type="text" className="input-field font-bold" value={newItemName} onChange={e => setNewItemName(e.target.value)} placeholder="VD: Sách Khai Tâm..." autoFocus />
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Phân loại</label>
                              <select className="input-field" value={newItemCategory} onChange={e => setNewItemCategory(e.target.value as any)}>
                                  <option value="BOOK">Sách Giáo Lý</option>
                                  <option value="SCARF">Khăn Quàng</option>
                                  <option value="UNIFORM">Đồng Phục</option>
                                  <option value="OTHER">Khác</option>
                              </select>
                          </div>
                          <div>
                              <label className="label-text">Đơn vị tính</label>
                              <input type="text" className="input-field" value={newItemUnit} onChange={e => setNewItemUnit(e.target.value)} placeholder="Cái, Cuốn..." />
                          </div>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="label-text">Số lượng ban đầu</label>
                              <input type="number" className="input-field" value={newItemQty} onChange={e => setNewItemQty(Number(e.target.value))} />
                          </div>
                          <div>
                              <label className="label-text">Đơn giá (VNĐ)</label>
                              <input 
                                type="text" 
                                className="input-field font-mono font-bold text-blue-700" 
                                value={newItemPriceStr} 
                                onChange={e => setNewItemPriceStr(formatNumberWithDots(e.target.value))} 
                              />
                          </div>
                      </div>
                      <div>
                          <label className="label-text text-amber-600">Mức báo sắp hết hàng (Min)</label>
                          <input type="number" className="input-field border-amber-200 focus:border-amber-500" value={newItemMin} onChange={e => setNewItemMin(Number(e.target.value))} />
                          <p className="text-[10px] text-slate-400 mt-1">Hệ thống sẽ cảnh báo khi số lượng thấp hơn mức này.</p>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowItemModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleSaveItem} className="btn-primary">Lưu Thông Tin</button>
                  </div>
              </div>
          </div>
      )}

      {showAdjustModal && selectedItem && (
           <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-scale-in overflow-hidden">
                   <div className="p-4 border-b border-slate-200 bg-slate-50">
                      <h3 className="font-bold text-lg text-slate-800">Điều Chỉnh Kho</h3>
                      <p className="text-xs text-slate-500">{selectedItem.name} (Hiện có: {selectedItem.quantity})</p>
                   </div>
                   <div className="p-6 space-y-6">
                       <div className="flex p-1 bg-slate-100 rounded-lg">
                           <button onClick={() => setAdjustType('IMPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'IMPORT' ? 'bg-white shadow text-green-600' : 'text-slate-500'}`}>NHẬP KHO (+)</button>
                           <button onClick={() => setAdjustType('EXPORT')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${adjustType === 'EXPORT' ? 'bg-white shadow text-red-600' : 'text-slate-500'}`}>XUẤT KHO (-)</button>
                       </div>

                       <div className="text-center">
                           <label className="label-text mb-2">Số lượng {adjustType === 'IMPORT' ? 'nhập thêm' : 'xuất đi'}</label>
                           <div className="flex items-center justify-center gap-4">
                               <button onClick={() => setAdjustQty(Math.max(1, adjustQty - 1))} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Minus size={20}/></button>
                               <input type="number" className="w-24 text-center text-3xl font-bold text-slate-800 border-b-2 border-slate-200 focus:border-blue-500 outline-none pb-1" value={adjustQty} onChange={e => setAdjustQty(Number(e.target.value))} />
                               <button onClick={() => setAdjustQty(adjustQty + 1)} className="p-2 rounded-full bg-slate-100 hover:bg-slate-200"><Plus size={20}/></button>
                           </div>
                       </div>

                       <div>
                           <label className="label-text">Lý do / Ghi chú</label>
                           <input type="text" className="input-field" placeholder="VD: Bán cho học viên, Mua thêm..." value={adjustReason} onChange={e => setAdjustReason(e.target.value)} />
                       </div>

                       <div className="bg-slate-50 p-3 rounded-lg text-center">
                           <span className="text-xs text-slate-500">Tồn kho sau điều chỉnh</span>
                           <div className="text-xl font-bold text-blue-600">
                               {selectedItem.quantity} {adjustType === 'IMPORT' ? '+' : '-'} {adjustQty} = {adjustType === 'IMPORT' ? selectedItem.quantity + adjustQty : selectedItem.quantity - adjustQty}
                           </div>
                       </div>
                   </div>
                   <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowAdjustModal(false)} className="btn-secondary">Hủy</button>
                      <button onClick={handleExecuteAdjust} className={`btn-primary ${adjustType === 'EXPORT' ? 'bg-red-600 hover:bg-red-700' : 'bg-green-600 hover:bg-green-700'}`}>Xác Nhận</button>
                  </div>
              </div>
           </div>
      )}

      <style>{`
        .label-text { display: block; font-size: 0.75rem; font-weight: 700; color: #64748b; margin-bottom: 0.25rem; text-transform: uppercase; }
        .input-field { width: 100%; padding: 0.6rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.5rem; outline: none; transition: all 0.2s; font-size: 0.9rem; }
        .input-field:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
        .btn-primary { padding: 0.5rem 1rem; background-color: #2563eb; color: white; border-radius: 0.5rem; font-weight: 700; font-size: 0.875rem; transition: background-color 0.2s; box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); }
        .btn-primary:hover { background-color: #1d4ed8; }
        .btn-secondary { padding: 0.5rem 1rem; background-color: white; color: #374151; border: 1px solid #d1d5db; border-radius: 0.5rem; font-weight: 600; font-size: 0.875rem; transition: background-color 0.2s; }
        .btn-secondary:hover { background-color: #f3f4f6; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
        .hide-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, AcademicRecord, TermConfig } from '../types';
import { CheckCircle2, Info, Save, Calendar, UserCheck, Search, ChevronDown, ChevronRight } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    termConfigs: TermConfig[];
}

type AttendanceStatus = 'P' | 'K' | ''; // Trống = Hiện diện, P: Phép, K: Không phép

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years, grades, setRecords, termConfigs }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [toast, setToast] = useState<string | null>(null);

  const [attendanceData, setAttendanceData] = useState<Record<string, AttendanceStatus>>({});

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => {
      return classes.filter(c => c.yearId === selectedYear);
  }, [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  // Only show ACTIVE students in attendance list
  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');

  const sundaysInMonth = useMemo(() => {
      if (!selectedMonth) return [];
      const [year, month] = selectedMonth.split('-').map(Number);
      const date = new Date(year, month - 1, 1);
      const sundays = [];
      while (date.getMonth() === month - 1) {
          if (date.getDay() === 0) {
              sundays.push(new Date(date));
          }
          date.setDate(date.getDate() + 1);
      }
      return sundays;
  }, [selectedMonth]);

  const handleStatusChange = (studentId: string, date: string, type: 'mass' | 'class', status: AttendanceStatus) => {
    const key = `${studentId}-${date}-${type}`;
    setAttendanceData(prev => ({
        ...prev,
        [key]: status
    }));
  };

  const handleSave = () => {
      const [yearStr, monthStr] = selectedMonth.split('-');
      const monthDateStr = `${selectedMonth}-15`;

      let term: 'HK1' | 'HK2' = 'HK1';

      const config1 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK1');
      const config2 = termConfigs.find(c => c.yearId === selectedYear && c.term === 'HK2');

      if (config1 && monthDateStr >= config1.startDate && monthDateStr <= config1.endDate) {
          term = 'HK1';
      } else if (config2 && monthDateStr >= config2.startDate && monthDateStr <= config2.endDate) {
          term = 'HK2';
      } else {
          const m = parseInt(monthStr);
          term = (m >= 9 || m <= 1) ? 'HK1' : 'HK2';
      }

      setRecords(prev => {
          const newRecords = [...prev];

          filteredStudents.forEach(student => {
              let currentP = 0;
              let currentK = 0;

              sundaysInMonth.forEach(sunday => {
                  const dateStr = sunday.toISOString().split('T')[0];
                  // Mass absences
                  const massStatus = attendanceData[`${student.id}-${dateStr}-mass`];
                  if (massStatus === 'P') currentP++;
                  else if (massStatus === 'K') currentK++;

                  // Class absences
                  const classStatus = attendanceData[`${student.id}-${dateStr}-class`];
                  if (classStatus === 'P') currentP++;
                  else if (classStatus === 'K') currentK++;
              });

              const existingIdx = newRecords.findIndex(r => r.studentId === student.id && r.term === term);
              if (existingIdx > -1) {
                  newRecords[existingIdx] = {
                      ...newRecords[existingIdx],
                      absentP: (newRecords[existingIdx].absentP || 0) + currentP,
                      absentK: (newRecords[existingIdx].absentK || 0) + currentK
                  };
              } else {
                  newRecords.push({
                      studentId: student.id,
                      term: term,
                      scores: {},
                      scorePray: 0,
                      scoreExam: 0,
                      average: 0,
                      absentP: currentP,
                      absentK: currentK
                  });
              }
          });

          return newRecords;
      });

      showToast(`Đã lưu & đồng bộ vắng mặt vào ${term === 'HK1' ? 'Học kỳ 1' : 'Học kỳ 2'} thành công!`);
  };

  const getStatusStyle = (status: AttendanceStatus | undefined) => {
      switch (status) {
          case 'P': return 'bg-amber-500 text-white border-amber-600 font-extrabold shadow-inner ring-1 ring-amber-600';
          case 'K': return 'bg-red-600 text-white border-red-700 font-extrabold shadow-inner ring-1 ring-red-700';
          default: return 'bg-white text-slate-400 border-slate-200 hover:border-blue-400 hover:bg-slate-50';
      }
  };

  const getStatusLabel = (status: AttendanceStatus | undefined) => {
      switch (status) {
          case 'P': return 'Phép';
          case 'K': return 'K.Phép';
          default: return 'Có mặt';
      }
  };

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50 md:bg-white/50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-2">
        <h2 className="text-2xl md:text-3xl font-bold text-slate-800">Điểm Danh</h2>
        <div className="flex items-center gap-3 text-sm md:text-base text-slate-600 bg-white px-3 py-2 rounded-lg border shadow-sm font-medium w-full md:w-auto">
            <Calendar size={18} className="text-blue-600" />
            <input 
                type="month" 
                className="bg-transparent outline-none font-bold text-blue-700 uppercase"
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)} 
            />
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-3 items-stretch md:items-center">
        <select className="px-4 py-2.5 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50 font-bold" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
        <div className="flex gap-2">
             <select className="flex-1 px-4 py-2.5 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50 font-bold" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
             <select className="flex-1 px-4 py-2.5 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none font-bold text-blue-700 bg-blue-50" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
        </div>
      </div>

      <div className="bg-blue-600 text-white p-4 mb-4 flex items-center gap-3 shadow-lg rounded-xl animate-fade-in border-b-4 border-blue-800 md:mx-0">
        <div className="bg-white/20 p-2 rounded-lg"><Info size={20} className="text-white" /></div>
        <div className="flex flex-col text-xs md:text-sm">
            <span className="font-extrabold tracking-wide uppercase">Lưu ý:</span>
            <span className="opacity-95">Trống = Hiện diện. P = Phép, K = Không phép.</span>
        </div>
      </div>

      <div className="bg-white md:rounded-xl md:shadow-sm md:border md:border-slate-300 flex-1 overflow-hidden flex flex-col bg-transparent">

        {/* MOBILE VIEW: CARD LIST */}
        <div className="md:hidden overflow-y-auto h-full space-y-4 pb-24">
            {filteredStudents.length > 0 ? (
                filteredStudents.map((s, idx) => (
                    <div key={s.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-3">
                        <div className="flex justify-between items-center border-b border-slate-100 pb-2">
                            <div className="flex items-center gap-3">
                                <span className="w-6 h-6 rounded-full bg-slate-100 text-slate-500 font-bold flex items-center justify-center text-xs">{idx + 1}</span>
                                <div>
                                    <div className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</div>
                                    <div className="text-[10px] text-slate-400 font-mono">ID: {s.id}</div>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-3">
                            {sundaysInMonth.map((sunday, i) => {
                                const dateStr = sunday.toISOString().split('T')[0];
                                const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                                const classStatus = attendanceData[`${s.id}-${dateStr}-class`];
                                return (
                                    <div key={i} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100">
                                        <div className="flex flex-col min-w-[60px]">
                                            <span className="text-[10px] font-bold text-slate-400 uppercase">CN {i + 1}</span>
                                            <span className="text-xs font-bold text-blue-600">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                                        </div>
                                        <div className="flex gap-2">
                                            <div className="flex flex-col items-center gap-1">
                                                <span className="text-[9px] font-bold text-purple-400 uppercase">Lễ</span>
                                                <select 
                                                    value={massStatus || ''} 
                                                    onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                                    className={`h-8 w-16 text-center rounded text-xs border outline-none font-bold transition-all ${getStatusStyle(massStatus)}`}
                                                >
                                                    <option value="">Có</option>
                                                    <option value="P">P</option>
                                                    <option value="K">K</option>
                                                </select>
                                            </div>
                                            <div className="flex flex-col items-center gap-1">
                                                <span className="text-[9px] font-bold text-blue-400 uppercase">Học</span>
                                                <select 
                                                    value={classStatus || ''} 
                                                    onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                                    className={`h-8 w-16 text-center rounded text-xs border outline-none font-bold transition-all ${getStatusStyle(classStatus)}`}
                                                >
                                                    <option value="">Có</option>
                                                    <option value="P">P</option>
                                                    <option value="K">K</option>
                                                </select>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    </div>
                ))
            ) : (
                <div className="p-10 text-center text-slate-400 italic bg-white rounded-xl border border-slate-200">Vui lòng chọn lớp để hiển thị danh sách</div>
            )}
        </div>

        {/* DESKTOP VIEW: TABLE */}
        <div className="hidden md:block overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse border-separate border-spacing-0">
             <thead>
               <tr className="bg-slate-100 text-slate-800 text-sm">
                 <th rowSpan={2} className="px-3 py-2 w-12 text-center sticky left-0 bg-slate-100 z-30 border-b border-r border-slate-400 font-bold">STT</th>
                 <th rowSpan={2} className="px-3 py-2 min-w-[200px] sticky left-12 bg-slate-100 z-30 border-b border-r border-slate-400 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)] font-bold">Học Viên</th>
                 {sundaysInMonth.map((sunday, idx) => {
                    const isEven = idx % 2 === 0;
                    const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50';
                    return (
                        <th key={idx} colSpan={2} className={`px-3 py-2 text-center border-b border-r border-slate-400 ${bgClass}`}>
                            <div className="flex flex-col">
                                <span className={`font-bold ${isEven ? 'text-slate-700' : 'text-blue-800'}`}>CN {idx + 1}</span>
                                <span className="text-xs font-normal text-slate-500">{sunday.getDate()}/{sunday.getMonth() + 1}</span>
                            </div>
                        </th>
                    );
                 })}
                 <th rowSpan={2} className="px-3 py-2 text-center border-b border-slate-400 min-w-[150px] font-bold">Ghi chú</th>
               </tr>
               <tr className="text-xs uppercase tracking-tighter font-bold bg-slate-50">
                    {sundaysInMonth.map((_, idx) => {
                        const isEven = idx % 2 === 0;
                        const bgClass = isEven ? 'bg-slate-50' : 'bg-blue-50/50';
                        return (
                            <React.Fragment key={idx}>
                                <th className={`px-2 py-1 text-center border-b border-r border-slate-400 min-w-[50px] text-purple-700 ${bgClass}`}>Lễ</th>
                                <th className={`px-2 py-1 text-center border-b border-r border-slate-400 min-w-[50px] text-blue-700 ${bgClass}`}>Học</th>
                            </React.Fragment>
                        );
                    })}
               </tr>
             </thead>
             <tbody className="">
               {filteredStudents.length > 0 ? (
                 filteredStudents.map((s, idx) => (
                 <tr key={s.id} className="hover:bg-blue-50/30 group transition-colors border-b border-slate-300 text-base">
                   <td className="px-3 py-2 text-center text-slate-600 sticky left-0 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-300 font-bold">{idx + 1}</td>
                   <td className="px-3 py-2 sticky left-12 bg-white group-hover:bg-slate-50 z-20 border-r border-slate-300 shadow-[4px_0_8px_-4px_rgba(0,0,0,0.1)]">
                    <div className="font-bold text-slate-800">{s.saintName} {s.fullName}</div>
                    <div className="text-xs text-slate-400 font-mono">{s.id}</div>
                   </td>

                   {sundaysInMonth.map((sunday, i) => {
                       const dateStr = sunday.toISOString().split('T')[0];
                       const isEven = i % 2 === 0;
                       const cellClass = isEven ? 'bg-white group-hover:bg-blue-50/20' : 'bg-blue-50/10 group-hover:bg-blue-50/30';

                       const massStatus = attendanceData[`${s.id}-${dateStr}-mass`];
                       const classStatus = attendanceData[`${s.id}-${dateStr}-class`];

                       return (
                           <React.Fragment key={i}>
                               <td className={`p-1 border-r border-slate-300 text-center ${cellClass}`}>
                                   <div className="relative">
                                     <select 
                                        value={massStatus || ''} 
                                        onChange={(e) => handleStatusChange(s.id, dateStr, 'mass', e.target.value as AttendanceStatus)}
                                        className={`w-full text-center py-1.5 rounded text-sm border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none appearance-none font-bold transition-all ${getStatusStyle(massStatus)}`}
                                     >
                                         <option value="" className="bg-white text-slate-400 font-normal">v</option>
                                         <option value="P" className="bg-amber-500 text-white font-bold">P</option>
                                         <option value="K" className="bg-red-600 text-white font-bold">K</option>
                                     </select>
                                     {!massStatus && <ChevronDown size={12} className="absolute right-1 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none"/>}
                                   </div>
                               </td>
                               <td className={`p-1 border-r border-slate-300 text-center ${cellClass}`}>
                                   <div className="relative">
                                     <select 
                                        value={classStatus || ''} 
                                        onChange={(e) => handleStatusChange(s.id, dateStr, 'class', e.target.value as AttendanceStatus)}
                                        className={`w-full text-center py-1.5 rounded text-sm border cursor-pointer focus:ring-2 focus:ring-blue-400 outline-none appearance-none font-bold transition-all ${getStatusStyle(classStatus)}`}
                                     >
                                         <option value="" className="bg-white text-slate-400 font-normal">v</option>
                                         <option value="P" className="bg-amber-500 text-white font-bold">P</option>
                                         <option value="K" className="bg-red-600 text-white font-bold">K</option>
                                     </select>
                                     {!classStatus && <ChevronDown size={12} className="absolute right-1 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none"/>}
                                   </div>
                               </td>
                           </React.Fragment>
                       );
                   })}

                   <td className="px-3 py-2 border-r border-slate-300">
                     <input type="text" className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 outline-none text-sm py-1 transition-all" placeholder="..." />
                   </td>
                 </tr>
               ))) : (
                  <tr><td colSpan={sundaysInMonth.length * 2 + 3} className="p-12 text-center text-slate-400 italic bg-slate-50 text-lg">Vui lòng chọn lớp để hiển thị danh sách học viên</td></tr>
               )}
             </tbody>
           </table>
        </div>

        {filteredStudents.length > 0 && (
            <div className="p-4 md:p-5 border-t border-slate-300 bg-slate-100 flex flex-col md:flex-row justify-between items-center sticky bottom-0 z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.05)] gap-3 md:gap-0">
                 <div className="flex gap-4 md:gap-8 text-xs md:text-base w-full md:w-auto overflow-x-auto">
                     <div className="flex items-center gap-2 font-medium whitespace-nowrap"><span className="w-4 h-4 md:w-6 md:h-6 bg-white border border-slate-300 rounded shadow-sm"></span> <span className="text-slate-600">Trống: Có mặt</span></div>
                     <div className="flex items-center gap-2 font-medium whitespace-nowrap"><span className="w-4 h-4 md:w-6 md:h-6 bg-amber-500 border border-amber-600 rounded shadow-sm text-[10px] md:text-xs flex items-center justify-center font-black text-white">P</span> <span className="text-amber-700 font-bold">Phép</span></div>
                     <div className="flex items-center gap-2 font-medium whitespace-nowrap"><span className="w-4 h-4 md:w-6 md:h-6 bg-red-600 border border-red-700 rounded shadow-sm text-[10px] md:text-xs flex items-center justify-center font-black text-white">K</span> <span className="text-red-700 font-bold">K.Phép</span></div>
                 </div>
                 <button onClick={handleSave} className="w-full md:w-auto px-6 py-3 bg-blue-600 text-white rounded-xl shadow-lg hover:bg-blue-700 font-bold flex items-center justify-center gap-2 transition-all transform active:scale-95 text-sm md:text-base">
                     <Save size={20}/> Lưu Điểm Danh
                 </button>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        select { text-align-last: center; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Save, Table, UserCheck, XCircle, CheckCircle2, ListChecks, Download, Settings2, Trash2, X, AlertCircle, ChevronDown, ChevronRight, Calculator } from 'lucide-react';
import { AcademicRecord, Student, ClassRoom, SchoolYear, Grade } from '../types';

interface GradesProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    grades: Grade[];
}

interface TestColumn {
  id: string;
  name: string;
  weight: number;
  term: 'HK1' | 'HK2';
}

// Cấu hình độ rộng cố định cho các cột (Pixel)
const COL_WIDTHS = {
    index: 40,
    studentInfo: 220, 
    score: 60,
    absent: 35,
    avg: 50,
    final: 60,
    rank: 85,
    ranking: 50
};

export const Grades: React.FC<GradesProps> = ({ students, classes, years, records, setRecords, grades }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [viewMode, setViewMode] = useState<'entry' | 'summary'>('entry');
  const [toast, setToast] = useState<string | null>(null);
  const [isConfigModalOpen, setIsConfigModalOpen] = useState(false);

  // Mobile accordion states
  const [openStudentId, setOpenStudentId] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [testColumns, setTestColumns] = useState<TestColumn[]>([
    { id: 'hk1_15m', name: "15'", weight: 1, term: 'HK1' },
    { id: 'hk1_45m', name: "45'", weight: 2, term: 'HK1' },
    { id: 'hk1_exam', name: "Thi", weight: 3, term: 'HK1' },
    { id: 'hk2_15m', name: "15'", weight: 1, term: 'HK2' },
    { id: 'hk2_45m', name: "45'", weight: 2, term: 'HK2' },
    { id: 'hk2_exam', name: "Thi", weight: 3, term: 'HK2' },
  ]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const classesInYear = useMemo(() => classes.filter(c => c.yearId === selectedYear), [classes, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  useEffect(() => {
      if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
          setSelectedClass(availableClasses[0].id);
      } else if (availableClasses.length === 0) {
          setSelectedClass('');
      }
  }, [availableClasses, selectedClass]);

  const filteredStudents = students.filter(s => s.classId === selectedClass && s.status === 'ACTIVE');
  const currentClass = classes.find(c => c.id === selectedClass);

  const hk1Columns = useMemo(() => testColumns.filter(c => c.term === 'HK1'), [testColumns]);
  const hk2Columns = useMemo(() => testColumns.filter(c => c.term === 'HK2'), [testColumns]);

  const getRecord = (studentId: string, specificTerm: 'HK1' | 'HK2') => {
    return records.find(r => r.studentId === studentId && r.term === specificTerm) || {
      studentId, term: specificTerm, scores: {}, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0
    };
  };

  const handleScoreChange = (studentId: string, term: 'HK1' | 'HK2', field: string, value: string) => {
    let numValue = value === '' ? 0 : (parseFloat(value) || 0);
    if (numValue > 10) numValue = 10;
    if (numValue < 0) numValue = 0;

    setRecords(prev => {
        const existingIndex = prev.findIndex(r => r.studentId === studentId && r.term === term);
        const newRecords = [...prev];
        if (existingIndex > -1) {
            newRecords[existingIndex] = { ...prev[existingIndex], scores: { ...prev[existingIndex].scores, [field]: numValue } };
            return newRecords;
        } else {
             return [...newRecords, { studentId, term, scores: { [field]: numValue }, scorePray: 0, scoreExam: 0, average: 0, absentP: 0, absentK: 0 }];
        }
    });
  };

  const calculateAvg = (record: AcademicRecord) => {
      let totalScore = 0;
      let totalWeight = 0;
      const termColumns = testColumns.filter(c => c.term === record.term);
      termColumns.forEach(col => {
          const score = (record.scores && record.scores[col.id] !== undefined) ? record.scores[col.id] : 0;
          totalScore += score * col.weight;
          totalWeight += col.weight;
      });
      return totalWeight > 0 ? parseFloat((totalScore / totalWeight).toFixed(1)) : 0;
  };

  const handleSaveGrades = () => {
     const updatedRecords = records.map(r => {
         const student = filteredStudents.find(s => s.id === r.studentId);
         if (student) {
            return { ...r, average: calculateAvg(r) };
         }
         return r;
     });
     setRecords(updatedRecords);
     showToast(`Đã lưu bảng điểm lớp ${currentClass?.name}!`);
  };

  const getRank = (avg: number) => {
    if (avg === 0) return { label: '-', color: 'text-slate-400 bg-slate-50' };
    if (avg < 5) return { label: 'Yếu', color: 'text-red-600 bg-red-50' };
    if (avg < 6.5) return { label: 'TB', color: 'text-orange-600 bg-orange-50' };
    if (avg < 8) return { label: 'Khá', color: 'text-blue-600 bg-blue-50' };
    return { label: 'Giỏi', color: 'text-green-600 bg-green-50' };
  };

  const processedStudentsYear = useMemo(() => {
    let list = filteredStudents.map(s => {
      const r1 = getRecord(s.id, 'HK1');
      const r2 = getRecord(s.id, 'HK2');
      const avg1 = calculateAvg(r1);
      const avg2 = calculateAvg(r2);
      const finalAvg = (avg1 > 0 || avg2 > 0) ? (avg1 + avg2) / 2 : 0;
      return { 
        ...s, 
        avg1, avg2, avgYear: finalAvg, 
        rank: getRank(finalAvg), 
        isPassed: finalAvg >= 5.0,
        absentP1: r1.absentP || 0,
        absentK1: r1.absentK || 0,
        absentP2: r2.absentP || 0,
        absentK2: r2.absentK || 0,
        nameForSort: s.fullName.split(' ').pop() || ''
      };
    });
    const sortedByScore = [...list].sort((a, b) => b.avgYear - a.avgYear);
    const rankedMap = new Map();
    sortedByScore.forEach((s, index) => { rankedMap.set(s.id, index + 1); });
    return list.map(s => ({ ...s, ranking: rankedMap.get(s.id) })).sort((a, b) => a.nameForSort.localeCompare(b.nameForSort, 'vi'));
  }, [filteredStudents, records, testColumns]);

  const passedStudents = processedStudentsYear.filter(s => s.isPassed);
  const failedStudents = processedStudentsYear.filter(s => !s.isPassed);

  const addConfigColumn = (term: 'HK1' | 'HK2') => {
      setTestColumns([...testColumns, { id: `col_${Date.now()}`, name: 'Cột mới', weight: 1, term }]);
  };

  const removeConfigColumn = (id: string) => setTestColumns(testColumns.filter(c => c.id !== id));

  const updateConfigColumn = (id: string, field: keyof TestColumn, value: any) => {
      setTestColumns(testColumns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50 text-slate-900">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-5 py-3 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast}</span>
           </div>
        </div>
      )}

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-5 gap-3">
        <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Sổ Điểm & Tổng Kết</h2>
        <div className="flex bg-slate-200 p-1 rounded-lg border border-slate-300 w-full md:w-auto">
           <button onClick={() => setViewMode('entry')} className={`flex-1 md:flex-none justify-center px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'entry' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><Table size={16}/> <span className="md:inline hidden">Sổ Điểm</span><span className="md:hidden inline">Nhập Điểm</span></button>
           <button onClick={() => setViewMode('summary')} className={`flex-1 md:flex-none justify-center px-4 py-1.5 rounded-md text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'summary' ? 'bg-white shadow text-blue-600' : 'text-slate-600 hover:text-slate-800'}`}><ListChecks size={16}/> <span className="md:inline hidden">Thống Kê</span><span className="md:hidden inline">Tổng Kết</span></button>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-5 flex justify-between items-center flex-wrap gap-3">
        <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center w-full md:w-auto">
          <select className="px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}</select>
          <div className="flex gap-2">
              <select className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 outline-none" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}><option value="all">Tất cả Khối</option>{grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}</select>
              <select className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold bg-slate-50 text-blue-800 outline-none" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>{availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}{availableClasses.length === 0 && <option value="">Không có lớp</option>}</select>
          </div>
        </div>
        <div className="flex items-center gap-2 w-full md:w-auto">
            {viewMode === 'entry' && (
                <button onClick={() => setIsConfigModalOpen(true)} className="flex-1 md:flex-none justify-center flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 border border-slate-300 rounded-lg hover:bg-slate-200 text-xs font-bold transition-all whitespace-nowrap"><Settings2 size={16} /> Cấu hình</button>
            )}
             <button className="flex-1 md:flex-none justify-center flex items-center gap-2 px-4 py-2 bg-green-600 text-white border border-green-700 rounded-lg text-xs hover:bg-green-700 font-bold uppercase shadow-sm transition-all whitespace-nowrap"><Download size={16}/> Xuất Excel</button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-white md:rounded-xl md:shadow-md md:border md:border-slate-300 flex-1 overflow-hidden flex flex-col bg-transparent">
        {viewMode === 'entry' ? (
        <>
            {/* MOBILE: CARD VIEW FOR GRADE ENTRY */}
