  birthPlace: string; // Nơi sinh
  gender: 'Male' | 'Female';
  classId: string;
  status: 'ACTIVE' | 'TRANSFERRED' | 'DROPPED'; // Tình trạng: Đang học | Chuyển xứ | Nghỉ học

  // Family
  fatherName: string; // Tên bố
  motherName: string; // Tên mẹ
  fatherPhone: string; // Sđt bố
  motherPhone: string; // Sđt mẹ
  parish: string; // Giáo họ
  address: string; // Địa chỉ

  // Sacraments
  baptismDate?: string; // Ngày rửa tội
