export const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, setActiveTab, isCollapsed, setIsCollapsed, isMobileOpen, setIsMobileOpen, currentUser, onLogout 
}) => {
  const menuItems = [
    { id: 'dashboard', label: 'Trang Chủ', icon: LayoutDashboard },
