                  {item.label}
                </div>
              )}
            </button>
          );
        })}
      </nav>

      {/* Footer */}
      <div className={`p-4 border-t border-slate-800 bg-slate-900/80 transition-all duration-300 ${isCollapsed && !isMobileOpen ? 'flex justify-center' : ''}`}>
        <button 
          onClick={onLogout}
          className={`w-full flex items-center text-rose-400 hover:text-white hover:bg-rose-600/20 rounded-xl transition-all ${
            isCollapsed && !isMobileOpen ? 'justify-center p-3' : 'px-4 py-2.5 gap-3'
          }`}
          title="Đăng xuất"
        >
           <LogOut size={isCollapsed && !isMobileOpen ? 24 : 18} /> 
           <span className={`font-black text-xs uppercase tracking-widest transition-all duration-300 ${isCollapsed && !isMobileOpen ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
             Đăng xuất
           </span>
        </button>

        {(!isCollapsed || isMobileOpen) && (
          <div className="mt-4 flex flex-col items-center">
            <div className="h-px w-8 bg-slate-800 mb-3"></div>
            <div className="text-[9px] text-slate-600 text-center font-black uppercase tracking-widest leading-loose">
              Hệ thống Quản lý <br/> 
              <span className="text-blue-900/50">Version 2.6.0 RBAC</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

