  const [address, setAddress] = useState('123 Đường Chúa Cứu Thế, Quận 3, TP.HCM');
  const [phone, setPhone] = useState('028 3838 3838');

  // --- GRADING CONFIG STATE ---
  const [passScore, setPassScore] = useState(5.0);
