  const handleColDrop = (e: React.DragEvent, targetId: string) => {
      e.preventDefault(); setDragOverColId(null);
      if (!draggedColId || draggedColId === targetId) return;
      const sourceIndex = scoreColumns.findIndex(c => c.id === draggedColId);
