  );
};

import React from 'react';
import { 
  LayoutDashboard, Users, CalendarCheck, BookOpenCheck, Settings, Wallet, 
  Church, GraduationCap, LogOut, School, ArrowRightLeft, Package, Menu, ChevronLeft, X
} from 'lucide-react';
import { Teacher } from '../types';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  isCollapsed: boolean;
  setIsCollapsed: (val: boolean) => void;
  isMobileOpen: boolean;
  setIsMobileOpen: (val: boolean) => void;
  currentUser: Teacher | null;
  onLogout: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, setActiveTab, isCollapsed, setIsCollapsed, isMobileOpen, setIsMobileOpen, currentUser, onLogout 
}) => {
  const menuItems = [
    { id: 'dashboard', label: 'Trang Chủ', icon: LayoutDashboard },
    { id: 'classes', label: 'Lớp Học', icon: School },
    { id: 'students', label: 'Học Viên', icon: Users },
    { id: 'placement', label: 'Xếp Lớp', icon: ArrowRightLeft },
    { id: 'attendance', label: 'Chuyên Cần', icon: CalendarCheck },
    { id: 'grades', label: 'Bảng Điểm', icon: BookOpenCheck },
    { id: 'teachers', label: 'Giáo Lý Viên', icon: GraduationCap },
    { id: 'inventory', label: 'Kho & Vật Tư', icon: Package },
    { id: 'finance', label: 'Thủ Quỹ', icon: Wallet },
    { id: 'settings', label: 'Cài Đặt', icon: Settings },
  ];

  // Filter menu items based on permissions
  const visibleMenuItems = menuItems.filter(item => {
      if (!currentUser) return false;
      if (currentUser.role === 'ADMIN') return true;
      if (item.id === 'settings') return true; // Settings is always available
      // If GLV, check allowedTabs. Default to Dashboard only if undefined.
      return currentUser.allowedTabs?.includes(item.id);
  });

  return (
    <div 
      className={`bg-slate-900 text-white flex flex-col h-screen fixed left-0 top-0 shadow-2xl z-50 transition-transform duration-300 ease-in-out 
        ${isMobileOpen ? 'translate-x-0 w-64' : '-translate-x-full w-64'} 
        md:translate-x-0 
        ${isCollapsed ? 'md:w-20' : 'md:w-64'}
      `}
    >
      {/* Header */}
      <div className={`p-4 flex items-center border-b border-slate-800 min-h-[81px] transition-all duration-300 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>

        {(!isCollapsed || isMobileOpen) && (
          <div className="flex items-center gap-3 overflow-hidden animate-fade-in">
            <div className="p-2 bg-blue-600 rounded-lg shadow-lg shadow-blue-900/40">
              <Church className="w-6 h-6 text-white" />
            </div>
            <div className="whitespace-nowrap">
              <h1 className="font-black text-sm leading-tight uppercase tracking-tight">Quản lý Giáo Lý</h1>
              <p className="text-[9px] text-blue-400 uppercase font-bold tracking-[0.2em]">{currentUser?.role === 'ADMIN' ? 'Quản trị viên' : 'Giáo Lý Viên'}</p>
            </div>
          </div>
        )}

        {/* Desktop Toggle */}
        <button 
          onClick={() => setIsCollapsed(!isCollapsed)}
          className={`hidden md:flex p-2 rounded-xl transition-all duration-200 group items-center justify-center ${
            isCollapsed 
              ? 'bg-slate-800 text-white hover:bg-blue-600' 
              : 'text-slate-400 hover:text-white hover:bg-slate-800'
          }`}
          title={isCollapsed ? "Mở rộng" : "Thu gọn"}
        >
          <Menu className={`transition-transform duration-300 ${isCollapsed ? 'w-6 h-6' : 'w-5 h-5 group-hover:rotate-90'}`} />
        </button>

        {/* Mobile Close Button */}
        <button 
            onClick={() => setIsMobileOpen(false)}
            className="md:hidden p-2 text-slate-400 hover:text-white"
        >
            <X size={24} />
        </button>
      </div>

      {/* User Info (Collapsed Only) */}
      {!isCollapsed && (
          <div className="px-4 pt-4 pb-2">
              <div className="p-3 bg-slate-800 rounded-xl flex items-center gap-3 border border-slate-700/50">
                  <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs shadow-md border-2 border-slate-900">
                      {currentUser?.fullName.charAt(0)}
                  </div>
                  <div className="overflow-hidden">
                      <div className="text-xs font-bold truncate text-white">{currentUser?.saintName} {currentUser?.fullName}</div>
                      <div className="text-[10px] text-slate-400 truncate">@{currentUser?.username}</div>
                  </div>
              </div>
          </div>
      )}

      {/* Navigation */}
      <nav className="flex-1 p-3 space-y-1.5 overflow-y-auto custom-scrollbar overflow-x-hidden">
        {visibleMenuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center rounded-xl transition-all duration-200 group relative ${
                isCollapsed && !isMobileOpen ? 'justify-center px-0 py-3.5' : 'px-4 py-3 gap-3'
              } ${
                isActive 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/30' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
