                                              onClick={() => togglePermission(tab.id)}
                                           >
                                               <div className={`w-4 h-4 rounded border flex items-center justify-center ${formData.allowedTabs?.includes(tab.id) ? 'bg-blue-600 border-blue-600' : 'border-slate-300'}`}>
                                                   {formData.allowedTabs?.includes(tab.id) && <Check size={12} className="text-white"/>}
                                               </div>
                                               <span className="text-xs font-bold">{tab.label}</span>
                                           </div>
                                       ))}
                                   </div>
                               </div>
                           )}
                       </div>

                   </div>
               </div>
            </div>

            <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
              <button onClick={closeModal} className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-100 font-medium">Hủy</button>
              <button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-sm">Lưu Thông Tin</button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {teacherToDelete && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-scale-in">
            <div className="flex items-center gap-3 text-red-600 mb-4">
              <div className="p-3 bg-red-100 rounded-full">
                <AlertTriangle size={24} />
              </div>
              <h3 className="text-lg font-bold text-slate-800">Xác nhận xóa</h3>
            </div>

            <p className="text-slate-600 mb-6 leading-relaxed">
              Bạn có chắc chắn muốn xóa Giáo Lý Viên <span className="font-bold text-slate-800">{teacherToDelete.saintName} {teacherToDelete.fullName}</span> không? 
              <br/><span className="text-sm italic text-red-500">Hành động này không thể hoàn tác.</span>
            </p>

            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setTeacherToDelete(null)} 
                className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 font-medium transition-colors"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleDeleteTeacher} 
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-medium shadow-sm transition-colors"
              >
                Xóa Vĩnh Viễn
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { Inventory } from './components/Inventory';
import { Login } from './components/Login';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES, MOCK_TERM_CONFIGS, MOCK_INVENTORY, MOCK_SCORE_COLUMNS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade, TermConfig, InventoryItem, ScoreColumn, Teacher } from './types';
import { Menu, Church } from 'lucide-react';

const App: React.FC = () => {
  // --- AUTH STATE ---
  const [currentUser, setCurrentUser] = useState<Teacher | null>(null);

  // --- UI STATE ---
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- DATA STATE ---
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);
  const [termConfigs, setTermConfigs] = useState<TermConfig[]>(MOCK_TERM_CONFIGS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [scoreColumns, setScoreColumns] = useState<ScoreColumn[]>(MOCK_SCORE_COLUMNS);

  // Check permissions when activeTab changes
  useEffect(() => {
      if (currentUser && currentUser.role !== 'ADMIN' && currentUser.allowedTabs) {
          // Allow settings by default regardless of allowedTabs
          if (activeTab !== 'settings' && !currentUser.allowedTabs.includes(activeTab)) {
              // Redirect to first allowed tab if current is forbidden
              if (currentUser.allowedTabs.length > 0) {
                  setActiveTab(currentUser.allowedTabs[0]);
              } else {
                  setActiveTab('dashboard'); // Fallback
              }
          }
      }
  }, [activeTab, currentUser]);

  const handleLogin = (user: Teacher) => {
      setCurrentUser(user);
      // Reset tab to dashboard or first allowed tab on login
      if (user.role !== 'ADMIN' && user.allowedTabs && user.allowedTabs.length > 0) {
          setActiveTab(user.allowedTabs[0]);
      } else {
          setActiveTab('dashboard');
      }
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setActiveTab('dashboard');
  };

  if (!currentUser) {
      return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    // Double check permission before rendering (except settings)
    if (activeTab !== 'settings' && currentUser.role !== 'ADMIN' && currentUser.allowedTabs && !currentUser.allowedTabs.includes(activeTab)) {
        return (
            <div className="flex h-full items-center justify-center flex-col text-slate-400">
                <div className="text-4xl font-bold mb-2">403</div>
                <div className="text-sm">Bạn không có quyền truy cập chức năng này.</div>
            </div>
        );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'classes': return <Classes classes={classes} setClasses={setClasses} students={students} years={years} grades={grades} currentUser={currentUser} />;
      case 'students': return <Students students={students} setStudents={setStudents} classes={classes} years={years} records={records} grades={grades} currentUser={currentUser} />;
      case 'placement': return <ClassPlacement students={students} setStudents={setStudents} classes={classes} years={years} grades={grades} currentUser={currentUser} />;
      case 'teachers': return <Teachers />;
      case 'attendance': return <Attendance students={students} classes={classes} years={years} grades={grades} setRecords={setRecords} termConfigs={termConfigs} currentUser={currentUser} />;
      case 'grades': return <Grades students={students} classes={classes} years={years} records={records} setRecords={setRecords} grades={grades} scoreColumns={scoreColumns} currentUser={currentUser} />;
      case 'inventory': return <Inventory items={inventory} setItems={setInventory} />;
      case 'finance': return <Finance transactions={transactions} setTransactions={setTransactions} />;
      case 'settings': return <Settings years={years} setYears={setYears} classes={classes} setClasses={setClasses} grades={grades} setGrades={setGrades} termConfigs={termConfigs} setTermConfigs={setTermConfigs} scoreColumns={scoreColumns} setScoreColumns={setScoreColumns} currentUser={currentUser} />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans relative">
      {/* Mobile Header Bar */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-40 flex items-center justify-between px-4 shadow-sm">
        <div className="flex items-center gap-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu size={24} />
            </button>
            <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                    <Church size={16} />
                </div>
                <span className="font-bold text-slate-800 text-sm uppercase">Gx. Tân Thành</span>
            </div>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
            setActiveTab(tab);
            setIsMobileMenuOpen(false); // Close mobile menu on select
        }}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        isMobileOpen={isMobileMenuOpen}
        setIsMobileOpen={setIsMobileMenuOpen}
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      {/* Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm animate-fade-in"
            onClick={() => setIsMobileMenuOpen(false)}
        ></div>
      )}

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out pt-16 md:pt-0 ${
          isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'
        } w-full`}
      >
        {renderContent()}
      </main>

      <style>{`
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_TEACHERS } from '../constants';
import { ClassRoom, SchoolYear, Student, Grade, Teacher } from '../types';
import { Users, User, UserCheck, Edit, X, Save, CheckCircle2, Search } from 'lucide-react';

interface ClassesProps {
    classes: ClassRoom[];
    setClasses: (classes: ClassRoom[]) => void;
    students: Student[];
    years: SchoolYear[];
    grades: Grade[];
    currentUser: Teacher | null;
}

export const Classes: React.FC<ClassesProps> = ({ classes, setClasses, students, years, grades, currentUser }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [toast, setToast] = useState<string | null>(null);

  const isAdmin = currentUser?.role === 'ADMIN';

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  const [editingClass, setEditingClass] = useState<ClassRoom | null>(null);

  const [mainTeacherInput, setMainTeacherInput] = useState('');
  const [showMainTeacherSuggestions, setShowMainTeacherSuggestions] = useState(false);

  const [assistants, setAssistants] = useState<string[]>(['', '', '']);
  const [showAssistSuggestions, setShowAssistSuggestions] = useState<boolean[]>([false, false, false]);

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  useEffect(() => {
    if (editingClass) {
        const parts = editingClass.assistants ? editingClass.assistants.split(',').map(s => s.trim()) : [];
        setAssistants([parts[0] || '', parts[1] || '', parts[2] || '']);
        setMainTeacherInput(editingClass.mainTeacher || '');
    }
  }, [editingClass]);

  const availableClasses = useMemo(() => {
      if (!currentUser) return [];
      if (currentUser.role === 'ADMIN') return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser]);

  const filteredClasses = useMemo(() => {
      return availableClasses.filter(c => {
          const matchYear = c.yearId === selectedYear;
          const matchGrade = selectedGrade === 'all' || c.gradeId === selectedGrade;
          return matchYear && matchGrade;
      });
  }, [availableClasses, selectedYear, selectedGrade]);

  const getClassStats = (classId: string) => {
      const classStudents = students.filter(s => s.classId === classId);
      return {
          total: classStudents.length,
          male: classStudents.filter(s => s.gender === 'Male').length,
          female: classStudents.filter(s => s.gender === 'Female').length
      };
  };

  const handleEditClass = (c: ClassRoom) => {
    setEditingClass({ ...c });
  };

  const handleSaveClass = () => {
    if (editingClass) {
        const combinedAssistants = assistants
            .map(s => s.trim())
            .filter(s => s !== '')
            .join(', ');

        const finalClassData = { 
            ...editingClass, 
            mainTeacher: mainTeacherInput, 
            assistants: combinedAssistants 
        };

        const updatedClasses = classes.map(c => c.id === editingClass.id ? finalClassData : c);
        setClasses(updatedClasses);
        showToast(`Đã cập nhật thông tin lớp ${editingClass.name} thành công!`);
        setEditingClass(null);
    }
  };

  const sortedTeachers = useMemo(() => {
      return [...MOCK_TEACHERS].sort((a, b) => a.fullName.localeCompare(b.fullName));
  }, []);

  const getFilteredTeachers = (input: string) => {
      if (!input) return sortedTeachers;
      const lowerInput = input.toLowerCase();
      return sortedTeachers.filter(t => 
          t.fullName.toLowerCase().includes(lowerInput) || 
          t.saintName.toLowerCase().includes(lowerInput)
      );
  };

  const filteredMainTeacherSuggestions = useMemo(() => getFilteredTeachers(mainTeacherInput), [mainTeacherInput, sortedTeachers]);

  const updateAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = true;
      setShowAssistSuggestions(newShow);
  };

  const selectAssistant = (index: number, value: string) => {
      const newAssistants = [...assistants];
      newAssistants[index] = value;
      setAssistants(newAssistants);

      const newShow = [...showAssistSuggestions];
      newShow[index] = false;
      setShowAssistSuggestions(newShow);
  }

  const toggleAssistSuggestion = (index: number, status: boolean) => {
      const newShow = [...showAssistSuggestions];
      newShow[index] = status;
      setShowAssistSuggestions(newShow);
  }

  return (
    <div className="p-6 h-screen flex flex-col relative">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-slate-800">Danh Sách Lớp Học</h2>
      </div>

      <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 mb-6 flex gap-4 items-center">
         <select 
            className="px-4 py-2.5 border rounded-lg bg-white font-medium min-w-[150px] text-base"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
         >
            {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
         </select>

         <select 
            className="px-4 py-2.5 border rounded-lg bg-white min-w-[150px] text-base"
            value={selectedGrade}
            onChange={(e) => setSelectedGrade(e.target.value)}
         >
            <option value="all">Tất cả Khối</option>
            {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
         </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
         <div className="overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead>
                     <tr className="bg-slate-50 text-slate-600 text-base border-b border-slate-300">
                         <th className="px-4 py-3 w-16 text-center font-bold">STT</th>
                         <th className="px-4 py-3 font-bold">Tên Lớp</th>
                         <th className="px-4 py-3 font-bold">Khối</th>
                         <th className="px-4 py-3 text-center font-bold">Sĩ số</th>
                         <th className="px-4 py-3 text-center font-bold">Nam</th>
                         <th className="px-4 py-3 text-center font-bold">Nữ</th>
                         <th className="px-4 py-3 text-center font-bold">Phòng Học</th>
                         <th className="px-4 py-3 font-bold">GLV Chủ Nhiệm</th>
                         <th className="px-4 py-3 font-bold">GLV Phụ Trách</th>
                         {isAdmin && <th className="px-4 py-3 w-16 text-center"></th>}
                     </tr>
                 </thead>
                 <tbody className="">
                     {filteredClasses.length > 0 ? (
                         filteredClasses.map((c, index) => {
                             const stats = getClassStats(c.id);
                             const gradeName = grades.find(g => g.id === c.gradeId)?.name;

                             return (
                                 <tr key={c.id} className="hover:bg-slate-50 border-b border-slate-200 text-base text-slate-700">
                                     <td className="px-4 py-3 text-center text-slate-500">{index + 1}</td>
                                     <td className="px-4 py-3 font-bold text-slate-800">{c.name}</td>
                                     <td className="px-4 py-3 text-slate-600">{gradeName}</td>
                                     <td className="px-4 py-3 text-center font-bold text-blue-600 bg-blue-50/50">{stats.total}</td>
                                     <td className="px-4 py-3 text-center text-slate-600">{stats.male}</td>
                                     <td className="px-4 py-3 text-center text-slate-600">{stats.female}</td>
                                     <td className="px-4 py-3 text-center font-medium text-slate-700">{c.room || '--'}</td>
                                     <td className="px-4 py-3 font-medium text-slate-800">{c.mainTeacher || '---'}</td>
                                     <td className="px-4 py-3 text-slate-600 max-w-xs truncate" title={c.assistants}>{c.assistants || '---'}</td>
                                     {isAdmin && (
                                         <td className="px-4 py-3 text-center">
                                             <button onClick={() => handleEditClass(c)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full transition-colors">
                                                 <Edit size={18} />
                                             </button>
                                         </td>
                                     )}
                                 </tr>
                             );
                         })
                     ) : (
                         <tr><td colSpan={isAdmin ? 10 : 9} className="p-10 text-center text-slate-400 text-lg">Không có lớp học nào phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
         <div className="p-4 bg-slate-50 border-t border-slate-200 flex gap-8 justify-end text-base font-medium text-slate-600">
             <div className="flex items-center gap-2"><Users size={18}/> Tổng: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).total, 0)}</div>
             <div className="flex items-center gap-2"><User size={18}/> Nam: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).male, 0)}</div>
             <div className="flex items-center gap-2"><UserCheck size={18}/> Nữ: {filteredClasses.reduce((acc, c) => acc + getClassStats(c.id).female, 0)}</div>
         </div>
      </div>

      {editingClass && isAdmin && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-xl text-slate-800">Cập nhật Lớp học</h3>
                    <button onClick={() => setEditingClass(null)} className="text-slate-400 hover:text-slate-600"><X size={22}/></button>
                </div>
                <div className="p-6 space-y-5 overflow-y-auto custom-scrollbar">
                    {/* ... (Existing Edit Form Content - No Changes) ... */}
                    <div>
                        <label className="block text-base font-bold text-slate-700 mb-2">Tên Lớp</label>
                        <input 
                            type="text" 
                            className="w-full p-3 border rounded-lg bg-slate-100 text-slate-500 text-base" 
                            value={editingClass.name} 
                            disabled 
                        />
                    </div>
                    <div>
                        <label className="block text-base font-bold text-slate-700 mb-2">Số Phòng Học</label>
                        <input 
                            type="text" 
                            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-base" 
                            value={editingClass.room || ''} 
                            onChange={(e) => setEditingClass({...editingClass, room: e.target.value})}
                            placeholder="Nhập số phòng..."
                        />
                    </div>

                    <div className="relative">
                        <label className="block text-base font-bold text-slate-700 mb-2">GLV Chủ Nhiệm</label>
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full p-3 pl-4 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-base"
                                value={mainTeacherInput}
                                onChange={(e) => {
                                    setMainTeacherInput(e.target.value);
                                    setShowMainTeacherSuggestions(true);
                                }}
                                onFocus={() => setShowMainTeacherSuggestions(true)}
                                onBlur={() => setTimeout(() => setShowMainTeacherSuggestions(false), 200)}
                                placeholder="Nhập tên GLV..."
                            />
                            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        </div>
                        {showMainTeacherSuggestions && (
                            <div className="absolute z-10 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                {filteredMainTeacherSuggestions.length > 0 ? (
                                    filteredMainTeacherSuggestions.map(t => (
                                        <div 
                                            key={t.id}
                                            className="p-3 hover:bg-blue-50 cursor-pointer text-base flex items-center justify-between border-b border-slate-50 last:border-0"
                                            onClick={() => {
                                                setMainTeacherInput(`${t.saintName} ${t.fullName}`);
                                                setShowMainTeacherSuggestions(false);
                                            }}
                                        >
                                            <span>{t.saintName} {t.fullName}</span>
                                        </div>
                                    ))
                                ) : (
                                    <div className="p-3 text-sm text-slate-400 text-center italic">Không tìm thấy GLV phù hợp</div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                        <label className="block text-base font-bold text-slate-700 mb-3">GLV Phụ Trách</label>
                        <div className="space-y-3">
                             {assistants.map((val, idx) => {
                                const suggestions = getFilteredTeachers(val);
                                return (
                                    <div key={idx} className="relative">
                                        <div className="relative">
                                            <input 
                                                type="text"
                                                className="w-full p-3 pl-4 pr-8 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-base bg-white"
                                                placeholder={`GLV Phụ trách ${idx + 1}`}
                                                value={val}
                                                onChange={(e) => updateAssistant(idx, e.target.value)}
                                                onFocus={() => toggleAssistSuggestion(idx, true)}
                                                onBlur={() => setTimeout(() => toggleAssistSuggestion(idx, false), 200)}
                                            />
                                             <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                                        </div>
                                        {showAssistSuggestions[idx] && (
                                            <div className="absolute z-20 w-full bg-white border border-slate-200 rounded-lg shadow-lg max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {suggestions.length > 0 ? (
                                                    suggestions.map(t => (
                                                        <div 
                                                            key={t.id}
                                                            className="p-3 hover:bg-blue-50 cursor-pointer text-base flex items-center justify-between border-b border-slate-50 last:border-0"
                                                            onClick={() => selectAssistant(idx, `${t.saintName} ${t.fullName}`)}
                                                        >
                                                            <span>{t.saintName} {t.fullName}</span>
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="p-3 text-sm text-slate-400 text-center italic">Không tìm thấy</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                             })}
                        </div>
                    </div>
                </div>
                <div className="p-5 border-t border-slate-200 bg-slate-50 flex justify-end gap-3 mt-auto">
                    <button onClick={() => setEditingClass(null)} className="px-5 py-2.5 text-slate-600 hover:bg-slate-200 rounded-lg font-medium text-base">Hủy</button>
                    <button onClick={handleSaveClass} className="px-5 py-2.5 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2 text-base">
                        <Save size={20} /> Lưu Thay Đổi
                    </button>
                </div>
            </div>
        </div>
      )}
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher } from '../types';
import { Search, Plus, Edit, CheckCircle2, AlertTriangle, Save, User, History, GitMerge, ScrollText, X, Check, Phone, Fingerprint, Calendar, MapPin, Map } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  useEffect(() => {
     const active = years.find(y => y.isActive);
     if (active) setSelectedYear(active.id);
  }, [years]);

  const [showModal, setShowModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Deduplication States
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // --- FORM STATE ---
  // Core Info
  const [inputId, setInputId] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [inputBirthPlace, setInputBirthPlace] = useState('');
  const [inputClassId, setInputClassId] = useState(''); // New input state for class selection in modal

  // Family
  const [inputFatherName, setInputFatherName] = useState('');
  const [inputMotherName, setInputMotherName] = useState('');
  const [inputFatherPhone, setInputFatherPhone] = useState('');
  const [inputMotherPhone, setInputMotherPhone] = useState('');
  const [inputAddress, setInputAddress] = useState('');

  // Sacraments & Note
  const [inputBaptismDate, setInputBaptismDate] = useState('');
  const [inputBaptismBy, setInputBaptismBy] = useState('');
  const [inputBaptismSponsor, setInputBaptismSponsor] = useState('');
  const [inputBaptismPlace, setInputBaptismPlace] = useState('');

  const [inputEucharistDate, setInputEucharistDate] = useState('');
  const [inputEucharistBy, setInputEucharistBy] = useState('');
  const [inputEucharistPlace, setInputEucharistPlace] = useState('');

  const [inputConfirmationDate, setInputConfirmationDate] = useState('');
  const [inputConfirmationBy, setInputConfirmationBy] = useState('');
  const [inputConfirmationSponsor, setInputConfirmationSponsor] = useState('');
  const [inputConfirmationPlace, setInputConfirmationPlace] = useState('');

  const [inputOathDate, setInputOathDate] = useState('');
  const [inputNote, setInputNote] = useState('');

  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  // Real-time duplicate check
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  // Filter allowed classes
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (currentUser.role === 'ADMIN') return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser]);

  const classesInYear = useMemo(() => allowedClasses.filter(c => c.yearId === selectedYear), [allowedClasses, selectedYear]);

  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);

  const modalAvailableClasses = useMemo(() => {
      // In modal, we generally want to allow picking from any allowed class in the active year
      // Or simply reuse classesInYear
      return classesInYear;
  }, [classesInYear]);

  useEffect(() => {
    if (!showModal) return;
    const cleanName = inputName.trim().toLowerCase();
    if (cleanName.length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === cleanName && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  // Load data into form when modal opens
  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              // Edit Mode
              setInputId(selectedStudent.id);
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
              setInputBirthPlace(selectedStudent.birthPlace || '');
              setInputClassId(selectedStudent.classId);

              setInputFatherName(selectedStudent.fatherName || '');
              setInputMotherName(selectedStudent.motherName || '');
              setInputFatherPhone(selectedStudent.fatherPhone || '');
              setInputMotherPhone(selectedStudent.motherPhone || '');
              setInputAddress(selectedStudent.address || '');

              setInputBaptismDate(selectedStudent.baptismDate || '');
              setInputBaptismBy(selectedStudent.baptismBy || '');
              setInputBaptismSponsor(selectedStudent.baptismSponsor || '');
              setInputBaptismPlace(selectedStudent.baptismPlace || '');

              setInputEucharistDate(selectedStudent.eucharistDate || '');
              setInputEucharistBy(selectedStudent.eucharistBy || '');
              setInputEucharistPlace(selectedStudent.eucharistPlace || '');

              setInputConfirmationDate(selectedStudent.confirmationDate || '');
              setInputConfirmationBy(selectedStudent.confirmationBy || '');
              setInputConfirmationSponsor(selectedStudent.confirmationSponsor || '');
              setInputConfirmationPlace(selectedStudent.confirmationPlace || '');

              setInputOathDate(selectedStudent.confirmationOathDate || '');
              setInputNote(selectedStudent.note || '');
          } else {
              // Add Mode - Reset all
              const prefix = selectedYear.slice(2, 4);
              const yearStudents = students.filter(s => s.id.startsWith(prefix));
              const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
              setInputId(`${prefix}${nextNum}`); // Auto generate ID preview

              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
              // Default to first available class or selected class in filter
              setInputClassId(selectedClass !== 'all' ? selectedClass : (modalAvailableClasses[0]?.id || '')); 
              setInputBirthPlace('');
              setInputFatherName('');
              setInputMotherName('');
              setInputFatherPhone('');
              setInputMotherPhone('');
              setInputAddress('');
              setInputBaptismDate('');
              setInputBaptismBy('');
              setInputBaptismSponsor('');
              setInputBaptismPlace('');
              setInputEucharistDate('');
              setInputEucharistBy('');
              setInputEucharistPlace('');
              setInputConfirmationDate('');
              setInputConfirmationBy('');
              setInputConfirmationSponsor('');
              setInputConfirmationPlace('');
              setInputOathDate('');
              setInputNote('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent, selectedYear, students, selectedClass, modalAvailableClasses]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());

        let validClassIds: string[] = [];

        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else {
            // If selecting "All Classes", only show classes this teacher is allowed to see
            validClassIds = availableClasses.map(c => c.id);
        }

        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, availableClasses]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const getClassColor = (classId: string) => {
      const cls = classes.find(c => c.id === classId);
      if (!cls) return 'bg-slate-100 text-slate-700 border-slate-200';

      // Map based on Grade ID from constants (g1, g2, g3, g4)
      switch (cls.gradeId) {
          case 'g1': return 'bg-pink-100 text-pink-700 border-pink-200'; // Khai Tâm (Hồng)
          case 'g2': return 'bg-green-100 text-green-700 border-green-200'; // Rước Lễ (Xanh lá)
          case 'g3': return 'bg-blue-100 text-blue-700 border-blue-200'; // Thêm Sức (Xanh dương)
          case 'g4': return 'bg-yellow-100 text-yellow-800 border-yellow-200'; // Bao Đồng (Vàng - text tối hơn để dễ đọc)
          default: return 'bg-slate-100 text-slate-700 border-slate-200';
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.pop() || '';
      const lastName = parts.join(' ');
      return { lastName, firstName };
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ: Tên Thánh, Họ tên, Ngày sinh.");
    if (!inputClassId) return alert("Vui lòng chọn lớp cho học viên.");

    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        const confirmSave = window.confirm(`Hệ thống phát hiện ${realtimeDuplicates.length} học viên có cùng Họ tên và Ngày sinh. Bạn có chắc chắn muốn tạo thêm hồ sơ mới này không?`);
        if (!confirmSave) return;
    }

    const studentData: Student = {
        id: inputId, // Use the ID from state (either existing or generated)
        fullName: inputName,
        dob: inputDob,
        saintName: saintInput,
        gender: inputGender,
        status: inputStatus,
        classId: inputClassId,
        parish: 'Gx. Tân Thành', // Default or add input if needed

        // Extended fields
        birthPlace: inputBirthPlace,
        fatherName: inputFatherName,
        motherName: inputMotherName,
        fatherPhone: inputFatherPhone,
        motherPhone: inputMotherPhone,
        address: inputAddress,

        baptismDate: inputBaptismDate,
        baptismBy: inputBaptismBy,
        baptismSponsor: inputBaptismSponsor,
        baptismPlace: inputBaptismPlace,

        eucharistDate: inputEucharistDate,
        eucharistBy: inputEucharistBy,
        eucharistPlace: inputEucharistPlace,

        confirmationDate: inputConfirmationDate,
        confirmationBy: inputConfirmationBy,
        confirmationSponsor: inputConfirmationSponsor,
        confirmationPlace: inputConfirmationPlace,

        confirmationOathDate: inputOathDate,
        note: inputNote
    };

    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? studentData : s));
        showToast("Đã cập nhật hồ sơ thành công!");
    } else {
        setStudents(prev => [...prev, studentData]);
        showToast(`Đã thêm học viên mới: ${inputId}`);
    }
    setShowModal(false);
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      // Only scan duplicates within allowed students for this teacher
      filteredStudents.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;

      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Xác nhận giữ lại hồ sơ [${survivorId}] và xóa ${idsToDelete.length} bản ghi trùng?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp và làm sạch dữ liệu thành công!`);
          if (duplicateGroups.length <= 1) setShowDedupModal(false);
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
        default: return null;
    }
  };

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
      {/* ... (Keep existing Toast) ... */}
      {toast && (
        <div className="fixed top-20 right-4 z-[100] animate-slide-in max-w-[90vw]">
           <div className={`text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast.message}</span>
           </div>
        </div>
      )}

      {/* Header Mobile: Stack vertical, Desktop: Horizontal */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">HỌC VIÊN</h2>
            <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200 uppercase tracking-widest">{filteredStudents.length} hồ sơ</div>
        </div>
        <div className="flex w-full md:w-auto gap-2">
            <button onClick={scanDuplicates} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-3 py-2.5 bg-white border border-amber-400 text-amber-700 rounded-xl hover:bg-amber-50 text-xs font-black shadow-sm transition-all active:scale-95 group whitespace-nowrap">
                <GitMerge size={16} /> <span className="hidden sm:inline">RÀ SOÁT</span> TRÙNG
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase tracking-wide text-xs">
                <Plus size={18} /> Thêm Mới
            </button>
        </div>
      </div>

      {/* Filter Bar: Mobile - Column, Desktop - Row */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4">
        <div className="flex flex-col md:flex-row flex-wrap gap-2 items-stretch md:items-center">
            <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
              {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
            </select>
            <div className="flex gap-2">
                <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
                <option value="all">Tất cả Khối</option>
                {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
                </select>
                <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
                <option value="all">Tất cả Lớp</option>
                {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
            </div>
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      {/* --- CONTENT AREA: TABLE FOR DESKTOP / CARDS FOR MOBILE --- */}
      <div className="flex-1 overflow-hidden flex flex-col bg-slate-50 md:bg-white md:rounded-2xl md:shadow-sm md:border md:border-slate-200">

        {/* MOBILE: CARD LIST VIEW */}
        <div className="md:hidden overflow-y-auto custom-scrollbar h-full space-y-3 pb-20">
            {filteredStudents.length > 0 ? (
                filteredStudents.map((s) => (
                    <div key={s.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col gap-3 relative overflow-hidden">
                        {/* Status Strip */}
                        <div className={`absolute top-0 left-0 bottom-0 w-1.5 ${s.status === 'ACTIVE' ? 'bg-green-500' : s.status === 'DROPPED' ? 'bg-red-500' : 'bg-orange-500'}`}></div>

                        <div className="flex justify-between items-start pl-2">
                            <div>
                                <div className="flex items-center gap-2 mb-1">
                                    <span className="font-mono text-[10px] text-slate-400 font-bold bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200">#{s.id}</span>
                                    <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded border ${getClassColor(s.classId)}`}>{getClassName(s.classId)}</span>
                                </div>
                                <h3 className="font-black text-slate-800 text-lg leading-tight uppercase">
                                    <span className="text-slate-500 text-sm block mb-0.5 font-bold">{s.saintName}</span>
                                    {s.fullName}
                                </h3>
                            </div>
                            <button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-2 bg-slate-50 text-blue-600 rounded-lg border border-slate-200 hover:bg-blue-50 active:scale-95 transition-all">
                                <Edit size={18} />
                            </button>
                        </div>

                        <div className="grid grid-cols-2 gap-2 pl-2 text-xs">
                             <div className="flex items-center gap-2 text-slate-600">
                                <Calendar size={14} className="text-slate-400"/>
                                <span className="font-medium">{new Date(s.dob).toLocaleDateString('vi-VN')}</span>
                             </div>
                             <div className="flex items-center gap-2">
                                <User size={14} className={s.gender === 'Male' ? 'text-blue-400' : 'text-pink-400'}/>
                                <span className={`font-black ${s.gender === 'Male' ? 'text-blue-600' : 'text-pink-600'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span>
                             </div>
                        </div>

                        {/* ... (Rest of Mobile Card - same as before) ... */}
                        {(s.fatherPhone || s.motherPhone || s.address) && (
                            <div className="pl-2 pt-2 border-t border-slate-100 space-y-1.5">
                                {(s.fatherPhone || s.motherPhone) && (
                                    <div className="flex gap-3 text-sm font-medium">
                                        {s.fatherPhone && <div className="flex items-center gap-1 text-slate-600"><Phone size={12} className="text-slate-400"/> <span className="font-bold">B:</span> {s.fatherPhone}</div>}
                                        {s.motherPhone && <div className="flex items-center gap-1 text-slate-600"><Phone size={12} className="text-slate-400"/> <span className="font-bold">M:</span> {s.motherPhone}</div>}
                                    </div>
                                )}
                                {s.address && (
                                    <div className="flex items-start gap-1.5 text-xs text-slate-500">
                                        <MapPin size={12} className="mt-0.5 text-slate-400 shrink-0"/> 
                                        <span className="line-clamp-1">{s.address}</span>
                                    </div>
                                )}
                            </div>
                        )}

                        <div className="pl-2 flex justify-between items-center pt-1">
                             {getStatusBadge(s.status)}
                             {s.note && <span className="text-[10px] text-slate-400 italic max-w-[150px] truncate text-right">"{s.note}"</span>}
                        </div>
                    </div>
                ))
            ) : (
                <div className="p-10 text-center text-slate-400 italic font-medium bg-white rounded-xl border border-slate-200 mx-4">
                    Không tìm thấy dữ liệu.
                </div>
            )}
        </div>

        {/* DESKTOP: TABLE VIEW */}
        <div className="hidden md:block overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b border-slate-300 uppercase text-[11px] tracking-wider">
              <tr>
                <th className="px-4 py-4 w-12 text-center">#</th>
                <th className="px-4 py-4 w-24">Mã</th>
                <th className="px-4 py-4 w-32">Tên Thánh</th>
                <th className="px-4 py-4">Họ & Đệm</th>
