                                <div key={col.id} draggable onDragStart={(e) => handleColDragStart(e, col.id)} onDragOver={handleColDragOver} onDragEnter={() => handleColDragEnter(col.id)} onDragEnd={handleColDragEnd} onDrop={(e) => handleColDrop(e, col.id)} className={`flex gap-2 items-center bg-purple-50/50 p-2 rounded-lg border transition-all ${isDragging ? 'opacity-30 border-purple-500 border-dashed' : 'border-purple-100'} ${isOver ? 'ring-2 ring-purple-300 translate-x-1' : ''}`}>
                                    <div className="cursor-grab text-slate-300 hover:text-purple-500"><GripVertical size={16}/></div>
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateScoreColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col"><span className="text-[8px] font-bold text-purple-400 uppercase">Hệ số</span><select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateScoreColumn(col.id, 'weight', Number(e.target.value))}><option value={0}>x0</option><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select></div>
                                    <button onClick={() => removeScoreColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            )})}
                        </div>
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleSaveScoreColumns} className="px-6 py-2 bg-violet-600 text-white rounded-lg font-bold hover:bg-violet-700 transition-all shadow flex items-center gap-2">
                        <Save size={18}/> Lưu Cấu Hình Điểm
                    </button>
                </div>
            </div>

            {/* 8. Quản Lý Tên Thánh */}
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
            <div className="flex items-center gap-3 mb-6 border-b pb-4"><Cross className="text-amber-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Tên Thánh</h3></div>
            <div className="space-y-6">
                <div className="flex gap-3 bg-amber-50 p-4 rounded-xl border border-amber-100"><input type="text" placeholder="Nhập tên thánh..." className="flex-1 p-3 border border-amber-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-amber-500" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-3 border border-amber-200 rounded-xl text-sm bg-white" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-6 py-3 bg-amber-600 text-white rounded-xl hover:bg-amber-700 font-extrabold shadow-md transition-all">+</button></div>
                <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-80 overflow-y-auto custom-scrollbar bg-slate-50"><table className="w-full text-left text-sm border-collapse"><thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10"><tr><th className="p-4 font-bold text-slate-600">Tên Thánh</th><th className="p-4 font-bold text-slate-600 w-24">Giới tính</th><th className="p-4 w-16"></th></tr></thead><tbody className="bg-white">{saints.map(s => (<tr key={s.id} className="hover:bg-amber-50/50 transition-colors border-b border-slate-200"><td className="p-4 font-bold text-slate-700">{s.name}</td><td className="p-4"><span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${s.gender === 'Male' ? 'bg-blue-100 text-blue-700' : 'bg-pink-100 text-pink-700'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td><td className="p-4 text-right"><button onClick={() => handleRemoveSaint(s.id)} className="p-2 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={18} /></button></td></tr>))}</tbody></table></div>
            </div>
            </div>
        </>
        )}

        {/* 9. Tài khoản & Bảo mật (Visible to Everyone) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
             <div className="flex items-center gap-3 mb-6 border-b pb-4">
                <UserCog className="text-slate-600 w-6 h-6" />
                <h3 className="font-bold text-xl text-slate-800">Tài Khoản & Bảo Mật</h3>
            </div>
            <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu hiện tại</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={currentPass} onChange={e => setCurrentPass(e.target.value)}/>
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu mới</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={newPass} onChange={e => setNewPass(e.target.value)}/>
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Nhập lại mật khẩu mới</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={confirmPass} onChange={e => setConfirmPass(e.target.value)}/>
                    </div>
                </div>
                <button onClick={handleChangePassword} className="w-full py-2 bg-slate-800 text-white rounded-lg font-bold text-sm hover:bg-slate-900 shadow mt-2">
                    Đổi Mật Khẩu
                </button>
            </div>
        </div>

      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher, Saint } from '../types';
import { MOCK_SAINTS } from '../constants';
import { Search, Plus, Filter, Edit, Trash2, X, Save, CheckCircle2, User, Phone, MapPin, Calendar, Users, ChevronDown, ChevronRight, Download } from 'lucide-react';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<string | null>(null);

  // Modal States
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState<Partial<Student>>({});

  // Saint Autocomplete
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [saintInput, setSaintInput] = useState('');

  const isAdmin = currentUser?.role === 'ADMIN';

  const showToast = (message: string) => {
    setToast(message);
    setTimeout(() => setToast(null), 3000);
  };

  // Filter Allowed Classes based on User Role
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (currentUser.role === 'ADMIN') return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser]);

  // Initial Filter Selection
  useEffect(() => {
     const active = years.find(y => y.isActive);
     const activeYearId = active ? active.id : (years[0]?.id || '');
     setSelectedYear(activeYearId);

     if (!isAdmin && activeYearId) {
         const myClassesInYear = allowedClasses.filter(c => c.yearId === activeYearId);
         if (myClassesInYear.length > 0) {
             setSelectedClass(myClassesInYear[0].id);
         } else {
             setSelectedClass('');
         }
     }
  }, [years, isAdmin, allowedClasses]);

  const classesInYear = useMemo(() => allowedClasses.filter(c => c.yearId === selectedYear), [allowedClasses, selectedYear]);

  const availableClasses = useMemo(() => {
    if (selectedGrade === 'all') return classesInYear;
    return classesInYear.filter(c => c.gradeId === selectedGrade);
  }, [classesInYear, selectedGrade]);

  // Update selected class when available classes change (mostly for Admin)
  useEffect(() => {
      if (isAdmin) {
          if (availableClasses.length > 0 && !availableClasses.find(c => c.id === selectedClass)) {
              // setSelectedClass(availableClasses[0].id); // Optional: Auto select first class
              setSelectedClass(''); // Better to reset if filtered out
          }
      }
  }, [availableClasses, selectedClass, isAdmin]);

  // Filter Students
  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchYear = classes.find(c => c.id === s.classId)?.yearId === selectedYear;
      const matchGrade = selectedGrade === 'all' || classes.find(c => c.id === s.classId)?.gradeId === selectedGrade;
      const matchClass = !selectedClass || s.classId === selectedClass;

      const q = searchTerm.toLowerCase();
      const matchSearch = s.fullName.toLowerCase().includes(q) || 
                          s.saintName.toLowerCase().includes(q) || 
                          s.id.toLowerCase().includes(q);

      // Security check: GLV can only see students in their allowed classes
      const isInAllowedClass = allowedClasses.some(c => c.id === s.classId);

      return matchYear && matchGrade && matchClass && matchSearch && isInAllowedClass;
    });
  }, [students, classes, selectedYear, selectedGrade, selectedClass, searchTerm, allowedClasses]);

  // Handlers
  const handleAddNew = () => {
      setIsEditing(false);
      setFormData({
          id: `${new Date().getFullYear().toString().slice(2)}00${Math.floor(Math.random() * 1000)}`,
          status: 'ACTIVE',
          gender: 'Male',
          classId: selectedClass || availableClasses[0]?.id || '',
          saintName: '',
          fullName: ''
      });
      setSaintInput('');
      setShowModal(true);
  };

  const handleEdit = (student: Student) => {
      setIsEditing(true);
      setFormData({ ...student });
      setSaintInput(student.saintName);
      setShowModal(true);
  };

  const handleDelete = (id: string) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa học viên này? Hành động này sẽ xóa cả điểm số và chuyên cần.")) {
          setStudents(students.filter(s => s.id !== id));
          showToast("Đã xóa học viên thành công!");
      }
  };

  const handleSave = () => {
      if (!formData.fullName || !formData.saintName || !formData.classId) {
          alert("Vui lòng nhập đầy đủ thông tin bắt buộc (Tên Thánh, Họ tên, Lớp)");
          return;
      }

      if (isEditing) {
          setStudents(students.map(s => s.id === formData.id ? { ...s, ...formData } as Student : s));
          showToast("Đã cập nhật thông tin học viên!");
      } else {
          setStudents([...students, formData as Student]);
          showToast("Đã thêm học viên mới!");
      }
      setShowModal(false);
  };

  const filteredSaints = MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));

  // Render Helpers
  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || '---';

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50 md:bg-white/50">
       {/* Toast */}
       {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
            <h2 className="text-2xl md:text-3xl font-bold text-slate-800">Danh Sách Học Viên</h2>
            <p className="text-slate-500 text-sm mt-1">Quản lý hồ sơ và thông tin chi tiết</p>
        </div>
        <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all font-bold text-sm">
            <Plus size={18} /> Thêm Học Viên
        </button>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-3 items-stretch md:items-center">
         {/* Common Filters */}
         <div className="flex flex-col md:flex-row gap-2 flex-1">
             {isAdmin ? (
                 <>
                    <select className="input-select font-bold" value={selectedYear} onChange={e => setSelectedYear(e.target.value)}>
                        {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
                    </select>
                    <div className="flex gap-2">
                        <select className="input-select font-bold" value={selectedGrade} onChange={e => setSelectedGrade(e.target.value)}>
                            <option value="all">Tất cả Khối</option>
                            {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
                        </select>
                        <select className="input-select font-bold text-blue-700 bg-blue-50" value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
                            <option value="">Tất cả Lớp</option>
                            {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                 </>
             ) : (
                // GLV Simplified View
                 <div className="flex flex-col md:flex-row items-start md:items-center gap-2 w-full">
                     <div className="bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 flex items-center gap-2 text-sm font-bold text-slate-700 min-w-fit">
                         <Calendar size={16} className="text-slate-400"/>
                         {years.find(y => y.id === selectedYear)?.name}
                     </div>
                     <select className="input-select font-bold text-blue-700 bg-blue-50 w-full md:w-auto" value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
                        {availableClasses.length > 1 && <option value="">Tất cả Lớp Phụ Trách</option>}
                        {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                     </select>
                 </div>
             )}
         </div>

         {/* Search Box */}
         <div className="relative w-full md:w-64">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
                type="text" 
                placeholder="Tìm tên, tên thánh..." 
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
             />
         </div>
      </div>

      {/* List / Table */}
      <div className="bg-white md:rounded-xl md:shadow-sm md:border md:border-slate-300 flex-1 overflow-hidden flex flex-col bg-transparent">
         {/* MOBILE LIST */}
         <div className="md:hidden overflow-y-auto h-full space-y-3 pb-20">
             {filteredStudents.map(s => (
                 <div key={s.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-3">
                     <div className="flex justify-between items-start">
                         <div className="flex items-start gap-3">
                             <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white text-sm ${s.gender === 'Male' ? 'bg-blue-500' : 'bg-pink-500'}`}>
                                 {s.fullName.charAt(0)}
                             </div>
                             <div>
                                 <h3 className="font-bold text-slate-800 text-sm">{s.saintName} {s.fullName}</h3>
                                 <div className="text-xs text-slate-500">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                                 <div className="text-[10px] text-slate-400 mt-0.5 font-mono">ID: {s.id}</div>
                             </div>
                         </div>
                         <div className="flex flex-col items-end gap-1">
                             <span className="text-[10px] font-bold bg-slate-100 text-slate-600 px-2 py-0.5 rounded">{getClassName(s.classId)}</span>
                             {s.status === 'ACTIVE' ? (
                                 <span className="text-[10px] font-bold text-green-600 flex items-center gap-1"><CheckCircle2 size={10}/> Đang học</span>
                             ) : (
                                 <span className="text-[10px] font-bold text-red-600">Nghỉ/Chuyển</span>
                             )}
                         </div>
                     </div>

                     <div className="grid grid-cols-2 gap-2 text-xs border-t border-slate-50 pt-3 mt-1">
                         <div>
                             <span className="block text-[10px] text-slate-400 uppercase font-bold">Cha</span>
                             <span className="font-medium text-slate-700">{s.fatherName || '---'}</span>
                             {s.fatherPhone && <div className="text-blue-600 flex items-center gap-1 mt-0.5"><Phone size={10}/> {s.fatherPhone}</div>}
                         </div>
                         <div>
                             <span className="block text-[10px] text-slate-400 uppercase font-bold">Mẹ</span>
                             <span className="font-medium text-slate-700">{s.motherName || '---'}</span>
                             {s.motherPhone && <div className="text-blue-600 flex items-center gap-1 mt-0.5"><Phone size={10}/> {s.motherPhone}</div>}
                         </div>
                     </div>

                     <div className="flex gap-2 mt-2">
                         <button onClick={() => handleEdit(s)} className="flex-1 py-2 rounded-lg bg-blue-50 text-blue-600 font-bold text-xs flex items-center justify-center gap-2 hover:bg-blue-100"><Edit size={14}/> Chi tiết</button>
                         {isAdmin && <button onClick={() => handleDelete(s.id)} className="p-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-100"><Trash2 size={14}/></button>}
                     </div>
                 </div>
             ))}
             {filteredStudents.length === 0 && (
                 <div className="text-center p-8 text-slate-400 italic bg-white rounded-xl border border-slate-200 mx-4">Không tìm thấy học viên nào.</div>
             )}
         </div>

         {/* DESKTOP TABLE */}
         <div className="hidden md:block overflow-x-auto custom-scrollbar">
             <table className="w-full text-left border-collapse">
                 <thead className="bg-slate-50 text-slate-600 text-xs uppercase sticky top-0 z-10 font-bold">
                     <tr>
                         <th className="px-4 py-3 w-16 text-center border-b border-slate-300">STT</th>
                         <th className="px-4 py-3 border-b border-slate-300">Mã HV</th>
                         <th className="px-4 py-3 border-b border-slate-300">Họ và Tên</th>
                         <th className="px-4 py-3 border-b border-slate-300">Ngày sinh / Nơi sinh</th>
                         <th className="px-4 py-3 border-b border-slate-300">Lớp</th>
                         <th className="px-4 py-3 border-b border-slate-300">Phụ Huynh</th>
                         <th className="px-4 py-3 border-b border-slate-300 text-center">Trạng Thái</th>
                         <th className="px-4 py-3 border-b border-slate-300 text-center w-24">Thao tác</th>
                     </tr>
                 </thead>
                 <tbody className="text-sm">
                     {filteredStudents.map((s, idx) => (
                         <tr key={s.id} className="hover:bg-slate-50 border-b border-slate-200 transition-colors">
                             <td className="px-4 py-3 text-center text-slate-500">{idx + 1}</td>
                             <td className="px-4 py-3 font-mono text-xs text-slate-500">{s.id}</td>
                             <td className="px-4 py-3">
                                 <div className="font-bold text-slate-800">{s.saintName} {s.fullName}</div>
                                 <div className="text-xs text-slate-500 flex items-center gap-1">
                                     {s.gender === 'Male' ? <span className="text-blue-500">Nam</span> : <span className="text-pink-500">Nữ</span>}
                                 </div>
                             </td>
                             <td className="px-4 py-3">
                                 <div className="font-medium text-slate-700">{new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                                 <div className="text-xs text-slate-500 truncate max-w-[150px]" title={s.birthPlace}>{s.birthPlace}</div>
                             </td>
                             <td className="px-4 py-3">
                                 <span className="px-2 py-1 bg-slate-100 text-slate-700 rounded text-xs font-bold whitespace-nowrap">
                                     {getClassName(s.classId)}
                                 </span>
                             </td>
                             <td className="px-4 py-3">
                                 <div className="text-xs">
                                     <div className="flex gap-1"><span className="font-bold text-slate-400">B:</span> <span className="truncate max-w-[100px]">{s.fatherName}</span></div>
                                     <div className="flex gap-1"><span className="font-bold text-slate-400">M:</span> <span className="truncate max-w-[100px]">{s.motherName}</span></div>
                                 </div>
                             </td>
                             <td className="px-4 py-3 text-center">
                                 {s.status === 'ACTIVE' ? (
                                     <span className="inline-flex items-center gap-1 px-2 py-1 bg-green-100 text-green-700 rounded-full text-[10px] font-bold uppercase">
                                         <CheckCircle2 size={10}/> Đang học
                                     </span>
                                 ) : (
                                     <span className="inline-flex items-center gap-1 px-2 py-1 bg-red-100 text-red-700 rounded-full text-[10px] font-bold uppercase">
                                         Nghỉ/Chuyển
                                     </span>
                                 )}
                             </td>
                             <td className="px-4 py-3 text-center">
                                 <div className="flex justify-center gap-2">
                                     <button onClick={() => handleEdit(s)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors"><Edit size={16}/></button>
                                     {isAdmin && <button onClick={() => handleDelete(s.id)} className="p-1.5 text-red-500 hover:bg-red-100 rounded-lg transition-colors"><Trash2 size={16}/></button>}
                                 </div>
                             </td>
                         </tr>
                     ))}
                     {filteredStudents.length === 0 && (
                         <tr><td colSpan={8} className="p-10 text-center text-slate-400 italic">Không tìm thấy dữ liệu phù hợp</td></tr>
                     )}
                 </tbody>
             </table>
         </div>
      </div>

      {/* Modal - Add/Edit Student */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-4xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
