import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, AcademicRecord, Teacher } from '../types';
import { Search, Plus, Edit, Trash2, X, Filter, CheckCircle2, AlertTriangle, Download } from 'lucide-react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<string | null>(null);

  // Modal State
  const [showModal, setShowModal] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);

  // Delete Confirmation
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Student>>({});
  const [saintInput, setSaintInput] = useState('');
  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);

  const isAdmin = currentUser?.role === 'ADMIN';

  // Initialize selected year
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) setSelectedYear(active.id);
  }, [years]);

  // GLV Permission Logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (isAdmin) return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser, isAdmin]);

  // Filter classes based on year/grade and permissions
  const availableClasses = useMemo(() => {
    return allowedClasses.filter(c => 
        c.yearId === selectedYear && 
        (selectedGrade === 'all' || c.gradeId === selectedGrade)
    );
  }, [allowedClasses, selectedYear, selectedGrade]);

  // Auto-select class for GLV
  useEffect(() => {
      if (!isAdmin && availableClasses.length > 0 && !selectedClass) {
          setSelectedClass(availableClasses[0].id);
      }
  }, [availableClasses, isAdmin, selectedClass]);

  // Filter Students
  const filteredStudents = useMemo(() => {
      return students.filter(s => {
          // 1. Filter by Class (if selected) or Year context
          let classMatch = true;
          if (selectedClass) {
              classMatch = s.classId === selectedClass;
          } else {
              // If no class selected, filtering by available classes in current context
              const availableClassIds = availableClasses.map(c => c.id);
              classMatch = availableClassIds.includes(s.classId);
          }

          // 2. Search
          const searchLower = searchTerm.toLowerCase();
          const searchMatch = !searchTerm || 
              s.fullName.toLowerCase().includes(searchLower) ||
              s.saintName.toLowerCase().includes(searchLower) ||
              s.id.includes(searchTerm);

          return classMatch && searchMatch;
      });
  }, [students, selectedClass, availableClasses, searchTerm]);

  const showToast = (msg: string) => {
      setToast(msg);
      setTimeout(() => setToast(null), 3000);
  };

  const handleAddNew = () => {
      setEditingStudent(null);
      setFormData({
          id: `23${Date.now().toString().slice(-4)}`,
          gender: 'Male',
          status: 'ACTIVE',
          classId: selectedClass || availableClasses[0]?.id || ''
      });
      setSaintInput('');
      setShowModal(true);
  };

  const handleEdit = (s: Student) => {
      setEditingStudent(s);
      setFormData({ ...s });
      setSaintInput(s.saintName);
      setShowModal(true);
  };

  const handleDelete = () => {
      if (studentToDelete) {
          setStudents(students.filter(s => s.id !== studentToDelete.id));
          showToast(`Đã xóa học viên ${studentToDelete.fullName}`);
          setStudentToDelete(null);
      }
  };

  const handleSave = () => {
      if (!formData.fullName || !formData.classId) return alert('Vui lòng nhập tên và chọn lớp');

      const studentData: Student = {
          ...formData as Student,
          saintName: saintInput || formData.saintName || ''
      };

      if (editingStudent) {
          setStudents(students.map(s => s.id === editingStudent.id ? studentData : s));
          showToast('Cập nhật học viên thành công');
      } else {
          setStudents([...students, studentData]);
          showToast('Thêm học viên mới thành công');
      }
      setShowModal(false);
  };

  const filteredSaints = MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));

  const exportExcel = () => {
      // Mock export functionality
      const headers = ["ID", "Tên Thánh", "Họ Tên", "Ngày Sinh", "Giới Tính", "Lớp", "Phụ Huynh", "SĐT"];
      const rows = filteredStudents.map(s => [
          s.id, s.saintName, s.fullName, s.dob, s.gender === 'Male' ? 'Nam' : 'Nữ',
          classes.find(c => c.id === s.classId)?.name || '',
          `${s.fatherName || ''} - ${s.motherName || ''}`,
          `${s.fatherPhone || ''} ${s.motherPhone || ''}`
      ]);

      const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].map(e => e.join(",")).join("\n");
      const encodedUri = encodeURI(csvContent);
      const link = document.createElement("a");
      link.setAttribute("href", encodedUri);
      link.setAttribute("download", `danh_sach_hoc_vien_${selectedClass || 'all'}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Quản Lý Học Viên</h2>
            <p className="text-sm text-slate-500">Tổng số: {filteredStudents.length} học viên</p>
        </div>
        <div className="flex gap-2">
            <button onClick={exportExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-bold text-sm shadow-sm transition-all">
                <Download size={16} /> Xuất Excel
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold text-sm shadow-sm transition-all">
                <Plus size={16} /> Thêm Mới
            </button>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Niên khóa</label>
              <select className="w-full p-2 border rounded-lg text-sm" value={selectedYear} onChange={e => setSelectedYear(e.target.value)}>
                  {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
              </select>
          </div>
          <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Khối</label>
              <select className="w-full p-2 border rounded-lg text-sm" value={selectedGrade} onChange={e => setSelectedGrade(e.target.value)}>
                  <option value="all">Tất cả</option>
                  {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
              </select>
          </div>
          <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Lớp</label>
              <select className="w-full p-2 border rounded-lg text-sm font-bold text-blue-700" value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
                  <option value="">-- Tất cả lớp --</option>
                  {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
          </div>
          <div className="relative">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Tìm kiếm</label>
              <input 
                 type="text" 
                 className="w-full p-2 pl-9 border rounded-lg text-sm" 
                 placeholder="Tên, tên thánh..." 
                 value={searchTerm}
                 onChange={e => setSearchTerm(e.target.value)}
              />
              <Search className="absolute left-3 top-8 text-slate-400" size={16} />
          </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
          <div className="overflow-x-auto custom-scrollbar">
