import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, AcademicRecord, TermConfig, Teacher } from '../types';
import { Calendar, Save, CheckCircle2, Search, Filter, AlertCircle, ChevronLeft, ChevronRight } from 'lucide-react';

interface AttendanceProps {
    students: Student[];
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
    records: AcademicRecord[]; // Added records prop
    setRecords: React.Dispatch<React.SetStateAction<AcademicRecord[]>>;
    termConfigs: TermConfig[];
    currentUser: Teacher | null;
}

export const Attendance: React.FC<AttendanceProps> = ({ students, classes, years, grades, records, setRecords, termConfigs, currentUser }) => {
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedTerm, setSelectedTerm] = useState<'HK1'|'HK2'>('HK1');
  const [toast, setToast] = useState<string | null>(null);

  const isAdmin = currentUser?.role === 'ADMIN';

  // Initialize selected year
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (active) setSelectedYear(active.id);
  }, [years]);

  // Determine current term based on date
  useEffect(() => {
      const now = new Date();
      const currentConfig = termConfigs.find(t => 
          t.yearId === selectedYear && 
          new Date(t.startDate) <= now && 
          new Date(t.endDate) >= now
      );
      if (currentConfig) {
          setSelectedTerm(currentConfig.term);
      }
  }, [termConfigs, selectedYear]);

  // Permissions & Classes Logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (isAdmin) return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser, isAdmin]);

  const availableClasses = useMemo(() => {
      return allowedClasses.filter(c => c.yearId === selectedYear);
  }, [allowedClasses, selectedYear]);

  useEffect(() => {
      if (!isAdmin && availableClasses.length > 0 && !selectedClass) {
          setSelectedClass(availableClasses[0].id);
      }
  }, [availableClasses, isAdmin, selectedClass]);

  // Filter students
  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students
        .filter(s => s.classId === selectedClass && s.status === 'ACTIVE')
        .sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, selectedClass]);

  const showToast = (msg: string) => {
      setToast(msg);
      setTimeout(() => setToast(null), 3000);
  };

  // Helper to update record
  const updateAbsence = (studentId: string, type: 'P' | 'K', delta: number) => {
      setRecords(prev => {
          const existingIdx = prev.findIndex(r => r.studentId === studentId && r.term === selectedTerm);
          const newRecords = [...prev];

          if (existingIdx > -1) {
              const record = newRecords[existingIdx];
              const newVal = type === 'P' 
                  ? Math.max(0, (record.absentP || 0) + delta) 
                  : Math.max(0, (record.absentK || 0) + delta);

              newRecords[existingIdx] = {
                  ...record,
                  absentP: type === 'P' ? newVal : (record.absentP || 0),
                  absentK: type === 'K' ? newVal : (record.absentK || 0)
              };
              return newRecords;
          } else {
              // Create new record
              return [...newRecords, {
                  studentId,
                  term: selectedTerm,
                  scores: {},
                  scorePray: 0,
                  scoreExam: 0,
                  average: 0,
                  absentP: type === 'P' ? Math.max(0, delta) : 0,
                  absentK: type === 'K' ? Math.max(0, delta) : 0
              }];
          }
      });
  };

  return (
      <AttendanceContent 
          students={filteredStudents} 
          records={records}
          updateAbsence={updateAbsence} 
          selectedTerm={selectedTerm}
          setSelectedTerm={setSelectedTerm}
          selectedYear={selectedYear}
          setSelectedYear={setSelectedYear}
          selectedClass={selectedClass}
          setSelectedClass={setSelectedClass}
          years={years}
          availableClasses={availableClasses}
          toast={toast}
      />
  );
};

