    inventory: InventoryItem[];
}

export const DeviceRegistration: React.FC<DeviceRegistrationProps> = ({ requests, setRequests, currentUser, inventory }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [filterStatus, setFilterStatus] = useState<string>('all');
    const [showModal, setShowModal] = useState(false);
    const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

    const isAdmin = currentUser?.role === 'ADMIN';

    // Form State
    const [inputDeviceName, setInputDeviceName] = useState('');
    const [inputDate, setInputDate] = useState(new Date().toISOString().split('T')[0]);
    const [inputSession, setInputSession] = useState<'Sáng' | 'Chiều' | 'Tối'>('Sáng');
    const [inputPurpose, setInputPurpose] = useState('');

    const showToast = (message: string, type: 'success' | 'error' = 'success') => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    };

    // Filter requests
    const filteredRequests = useMemo(() => {
        let list = requests;

        // GLV only sees their own requests
        if (!isAdmin && currentUser) {
            list = list.filter(r => r.teacherId === currentUser.id);
        }

        if (filterStatus !== 'all') {
            list = list.filter(r => r.status === filterStatus);
        }

        if (searchTerm) {
            const lowerSearch = searchTerm.toLowerCase();
            list = list.filter(r => 
                r.deviceName.toLowerCase().includes(lowerSearch) || 
                r.teacherName.toLowerCase().includes(lowerSearch) ||
                r.purpose.toLowerCase().includes(lowerSearch)
            );
        }

        // Sort by date desc
        return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [requests, isAdmin, currentUser, filterStatus, searchTerm]);

    const handleRegister = () => {
        if (!inputDeviceName || !inputPurpose) return alert("Vui lòng điền đầy đủ thông tin");
        if (!currentUser) return;

        const newRequest: DeviceRequest = {
            id: `DR${Date.now()}`,
            teacherId: currentUser.id,
            teacherName: `${currentUser.saintName} ${currentUser.fullName}`,
            deviceName: inputDeviceName,
            date: inputDate,
            session: inputSession,
            purpose: inputPurpose,
            status: 'PENDING'
        };

        setRequests([newRequest, ...requests]);
        showToast("Đăng ký thành công! Vui lòng chờ duyệt.");
        setShowModal(false);
        // Reset form
        setInputDeviceName('');
        setInputPurpose('');
    };

    const handleStatusChange = (id: string, newStatus: DeviceRequest['status']) => {
        setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus } : r));
        const messages = {
            'APPROVED': 'Đã duyệt yêu cầu!',
            'REJECTED': 'Đã từ chối yêu cầu!',
            'RETURNED': 'Đã xác nhận trả thiết bị!'
        };
        showToast(messages[newStatus] || 'Cập nhật trạng thái thành công');
    };

    const getStatusBadge = (status: DeviceRequest['status']) => {
        switch (status) {
            case 'PENDING': return <span className="px-2 py-1 bg-yellow-100 text-yellow-700 rounded-full text-xs font-bold border border-yellow-200 flex items-center gap-1"><Clock size={12}/> Chờ duyệt</span>;
            case 'APPROVED': return <span className="px-2 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold border border-green-200 flex items-center gap-1"><Check size={12}/> Đã duyệt</span>;
            case 'REJECTED': return <span className="px-2 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold border border-red-200 flex items-center gap-1"><X size={12}/> Từ chối</span>;
            case 'RETURNED': return <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-bold border border-blue-200 flex items-center gap-1"><RotateCcw size={12}/> Đã trả</span>;
        }
    };

    // Filter "Device" type items from inventory for the dropdown
    const availableDevices = useMemo(() => {
        // Assume 'OTHER' category contains devices or suggest commonly used ones
        const inventoryDevices = inventory.filter(i => i.category === 'OTHER' || i.name.toLowerCase().includes('máy') || i.name.toLowerCase().includes('loa') || i.name.toLowerCase().includes('mic'));
        // Add some defaults if inventory is empty of devices
        const defaults = ['Máy chiếu', 'Loa kéo', 'Micro', 'Laptop', 'Dây HDMI', 'Ổ cắm điện'];
        // Merge unique names
        const names = new Set([...inventoryDevices.map(i => i.name), ...defaults]);
        return Array.from(names);
    }, [inventory]);

    return (
        <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
            {toast && (
                <div className="fixed top-20 right-4 z-[100] animate-slide-in max-w-[90vw]">
                    <div className={`text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
                        <CheckCircle2 size={20} />
                        <span className="font-bold text-sm">{toast.message}</span>
                    </div>
                </div>
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2"><MonitorPlay className="text-blue-600"/> Đăng Ký Thiết Bị</h2>
                    <p className="text-slate-500 text-sm">Quản lý việc mượn/trả thiết bị giảng dạy</p>
                </div>
                <button onClick={() => setShowModal(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-md font-bold text-sm transition-all active:scale-95">
                    <Plus size={18} /> Đăng Ký Mới
                </button>
            </div>

            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row gap-4 items-center">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Tìm theo thiết bị, người mượn..." 
                        className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
                    {['all', 'PENDING', 'APPROVED', 'RETURNED'].map(st => (
                        <button 
                            key={st}
                            onClick={() => setFilterStatus(st)}
                            className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all border ${filterStatus === st ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                        >
                            {st === 'all' ? 'Tất cả' : st === 'PENDING' ? 'Chờ duyệt' : st === 'APPROVED' ? 'Đã duyệt' : 'Đã trả'}
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">

                {/* Mobile View */}
                <div className="md:hidden overflow-y-auto h-full p-4 space-y-3">
                    {filteredRequests.length > 0 ? (
                        filteredRequests.map(r => (
                            <div key={r.id} className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm relative">
                                <div className="flex justify-between items-start mb-2">
                                    <h4 className="font-bold text-slate-800 text-lg">{r.deviceName}</h4>
                                    {getStatusBadge(r.status)}
                                </div>
                                <div className="text-sm text-slate-600 mb-1 font-medium"><span className="text-slate-400">Người mượn:</span> {r.teacherName}</div>
                                <div className="text-sm text-slate-600 mb-1 flex items-center gap-2">
                                    <Calendar size={14}/> {new Date(r.date).toLocaleDateString('vi-VN')} - {r.session}
                                </div>
                                <div className="text-xs text-slate-500 italic bg-slate-50 p-2 rounded mt-2">"{r.purpose}"</div>

                                {isAdmin && (
                                    <div className="flex gap-2 mt-3 pt-3 border-t border-slate-100">
                                        {r.status === 'PENDING' && (
                                            <>
                                                <button onClick={() => handleStatusChange(r.id, 'APPROVED')} className="flex-1 py-2 bg-green-50 text-green-700 font-bold rounded-lg text-xs hover:bg-green-100">Duyệt</button>
                                                <button onClick={() => handleStatusChange(r.id, 'REJECTED')} className="flex-1 py-2 bg-red-50 text-red-700 font-bold rounded-lg text-xs hover:bg-red-100">Từ chối</button>
                                            </>
                                        )}
                                        {r.status === 'APPROVED' && (
                                            <button onClick={() => handleStatusChange(r.id, 'RETURNED')} className="flex-1 py-2 bg-blue-50 text-blue-700 font-bold rounded-lg text-xs hover:bg-blue-100">Xác nhận trả</button>
                                        )}
                                    </div>
                                )}
                            </div>
                        ))
                    ) : (
                        <div className="text-center text-slate-400 py-10 italic">Không có dữ liệu</div>
                    )}
                </div>

                {/* Desktop View */}
                <div className="hidden md:block overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-slate-600 text-xs uppercase font-bold sticky top-0 z-10">
                            <tr>
                                <th className="px-4 py-3">Thiết Bị</th>
                                <th className="px-4 py-3">Người Mượn</th>
                                <th className="px-4 py-3">Ngày & Buổi</th>
                                <th className="px-4 py-3">Mục Đích</th>
                                <th className="px-4 py-3 text-center">Trạng Thái</th>
                                {isAdmin && <th className="px-4 py-3 text-center">Thao Tác</th>}
                            </tr>
                        </thead>
                        <tbody className="text-sm">
                            {filteredRequests.length > 0 ? (
                                filteredRequests.map(r => (
                                    <tr key={r.id} className="hover:bg-slate-50 border-b border-slate-200 last:border-0 transition-colors">
                                        <td className="px-4 py-3 font-bold text-slate-800">{r.deviceName}</td>
                                        <td className="px-4 py-3 text-slate-600">{r.teacherName}</td>
                                        <td className="px-4 py-3">
                                            <div className="font-medium text-slate-700">{new Date(r.date).toLocaleDateString('vi-VN')}</div>
                                            <div className="text-xs text-slate-500">{r.session}</div>
                                        </td>
                                        <td className="px-4 py-3 text-slate-600 max-w-xs truncate" title={r.purpose}>{r.purpose}</td>
                                        <td className="px-4 py-3 text-center">{getStatusBadge(r.status)}</td>
                                        {isAdmin && (
                                            <td className="px-4 py-3 text-center">
                                                <div className="flex justify-center gap-2">
                                                    {r.status === 'PENDING' && (
                                                        <>
                                                            <button onClick={() => handleStatusChange(r.id, 'APPROVED')} className="p-1.5 bg-green-100 text-green-700 rounded hover:bg-green-200" title="Duyệt"><Check size={16}/></button>
                                                            <button onClick={() => handleStatusChange(r.id, 'REJECTED')} className="p-1.5 bg-red-100 text-red-700 rounded hover:bg-red-200" title="Từ chối"><X size={16}/></button>
                                                        </>
                                                    )}
                                                    {r.status === 'APPROVED' && (
                                                        <button onClick={() => handleStatusChange(r.id, 'RETURNED')} className="p-1.5 bg-blue-100 text-blue-700 rounded hover:bg-blue-200" title="Xác nhận trả"><RotateCcw size={16}/></button>
                                                    )}
                                                </div>
                                            </td>
                                        )}
                                    </tr>
                                ))
                            ) : (
                                <tr><td colSpan={isAdmin ? 6 : 5} className="p-8 text-center text-slate-400 italic">Không tìm thấy yêu cầu nào</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modal Register */}
            {showModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-scale-in overflow-hidden">
                        <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                            <h3 className="font-bold text-lg text-slate-800">Đăng Ký Mượn Thiết Bị</h3>
                            <button onClick={() => setShowModal(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Chọn Thiết Bị <span className="text-red-500">*</span></label>
                                <div className="relative">
                                    <input 
                                        list="devices" 
                                        className="w-full p-2.5 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 font-medium"
                                        placeholder="Nhập hoặc chọn..."
                                        value={inputDeviceName}
                                        onChange={e => setInputDeviceName(e.target.value)}
                                        autoFocus
                                    />
                                    <datalist id="devices">
                                        {availableDevices.map((d, i) => <option key={i} value={d} />)}
                                    </datalist>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ngày mượn</label>
                                    <input 
                                        type="date" 
                                        className="w-full p-2.5 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                                        value={inputDate}
                                        onChange={e => setInputDate(e.target.value)}
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Buổi</label>
                                    <select 
                                        className="w-full p-2.5 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                                        value={inputSession}
                                        onChange={e => setInputSession(e.target.value as any)}
                                    >
                                        <option value="Sáng">Sáng</option>
                                        <option value="Chiều">Chiều</option>
                                        <option value="Tối">Tối</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Mục đích sử dụng <span className="text-red-500">*</span></label>
                                <textarea 
                                    className="w-full p-2.5 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 h-24 resize-none"
                                    placeholder="VD: Dạy bài 5 lớp KT1..."
                                    value={inputPurpose}
                                    onChange={e => setInputPurpose(e.target.value)}
                                ></textarea>
                            </div>

                            <div className="bg-blue-50 p-3 rounded-lg flex items-start gap-2 text-xs text-blue-700">
                                <AlertCircle size={16} className="shrink-0 mt-0.5"/>
                                <span>Vui lòng bảo quản thiết bị cẩn thận và trả lại đúng vị trí sau khi sử dụng.</span>
                            </div>
                        </div>
                        <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                            <button onClick={() => setShowModal(false)} className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg font-bold text-sm hover:bg-slate-100">Hủy</button>
                            <button onClick={handleRegister} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700 shadow-sm">Đăng Ký</button>
                        </div>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
                .animate-slide-in { animation: slide-in 0.3s ease-out; }
                @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
                .animate-scale-in { animation: scale-in 0.2s ease-out; }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { Inventory } from './components/Inventory';
import { Login } from './components/Login';
import { DeviceRegistration } from './components/DeviceRegistration';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES, MOCK_TERM_CONFIGS, MOCK_INVENTORY, MOCK_SCORE_COLUMNS, MOCK_DEVICE_REQUESTS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade, TermConfig, InventoryItem, ScoreColumn, Teacher, DeviceRequest } from './types';
import { Menu, Church } from 'lucide-react';

const App: React.FC = () => {
  // --- AUTH STATE ---
  const [currentUser, setCurrentUser] = useState<Teacher | null>(null);

  // --- UI STATE ---
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- DATA STATE ---
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);
  const [termConfigs, setTermConfigs] = useState<TermConfig[]>(MOCK_TERM_CONFIGS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [scoreColumns, setScoreColumns] = useState<ScoreColumn[]>(MOCK_SCORE_COLUMNS);
  const [deviceRequests, setDeviceRequests] = useState<DeviceRequest[]>(MOCK_DEVICE_REQUESTS);

  // Check permissions when activeTab changes
  useEffect(() => {
      if (currentUser && currentUser.role !== 'ADMIN' && currentUser.allowedTabs) {
          // Allow settings by default regardless of allowedTabs
          if (activeTab !== 'settings' && !currentUser.allowedTabs.includes(activeTab)) {
              // Redirect to first allowed tab if current is forbidden
              if (currentUser.allowedTabs.length > 0) {
                  setActiveTab(currentUser.allowedTabs[0]);
              } else {
                  setActiveTab('dashboard'); // Fallback
              }
          }
      }
  }, [activeTab, currentUser]);

  const handleLogin = (user: Teacher) => {
      setCurrentUser(user);
      // Reset tab to dashboard or first allowed tab on login
      if (user.role !== 'ADMIN' && user.allowedTabs && user.allowedTabs.length > 0) {
          setActiveTab(user.allowedTabs[0]);
      } else {
          setActiveTab('dashboard');
      }
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setActiveTab('dashboard');
  };

  if (!currentUser) {
      return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    // Double check permission before rendering (except settings)
    if (activeTab !== 'settings' && currentUser.role !== 'ADMIN' && currentUser.allowedTabs && !currentUser.allowedTabs.includes(activeTab)) {
        return (
            <div className="flex h-full items-center justify-center flex-col text-slate-400">
                <div className="text-4xl font-bold mb-2">403</div>
                <div className="text-sm">Bạn không có quyền truy cập chức năng này.</div>
            </div>
        );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard currentUser={currentUser} classes={classes} years={years} />;
      case 'classes': return <Classes classes={classes} setClasses={setClasses} students={students} years={years} grades={grades} currentUser={currentUser} />;
      case 'students': return <Students students={students} setStudents={setStudents} classes={classes} years={years} records={records} grades={grades} currentUser={currentUser} />;
      case 'placement': return <ClassPlacement students={students} setStudents={setStudents} classes={classes} years={years} grades={grades} currentUser={currentUser} />;
      case 'teachers': return <Teachers />;
      case 'attendance': return <Attendance students={students} classes={classes} years={years} grades={grades} setRecords={setRecords} termConfigs={termConfigs} currentUser={currentUser} />;
      case 'grades': return <Grades students={students} classes={classes} years={years} records={records} setRecords={setRecords} grades={grades} scoreColumns={scoreColumns} currentUser={currentUser} />;
      case 'devices': return <DeviceRegistration requests={deviceRequests} setRequests={setDeviceRequests} currentUser={currentUser} inventory={inventory} />;
      case 'inventory': return <Inventory items={inventory} setItems={setInventory} />;
      case 'finance': return <Finance transactions={transactions} setTransactions={setTransactions} />;
      case 'settings': return <Settings years={years} setYears={setYears} classes={classes} setClasses={setClasses} grades={grades} setGrades={setGrades} termConfigs={termConfigs} setTermConfigs={setTermConfigs} scoreColumns={scoreColumns} setScoreColumns={setScoreColumns} currentUser={currentUser} />;
      default: return <Dashboard currentUser={currentUser} classes={classes} years={years} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans relative">
      {/* Mobile Header Bar */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-40 flex items-center justify-between px-4 shadow-sm">
        <div className="flex items-center gap-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu size={24} />
            </button>
            <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                    <Church size={16} />
                </div>
                <span className="font-bold text-slate-800 text-sm uppercase">Gx. Tân Thành</span>
            </div>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
            setActiveTab(tab);
            setIsMobileMenuOpen(false); // Close mobile menu on select
        }}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        isMobileOpen={isMobileMenuOpen}
        setIsMobileOpen={setIsMobileMenuOpen}
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      {/* Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm animate-fade-in"
            onClick={() => setIsMobileMenuOpen(false)}
        ></div>
      )}

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out pt-16 md:pt-0 ${
          isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'
        } w-full`}
      >
        {renderContent()}
      </main>

      <style>{`
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

export default App;

export interface Teacher {
  id: string; // Mã GLV (Tự động)
  saintName: string;
  fullName: string;
  dob: string;
  birthPlace: string;
  address: string;
  phone: string;
  email: string;
