                                                    <button onClick={() => handleDeleteDevice(d.id)} className="text-slate-400 hover:text-red-500">
                                                        <Trash2 size={16}/>
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            ) : (
                                <div className="p-4 text-center text-xs text-slate-400 italic">Chưa có thiết bị nào.</div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* 7. Cấu hình Cột điểm (MỚI) */}
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 xl:col-span-2">
                <div className="flex items-center gap-3 mb-6 border-b pb-4">
                    <FileText className="text-violet-600 w-6 h-6" />
                    <h3 className="font-bold text-xl text-slate-800">Cấu Hình Cột Điểm & Hệ Số</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* HK1 */}
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-blue-200">
                            <h4 className="font-bold text-blue-700 uppercase tracking-wider text-sm flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-blue-600"></span> Học Kỳ 1</h4>
                            <button onClick={() => addScoreColumn('HK1')} className="text-[10px] flex items-center gap-1 font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded hover:bg-blue-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-2">
                            {hk1Columns.map(col => {
                                const isDragging = draggedColId === col.id;
                                const isOver = dragOverColId === col.id;
                                return (
                                <div key={col.id} draggable onDragStart={(e) => handleColDragStart(e, col.id)} onDragOver={handleColDragOver} onDragEnter={() => handleColDragEnter(col.id)} onDragEnd={handleColDragEnd} onDrop={(e) => handleColDrop(e, col.id)} className={`flex gap-2 items-center bg-blue-50/50 p-2 rounded-lg border transition-all ${isDragging ? 'opacity-30 border-blue-500 border-dashed' : 'border-blue-100'} ${isOver ? 'ring-2 ring-blue-300 translate-x-1' : ''}`}>
                                    <div className="cursor-grab text-slate-300 hover:text-blue-500"><GripVertical size={16}/></div>
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateScoreColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col"><span className="text-[8px] font-bold text-blue-400 uppercase">Hệ số</span><select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateScoreColumn(col.id, 'weight', Number(e.target.value))}><option value={0}>x0</option><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select></div>
                                    <button onClick={() => removeScoreColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            )})}
                        </div>
                    </div>
                    {/* HK2 */}
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b pb-2 border-purple-200">
                            <h4 className="font-bold text-purple-700 uppercase tracking-wider text-sm flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-purple-600"></span> Học Kỳ 2</h4>
                            <button onClick={() => addScoreColumn('HK2')} className="text-[10px] flex items-center gap-1 font-bold text-purple-600 bg-purple-50 px-2 py-1 rounded hover:bg-purple-100 transition-colors"><Plus size={12}/> Thêm cột</button>
                        </div>
                        <div className="space-y-2">
                            {hk2Columns.map(col => {
                                const isDragging = draggedColId === col.id;
                                const isOver = dragOverColId === col.id;
                                return (
                                <div key={col.id} draggable onDragStart={(e) => handleColDragStart(e, col.id)} onDragOver={handleColDragOver} onDragEnter={() => handleColDragEnter(col.id)} onDragEnd={handleColDragEnd} onDrop={(e) => handleColDrop(e, col.id)} className={`flex gap-2 items-center bg-purple-50/50 p-2 rounded-lg border transition-all ${isDragging ? 'opacity-30 border-purple-500 border-dashed' : 'border-purple-100'} ${isOver ? 'ring-2 ring-purple-300 translate-x-1' : ''}`}>
                                    <div className="cursor-grab text-slate-300 hover:text-purple-500"><GripVertical size={16}/></div>
                                    <input className="flex-1 text-sm p-1.5 border rounded outline-none font-bold" value={col.name} onChange={e => updateScoreColumn(col.id, 'name', e.target.value)} />
                                    <div className="flex flex-col"><span className="text-[8px] font-bold text-purple-400 uppercase">Hệ số</span><select className="text-xs p-1 border rounded font-bold" value={col.weight} onChange={e => updateScoreColumn(col.id, 'weight', Number(e.target.value))}><option value={0}>x0</option><option value={1}>x1</option><option value={2}>x2</option><option value={3}>x3</option></select></div>
                                    <button onClick={() => removeScoreColumn(col.id)} className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            )})}
                        </div>
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleSaveScoreColumns} className="px-6 py-2 bg-violet-600 text-white rounded-lg font-bold hover:bg-violet-700 transition-all shadow flex items-center gap-2">
                        <Save size={18}/> Lưu Cấu Hình Điểm
                    </button>
                </div>
            </div>

            {/* 8. Quản Lý Tên Thánh */}
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
            <div className="flex items-center gap-3 mb-6 border-b pb-4"><Cross className="text-amber-600 w-6 h-6" /><h3 className="font-bold text-xl text-slate-800">Quản Lý Tên Thánh</h3></div>
            <div className="space-y-6">
                <div className="flex gap-3 bg-amber-50 p-4 rounded-xl border border-amber-100"><input type="text" placeholder="Nhập tên thánh..." className="flex-1 p-3 border border-amber-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-amber-500" value={newSaintName} onChange={(e) => setNewSaintName(e.target.value)}/><select className="p-3 border border-amber-200 rounded-xl text-sm bg-white" value={newSaintGender} onChange={(e) => setNewSaintGender(e.target.value as 'Male'|'Female')}><option value="Male">Nam</option><option value="Female">Nữ</option></select><button onClick={handleAddSaint} className="px-6 py-3 bg-amber-600 text-white rounded-xl hover:bg-amber-700 font-extrabold shadow-md transition-all">+</button></div>
                <div className="border border-slate-200 rounded-2xl overflow-hidden max-h-80 overflow-y-auto custom-scrollbar bg-slate-50"><table className="w-full text-left text-sm border-collapse"><thead className="bg-slate-100 border-b border-slate-300 sticky top-0 z-10"><tr><th className="p-4 font-bold text-slate-600">Tên Thánh</th><th className="p-4 font-bold text-slate-600 w-24">Giới tính</th><th className="p-4 w-16"></th></tr></thead><tbody className="bg-white">{saints.map(s => (<tr key={s.id} className="hover:bg-amber-50/50 transition-colors border-b border-slate-200"><td className="p-4 font-bold text-slate-700">{s.name}</td><td className="p-4"><span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${s.gender === 'Male' ? 'bg-blue-100 text-blue-700' : 'bg-pink-100 text-pink-700'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td><td className="p-4 text-right"><button onClick={() => handleRemoveSaint(s.id)} className="p-2 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={18} /></button></td></tr>))}</tbody></table></div>
            </div>
            </div>
        </>
        )}

        {/* 9. Tài khoản & Bảo mật (Visible to Everyone) */}
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
             <div className="flex items-center gap-3 mb-6 border-b pb-4">
                <UserCog className="text-slate-600 w-6 h-6" />
                <h3 className="font-bold text-xl text-slate-800">Tài Khoản & Bảo Mật</h3>
            </div>
            <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu hiện tại</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={currentPass} onChange={e => setCurrentPass(e.target.value)}/>
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Mật khẩu mới</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={newPass} onChange={e => setNewPass(e.target.value)}/>
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Nhập lại mật khẩu mới</label>
                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input type="password" className="w-full pl-10 pr-3 py-2 border rounded-lg text-sm" value={confirmPass} onChange={e => setConfirmPass(e.target.value)}/>
                    </div>
                </div>
                <button onClick={handleChangePassword} className="w-full py-2 bg-slate-800 text-white rounded-lg font-bold text-sm hover:bg-slate-900 shadow mt-2">
                    Đổi Mật Khẩu
                </button>
            </div>
        </div>

      </div>
      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Student, ClassRoom, SchoolYear, Grade, Teacher } from '../types';
import { ArrowRight, Search, CheckCircle2, Users, ArrowRightLeft, ArrowUpRight, GraduationCap, Filter, Globe, List, AlertCircle, X } from 'lucide-react';

interface ClassPlacementProps {
    students: Student[];
    setStudents: (students: Student[]) => void;
    classes: ClassRoom[];
    years: SchoolYear[];
    grades: Grade[];
    currentUser: Teacher | null;
}

type Mode = 'TRANSFER' | 'PROMOTION';
type SearchMode = 'CLASS' | 'GLOBAL';

export const ClassPlacement: React.FC<ClassPlacementProps> = ({ students, setStudents, classes, years, grades, currentUser }) => {
  const [mode, setMode] = useState<Mode>('TRANSFER'); 
  const [searchMode, setSearchMode] = useState<SearchMode>('CLASS');
  const [toast, setToast] = useState<string | null>(null);
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  // === FILTER STATE ===
  // Source (Nguồn)
  const [srcYear, setSrcYear] = useState('');
  const [srcGrade, setSrcGrade] = useState('all');
  const [srcClassId, setSrcClassId] = useState('');
  const [srcSearch, setSrcSearch] = useState('');

  // Target (Đích)
  const [tgtYear, setTgtYear] = useState('');
  const [tgtGrade, setTgtGrade] = useState('all');
  const [tgtClassId, setTgtClassId] = useState('');

  // Selection
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Init default years
  useEffect(() => {
    const active = years.find(y => y.isActive);
    if (!active) return;
    setSrcYear(active.id);
    setTgtYear(active.id); 
  }, [years]);

  // Reset selection when source changes
  useEffect(() => {
    setSelectedStudentIds([]);
  }, [srcClassId, searchMode]);

  // Allowed Classes Logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (currentUser.role === 'ADMIN') return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser]);

  // Logic to filter Source Classes
  const srcClasses = useMemo(() => {
    // If Admin, show all. If GLV, only show allowed classes in dropdown
    return allowedClasses.filter(c => c.yearId === srcYear && (srcGrade === 'all' || c.gradeId === srcGrade));
  }, [allowedClasses, srcYear, srcGrade]);

  // Logic to filter Target Classes
  const tgtClasses = useMemo(() => {
    // Target classes also restricted to what the teacher can see/manage
    return allowedClasses.filter(c => c.yearId === tgtYear && (tgtGrade === 'all' || c.gradeId === tgtGrade));
  }, [allowedClasses, tgtYear, tgtGrade]);

  // Students in Source
  const srcStudents = useMemo(() => {
    let list: Student[] = [];

    if (searchMode === 'CLASS') {
        if (!srcClassId) return [];
        list = students.filter(s => s.classId === srcClassId);
    } else {
        if (!srcSearch) return [];
        list = students; 
    }

    if (srcSearch) {
        const q = srcSearch.toLowerCase();
        list = list.filter(s => s.fullName.toLowerCase().includes(q) || s.saintName.toLowerCase().includes(q) || s.id.toLowerCase().includes(q));
    }

    // Only show students belonging to allowed classes if GLV
    if (currentUser?.role !== 'ADMIN') {
        const allowedIds = allowedClasses.map(c => c.id);
        list = list.filter(s => allowedIds.includes(s.classId));
    }

    return list.slice(0, 100); 
  }, [students, srcClassId, srcSearch, searchMode, allowedClasses, currentUser]);

  // Students in Target Class (for preview)
  const tgtStudents = useMemo(() => {
    if (!tgtClassId) return [];
    return students.filter(s => s.classId === tgtClassId);
  }, [students, tgtClassId]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
        setSelectedStudentIds(srcStudents.map(s => s.id));
    } else {
        setSelectedStudentIds([]);
    }
  };

  const toggleSelect = (id: string) => {
      setSelectedStudentIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const handleExecute = () => {
      if (selectedStudentIds.length === 0) return alert("Chưa chọn học viên nào!");
      if (!tgtClassId) return alert("Chưa chọn lớp đích!");
      setShowConfirmModal(true);
  };

  const confirmTransfer = () => {
      const tgtClass = classes.find(c => c.id === tgtClassId);
      const updatedStudents = students.map(s => {
          if (selectedStudentIds.includes(s.id)) {
              return { ...s, classId: tgtClassId };
          }
          return s;
      });
      setStudents(updatedStudents);
      setToast(`Đã chuyển thành công ${selectedStudentIds.length} học viên!`);
      setSelectedStudentIds([]);
      setShowConfirmModal(false);
  };

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'Chưa xếp lớp';

  return (
    <div className="p-6 h-screen flex flex-col bg-slate-100 relative">
       {/* Toast */}
       {toast && (
        <div className="fixed top-6 right-6 z-[100] animate-slide-in">
           <div className="bg-emerald-600 text-white px-6 py-4 rounded-xl shadow-2xl flex items-center gap-3 border border-emerald-500/50">
              <CheckCircle2 size={24} />
              <span className="font-bold">{toast}</span>
           </div>
        </div>
      )}

      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Xếp Lớp & Điều Chuyển</h2>
            <p className="text-slate-500 text-sm">Quản lý danh sách học viên giữa các lớp</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg shadow-sm border border-slate-200">
            <button 
                onClick={() => setMode('TRANSFER')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'TRANSFER' ? 'bg-blue-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowRightLeft size={16} /> Chuyển Lớp (Trong năm)
            </button>
            <button 
                onClick={() => setMode('PROMOTION')}
                className={`px-4 py-2 rounded-md flex items-center gap-2 text-sm font-bold transition-all ${mode === 'PROMOTION' ? 'bg-green-600 text-white shadow' : 'text-slate-600 hover:bg-slate-50'}`}
            >
                <ArrowUpRight size={16} /> Lên Lớp (Niên khóa mới)
            </button>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="flex flex-1 gap-6 overflow-hidden">

          {/* LEFT: SOURCE */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
              <div className="bg-slate-50 border-b border-slate-200">
                  <div className="flex border-b border-slate-200">
                      <button 
                        onClick={() => setSearchMode('CLASS')}
                        className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'CLASS' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <List size={14}/> Theo Lớp
                      </button>
                      <button 
                         onClick={() => setSearchMode('GLOBAL')}
                         className={`flex-1 py-3 text-xs font-bold uppercase flex justify-center items-center gap-2 transition-colors ${searchMode === 'GLOBAL' ? 'bg-white text-purple-600 border-b-2 border-purple-600' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                         <Globe size={14}/> Tìm Học Viên
                      </button>
                  </div>

                  <div className="p-4">
                    {searchMode === 'CLASS' ? (
                        <div className="space-y-2">
                             <div className="grid grid-cols-2 gap-2">
                                <select className="input-select" value={srcYear} onChange={e => setSrcYear(e.target.value)}>
                                    {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                                </select>
                                <select className="input-select" value={srcGrade} onChange={e => setSrcGrade(e.target.value)}>
                                    <option value="all">Tất cả Khối</option>
                                    {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                </select>
                            </div>
                            <select className={`input-select w-full font-bold ${srcClassId ? 'text-slate-800' : 'text-slate-400'}`} value={srcClassId} onChange={e => setSrcClassId(e.target.value)}>
                                <option value="">-- Chọn Lớp Nguồn --</option>
                                {srcClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    ) : (
                        <div className="relative">
                            <input 
                                type="text" 
                                placeholder="Nhập tên học viên để tìm..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border border-purple-300 rounded-lg bg-white focus:ring-2 focus:ring-purple-200 outline-none"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                                autoFocus
                            />
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-purple-400" size={16}/>
                            <div className="text-[10px] text-slate-400 mt-1 italic text-right">*Tìm trong toàn bộ hệ thống</div>
                        </div>
                    )}
                  </div>
              </div>

              {/* Source List */}
              <div className="flex-1 flex flex-col overflow-hidden relative">
                 {searchMode === 'CLASS' && srcClassId && (
                     <div className="p-2 border-b border-slate-100 sticky top-0 bg-white z-10">
                         <div className="relative">
                             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                             <input 
                                type="text" 
                                placeholder="Lọc tên trong lớp này..." 
                                className="w-full pl-9 pr-3 py-2 text-sm border rounded-lg bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-100"
                                value={srcSearch}
                                onChange={e => setSrcSearch(e.target.value)}
                             />
                         </div>
                     </div>
                 )}

                 <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {(searchMode === 'GLOBAL' && srcSearch) || (searchMode === 'CLASS' && srcClassId) ? (
                         srcStudents.length > 0 ? (
                             <div className="space-y-1">
                                 <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg mb-2">
                                     <input type="checkbox" className="w-4 h-4 rounded cursor-pointer" onChange={handleSelectAll} checked={srcStudents.length > 0 && selectedStudentIds.length === srcStudents.length}/>
                                     <span className="text-sm font-bold text-slate-600">Chọn tất cả ({srcStudents.length})</span>
                                 </div>
                                 {srcStudents.map(s => (
                                     <div 
                                        key={s.id} 
                                        onClick={() => toggleSelect(s.id)}
                                        className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all ${selectedStudentIds.includes(s.id) ? 'bg-blue-50 border-blue-300 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
                                     >
                                         <input 
                                            type="checkbox" 
                                            className="w-4 h-4 rounded cursor-pointer pointer-events-none" 
                                            checked={selectedStudentIds.includes(s.id)} 
                                            readOnly
                                         />
                                         <div className="flex-1">
                                             <div className="flex justify-between">
                                                <div className="text-sm font-bold text-slate-800">{s.saintName} {s.fullName}</div>
                                                {searchMode === 'GLOBAL' && <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-medium">{getClassName(s.classId)}</span>}
                                             </div>
                                             <div className="text-[10px] text-slate-400 font-mono">{s.id} - {new Date(s.dob).toLocaleDateString('vi-VN')}</div>
                                         </div>
                                     </div>
                                 ))}
                             </div>
                         ) : (
                             <div className="h-full flex flex-col items-center justify-center text-slate-400">
                                 <span className="text-sm italic">Không tìm thấy học viên</span>
                             </div>
                         )
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <GraduationCap size={48} className="mb-2"/>
                             <span className="text-sm font-medium">
                                 {searchMode === 'CLASS' ? 'Vui lòng chọn lớp nguồn' : 'Nhập tên để tìm kiếm'}
                             </span>
                         </div>
                     )}
                 </div>
              </div>
              <div className="p-3 bg-slate-50 border-t border-slate-200 text-xs font-bold text-slate-500 text-right">
                  Đã chọn: {selectedStudentIds.length} / {srcStudents.length}
              </div>
          </div>

          {/* MIDDLE: ACTIONS */}
          <div className="flex flex-col items-center justify-center gap-4">
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
              <button 
                onClick={handleExecute}
                disabled={selectedStudentIds.length === 0 || !tgtClassId}
                className={`w-14 h-14 rounded-full flex items-center justify-center shadow-lg transition-all transform hover:scale-110 active:scale-95 ${selectedStudentIds.length > 0 && tgtClassId ? 'bg-blue-600 text-white cursor-pointer' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                title="Thực hiện chuyển lớp"
              >
                  <ArrowRight size={24} />
              </button>
              <div className="h-full w-[1px] bg-slate-200 my-10 hidden lg:block"></div>
          </div>

          {/* RIGHT: TARGET */}
          <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-300 overflow-hidden">
             <div className={`p-4 border-b border-slate-200 ${mode === 'PROMOTION' ? 'bg-green-50' : 'bg-blue-50'}`}>
                  <div className={`flex items-center gap-2 mb-3 font-bold uppercase text-xs tracking-wider ${mode === 'PROMOTION' ? 'text-green-800' : 'text-blue-800'}`}>
                      <Users size={14}/> Lớp Đích
                  </div>
                  <div className="grid grid-cols-2 gap-2 mb-2">
                      <select className="input-select" value={tgtYear} onChange={e => setTgtYear(e.target.value)}>
                          {years.map(y => <option key={y.id} value={y.id}>{y.name}</option>)}
                      </select>
                      <select className="input-select" value={tgtGrade} onChange={e => setTgtGrade(e.target.value)}>
                          <option value="all">Tất cả Khối</option>
                          {grades.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                      </select>
                  </div>
                  <select className={`input-select w-full font-bold ${tgtClassId ? 'text-slate-800' : 'text-slate-400'} ${mode === 'PROMOTION' ? 'focus:ring-green-500' : 'focus:ring-blue-500'}`} value={tgtClassId} onChange={e => setTgtClassId(e.target.value)}>
                      <option value="">-- Chọn Lớp Đích --</option>
                      {tgtClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
              </div>

              {/* Target Preview List */}
              <div className="flex-1 flex flex-col overflow-hidden bg-slate-50/30">
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                     {tgtClassId ? (
                         <div className="space-y-1">
                             <div className="text-xs font-bold text-slate-400 uppercase p-2">Danh sách hiện tại ({tgtStudents.length})</div>
                             {tgtStudents.map((s, idx) => (
                                 <div key={s.id} className="flex items-center justify-between p-3 bg-white rounded-lg border border-slate-100">
                                     <div className="flex items-center gap-3">
                                         <span className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center text-[10px] text-slate-500 font-bold">{idx + 1}</span>
                                         <div>
                                             <div className="text-sm font-medium text-slate-700">{s.saintName} {s.fullName}</div>
                                         </div>
                                     </div>
                                 </div>
                             ))}
                             {tgtStudents.length === 0 && <div className="p-8 text-center text-sm text-slate-400 italic">Lớp chưa có học viên</div>}
                         </div>
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                             <Users size={48} className="mb-2"/>
                             <span className="text-sm font-medium">Vui lòng chọn lớp đích</span>
                         </div>
                     )}
                  </div>
              </div>
          </div>

      </div>

      {/* Confirmation Modal */}
      {showConfirmModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-fade-in backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-scale-in border border-slate-300">
                <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-3 text-blue-600">
                        <div className="p-3 bg-blue-50 rounded-full border border-blue-100">
                            <AlertCircle size={28} strokeWidth={2.5}/>
                        </div>
                        <h3 className="text-xl font-bold text-slate-800">Xác nhận chuyển lớp</h3>
                    </div>
                    <button onClick={() => setShowConfirmModal(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                        <X size={24}/>
                    </button>
                </div>

                <p className="text-slate-600 mb-8 leading-relaxed text-sm">
                    Bạn có chắc chắn muốn chuyển <span className="font-black text-slate-900 bg-slate-100 px-1.5 py-0.5 rounded">{selectedStudentIds.length} học viên</span> sang lớp <span className="font-black text-blue-700 bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100">{classes.find(c => c.id === tgtClassId)?.name}</span> không?
                </p>

                <div className="flex justify-end gap-3 pt-2">
                    <button onClick={() => setShowConfirmModal(false)} className="px-5 py-2.5 bg-white border border-slate-300 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-all active:scale-95 text-sm">
                        Hủy bỏ
                    </button>
                    <button onClick={confirmTransfer} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-all active:scale-95 text-sm flex items-center gap-2">
                        <CheckCircle2 size={18}/> Xác nhận
                    </button>
                </div>
            </div>
        </div>
      )}

      <style>{`
        .input-select {
            width: 100%;
            padding: 0.5rem;
            border-radius: 0.5rem;
            border: 1px solid #cbd5e1;
            font-size: 0.875rem;
            outline: none;
            transition: all 0.2s;
        }
        .input-select:focus {
            border-color: #3b82f6;
            box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
        }
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher } from '../types';
import { Search, Plus, Edit, CheckCircle2, AlertTriangle, Save, User, History, GitMerge, ScrollText, X, Check, Fingerprint, Calendar, MapPin, Map, School } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const isAdmin = currentUser?.role === 'ADMIN';

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Filter allowed classes logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (isAdmin) return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser, isAdmin]);

  // Initial Logic
  useEffect(() => {
     const active = years.find(y => y.isActive);
     const activeYearId = active ? active.id : (years[0]?.id || '');
     setSelectedYear(activeYearId);

     // If GLV, auto select the class context
     if (!isAdmin && activeYearId) {
         const myClassesInYear = allowedClasses.filter(c => c.yearId === activeYearId);
         if (myClassesInYear.length > 0) {
             setSelectedClass(myClassesInYear[0].id);
         } else {
             setSelectedClass('');
         }
     }
  }, [years, isAdmin, allowedClasses]);

  const [showModal, setShowModal] = useState(false);
  const [showDuplicateConfirmModal, setShowDuplicateConfirmModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Deduplication States
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // --- FORM STATE ---
  const [inputId, setInputId] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [inputBirthPlace, setInputBirthPlace] = useState('');
  const [inputClassId, setInputClassId] = useState(''); 

  const [inputFatherName, setInputFatherName] = useState('');
  const [inputMotherName, setInputMotherName] = useState('');
  const [inputFatherPhone, setInputFatherPhone] = useState('');
  const [inputMotherPhone, setInputMotherPhone] = useState('');
  const [inputAddress, setInputAddress] = useState('');

  const [inputBaptismDate, setInputBaptismDate] = useState('');
  const [inputBaptismBy, setInputBaptismBy] = useState('');
  const [inputBaptismSponsor, setInputBaptismSponsor] = useState('');
  const [inputBaptismPlace, setInputBaptismPlace] = useState('');

  const [inputEucharistDate, setInputEucharistDate] = useState('');
  const [inputEucharistBy, setInputEucharistBy] = useState('');
  const [inputEucharistPlace, setInputEucharistPlace] = useState('');

  const [inputConfirmationDate, setInputConfirmationDate] = useState('');
  const [inputConfirmationBy, setInputConfirmationBy] = useState('');
  const [inputConfirmationSponsor, setInputConfirmationSponsor] = useState('');
  const [inputConfirmationPlace, setInputConfirmationPlace] = useState('');

  const [inputOathDate, setInputOathDate] = useState('');
  const [inputNote, setInputNote] = useState('');

  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  const classesInYear = useMemo(() => allowedClasses.filter(c => c.yearId === selectedYear), [allowedClasses, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);
  const modalAvailableClasses = useMemo(() => classesInYear, [classesInYear]);
  const glvMyClasses = useMemo(() => isAdmin ? [] : classesInYear, [isAdmin, classesInYear]);

  useEffect(() => {
    if (!showModal) return;
    const cleanName = inputName.trim().toLowerCase();
    if (cleanName.length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === cleanName && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputId(selectedStudent.id);
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
              setInputBirthPlace(selectedStudent.birthPlace || '');
              setInputClassId(selectedStudent.classId);
              setInputFatherName(selectedStudent.fatherName || '');
              setInputMotherName(selectedStudent.motherName || '');
              setInputFatherPhone(selectedStudent.fatherPhone || '');
              setInputMotherPhone(selectedStudent.motherPhone || '');
              setInputAddress(selectedStudent.address || '');
              setInputBaptismDate(selectedStudent.baptismDate || '');
              setInputBaptismBy(selectedStudent.baptismBy || '');
              setInputBaptismSponsor(selectedStudent.baptismSponsor || '');
              setInputBaptismPlace(selectedStudent.baptismPlace || '');
              setInputEucharistDate(selectedStudent.eucharistDate || '');
              setInputEucharistBy(selectedStudent.eucharistBy || '');
              setInputEucharistPlace(selectedStudent.eucharistPlace || '');
              setInputConfirmationDate(selectedStudent.confirmationDate || '');
              setInputConfirmationBy(selectedStudent.confirmationBy || '');
              setInputConfirmationSponsor(selectedStudent.confirmationSponsor || '');
              setInputConfirmationPlace(selectedStudent.confirmationPlace || '');
              setInputOathDate(selectedStudent.confirmationOathDate || '');
              setInputNote(selectedStudent.note || '');
          } else {
              const prefix = selectedYear.slice(2, 4);
              const yearStudents = students.filter(s => s.id.startsWith(prefix));
              const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
              setInputId(`${prefix}${nextNum}`);
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
              setInputClassId((!isAdmin && selectedClass !== 'all') ? selectedClass : (modalAvailableClasses[0]?.id || '')); 
              setInputBirthPlace('');
              setInputFatherName('');
              setInputMotherName('');
              setInputFatherPhone('');
              setInputMotherPhone('');
              setInputAddress('');
              setInputBaptismDate('');
              setInputBaptismBy('');
              setInputBaptismSponsor('');
              setInputBaptismPlace('');
              setInputEucharistDate('');
              setInputEucharistBy('');
              setInputEucharistPlace('');
              setInputConfirmationDate('');
              setInputConfirmationBy('');
              setInputConfirmationSponsor('');
              setInputConfirmationPlace('');
              setInputOathDate('');
              setInputNote('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent, selectedYear, students, selectedClass, modalAvailableClasses, isAdmin]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else {
            validClassIds = availableClasses.map(c => c.id);
        }
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, availableClasses]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const getClassColor = (classId: string) => {
      const cls = classes.find(c => c.id === classId);
      if (!cls) return 'bg-slate-100 text-slate-700 border-slate-200';
      switch (cls.gradeId) {
          case 'g1': return 'bg-pink-100 text-pink-700 border-pink-200';
          case 'g2': return 'bg-green-100 text-green-700 border-green-200';
          case 'g3': return 'bg-blue-100 text-blue-700 border-blue-200';
          case 'g4': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
          default: return 'bg-slate-100 text-slate-700 border-slate-200';
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.pop() || '';
      const lastName = parts.join(' ');
      return { lastName, firstName };
  };

  const executeSaveStudent = () => {
    const studentData: Student = {
        id: inputId,
        fullName: inputName,
        dob: inputDob,
        saintName: saintInput,
        gender: inputGender,
        status: inputStatus,
        classId: inputClassId,
        parish: 'Gx. Tân Thành',
        birthPlace: inputBirthPlace,
        fatherName: inputFatherName,
        motherName: inputMotherName,
        fatherPhone: inputFatherPhone,
        motherPhone: inputMotherPhone,
        address: inputAddress,
        baptismDate: inputBaptismDate,
        baptismBy: inputBaptismBy,
        baptismSponsor: inputBaptismSponsor,
        baptismPlace: inputBaptismPlace,
        eucharistDate: inputEucharistDate,
        eucharistBy: inputEucharistBy,
        eucharistPlace: inputEucharistPlace,
        confirmationDate: inputConfirmationDate,
        confirmationBy: inputConfirmationBy,
        confirmationSponsor: inputConfirmationSponsor,
        confirmationPlace: inputConfirmationPlace,
        confirmationOathDate: inputOathDate,
        note: inputNote
    };
    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? studentData : s));
        showToast("Đã cập nhật hồ sơ thành công!");
    } else {
        setStudents(prev => [...prev, studentData]);
        showToast(`Đã thêm học viên mới: ${inputId}`);
    }
    setShowModal(false);
    setShowDuplicateConfirmModal(false);
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ: Tên Thánh, Họ tên, Ngày sinh.");
    if (!inputClassId) return alert("Vui lòng chọn lớp cho học viên.");

    // Check duplicates
    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        setShowDuplicateConfirmModal(true);
        return;
    }

    executeSaveStudent();
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      filteredStudents.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Xác nhận giữ lại hồ sơ [${survivorId}] và xóa ${idsToDelete.length} bản ghi trùng?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp và làm sạch dữ liệu thành công!`);
          if (duplicateGroups.length <= 1) setShowDedupModal(false);
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
        default: return null;
    }
  };

  const currentYearName = years.find(y => y.id === selectedYear)?.name || '---';

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-20 right-4 z-[100] animate-slide-in max-w-[90vw]">
           <div className={`text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">HỌC VIÊN</h2>
            <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200 uppercase tracking-widest">{filteredStudents.length} hồ sơ</div>
        </div>
        <div className="flex w-full md:w-auto gap-2">
            <button onClick={scanDuplicates} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-3 py-2.5 bg-white border border-amber-400 text-amber-700 rounded-xl hover:bg-amber-50 text-xs font-black shadow-sm transition-all active:scale-95 group whitespace-nowrap">
                <GitMerge size={16} /> <span className="hidden sm:inline">RÀ SOÁT</span> TRÙNG
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase tracking-wide text-xs">
                <Plus size={18} /> Thêm Mới
            </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4 items-center">
        {isAdmin ? (
            <div className="flex flex-col md:flex-row flex-wrap gap-2 items-stretch md:items-center w-full md:w-auto">
                <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
                </select>
                <div className="flex gap-2">
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
                    <option value="all">Tất cả Khối</option>
                    {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
                    </select>
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
                    <option value="all">Tất cả Lớp</option>
                    {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                </div>
            </div>
        ) : (
            <div className="flex flex-col md:flex-row items-start md:items-center gap-4 w-full md:w-auto">
                <div className="bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 flex items-center gap-2">
                    <Calendar size={16} className="text-slate-400"/>
                    <span className="text-sm font-bold text-slate-700">{currentYearName}</span>
                </div>
