                    </div>
                    <button onClick={() => setShowDuplicateConfirmModal(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                        <X size={24}/>
                    </button>
                </div>

                <div className="text-slate-600 mb-6 text-sm">
                    <p className="mb-3">Hệ thống phát hiện <span className="font-bold text-slate-900">{realtimeDuplicates.length} học viên</span> có cùng Họ tên và Ngày sinh:</p>
                    <div className="bg-slate-50 p-3 rounded-xl border border-slate-200 max-h-40 overflow-y-auto space-y-2">
                        {realtimeDuplicates.map(d => (
                            <div key={d.id} className="flex items-center gap-2 text-xs">
                                <span className="font-mono font-bold text-slate-500 bg-white px-1.5 py-0.5 rounded border border-slate-200">{d.id}</span>
                                <span className="font-bold text-slate-800">{d.saintName} {d.fullName}</span>
                                <span className="text-slate-400">- {getClassName(d.classId)}</span>
                            </div>
                        ))}
                    </div>
                    <p className="mt-4">Bạn có chắc chắn muốn tạo thêm hồ sơ mới này không?</p>
                </div>

                <div className="flex justify-end gap-3 pt-2">
                    <button onClick={() => setShowDuplicateConfirmModal(false)} className="px-5 py-2.5 bg-white border border-slate-300 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-all active:scale-95 text-sm">
                        Kiểm tra lại
                    </button>
                    <button onClick={executeSaveStudent} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg transition-all active:scale-95 text-sm flex items-center gap-2">
                        <CheckCircle2 size={18}/> Vẫn tạo mới
                    </button>
                </div>
            </div>
        </div>
      )}

      {showDedupModal && (
        <div className="fixed inset-0 bg-slate-900/80 z-[100] flex items-center justify-center p-2 md:p-4 backdrop-blur-lg animate-fade-in">
           <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden border-4 md:border-8 border-amber-400">
              <div className="p-4 md:p-8 bg-amber-400 flex justify-between items-center shadow-xl">
                 <div className="flex items-center gap-3 md:gap-5 text-amber-950">
                    <div className="p-2 md:p-3 bg-white/40 rounded-2xl"><GitMerge size={24} className="md:w-10 md:h-10"/></div>
                    <div>
                        <h3 className="font-black text-lg md:text-3xl uppercase tracking-tighter leading-tight">Rà soát trùng lặp</h3>
                        <p className="text-[10px] md:text-sm font-black opacity-80 uppercase tracking-widest">Phát hiện {duplicateGroups.length} nhóm</p>
                    </div>
                 </div>
                 <button onClick={() => setShowDedupModal(false)} className="p-2 hover:bg-amber-500 rounded-full transition-colors text-amber-950 bg-white/20"><X size={24}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 md:p-10 custom-scrollbar bg-slate-50/50">
                 {duplicateGroups.length > 0 ? (
                     <div className="space-y-6 md:space-y-12">
                         {duplicateGroups.map((group, gIdx) => (
                             <div key={group.key} className="bg-white rounded-2xl md:rounded-[2rem] shadow-lg border-2 border-amber-100 overflow-hidden">
                                 <div className="px-4 py-3 md:px-6 md:py-4 bg-amber-50 border-b border-amber-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-2">
                                     <div className="flex items-center gap-3 md:gap-4">
                                         <span className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-amber-200 flex items-center justify-center font-black text-amber-800 text-sm md:text-lg shadow-sm border border-amber-300">#{gIdx + 1}</span>
                                         <span className="text-xs md:text-sm font-black text-slate-600 uppercase tracking-wider">
                                             {group.key.split('|')[0]} <span className="hidden md:inline mx-3 opacity-30">•</span> <br className="md:hidden"/>
                                             <span className="text-blue-800 font-black">{new Date(group.key.split('|')[1]).toLocaleDateString('vi-VN')}</span>
                                         </span>
                                     </div>
                                 </div>
                                 <div className="divide-y divide-slate-100">
                                     {group.students.map(s => (
                                         <div key={s.id} className="p-4 md:p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 hover:bg-blue-50/50 transition-colors">
                                             <div className="flex items-center gap-4 md:gap-6 w-full">
                                                 <div className="text-xs font-mono font-black text-slate-400 bg-slate-100 px-2 py-1 md:px-3 md:py-1.5 rounded-xl border border-slate-200">ID: {s.id}</div>
                                                 <div className="flex-1">
                                                     <div className="font-black text-slate-800 uppercase text-sm md:text-lg leading-tight mb-1">{s.saintName} {s.fullName}</div>
                                                     <div className="text-[10px] md:text-[11px] text-slate-500 font-black uppercase tracking-tight">LỚP: {getClassName(s.classId)}</div>
                                                 </div>
                                             </div>
                                             <button onClick={() => handleMerge(group.key, s.id)} className="w-full md:w-auto px-6 py-2 md:px-8 md:py-3 bg-blue-600 text-white rounded-xl md:rounded-2xl text-[10px] md:text-[11px] font-black uppercase tracking-widest hover:bg-blue-700 shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95">
                                                <Check size={14} strokeWidth={4}/> GIỮ LẠI
                                             </button>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         ))}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-60">
                        <div className="w-20 h-20 md:w-28 md:h-28 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 border-8 border-emerald-50 shadow-inner"><Check size={40} strokeWidth={3}/></div>
                        <h4 className="font-black text-lg md:text-2xl uppercase tracking-widest text-slate-600">DỮ LIỆU SẠCH</h4>
                     </div>
                 )}
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }

        .form-label { display: block; font-size: 0.75rem; font-weight: 600; color: #475569; margin-bottom: 0.25rem; text-transform: uppercase; letter-spacing: 0.02em; }
        .form-input { width: 100%; padding: 0.5rem 0.75rem; border: 1px solid #cbd5e1; border-radius: 0.5rem; outline: none; transition: all 0.2s; font-size: 0.875rem; color: #1e293b; background-color: #fff; font-weight: 500; }
        .form-input:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
        .form-input:disabled { background-color: #f1f5f9; color: #64748b; cursor: not-allowed; }
        .label-tiny { display: block; font-size: 0.65rem; font-weight: 700; color: #94a3b8; margin-bottom: 0.1rem; }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher } from '../types';
import { Search, Plus, Edit, CheckCircle2, AlertTriangle, Save, User, History, GitMerge, ScrollText, X, Check, Fingerprint, Calendar, MapPin, Map, School, Droplets, BookOpen, Flame, Star } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const isAdmin = currentUser?.role === 'ADMIN';

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Filter allowed classes logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (isAdmin) return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser, isAdmin]);

  // Initial Logic
  useEffect(() => {
     const active = years.find(y => y.isActive);
     const activeYearId = active ? active.id : (years[0]?.id || '');
     setSelectedYear(activeYearId);

     // If GLV, auto select the class context
     if (!isAdmin && activeYearId) {
         const myClassesInYear = allowedClasses.filter(c => c.yearId === activeYearId);
         if (myClassesInYear.length > 0) {
             setSelectedClass(myClassesInYear[0].id);
         } else {
             setSelectedClass('');
         }
     }
  }, [years, isAdmin, allowedClasses]);

  const [showModal, setShowModal] = useState(false);
  const [showDuplicateConfirmModal, setShowDuplicateConfirmModal] = useState(false);
  const [modalTab, setModalTab] = useState<'PROFILE' | 'HISTORY'>('PROFILE');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Deduplication States
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // --- FORM STATE ---
  const [inputId, setInputId] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [inputBirthPlace, setInputBirthPlace] = useState('');
  const [inputClassId, setInputClassId] = useState(''); 

  const [inputFatherName, setInputFatherName] = useState('');
  const [inputMotherName, setInputMotherName] = useState('');
  const [inputFatherPhone, setInputFatherPhone] = useState('');
  const [inputMotherPhone, setInputMotherPhone] = useState('');
  const [inputAddress, setInputAddress] = useState('');

  const [inputBaptismDate, setInputBaptismDate] = useState('');
  const [inputBaptismBy, setInputBaptismBy] = useState('');
  const [inputBaptismSponsor, setInputBaptismSponsor] = useState('');
  const [inputBaptismPlace, setInputBaptismPlace] = useState('');

  const [inputEucharistDate, setInputEucharistDate] = useState('');
  const [inputEucharistBy, setInputEucharistBy] = useState('');
  const [inputEucharistPlace, setInputEucharistPlace] = useState('');

  const [inputConfirmationDate, setInputConfirmationDate] = useState('');
  const [inputConfirmationBy, setInputConfirmationBy] = useState('');
  const [inputConfirmationSponsor, setInputConfirmationSponsor] = useState('');
  const [inputConfirmationPlace, setInputConfirmationPlace] = useState('');

  const [inputOathDate, setInputOathDate] = useState('');
  const [inputNote, setInputNote] = useState('');

  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  const classesInYear = useMemo(() => allowedClasses.filter(c => c.yearId === selectedYear), [allowedClasses, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);
  const modalAvailableClasses = useMemo(() => classesInYear, [classesInYear]);
  const glvMyClasses = useMemo(() => isAdmin ? [] : classesInYear, [isAdmin, classesInYear]);

  useEffect(() => {
    if (!showModal) return;
    const cleanName = inputName.trim().toLowerCase();
    if (cleanName.length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === cleanName && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputId(selectedStudent.id);
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
              setInputBirthPlace(selectedStudent.birthPlace || '');
              setInputClassId(selectedStudent.classId);
              setInputFatherName(selectedStudent.fatherName || '');
              setInputMotherName(selectedStudent.motherName || '');
              setInputFatherPhone(selectedStudent.fatherPhone || '');
              setInputMotherPhone(selectedStudent.motherPhone || '');
              setInputAddress(selectedStudent.address || '');
              setInputBaptismDate(selectedStudent.baptismDate || '');
              setInputBaptismBy(selectedStudent.baptismBy || '');
              setInputBaptismSponsor(selectedStudent.baptismSponsor || '');
              setInputBaptismPlace(selectedStudent.baptismPlace || '');
              setInputEucharistDate(selectedStudent.eucharistDate || '');
              setInputEucharistBy(selectedStudent.eucharistBy || '');
              setInputEucharistPlace(selectedStudent.eucharistPlace || '');
              setInputConfirmationDate(selectedStudent.confirmationDate || '');
              setInputConfirmationBy(selectedStudent.confirmationBy || '');
              setInputConfirmationSponsor(selectedStudent.confirmationSponsor || '');
              setInputConfirmationPlace(selectedStudent.confirmationPlace || '');
              setInputOathDate(selectedStudent.confirmationOathDate || '');
              setInputNote(selectedStudent.note || '');
          } else {
              const prefix = selectedYear.slice(2, 4);
              const yearStudents = students.filter(s => s.id.startsWith(prefix));
              const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
              setInputId(`${prefix}${nextNum}`);
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
              setInputClassId((!isAdmin && selectedClass !== 'all') ? selectedClass : (modalAvailableClasses[0]?.id || '')); 
              setInputBirthPlace('');
              setInputFatherName('');
              setInputMotherName('');
              setInputFatherPhone('');
              setInputMotherPhone('');
              setInputAddress('');
              setInputBaptismDate('');
              setInputBaptismBy('');
              setInputBaptismSponsor('');
              setInputBaptismPlace('');
              setInputEucharistDate('');
              setInputEucharistBy('');
              setInputEucharistPlace('');
              setInputConfirmationDate('');
              setInputConfirmationBy('');
              setInputConfirmationSponsor('');
              setInputConfirmationPlace('');
              setInputOathDate('');
              setInputNote('');
          }
          setModalTab('PROFILE');
      }
  }, [showModal, selectedStudent, selectedYear, students, selectedClass, modalAvailableClasses, isAdmin]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else {
            validClassIds = availableClasses.map(c => c.id);
        }
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, availableClasses]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const getClassColor = (classId: string) => {
      const cls = classes.find(c => c.id === classId);
      if (!cls) return 'bg-slate-100 text-slate-700 border-slate-200';
      switch (cls.gradeId) {
          case 'g1': return 'bg-pink-100 text-pink-700 border-pink-200';
          case 'g2': return 'bg-green-100 text-green-700 border-green-200';
          case 'g3': return 'bg-blue-100 text-blue-700 border-blue-200';
          case 'g4': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
          default: return 'bg-slate-100 text-slate-700 border-slate-200';
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.pop() || '';
      const lastName = parts.join(' ');
      return { lastName, firstName };
  };

  const executeSaveStudent = () => {
    const studentData: Student = {
        id: inputId,
        fullName: inputName,
        dob: inputDob,
        saintName: saintInput,
        gender: inputGender,
        status: inputStatus,
        classId: inputClassId,
        parish: 'Gx. Tân Thành',
        birthPlace: inputBirthPlace,
        fatherName: inputFatherName,
        motherName: inputMotherName,
        fatherPhone: inputFatherPhone,
        motherPhone: inputMotherPhone,
        address: inputAddress,
        baptismDate: inputBaptismDate,
        baptismBy: inputBaptismBy,
        baptismSponsor: inputBaptismSponsor,
        baptismPlace: inputBaptismPlace,
        eucharistDate: inputEucharistDate,
        eucharistBy: inputEucharistBy,
        eucharistPlace: inputEucharistPlace,
        confirmationDate: inputConfirmationDate,
        confirmationBy: inputConfirmationBy,
        confirmationSponsor: inputConfirmationSponsor,
        confirmationPlace: inputConfirmationPlace,
        confirmationOathDate: inputOathDate,
        note: inputNote
    };
    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? studentData : s));
        showToast("Đã cập nhật hồ sơ thành công!");
    } else {
        setStudents(prev => [...prev, studentData]);
        showToast(`Đã thêm học viên mới: ${inputId}`);
    }
    setShowModal(false);
    setShowDuplicateConfirmModal(false);
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ: Tên Thánh, Họ tên, Ngày sinh.");
    if (!inputClassId) return alert("Vui lòng chọn lớp cho học viên.");

    // Check duplicates
    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        setShowDuplicateConfirmModal(true);
        return;
    }

    executeSaveStudent();
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      filteredStudents.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Xác nhận giữ lại hồ sơ [${survivorId}] và xóa ${idsToDelete.length} bản ghi trùng?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp và làm sạch dữ liệu thành công!`);
          if (duplicateGroups.length <= 1) setShowDedupModal(false);
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
        default: return null;
    }
  };

  const currentYearName = years.find(y => y.id === selectedYear)?.name || '---';

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-20 right-4 z-[100] animate-slide-in max-w-[90vw]">
           <div className={`text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast.message}</span>
           </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">HỌC VIÊN</h2>
            <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200 uppercase tracking-widest">{filteredStudents.length} hồ sơ</div>
        </div>
        <div className="flex w-full md:w-auto gap-2">
            <button onClick={scanDuplicates} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-3 py-2.5 bg-white border border-amber-400 text-amber-700 rounded-xl hover:bg-amber-50 text-xs font-black shadow-sm transition-all active:scale-95 group whitespace-nowrap">
                <GitMerge size={16} /> <span className="hidden sm:inline">RÀ SOÁT</span> TRÙNG
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase tracking-wide text-xs">
                <Plus size={18} /> Thêm Mới
            </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4 items-center">
        {isAdmin ? (
            <div className="flex flex-col md:flex-row flex-wrap gap-2 items-stretch md:items-center w-full md:w-auto">
                <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
                </select>
                <div className="flex gap-2">
