                            <h3 className="font-black text-slate-800 text-lg leading-tight uppercase"><span className="text-slate-500 text-sm block mb-0.5 font-bold">{s.saintName}</span>{s.fullName}</h3>
                        </div>
                        <button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-2 bg-slate-50 text-blue-600 rounded-lg border border-slate-200 hover:bg-blue-50 active:scale-95 transition-all"><Edit size={18} /></button>
                    </div>
                </div>
            ))}
        </div>
        <div className="hidden md:block overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead className="bg-slate-100 text-slate-700 font-black sticky top-0 z-10 shadow-sm border-b border-slate-300 uppercase text-[11px] tracking-wider">
              <tr>
                <th className="px-4 py-4 w-12 text-center">#</th>
                <th className="px-4 py-4 w-24">Mã</th>
                <th className="px-4 py-4 w-32">Tên Thánh</th>
                <th className="px-4 py-4">Họ & Tên</th>
                <th className="px-4 py-4 w-32 text-left">Ngày Sinh</th>
                <th className="px-4 py-4 w-24 text-left">Giới Tính</th>
                <th className="px-4 py-4 w-44 text-left">SĐT Liên Hệ</th>
                <th className="px-4 py-4 w-32">Lớp</th>
                <th className="px-4 py-4 text-center w-28">Tình Trạng</th>
                <th className="px-4 py-4 text-center w-20">Sửa</th>
              </tr>
            </thead>
            <tbody className="text-base text-slate-800 divide-y divide-slate-100">
              {filteredStudents.map((s, index) => {
                const { lastName, firstName } = splitName(s.fullName);
                const gradeColorClass = getClassColor(s.classId);
                return (
                <tr key={s.id} className="hover:bg-blue-50 transition-colors">
                  <td className="px-4 py-3 text-center text-slate-400 font-bold text-xs">{index + 1}</td>
                  <td className="px-4 py-3 font-mono text-sm font-bold text-slate-500">{s.id}</td>
                  <td className="px-4 py-3 font-bold text-slate-700 text-sm">{s.saintName}</td>
                  <td className="px-4 py-3"><span className="text-slate-600 font-medium">{lastName}</span> <span className="font-black text-slate-900">{firstName}</span></td>
                  <td className="px-4 py-3 text-left font-medium text-slate-600">{new Date(s.dob).toLocaleDateString('vi-VN')}</td>
                  <td className="px-4 py-3 text-left"><span className={`text-[11px] font-black uppercase ${s.gender === 'Male' ? 'text-blue-600' : 'text-pink-600'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td>
                  <td className="px-4 py-3 text-left">
                    <div className="flex flex-col gap-0.5 text-sm font-bold text-blue-700">
                        {s.fatherPhone && <span className="whitespace-nowrap flex items-center gap-1">B: {s.fatherPhone}</span>}
                        {s.motherPhone && <span className="whitespace-nowrap flex items-center gap-1">M: {s.motherPhone}</span>}
                        {!s.fatherPhone && !s.motherPhone && <span className="text-slate-300">--</span>}
                    </div>
                  </td>
                  <td className="px-4 py-3"><span className={`px-2 py-1 rounded text-[10px] font-black uppercase whitespace-nowrap shadow-sm border ${gradeColorClass}`}>{getClassName(s.classId)}</span></td>
                  <td className="px-4 py-3 text-center">{getStatusBadge(s.status)}</td>
                  <td className="px-4 py-3 text-center"><button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-2 text-blue-600 hover:bg-blue-100 rounded-xl transition-all"><Edit size={18} /></button></td>
                </tr>
              )})}
            </tbody>
          </table>
        </div>
      </div>

      {/* --- MODAL HỒ SƠ HỌC VIÊN (FULL SCREEN GRID) --- */}
      {showModal && (
        <div className="fixed inset-0 bg-black/70 z-[60] flex items-center justify-center p-2 md:p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-slate-100 rounded-[1.5rem] shadow-2xl w-full max-w-[95vw] h-[90vh] flex flex-col overflow-hidden border border-slate-300 animate-scale-in">

            {/* Modal Header */}
            <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm z-20">
              <div className="flex items-center gap-4">
                 <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center font-bold shadow-blue-200 shadow-lg">
                    {selectedStudent ? <Fingerprint size={28}/> : <Plus size={28}/>}
                 </div>
                 <div>
                    <h3 className="font-black text-xl text-slate-800 uppercase tracking-tight leading-none mb-1">{selectedStudent ? 'Cập Nhật Hồ Sơ' : 'Thêm Học Viên Mới'}</h3>
                    <p className="text-xs font-mono text-slate-500 uppercase tracking-widest font-bold flex items-center gap-2">
                        MÃ: <span className="bg-slate-100 px-2 py-0.5 rounded text-slate-700">{inputId}</span>
                    </p>
                 </div>
              </div>
              <div className="flex items-center gap-3">
                  <button onClick={() => setShowModal(false)} className="px-5 py-2.5 bg-white border border-slate-300 text-slate-600 rounded-xl font-bold hover:bg-slate-50 text-sm transition-all">Hủy bỏ</button>
                  <button onClick={handleSaveStudent} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 flex items-center gap-2 text-sm active:scale-95 transition-all">
                      <Save size={18}/> Lưu Hồ Sơ
                  </button>
              </div>
            </div>

            {/* Modal Body - 2 Columns Layout */}
            <div className="flex-1 flex flex-col md:flex-row overflow-hidden relative">

                {/* LEFT COLUMN: IDENTITY & FAMILY (40%) */}
                <div className="w-full md:w-[40%] bg-white border-r border-slate-200 p-5 overflow-y-auto custom-scrollbar flex flex-col gap-5">

                    {/* 1. Identity */}
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200">
                        <h4 className="font-bold text-xs uppercase text-blue-700 mb-3 flex items-center gap-2 tracking-wide"><User size={16}/> Thông tin cá nhân</h4>
                        <div className="space-y-3">
                            <div className="grid grid-cols-12 gap-3">
                                <div className="col-span-12">
                                    <label className="label-tiny">Lớp học</label>
                                    <select className="form-input font-bold text-blue-700 py-1.5" value={inputClassId} onChange={(e) => setInputClassId(e.target.value)}>
                                        <option value="">-- Chọn lớp --</option>
                                        {modalAvailableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-5">
                                    <label className="label-tiny">Tên Thánh <span className="text-red-500">*</span></label>
                                    <div className="relative">
                                        <input className="form-input font-bold py-1.5" value={saintInput} onChange={(e) => {setSaintInput(e.target.value); setShowSaintSuggestions(true);}} onFocus={() => setShowSaintSuggestions(true)} onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)} placeholder="Giuse..." />
                                        {showSaintSuggestions && filteredSaints.length > 0 && (
                                            <div className="absolute z-50 w-full bg-white border border-slate-200 rounded-lg shadow-xl max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {filteredSaints.map(s => (<div key={s.id} className="p-2 hover:bg-blue-50 cursor-pointer text-xs font-medium border-b last:border-0" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}>{s.name}</div>))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div className="col-span-7">
                                    <label className="label-tiny">Họ và Tên <span className="text-red-500">*</span></label>
                                    <input className="form-input font-black text-slate-800 uppercase py-1.5" value={inputName} onChange={(e) => setInputName(e.target.value)} placeholder="NGUYỄN VĂN A" />
                                </div>
                                <div className="col-span-5">
                                    <label className="label-tiny">Ngày sinh <span className="text-red-500">*</span></label>
                                    <input type="date" className="form-input font-medium text-blue-700 py-1.5" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                </div>
                                <div className="col-span-3">
                                    <label className="label-tiny">Giới tính</label>
                                    <select className="form-input py-1.5" value={inputGender} onChange={(e) => setInputGender(e.target.value as any)}>
                                        <option value="Male">Nam</option>
                                        <option value="Female">Nữ</option>
                                    </select>
                                </div>
                                <div className="col-span-4">
                                    <label className="label-tiny">Tình trạng</label>
                                    <select className="form-input font-bold text-emerald-700 py-1.5" value={inputStatus} onChange={(e) => setInputStatus(e.target.value as any)}>
                                        <option value="ACTIVE">ĐANG HỌC</option>
                                        <option value="DROPPED">NGHỈ HỌC</option>
                                    </select>
                                </div>
                                <div className="col-span-12">
                                    <label className="label-tiny">Nơi sinh</label>
                                    <input className="form-input py-1.5" value={inputBirthPlace} onChange={(e) => setInputBirthPlace(e.target.value)} placeholder="Bệnh viện..." />
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* 2. Family */}
                    <div className="bg-orange-50/50 p-4 rounded-2xl border border-orange-100">
                        <h4 className="font-bold text-xs uppercase text-orange-700 mb-3 flex items-center gap-2 tracking-wide"><Phone size={16}/> Gia đình & Liên hệ</h4>
                        <div className="space-y-3">
                            <div className="grid grid-cols-12 gap-3">
                                <div className="col-span-7"><label className="label-tiny">Họ tên Bố</label><input className="form-input py-1.5" value={inputFatherName} onChange={(e) => setInputFatherName(e.target.value)} placeholder="Ông..." /></div>
