                                <div className="col-span-7"><label className="label-tiny">Họ tên Mẹ</label><input className="form-input py-1.5" value={inputMotherName} onChange={(e) => setInputMotherName(e.target.value)} placeholder="Bà..." /></div>
                                <div className="col-span-5"><label className="label-tiny">SĐT Mẹ</label><input className="form-input font-mono font-medium py-1.5" value={inputMotherPhone} onChange={(e) => setInputMotherPhone(e.target.value)} placeholder="09..." /></div>
                                <div className="col-span-12"><label className="label-tiny">Địa chỉ</label><input className="form-input py-1.5" value={inputAddress} onChange={(e) => setInputAddress(e.target.value)} placeholder="Số nhà, đường..." /></div>
