import React from 'react';
import { 
  LayoutDashboard, Users, CalendarCheck, BookOpenCheck, Settings, Wallet, 
  Church, GraduationCap, LogOut, School, ArrowRightLeft, Package, MonitorPlay
} from 'lucide-react';
import { Teacher } from '../types';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  isCollapsed: boolean; 
  setIsCollapsed: (val: boolean) => void;
  isMobileOpen: boolean;
  setIsMobileOpen: (val: boolean) => void;
  currentUser: Teacher | null;
  onLogout: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, setActiveTab, isMobileOpen, setIsMobileOpen, currentUser, onLogout 
}) => {
  const menuItems = [
    { id: 'dashboard', label: 'Trang Chủ', icon: LayoutDashboard, color: 'text-blue-600', bg: 'bg-blue-50', border: 'border-blue-200' },
    { id: 'classes', label: 'Lớp Học', icon: School, color: 'text-emerald-600', bg: 'bg-emerald-50', border: 'border-emerald-200' },
    { id: 'students', label: 'Học Viên', icon: Users, color: 'text-violet-600', bg: 'bg-violet-50', border: 'border-violet-200' },
    { id: 'placement', label: 'Xếp Lớp', icon: ArrowRightLeft, color: 'text-cyan-600', bg: 'bg-cyan-50', border: 'border-cyan-200' },
    { id: 'attendance', label: 'Chuyên Cần', icon: CalendarCheck, color: 'text-amber-600', bg: 'bg-amber-50', border: 'border-amber-200' },
    { id: 'grades', label: 'Bảng Điểm', icon: BookOpenCheck, color: 'text-rose-600', bg: 'bg-rose-50', border: 'border-rose-200' },
    { id: 'devices', label: 'Thiết bị', icon: MonitorPlay, color: 'text-fuchsia-600', bg: 'bg-fuchsia-50', border: 'border-fuchsia-200' },
    { id: 'teachers', label: 'Giáo Lý Viên', icon: GraduationCap, color: 'text-indigo-600', bg: 'bg-indigo-50', border: 'border-indigo-200' },
    { id: 'inventory', label: 'Kho & Vật Tư', icon: Package, color: 'text-orange-600', bg: 'bg-orange-50', border: 'border-orange-200' },
    { id: 'finance', label: 'Thủ Quỹ', icon: Wallet, color: 'text-green-700', bg: 'bg-green-50', border: 'border-green-200' },
    { id: 'settings', label: 'Cài Đặt', icon: Settings, color: 'text-slate-600', bg: 'bg-slate-100', border: 'border-slate-200' },
  ];

  // Filter menu items based on permissions
  const visibleMenuItems = menuItems.filter(item => {
      if (!currentUser) return false;
      if (currentUser.role === 'ADMIN') return true;
      if (item.id === 'settings') return true; 
      return currentUser.allowedTabs?.includes(item.id);
  });

  return (
    <div 
      className={`bg-white border-r border-slate-200 flex flex-col h-screen fixed left-0 top-0 z-[100] transition-transform duration-300 ease-in-out 
        ${isMobileOpen ? 'translate-x-0 w-16' : '-translate-x-full'} 
        md:translate-x-0 md:w-16 shadow-xl
      `}
    >
      {/* Header Logo */}
      <div className="h-14 flex items-center justify-center border-b border-slate-100 bg-slate-50/80 backdrop-blur-sm">
        <div className="w-9 h-9 bg-gradient-to-br from-blue-600 to-blue-700 rounded-xl shadow-lg shadow-blue-200/50 flex items-center justify-center">
           <Church className="text-white w-5 h-5" strokeWidth={2.5} />
        </div>
      </div>

      {/* Navigation - Removed overflow-hidden to allow tooltips */}
      <nav className="flex-1 py-3 flex flex-col items-center gap-2 w-full px-2">
        {visibleMenuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`group relative w-10 h-10 flex items-center justify-center rounded-xl transition-all duration-200 
                ${isActive ? `${item.bg} shadow-sm ring-1 ring-inset ${item.border}` : 'hover:bg-slate-50 bg-transparent'}
              `}
            >
              {/* Icon always shows color */}
              <Icon 
                className={`w-5 h-5 transition-all duration-200 ${item.color} ${isActive ? 'scale-110 drop-shadow-sm' : 'opacity-70 grayscale-[0.3] group-hover:grayscale-0 group-hover:opacity-100 group-hover:scale-110'}`} 
                strokeWidth={2.5}
              />

              {/* Tooltip - Fixed positioning strategy for reliability */}
              <div className="absolute left-full top-1/2 -translate-y-1/2 ml-3 px-3 py-1.5 bg-slate-800 text-white text-[11px] font-bold rounded-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all whitespace-nowrap z-[110] shadow-xl border border-slate-700 pointer-events-none origin-left scale-95 group-hover:scale-100">
                  {/* Arrow */}
                  <div className="absolute right-full top-1/2 -translate-y-1/2 -mr-[1px] border-4 border-transparent border-r-slate-800"></div>
                  {item.label}
              </div>
            </button>
          );
        })}
      </nav>

      {/* Footer / User / Logout */}
      <div className="p-3 border-t border-slate-100 flex flex-col items-center gap-3 bg-slate-50/50">
        {/* User Avatar */}
        <div className="w-9 h-9 rounded-full bg-white border border-slate-200 shadow-sm flex items-center justify-center font-black text-slate-600 text-xs" title={`${currentUser?.saintName} ${currentUser?.fullName}`}>
            {currentUser?.fullName.charAt(0)}
        </div>

        <button 
          onClick={onLogout}
          className="w-9 h-9 flex items-center justify-center text-rose-500 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all group relative"
        >
           <LogOut size={18} strokeWidth={2.5}/> 
           <div className="absolute left-full top-1/2 -translate-y-1/2 ml-3 px-3 py-1.5 bg-rose-600 text-white text-[11px] font-bold rounded-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all whitespace-nowrap z-[110] shadow-xl pointer-events-none origin-left scale-95 group-hover:scale-100">
              <div className="absolute right-full top-1/2 -translate-y-1/2 -mr-[1px] border-4 border-transparent border-r-rose-600"></div>
              Đăng xuất
           </div>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Students } from './components/Students';
import { Teachers } from './components/Teachers';
import { Attendance } from './components/Attendance';
import { Grades } from './components/Grades';
import { Finance } from './components/Finance';
import { Settings } from './components/Settings';
import { Classes } from './components/Classes';
import { ClassPlacement } from './components/ClassPlacement';
import { Inventory } from './components/Inventory';
import { Login } from './components/Login';
import { DeviceRegistration } from './components/DeviceRegistration';
import { MOCK_STUDENTS, MOCK_CLASSES, MOCK_YEARS, MOCK_FINANCE, MOCK_ACADEMIC_RECORDS, MOCK_GRADES, MOCK_TERM_CONFIGS, MOCK_INVENTORY, MOCK_SCORE_COLUMNS, MOCK_DEVICE_REQUESTS } from './constants';
import { Student, ClassRoom, SchoolYear, Transaction, AcademicRecord, Grade, TermConfig, InventoryItem, ScoreColumn, Teacher, DeviceRequest, DeviceConfig } from './types';
import { Menu, Church } from 'lucide-react';

const App: React.FC = () => {
  // --- AUTH STATE ---
  const [currentUser, setCurrentUser] = useState<Teacher | null>(null);

  // --- UI STATE ---
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- DATA STATE ---
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [classes, setClasses] = useState<ClassRoom[]>(MOCK_CLASSES);
  const [years, setYears] = useState<SchoolYear[]>(MOCK_YEARS);
  const [grades, setGrades] = useState<Grade[]>(MOCK_GRADES);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_FINANCE);
  const [records, setRecords] = useState<AcademicRecord[]>(MOCK_ACADEMIC_RECORDS);
  const [termConfigs, setTermConfigs] = useState<TermConfig[]>(MOCK_TERM_CONFIGS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [scoreColumns, setScoreColumns] = useState<ScoreColumn[]>(MOCK_SCORE_COLUMNS);
  const [deviceRequests, setDeviceRequests] = useState<DeviceRequest[]>(MOCK_DEVICE_REQUESTS);
  const [deviceConfig, setDeviceConfig] = useState<DeviceConfig>({ 
      openTime: '07:00', 
      closeTime: '17:00',
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString().split('T')[0]
  });

  // Check permissions when activeTab changes
  useEffect(() => {
      if (currentUser && currentUser.role !== 'ADMIN' && currentUser.allowedTabs) {
          // Allow settings by default regardless of allowedTabs
          if (activeTab !== 'settings' && !currentUser.allowedTabs.includes(activeTab)) {
              // Redirect to first allowed tab if current is forbidden
              if (currentUser.allowedTabs.length > 0) {
                  setActiveTab(currentUser.allowedTabs[0]);
              } else {
                  setActiveTab('dashboard'); // Fallback
              }
          }
      }
  }, [activeTab, currentUser]);

  const handleLogin = (user: Teacher) => {
      setCurrentUser(user);
      // Reset tab to dashboard or first allowed tab on login
      if (user.role !== 'ADMIN' && user.allowedTabs && user.allowedTabs.length > 0) {
          setActiveTab(user.allowedTabs[0]);
      } else {
          setActiveTab('dashboard');
      }
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setActiveTab('dashboard');
  };

  if (!currentUser) {
      return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    // Double check permission before rendering (except settings)
    if (activeTab !== 'settings' && currentUser.role !== 'ADMIN' && currentUser.allowedTabs && !currentUser.allowedTabs.includes(activeTab)) {
        return (
            <div className="flex h-full items-center justify-center flex-col text-slate-400">
                <div className="text-4xl font-bold mb-2">403</div>
                <div className="text-sm">Bạn không có quyền truy cập chức năng này.</div>
            </div>
        );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard currentUser={currentUser} classes={classes} years={years} />;
      case 'classes': return <Classes classes={classes} setClasses={setClasses} students={students} years={years} grades={grades} currentUser={currentUser} />;
      case 'students': return <Students students={students} setStudents={setStudents} classes={classes} years={years} records={records} grades={grades} currentUser={currentUser} />;
      case 'placement': return <ClassPlacement students={students} setStudents={setStudents} classes={classes} years={years} grades={grades} currentUser={currentUser} />;
      case 'teachers': return <Teachers />;
      case 'attendance': return <Attendance students={students} classes={classes} years={years} grades={grades} setRecords={setRecords} termConfigs={termConfigs} currentUser={currentUser} />;
      case 'grades': return <Grades students={students} classes={classes} years={years} records={records} setRecords={setRecords} grades={grades} scoreColumns={scoreColumns} currentUser={currentUser} />;
      case 'devices': return <DeviceRegistration requests={deviceRequests} setRequests={setDeviceRequests} currentUser={currentUser} inventory={inventory} config={deviceConfig} />;
      case 'inventory': return <Inventory items={inventory} setItems={setInventory} />;
      case 'finance': return <Finance transactions={transactions} setTransactions={setTransactions} />;
      case 'settings': return <Settings years={years} setYears={setYears} classes={classes} setClasses={setClasses} grades={grades} setGrades={setGrades} termConfigs={termConfigs} setTermConfigs={setTermConfigs} scoreColumns={scoreColumns} setScoreColumns={setScoreColumns} currentUser={currentUser} deviceConfig={deviceConfig} setDeviceConfig={setDeviceConfig} inventory={inventory} setInventory={setInventory} />;
      default: return <Dashboard currentUser={currentUser} classes={classes} years={years} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-100 font-sans relative">
      {/* Mobile Header Bar */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-40 flex items-center justify-between px-4 shadow-sm">
        <div className="flex items-center gap-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                <Menu size={24} />
            </button>
            <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                    <Church size={16} />
                </div>
                <span className="font-bold text-slate-800 text-sm uppercase">Gx. Tân Thành</span>
            </div>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
            setActiveTab(tab);
            setIsMobileMenuOpen(false); // Close mobile menu on select
        }}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        isMobileOpen={isMobileMenuOpen}
        setIsMobileOpen={setIsMobileMenuOpen}
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      {/* Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm animate-fade-in"
            onClick={() => setIsMobileMenuOpen(false)}
        ></div>
      )}

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out pt-16 md:pt-0 md:ml-16 w-full`}
      >
        {renderContent()}
      </main>

      <style>{`
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

export default App;

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher } from '../types';
import { Search, Plus, Edit, CheckCircle2, AlertTriangle, Save, User, History, GitMerge, ScrollText, X, Check, Fingerprint, Calendar, MapPin, Map, School, Droplets, BookOpen, Flame, Star, Phone } from 'lucide-react';
import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_SAINTS } from '../constants';

interface StudentsProps {
    students: Student[];
    setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
    classes: ClassRoom[];
    years: SchoolYear[];
    records: AcademicRecord[];
    grades: Grade[];
    currentUser: Teacher | null;
}

interface DuplicateGroup {
    key: string;
    students: Student[];
}

export const Students: React.FC<StudentsProps> = ({ students, setStudents, classes, years, records, grades, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const isAdmin = currentUser?.role === 'ADMIN';

  const [selectedYear, setSelectedYear] = useState('');
  const [selectedGrade, setSelectedGrade] = useState('all');
  const [selectedClass, setSelectedClass] = useState('all');

  // Filter allowed classes logic
  const allowedClasses = useMemo(() => {
      if (!currentUser) return [];
      if (isAdmin) return classes;

      const teacherName = `${currentUser.saintName} ${currentUser.fullName}`;
      return classes.filter(c => 
          (c.mainTeacher && c.mainTeacher.includes(teacherName)) || 
          (c.assistants && c.assistants.includes(teacherName))
      );
  }, [classes, currentUser, isAdmin]);

  // Initial Logic
  useEffect(() => {
     const active = years.find(y => y.isActive);
     const activeYearId = active ? active.id : (years[0]?.id || '');
     setSelectedYear(activeYearId);

     // If GLV, auto select the class context
     if (!isAdmin && activeYearId) {
         const myClassesInYear = allowedClasses.filter(c => c.yearId === activeYearId);
         if (myClassesInYear.length > 0) {
             setSelectedClass(myClassesInYear[0].id);
         } else {
             setSelectedClass('');
         }
     }
  }, [years, isAdmin, allowedClasses]);

  const [showModal, setShowModal] = useState(false);
  const [showDuplicateConfirmModal, setShowDuplicateConfirmModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Deduplication States
  const [showDedupModal, setShowDedupModal] = useState(false);
  const [duplicateGroups, setDuplicateGroups] = useState<DuplicateGroup[]>([]);

  // --- FORM STATE ---
  const [inputId, setInputId] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputDob, setInputDob] = useState('');
  const [inputGender, setInputGender] = useState<'Male' | 'Female'>('Male');
  const [inputStatus, setInputStatus] = useState<'ACTIVE' | 'TRANSFERRED' | 'DROPPED'>('ACTIVE');
  const [saintInput, setSaintInput] = useState('');
  const [inputBirthPlace, setInputBirthPlace] = useState('');
  const [inputClassId, setInputClassId] = useState(''); 

  const [inputFatherName, setInputFatherName] = useState('');
  const [inputMotherName, setInputMotherName] = useState('');
  const [inputFatherPhone, setInputFatherPhone] = useState('');
  const [inputMotherPhone, setInputMotherPhone] = useState('');
  const [inputAddress, setInputAddress] = useState('');

  const [inputBaptismDate, setInputBaptismDate] = useState('');
  const [inputBaptismBy, setInputBaptismBy] = useState('');
  const [inputBaptismSponsor, setInputBaptismSponsor] = useState('');
  const [inputBaptismPlace, setInputBaptismPlace] = useState('');

  const [inputEucharistDate, setInputEucharistDate] = useState('');
  const [inputEucharistBy, setInputEucharistBy] = useState('');
  const [inputEucharistPlace, setInputEucharistPlace] = useState('');

  const [inputConfirmationDate, setInputConfirmationDate] = useState('');
  const [inputConfirmationBy, setInputConfirmationBy] = useState('');
  const [inputConfirmationSponsor, setInputConfirmationSponsor] = useState('');
  const [inputConfirmationPlace, setInputConfirmationPlace] = useState('');

  const [inputOathDate, setInputOathDate] = useState('');
  const [inputNote, setInputNote] = useState('');

  const [showSaintSuggestions, setShowSaintSuggestions] = useState(false);
  const [realtimeDuplicates, setRealtimeDuplicates] = useState<Student[]>([]);

  const classesInYear = useMemo(() => allowedClasses.filter(c => c.yearId === selectedYear), [allowedClasses, selectedYear]);
  const availableClasses = useMemo(() => selectedGrade === 'all' ? classesInYear : classesInYear.filter(c => c.gradeId === selectedGrade), [classesInYear, selectedGrade]);
  const modalAvailableClasses = useMemo(() => classesInYear, [classesInYear]);
  const glvMyClasses = useMemo(() => isAdmin ? [] : classesInYear, [isAdmin, classesInYear]);

  useEffect(() => {
    if (!showModal) return;
    const cleanName = inputName.trim().toLowerCase();
    if (cleanName.length > 1 && inputDob) {
        const matches = students.filter(s => 
            s.fullName.trim().toLowerCase() === cleanName && 
            s.dob === inputDob && 
            s.id !== selectedStudent?.id
        );
        setRealtimeDuplicates(matches);
    } else {
        setRealtimeDuplicates([]);
    }
  }, [inputName, inputDob, students, selectedStudent, showModal]);

  useEffect(() => {
      if (showModal) {
          if (selectedStudent) {
              setInputId(selectedStudent.id);
              setInputName(selectedStudent.fullName);
              setInputDob(selectedStudent.dob);
              setSaintInput(selectedStudent.saintName);
              setInputGender(selectedStudent.gender);
              setInputStatus(selectedStudent.status);
              setInputBirthPlace(selectedStudent.birthPlace || '');
              setInputClassId(selectedStudent.classId);
              setInputFatherName(selectedStudent.fatherName || '');
              setInputMotherName(selectedStudent.motherName || '');
              setInputFatherPhone(selectedStudent.fatherPhone || '');
              setInputMotherPhone(selectedStudent.motherPhone || '');
              setInputAddress(selectedStudent.address || '');
              setInputBaptismDate(selectedStudent.baptismDate || '');
              setInputBaptismBy(selectedStudent.baptismBy || '');
              setInputBaptismSponsor(selectedStudent.baptismSponsor || '');
              setInputBaptismPlace(selectedStudent.baptismPlace || '');
              setInputEucharistDate(selectedStudent.eucharistDate || '');
              setInputEucharistBy(selectedStudent.eucharistBy || '');
              setInputEucharistPlace(selectedStudent.eucharistPlace || '');
              setInputConfirmationDate(selectedStudent.confirmationDate || '');
              setInputConfirmationBy(selectedStudent.confirmationBy || '');
              setInputConfirmationSponsor(selectedStudent.confirmationSponsor || '');
              setInputConfirmationPlace(selectedStudent.confirmationPlace || '');
              setInputOathDate(selectedStudent.confirmationOathDate || '');
              setInputNote(selectedStudent.note || '');
          } else {
              const prefix = selectedYear.slice(2, 4);
              const yearStudents = students.filter(s => s.id.startsWith(prefix));
              const nextNum = (yearStudents.length > 0 ? Math.max(...yearStudents.map(s => parseInt(s.id.slice(2)))) + 1 : 1).toString().padStart(4, '0');
              setInputId(`${prefix}${nextNum}`);
              setInputName('');
              setInputDob('');
              setSaintInput('');
              setInputGender('Male');
              setInputStatus('ACTIVE');
              setInputClassId((!isAdmin && selectedClass !== 'all') ? selectedClass : (modalAvailableClasses[0]?.id || '')); 
              setInputBirthPlace('');
              setInputFatherName('');
              setInputMotherName('');
              setInputFatherPhone('');
              setInputMotherPhone('');
              setInputAddress('');
              setInputBaptismDate('');
              setInputBaptismBy('');
              setInputBaptismSponsor('');
              setInputBaptismPlace('');
              setInputEucharistDate('');
              setInputEucharistBy('');
              setInputEucharistPlace('');
              setInputConfirmationDate('');
              setInputConfirmationBy('');
              setInputConfirmationSponsor('');
              setInputConfirmationPlace('');
              setInputOathDate('');
              setInputNote('');
          }
      }
  }, [showModal, selectedStudent, selectedYear, students, selectedClass, modalAvailableClasses, isAdmin]);

  const filteredSaints = useMemo(() => {
      return MOCK_SAINTS.filter(s => s.name.toLowerCase().includes(saintInput.toLowerCase()));
  }, [saintInput]);

  const filteredStudents = useMemo(() => {
    const list = students.filter(student => {
        const matchSearch = student.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            student.saintName.toLowerCase().includes(searchTerm.toLowerCase());
        let validClassIds: string[] = [];
        if (selectedClass !== 'all') {
            validClassIds = [selectedClass];
        } else {
            validClassIds = availableClasses.map(c => c.id);
        }
        return matchSearch && validClassIds.includes(student.classId);
    });
    return list.sort((a, b) => (a.fullName.split(' ').pop() || '').localeCompare(b.fullName.split(' ').pop() || '', 'vi'));
  }, [students, searchTerm, selectedClass, availableClasses]);

  const getClassName = (id: string) => classes.find(c => c.id === id)?.name || 'N/A';

  const getClassColor = (classId: string) => {
      const cls = classes.find(c => c.id === classId);
      if (!cls) return 'bg-slate-100 text-slate-700 border-slate-200';
      switch (cls.gradeId) {
          case 'g1': return 'bg-pink-100 text-pink-700 border-pink-200';
          case 'g2': return 'bg-green-100 text-green-700 border-green-200';
          case 'g3': return 'bg-blue-100 text-blue-700 border-blue-200';
          case 'g4': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
          default: return 'bg-slate-100 text-slate-700 border-slate-200';
      }
  };

  const splitName = (fullName: string) => {
      const parts = fullName.trim().split(' ');
      const firstName = parts.pop() || '';
      const lastName = parts.join(' ');
      return { lastName, firstName };
  };

  const executeSaveStudent = () => {
    const studentData: Student = {
        id: inputId,
        fullName: inputName,
        dob: inputDob,
        saintName: saintInput,
        gender: inputGender,
        status: inputStatus,
        classId: inputClassId,
        parish: 'Gx. Tân Thành',
        birthPlace: inputBirthPlace,
        fatherName: inputFatherName,
        motherName: inputMotherName,
        fatherPhone: inputFatherPhone,
        motherPhone: inputMotherPhone,
        address: inputAddress,
        baptismDate: inputBaptismDate,
        baptismBy: inputBaptismBy,
        baptismSponsor: inputBaptismSponsor,
        baptismPlace: inputBaptismPlace,
        eucharistDate: inputEucharistDate,
        eucharistBy: inputEucharistBy,
        eucharistPlace: inputEucharistPlace,
        confirmationDate: inputConfirmationDate,
        confirmationBy: inputConfirmationBy,
        confirmationSponsor: inputConfirmationSponsor,
        confirmationPlace: inputConfirmationPlace,
        confirmationOathDate: inputOathDate,
        note: inputNote
    };
    if (selectedStudent) {
        setStudents(prev => prev.map(s => s.id === selectedStudent.id ? studentData : s));
        showToast("Đã cập nhật hồ sơ thành công!");
    } else {
        setStudents(prev => [...prev, studentData]);
        showToast(`Đã thêm học viên mới: ${inputId}`);
    }
    setShowModal(false);
    setShowDuplicateConfirmModal(false);
  };

  const handleSaveStudent = () => {
    if (!inputName || !inputDob || !saintInput) return alert("Vui lòng nhập đầy đủ: Tên Thánh, Họ tên, Ngày sinh.");
    if (!inputClassId) return alert("Vui lòng chọn lớp cho học viên.");

    // Check duplicates
    if (realtimeDuplicates.length > 0 && !selectedStudent) {
        setShowDuplicateConfirmModal(true);
        return;
    }

    executeSaveStudent();
  };

  const scanDuplicates = () => {
      const groups: { [key: string]: Student[] } = {};
      filteredStudents.forEach(s => {
          const key = `${s.fullName.trim().toLowerCase()}|${s.dob}`;
          if (!groups[key]) groups[key] = [];
          groups[key].push(s);
      });
      const duplicates = Object.entries(groups).filter(([_, list]) => list.length > 1).map(([key, list]) => ({ key, students: list }));
      setDuplicateGroups(duplicates);
      setShowDedupModal(true);
  };

  const handleMerge = (groupKey: string, survivorId: string) => {
      const group = duplicateGroups.find(g => g.key === groupKey);
      if (!group) return;
      const idsToDelete = group.students.filter(s => s.id !== survivorId).map(s => s.id);
      if (window.confirm(`Xác nhận giữ lại hồ sơ [${survivorId}] và xóa ${idsToDelete.length} bản ghi trùng?`)) {
          setStudents(prev => prev.filter(s => !idsToDelete.includes(s.id)));
          setDuplicateGroups(prev => prev.filter(g => g.key !== groupKey)); 
          showToast(`Đã gộp và làm sạch dữ liệu thành công!`);
          if (duplicateGroups.length <= 1) setShowDedupModal(false);
      }
  };

  const getStatusBadge = (status: Student['status']) => {
    switch (status) {
        case 'ACTIVE': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-green-100 text-green-700 border border-green-200 uppercase whitespace-nowrap">Đang học</span>;
        case 'TRANSFERRED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-orange-100 text-orange-700 border border-orange-200 uppercase whitespace-nowrap">Chuyển xứ</span>;
        case 'DROPPED': return <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-red-100 text-red-700 border border-red-200 uppercase whitespace-nowrap">Nghỉ học</span>;
        default: return null;
    }
  };

  const currentYearName = years.find(y => y.id === selectedYear)?.name || '---';

  return (
    <div className="p-4 md:p-6 h-screen flex flex-col relative bg-slate-50">
      {toast && (
        <div className="fixed top-20 right-4 z-[100] animate-slide-in max-w-[90vw]">
           <div className={`text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-emerald-600 border-emerald-500/50' : 'bg-red-600 border-red-500/50'}`}>
              <CheckCircle2 size={20} />
              <span className="font-bold text-sm">{toast.message}</span>
           </div>
        </div>
      )}

      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">HỌC VIÊN</h2>
            <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200 uppercase tracking-widest">{filteredStudents.length} hồ sơ</div>
        </div>
        <div className="flex w-full md:w-auto gap-2">
            <button onClick={scanDuplicates} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-3 py-2.5 bg-white border border-amber-400 text-amber-700 rounded-xl hover:bg-amber-50 text-xs font-black shadow-sm transition-all active:scale-95 group whitespace-nowrap">
                <GitMerge size={16} /> <span className="hidden sm:inline">RÀ SOÁT</span> TRÙNG
            </button>
            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase tracking-wide text-xs">
                <Plus size={18} /> Thêm Mới
            </button>
        </div>
      </div>

      {/* FILTER & LIST SECTION (Existing Code - Keeping it mostly same for the list view) */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-6 flex flex-col xl:flex-row gap-4 items-center">
        {isAdmin ? (
            <div className="flex flex-col md:flex-row flex-wrap gap-2 items-stretch md:items-center w-full md:w-auto">
                <select className="px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {years.map(y => <option key={y.id} value={y.id}>{y.name.replace('Năm học ', '')}</option>)}
                </select>
                <div className="flex gap-2">
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
                    <option value="all">Tất cả Khối</option>
                    {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
                    </select>
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 outline-none text-sm cursor-pointer hover:border-blue-400 transition-colors" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
                    <option value="all">Tất cả Lớp</option>
                    {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                </div>
            </div>
        ) : (
            <div className="flex flex-col md:flex-row items-start md:items-center gap-4 w-full md:w-auto">
                <div className="bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 flex items-center gap-2">
                    <Calendar size={16} className="text-slate-400"/>
                    <span className="text-sm font-bold text-slate-700">{currentYearName}</span>
                </div>
                {glvMyClasses.length > 1 ? (
                    <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0">
                        {glvMyClasses.map(c => (
                            <button
                                key={c.id}
                                onClick={() => setSelectedClass(c.id)}
                                className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all border ${selectedClass === c.id ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                            >
                                {c.name}
                            </button>
                        ))}
                    </div>
                ) : (
                    <div className="bg-blue-50 px-3 py-2 rounded-lg border border-blue-100 flex items-center gap-2">
                        <School size={16} className="text-blue-500"/>
                        <span className="text-sm font-bold text-blue-800">{getClassName(selectedClass)}</span>
                    </div>
                )}
            </div>
        )}

        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input type="text" placeholder="Tìm theo Tên Thánh, Họ tên..." className="w-full pl-12 pr-4 py-2.5 rounded-xl border border-slate-300 outline-none focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}/>
        </div>
      </div>

      <div className="flex-1 overflow-hidden flex flex-col bg-slate-50 md:bg-white md:rounded-2xl md:shadow-sm md:border md:border-slate-200">
        <div className="md:hidden overflow-y-auto custom-scrollbar h-full space-y-3 pb-20">
            {filteredStudents.map((s) => (
                <div key={s.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col gap-3 relative overflow-hidden">
                    <div className={`absolute top-0 left-0 bottom-0 w-1.5 ${s.status === 'ACTIVE' ? 'bg-green-500' : s.status === 'DROPPED' ? 'bg-red-500' : 'bg-orange-500'}`}></div>
                    <div className="flex justify-between items-start pl-2">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="font-mono text-[10px] text-slate-400 font-bold bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200">#{s.id}</span>
                                <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded border ${getClassColor(s.classId)}`}>{getClassName(s.classId)}</span>
                            </div>
                            <h3 className="font-black text-slate-800 text-lg leading-tight uppercase"><span className="text-slate-500 text-sm block mb-0.5 font-bold">{s.saintName}</span>{s.fullName}</h3>
                        </div>
                        <button onClick={() => { setSelectedStudent(s); setShowModal(true); }} className="p-2 bg-slate-50 text-blue-600 rounded-lg border border-slate-200 hover:bg-blue-50 active:scale-95 transition-all"><Edit size={18} /></button>
                    </div>
                </div>
            ))}
        </div>
        <div className="hidden md:block overflow-x-auto custom-scrollbar h-full">
          <table className="w-full text-left border-collapse min-w-[1000px]">
