                  <td className="px-2 py-3 text-left"><span className={`text-[12px] font-black uppercase ${s.gender === 'Male' ? 'text-blue-600' : 'text-pink-600'}`}>{s.gender === 'Male' ? 'Nam' : 'Nữ'}</span></td>
