                        <div className="space-y-3">
                            <div className="grid grid-cols-12 gap-3">
                                <div className="col-span-12">
                                    <label className="label-tiny">Lớp học hiện tại</label>
                                    <select className="form-input font-black text-blue-700 py-2 text-sm uppercase" value={inputClassId} onChange={(e) => setInputClassId(e.target.value)}>
                                        <option value="">-- Chọn lớp học --</option>
                                        {modalAvailableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-5">
                                    <label className="label-tiny">Tên Thánh <span className="text-red-500">*</span></label>
                                    <div className="relative">
                                        <input className="form-input font-black py-2 text-sm uppercase" value={saintInput} onChange={(e) => {setSaintInput(e.target.value); setShowSaintSuggestions(true);}} onFocus={() => setShowSaintSuggestions(true)} onBlur={() => setTimeout(() => setShowSaintSuggestions(false), 200)} placeholder="VD: GIUSE..." />
                                        {showSaintSuggestions && filteredSaints.length > 0 && (
                                            <div className="absolute z-[250] w-full bg-white border border-slate-200 rounded-lg shadow-xl max-h-40 overflow-y-auto mt-1 custom-scrollbar">
                                                {filteredSaints.map(s => (<div key={s.id} className="p-3 hover:bg-blue-50 cursor-pointer text-sm font-bold border-b last:border-0 uppercase" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}>{s.name}</div>))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div className="col-span-7">
                                    <label className="label-tiny">Họ và Tên Học Viên <span className="text-red-500">*</span></label>
                                    <input className="form-input font-black text-slate-800 uppercase py-2 text-sm" value={inputName} onChange={(e) => setInputName(e.target.value)} placeholder="VD: NGUYỄN VĂN AN" />
                                </div>
                                <div className="col-span-5">
                                    <label className="label-tiny">Ngày sinh <span className="text-red-500">*</span></label>
                                    <input type="date" className="form-input font-black text-blue-700 py-2 text-sm" value={inputDob} onChange={(e) => setInputDob(e.target.value)}/>
                                </div>
                                <div className="col-span-3">
                                    <label className="label-tiny">Giới tính</label>
                                    <select className="form-input py-2 text-sm font-bold" value={inputGender} onChange={(e) => setInputGender(e.target.value as any)}>
                                        <option value="Male">Nam</option>
                                        <option value="Female">Nữ</option>
                                    </select>
                                </div>
                                <div className="col-span-4">
                                    <label className="label-tiny">Tình trạng học</label>
                                    <select className="form-input font-black text-emerald-700 py-2 text-sm" value={inputStatus} onChange={(e) => setInputStatus(e.target.value as any)}>
                                        <option value="ACTIVE">ĐANG HỌC</option>
                                        <option value="TRANSFERRED">CHUYỂN XỨ</option>
                                        <option value="DROPPED">NGHỈ HỌC</option>
                                    </select>
                                </div>
                                <div className="col-span-12">
                                    <label className="label-tiny">Nơi sinh</label>
                                    <input className="form-input py-2 text-sm font-bold" value={inputBirthPlace} onChange={(e) => setInputBirthPlace(e.target.value)} placeholder="VD: Bệnh viện Từ Dũ, TP.HCM..." />
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* 2. Family */}
                    <div className="bg-orange-50/50 p-4 rounded-xl border border-orange-100 shadow-sm">
