                            <div className="grid grid-cols-12 gap-3">
                                <div className="col-span-7"><label className="label-tiny">Họ tên Bố</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputFatherName} onChange={(e) => setInputFatherName(e.target.value)} placeholder="VD: NGUYỄN VĂN BA" /></div>
