                                <div className="col-span-7"><label className="label-tiny">Họ tên Mẹ</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputMotherName} onChange={(e) => setInputMotherName(e.target.value)} placeholder="VD: LÊ THỊ TƯ" /></div>
                                <div className="col-span-5"><label className="label-tiny">SĐT Mẹ</label><input className="form-input font-mono font-black py-2 text-sm text-blue-700" value={inputMotherPhone} onChange={(e) => setInputMotherPhone(e.target.value)} placeholder="09xxxxxxxx" /></div>
                                <div className="col-span-12"><label className="label-tiny">Địa chỉ cư trú</label><input className="form-input py-2 text-sm font-bold" value={inputAddress} onChange={(e) => setInputAddress(e.target.value)} placeholder="Số nhà, tên đường, phường/xã..." /></div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* RIGHT COLUMN: SACRAMENTS (60%) */}
                <div className="w-full md:w-[60%] bg-slate-50/50 p-4 overflow-y-auto custom-scrollbar flex flex-col gap-4">

                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <h4 className="font-black text-lg uppercase text-purple-600 mb-4 flex items-center gap-2 tracking-wide border-b border-purple-100 pb-2"><ScrollText size={22}/> Hồ Sơ Bí Tích</h4>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                            {/* Rửa Tội */}
                            <div className="bg-blue-50/50 rounded-xl border border-blue-200 overflow-hidden relative group hover:shadow-md transition-all">
                                <div className="bg-blue-100/80 px-4 py-2 border-b border-blue-200 flex items-center gap-2">
                                    <Droplets size={18} className="text-blue-600" />
                                    <span className="font-black text-xs text-blue-800 uppercase tracking-wider">Rửa Tội</span>
                                </div>
                                <div className="p-4 grid grid-cols-2 gap-3">
                                    <div className="col-span-1"><label className="label-tiny">Ngày Rửa Tội</label><input type="date" className="form-input py-2 text-sm font-bold" value={inputBaptismDate} onChange={e => setInputBaptismDate(e.target.value)} /></div>
                                    <div className="col-span-1"><label className="label-tiny">Tại (Giáo xứ)</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputBaptismPlace} onChange={e => setInputBaptismPlace(e.target.value)} placeholder="VD: TÂN THÀNH" /></div>
                                    <div className="col-span-2"><label className="label-tiny">Linh mục rửa tội</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputBaptismBy} onChange={e => setInputBaptismBy(e.target.value)} placeholder="CHA..." /></div>
                                    <div className="col-span-2"><label className="label-tiny">Người đỡ đầu</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputBaptismSponsor} onChange={e => setInputBaptismSponsor(e.target.value)} placeholder="VD: ÔNG/BÀ..." /></div>
                                </div>
                            </div>

                            {/* Rước Lễ */}
                            <div className="bg-emerald-50/50 rounded-xl border border-emerald-200 overflow-hidden relative group hover:shadow-md transition-all">
                                <div className="bg-emerald-100/80 px-4 py-2 border-b border-emerald-200 flex items-center gap-2">
                                    <BookOpen size={18} className="text-emerald-600" />
                                    <span className="font-black text-xs text-emerald-800 uppercase tracking-wider">Rước Lễ Lần Đầu</span>
                                </div>
                                <div className="p-4 space-y-3">
                                    <div className="grid grid-cols-2 gap-3">
                                        <div><label className="label-tiny">Ngày</label><input type="date" className="form-input py-2 text-sm font-bold" value={inputEucharistDate} onChange={e => setInputEucharistDate(e.target.value)} /></div>
                                        <div><label className="label-tiny">Tại (Giáo xứ)</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputEucharistPlace} onChange={e => setInputEucharistPlace(e.target.value)} placeholder="VD: TÂN THÀNH" /></div>
                                    </div>
                                    <div><label className="label-tiny">Linh mục chủ tế</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputEucharistBy} onChange={e => setInputEucharistBy(e.target.value)} placeholder="CHA..." /></div>
                                </div>
                            </div>

                            {/* Thêm Sức */}
                            <div className="bg-rose-50/50 rounded-xl border border-rose-200 overflow-hidden relative group hover:shadow-md transition-all">
                                <div className="bg-rose-100/80 px-4 py-2 border-b border-rose-200 flex items-center gap-2">
                                    <Flame size={18} className="text-rose-600" />
                                    <span className="font-black text-xs text-rose-800 uppercase tracking-wider">Thêm Sức</span>
                                </div>
                                <div className="p-4 space-y-3">
                                    <div className="grid grid-cols-2 gap-3">
                                        <div><label className="label-tiny">Ngày lãnh nhận</label><input type="date" className="form-input py-2 text-sm font-bold" value={inputConfirmationDate} onChange={e => setInputConfirmationDate(e.target.value)} /></div>
                                        <div><label className="label-tiny">Tại (Giáo xứ)</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputConfirmationPlace} onChange={e => setInputConfirmationPlace(e.target.value)} placeholder="VD: TÂN THÀNH" /></div>
                                    </div>
                                    <div><label className="label-tiny">Đức Cha / Linh mục</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputConfirmationBy} onChange={e => setInputConfirmationBy(e.target.value)} placeholder="ĐỨC CHA..." /></div>
                                    <div><label className="label-tiny">Người đỡ đầu</label><input className="form-input py-2 text-sm font-bold uppercase" value={inputConfirmationSponsor} onChange={e => setInputConfirmationSponsor(e.target.value)} placeholder="ÔN/BÀ..." /></div>
                                </div>
                            </div>

                            {/* Bao Đồng */}
                            <div className="bg-indigo-50/50 rounded-xl border border-indigo-200 overflow-hidden relative group hover:shadow-md transition-all">
                                <div className="bg-indigo-100/80 px-4 py-2 border-b border-indigo-200 flex items-center gap-2">
                                    <Star size={18} className="text-indigo-600" />
                                    <span className="font-black text-xs text-indigo-800 uppercase tracking-wider">Bao Đồng / Tuyên Hứa</span>
                                </div>
                                <div className="p-4">
                                    <label className="label-tiny">Ngày Tuyên Hứa</label>
                                    <input type="date" className="form-input py-2 text-sm font-black w-full" value={inputOathDate} onChange={e => setInputOathDate(e.target.value)} />
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Note Section */}
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex-1 flex flex-col min-h-[80px]">
                        <h4 className="font-black text-xs uppercase text-slate-500 mb-2 flex items-center gap-2 tracking-wide"><Map size={18}/> Ghi Chú Đặc Biệt</h4>
                        <textarea className="form-input resize-none flex-1 text-sm leading-relaxed font-medium" placeholder="Nhập thêm các lưu ý về hoàn cảnh gia đình, học tập..." value={inputNote} onChange={e => setInputNote(e.target.value)}></textarea>
                    </div>

                </div>
            </div>
          </div>
        </div>
      )}

