            <button onClick={() => { setSelectedStudent(null); setShowModal(true); }} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg font-black transition-all active:scale-95 uppercase text-sm">
