                <div className="flex gap-2">
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-sm" value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)}>
                        <option value="all">Tất cả Khối</option>
                        {grades.map(g => <option key={g.id} value={g.id}>{g.name.replace('Khối ', '')}</option>)}
                    </select>
                    <select className="flex-1 px-4 py-2 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 text-sm" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
                        <option value="all">Tất cả Lớp</option>
                        {availableClasses.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                </div>
            </div>
        ) : (
            <div className="flex items-center gap-4">
                <div className="bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 flex items-center gap-2 text-sm font-bold text-slate-700">
