                                                {filteredSaints.map(s => (<div key={s.id} className="p-2 hover:bg-blue-50 cursor-pointer text-xs font-bold border-b last:border-0" onClick={() => {setSaintInput(s.name); setShowSaintSuggestions(false);}}>{s.name}</div>))}
