                    <select className="flex-1 px-5 py-3.5 rounded-xl border border-slate-300 font-bold bg-slate-50 text-blue-800 text-lg outline-none hover:border-blue-400 transition-colors" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)}>
