                                <div className="p-5">
                                    <label className="label-tiny">Ngày tuyên hứa</label>
                                    <input type="date" className="form-input py-4 text-lg font-black w-full" value={inputOathDate} onChange={e => setInputOathDate(e.target.value)} />
                                </div>
                            </div>
