                    </div>

                    {/* Notes Section - Flexible */}
                    <div className="bg-white p-6 rounded-3xl border-2 border-slate-200 shadow-sm flex-1 flex flex-col min-h-[120px]">
                        <h4 className="font-black text-xs text-slate-500 mb-3 flex items-center gap-2 uppercase tracking-widest">Ghi chú quan trọng</h4>
                        <textarea className="form-input resize-none flex-1 text-lg leading-relaxed font-medium" placeholder="Nhập thêm các lưu ý quan trọng về hoàn cảnh gia đình, năng lực giáo lý..." value={inputNote} onChange={e => setInputNote(e.target.value)}></textarea>
                    </div>
                </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-in { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .animate-slide-in { animation: slide-in 0.3s ease-out; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
        @keyframes scale-in { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scale-in { animation: scale-in 0.2s ease-out; }
        .form-input { width: 100%; padding: 0.85rem 1.25rem; border: 2px solid #e2e8f0; border-radius: 1.25rem; outline: none; transition: all 0.2s; font-size: 1.125rem; color: #1e293b; background-color: #fff; font-weight: 600; }
        .form-input:focus { border-color: #3b82f6; box-shadow: 0 0 0 6px rgba(59, 130, 246, 0.1); }
        .label-tiny { display: block; font-size: 0.85rem; font-weight: 800; color: #94a3b8; margin-bottom: 0.35rem; text-transform: uppercase; letter-spacing: 0.05em; }

        .no-spinner::-webkit-inner-spin-button,
        .no-spinner::-webkit-outer-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
      `}</style>
    </div>
  );
};

import { Student, ClassRoom, SchoolYear, AcademicRecord, Grade, Teacher } from '../types';
