        ) : (
            // SUMMARY VIEW
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-50">
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
