                    </div>
                </div>
                <hr style="margin: 15px 0;"/>
                <h4>THÔNG TIN GIA ĐÌNH</h4>
                <p><span class="label">Họ tên Cha:</span> ${selectedStudent.fatherName || '...'} - SĐT: ${selectedStudent.fatherPhone || '...'}</p>
