                        <th style="width: 150px;">Tên Thánh & Họ Tên</th>
                        <th style="width: 80px;">Ngày sinh</th>
                        <th style="width: 40px;">Nam/Nữ</th>
                        <th>Họ tên Cha</th>
                        <th>Họ tên Mẹ</th>
