      <div className={`flex-1 flex-col h-full bg-slate-50 relative overflow-hidden ${selectedStudent || isCreating ? 'flex' : 'hidden md:flex'}`}>

          {(selectedStudent || isCreating) ? (
            <>
                {/* Form Header */}
