                            <Save size={18}/> <span className="hidden lg:inline">Lưu hồ sơ</span><span className="lg:hidden">Lưu</span>
                        </button>
                    </div>
                </div>

                {/* Form Content - Scrollable */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8">
